        Computed {
            font_size: 15.0,
            font_weight: 500,
            family: Family::Sans,
            letter_spacing: 0.0,
            line_spacing: 0.0,
            text_transform: None,
            padding: [0.0; 4],
            gap: (36.0, 36.0),
            direction: Dir::Row,
            align: Align::Center,
            justify: Align::Start,
            width: None,
            height: None,
