fn ind(n: usize) -> String {
    " ".repeat(n)
}

// CSS declarations for one property list, in canonical order.
pub fn css_decls(
    ctx: &Ctx,
    props: &[(String, Value)],
    vars: &mut Vec<String>,
    stroke_width_ctx: f64,
    text: bool,
) -> Result<Vec<(String, String)>, Diag> {
    let env = &ctx.sheet.env;
    let mut out = Vec::new();
    for &k in CSS_ORDER {
        let v = match get(props, k) {
