// affine [a b c d e f]: x' = a x + c y + e, y' = b x + d y + f
fn mul(m: &[f64; 6], n: &[f64; 6]) -> [f64; 6] {
    [
        m[0] * n[0] + m[2] * n[1],
        m[1] * n[0] + m[3] * n[1],
        m[0] * n[2] + m[2] * n[3],
        m[1] * n[2] + m[3] * n[3],
        m[0] * n[4] + m[2] * n[5] + m[4],
        m[1] * n[4] + m[3] * n[5] + m[5],
    ]
}

pub fn node_matrix(ctx: &Ctx, i: usize) -> [f64; 6] {
    let n = &ctx.nodes[i];
    let c = &ctx.comp[i];
    let t = [1.0, 0.0, 0.0, 1.0, n.x + c.translate.0, n.y + c.translate.1];
    if c.rotate != 0.0 {
        let a = c.rotate.to_radians();
        let r = [a.cos(), a.sin(), -a.sin(), a.cos(), 0.0, 0.0];
        mul(&t, &r)
    } else {
        t
    }
}

fn bbox_walk(ctx: &Ctx, i: usize, parent: &[f64; 6], b: &mut [f64; 4]) {
    let n = &ctx.nodes[i];
    let m = mul(parent, &node_matrix(ctx, i));
    let (ow, oh) = crate::layout::outer(ctx, i);
    for (px, py) in [(-ow / 2.0, -oh / 2.0), (ow / 2.0, -oh / 2.0), (ow / 2.0, oh / 2.0), (-ow / 2.0, oh / 2.0)] {
        let x = m[0] * px + m[2] * py + m[4];
        let y = m[1] * px + m[3] * py + m[5];
        b[0] = b[0].min(x);
        b[1] = b[1].min(y);
        b[2] = b[2].max(x);
        b[3] = b[3].max(y);
    }
    if n.prim != Prim::Text {
        for &ch in &n.children {
            bbox_walk(ctx, ch, &m, b);
        }
    }
}

