669	    // ------------------------------------------------------------- statements
670	    fn parse_children(&mut self) -> PResult<Vec<Stmt>> {
671	        self.bump(); // [
672	        let mut out = Vec::new();
673	        loop {
674	            self.skip_seps();
675	            match self.peek() {
676	                Tok::RBrack => {
677	                    self.bump();
678	                    return Ok(out);
679	                }
680	                Tok::Eof => return Err(perr("expected ']'", self.span())),
681	                _ => {}
682	            }
683	            let s = self.parse_stmt(true)?;
684	            out.push(s);
685	            match self.peek() {
686	                Tok::Newline | Tok::Semi | Tok::RBrack => {}
687	                // several bare strings may share a line inside [ ]
688	                Tok::Str(_) if matches!(out.last(), Some(Stmt::Text(_))) => {}
689	                _ => return Err(perr(SEP_ERR, self.span())),
690	            }
691	        }
692	    }
693	
694	    fn parse_stmt(&mut self, _in_children: bool) -> PResult<Stmt> {
695	        let start = self.span();
696	        match self.peek().clone() {
697	            Tok::Bar => {
698	                let node = self.parse_node()?;
699	                if matches!(self.peek(), Tok::LinkOp(_) | Tok::Amp | Tok::DimOp(_) | Tok::BarBar) {
700	                    return Err(perr(SEP_ERR, self.span()));
701	                }
702	                Ok(Stmt::Node(node))
703	            }
704	            Tok::Str(s) => {
705	                self.bump();
706	                let mut classes = Vec::new();
707	                while let Tok::Class(c) = self.peek().clone() {
708	                    self.bump();
709	                    classes.push(c);
710	                }
711	                let mut style = None;
712	                if matches!(self.peek(), Tok::LBrace) {
713	                    style = Some(self.parse_style_block()?.0);
714	                }
715	                Ok(Stmt::Text(TextStmt { text: s, classes, style, span: start.to(self.prev_span()) }))
716	            }
717	            Tok::Ident(_) => self.parse_link(),
718	            Tok::Var(_) => Err(perr("variables are declared in the stylesheet '{ }'", start)),
719	            _ => Err(perr("a node leads with bars — write '|box#X|' (a bare name is a link endpoint)", start)),
720	        }
721	    }
722	
723	    fn parse_node(&mut self) -> PResult<NodeStmt> {
724	        let start = self.span();
725	        self.bump(); // |
726	        let mut type_name = None;
727	        let mut id = None;
728	        if let Tok::Ident(t) = self.peek().clone() {
729	            self.bump();
730	            type_name = Some(t);
731	        }
732	        if let Tok::Hash(h) = self.peek().clone() {
733	            self.bump();
734	            id = Some(h);
735	        }
736	        if !matches!(self.peek(), Tok::Bar) {
737	            if type_name.is_none() && id.is_none() {
738	                return Err(perr("'| |' needs a type or an '#id'", start));
739	            }
740	            return Err(perr("expected '|'", self.span()));
741	        }
742	        let bar = self.bump();
743	        if type_name.is_none() && id.is_none() {
744	            return Err(perr("'| |' needs a type or an '#id'", start));
745	        }
746	        let head_span = start.to(bar.span);
747	        let mut node = NodeStmt {
748	            type_name,
749	            id,
750	            label: None,
751	            classes: vec![],
752	            classes_span: None,
753	            style: None,
754	            style_span: None,
755	            children: None,
756	            span: head_span,
757	            head_span,
758	        };
759	        self.parse_node_tail(&mut node)?;
760	        node.span = start.to(self.prev_span());
761	        Ok(node)
762	    }
763	
764	    fn parse_node_tail(&mut self, node: &mut NodeStmt) -> PResult<()> {
765	        if let Tok::Str(s) = self.peek().clone() {
766	            let t = self.bump();
767	            node.label = Some((s, t.span));
768	            if matches!(self.peek(), Tok::Str(_)) {
769	                return Err(perr("one inline label — put two or more in a '[ ]'", self.span()));
770	            }
771	        }
772	        if let Tok::Class(_) = self.peek() {
773	            let cs = self.span();
774	            while let Tok::Class(c) = self.peek().clone() {
775	                if self.tok().space_before && !node.classes.is_empty() {
776	                    return Err(perr("classes glue into a chain — write '.hot.loud', no space", self.span()));
777	                }
778	                self.bump();
779	                node.classes.push(c);
780	            }
781	            node.classes_span = Some(cs.to(self.prev_span()));
782	            if matches!(self.peek(), Tok::Str(_)) {
783	                return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
784	            }
785	        }
786	        if matches!(self.peek(), Tok::LBrace) {
787	            let (d, sp) = self.parse_style_block()?;
788	            node.style = Some(d);
789	            node.style_span = Some(sp);
790	            if matches!(self.peek(), Tok::Str(_)) {
791	                return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
792	            }
793	        }
794	        if matches!(self.peek(), Tok::LBrack) {
795	            node.children = Some(self.parse_children()?);
796	        }
797	        Ok(())
798	    }
