# usage: words.py WORDFILE  -> for each word, show classification in several contexts
import sys
sys.path.insert(0, '/tmp/hl')
from batch import batch
words = [w for w in open(sys.argv[1]).read().split() if w]
ctxs = [('norm', '%s'), ('val', 'x: %s'), ('bar', '|%s|'), ('call', 'x: %s(1)'), ('prop', '%s: 1'), ('ncall', '%s(1)')]
if len(sys.argv) > 2:
    ctxs = [c for c in ctxs if c[0] in sys.argv[2].split(',')]
res = {}
for name, fmt in ctxs:
    out = batch([fmt % w for w in words])
    res[name] = out
for i, w in enumerate(words):
    print('%-18s' % w, ' | '.join('%s' % res[n][i] for n, _ in ctxs))

