#!/usr/bin/env python3
# classify candidate words in contexts, save lists
import sys, re, json
sys.path.insert(0, '/tmp/hl')
from batch import batch
words = [w for w in open(sys.argv[1]).read().split() if w]
ctxs = {'bar': '|%s|', 'prop': '%s: 1', 'val': 'x: %s', 'call': 'x: %s(1)', 'norm': '%s', 'ncall': '%s(1)'}
res = {}
CH = 2000
for name, fmt in ctxs.items():
    out = []
    for i in range(0, len(words), CH):
        out += batch([fmt % w for w in words[i:i + CH]])
    res[name] = out


def kind_of(o, w):
    m = re.search(r'\[([A-Z]+):' + re.escape(w) + r'\]', o)
    return m.group(1) if m else '-'


table = {}
for i, w in enumerate(words):
    table[w] = {n: kind_of(res[n][i], w) for n in ctxs}
json.dump(table, open(sys.argv[2], 'w'), indent=0)
# summary
from collections import Counter
for n in ctxs:
    c = Counter(table[w][n] for w in words)
    print(n, dict(c))

