#!/usr/bin/env python3
# gather a big word corpus from python stdlib + man pages + docs
import re, glob, os, gzip
words = set()
files = glob.glob('/usr/lib/python3*/**/*.py', recursive=True)
files += glob.glob('/usr/share/man/**/*.gz', recursive=True)
files += glob.glob('/usr/share/doc/**/*', recursive=True)
files += glob.glob('/usr/share/cmake*/**/*.rst', recursive=True)
files += glob.glob('/usr/share/cmake*/**/*.txt', recursive=True)
n = 0
for p in files:
    if os.path.isdir(p):
        continue
    try:
        if p.endswith('.gz'):
            t = gzip.open(p).read().decode('utf-8', 'replace')
        else:
            if os.path.getsize(p) > 5_000_000:
                continue
            t = open(p, encoding='utf-8', errors='replace').read()
    except Exception:
        continue
    n += 1
    for w in re.findall(r'[A-Za-z][A-Za-z0-9_-]*', t):
        w = w.rstrip('-_')
        if 1 <= len(w) <= 30:
            words.add(w)
            words.add(w.lower())
            for part in re.split(r'[-_]', w):
                if part:
                    words.add(part)
                    words.add(part.lower())
old = set(open('/tmp/hl/cands.txt').read().split())
words -= old
words = sorted(words)
open('/tmp/hl/cands2.txt', 'w').write('\n'.join(words) + '\n')
print(n, len(words))

