#!/usr/bin/env python3
# mutation-based differential fuzzing using asset lines as seeds
import sys, random, subprocess, glob
sys.path.insert(0, '/tmp/hl')
from show import compact
ORIG = '/workspace/executable'
MINE = '/tmp/bin-hl/executable'
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 50
per = int(sys.argv[3]) if len(sys.argv) > 3 else 300
rng = random.Random(seed)
lines = []
for f in glob.glob('/workspace/assets/**/*.lini', recursive=True):
    lines += [l for l in open(f, encoding='utf-8').read().split('\n') if l.strip()]
inserts = list('{}[]();,:|#.-<>*~&+o"/\\ \t') + ['::', '//', '->', '--', '#fff', 'left', 'fill', 'box', '\r', 'é', ' ', ' ']


def mutate(l):
    l = list(l)
    for _ in range(rng.randint(1, 4)):
        r = rng.random()
        if not l:
            l = list(rng.choice(lines))
        p = rng.randrange(len(l) + 1)
        if r < 0.35 and l:
            del l[min(p, len(l) - 1)]
        elif r < 0.7:
            l[p:p] = list(rng.choice(inserts))
        elif r < 0.85 and l:
            q = rng.randrange(len(l))
            l[p:p] = l[q:q + rng.randint(1, 6)]
        else:
            other = rng.choice(lines)
            q = rng.randrange(len(other) + 1)
            l[p:] = list(other[q:])
    return ''.join(l)


def run(exe, s):
    return subprocess.run([exe, 'highlight', '-'], input=s.encode(), capture_output=True).stdout


def same(s):
    return run(ORIG, s) == run(MINE, s)


def minimize(s):
    changed = True
    while changed:
        changed = False
        for size in (16, 8, 4, 2, 1):
            i = 0
            while i < len(s):
                t = s[:i] + s[i + size:]
                if t and not same(t):
                    s = t
                    changed = True
                else:
                    i += size
    return s


bad = 0
seen = set()
for r in range(rounds):
    ls = [mutate(rng.choice(lines)) for _ in range(per)]
    src = '\n'.join(ls) + '\n'
    o1 = run(ORIG, src)
    o2 = run(MINE, src)
    if o1 == o2:
        continue
    a = o1.decode().split('\n')
    b = o2.decode().split('\n')
    for k, l in enumerate(ls):
        if k < len(a) and k < len(b) and a[k] == b[k]:
            continue
        if same(l):
            print('CROSS-LINE?', repr(l))
            break
        m = minimize(l)
        if m in seen:
            break
        seen.add(m)
        bad += 1
        print('MIN:', repr(m))
        print('   O:', compact(run(ORIG, m).decode()))
        print('   M:', compact(run(MINE, m).decode()))
        break
print('rounds', rounds, 'bad', bad)

