            i = 0
            while i < len(s):
                t = s[:i] + s[i + size:]
                if t and not same(t):
                    s = t
                    changed = True
                else:
                    i += size
    return s


seen = set()
for r in range(rounds):
    ls = [mutate(rng.choice(lines)) for _ in range(per)]
    src = '\n'.join(ls) + '\n'
    o1 = orig(src)
    o2 = js(src)
    if o1 == o2:
        continue
    a = o1.decode().split('\n')
    b = o2.decode().split('\n')
    for k, l in enumerate(ls):
        if k < len(a) and k < len(b) and a[k] == b[k]:
            continue
        m = minimize(l)
        if m in seen:
            break
        seen.add(m)
        print('MIN:', repr(m))
        print('   O:', compact(orig(m).decode()))
        print('   J:', compact(js(m).decode()))
        break
print('done', len(seen))

