// `lini fmt`: reprint a document in canonical style.
//
// The formatter has its own lexer and parser (src/format/) that keep source
// positions and comments; it follows the compiler's grammar and reports the
// same first syntax error.

mod cst;
mod expr;
mod lex;
mod parse;
mod print;

use crate::diag::Diag;

pub fn format(src: &str) -> Result<String, Diag> {
    let lexed = lex::lex(src)?;
    let mut p = parse::Parser::new(src, &lexed.toks, &lexed.comments);
    let doc = p.parse_doc()?;
    let mut out = print::Out::new();
    out.doc(&doc);
    Ok(out.finish())
}

