fn draw(&mut self, indent: usize, d: &Decl) {
    let prefix = format!("{}: ", d.name);
    let col = indent + prefix.len();
    let mut pieces: Vec<String> = Vec::new();
    let ng = d.groups.len();
    for (gi, g) in d.groups.iter().enumerate() {
        for (ti, t) in g.iter().enumerate() {
            let mut p = t.clone();
            if gi + 1 < ng && ti + 1 == g.len() {
                p.push(',');
            }
            pieces.push(p);
        }
        if g.is_empty() && gi + 1 < ng {
            pieces.push(",".to_string());
        }
    }
    if pieces.is_empty() {
        self.line(indent, &format!("{};", prefix.trim_end()));
        return;
    }
    let n = pieces.len();
    let mut cur = format!("{}{}{}", pad(indent), prefix, pieces[0]);
    for (k, p) in pieces.iter().enumerate().skip(1) {
        let extra = if k + 1 == n { 1 } else { 0 };
        if cur.len() + 1 + p.len() + extra > WIDTH {
            self.lines.push(cur);
            cur = format!("{}{}", pad(col), p);
        } else {
            cur.push(' ');
            cur.push_str(p);
        }
    }
    cur.push(';');
    self.lines.push(cur);
}

