#!/usr/bin/env python3
# usage: fuzz.py MINE [-n variants] [-s seed] [-k kinds] [-o outdir] files...
# Mutates input files, runs ORIGINAL and MINE `fmt --stdout`, reports mismatches.
import subprocess, sys, os, random, tempfile, re

args = sys.argv[1:]
mine = args.pop(0)
nvar = 10; seed = 1; kinds = None; outdir = '/tmp/fmt/fuzzout'; extra = ['fmt', '--stdout']
files = []
while args:
    a = args.pop(0)
    if a == '-n': nvar = int(args.pop(0))
    elif a == '-s': seed = int(args.pop(0))
    elif a == '-k': kinds = args.pop(0).split(',')
    elif a == '-o': outdir = args.pop(0)
    elif a == '-a': extra = args.pop(0).split()
    else: files.append(a)
os.makedirs(outdir, exist_ok=True)
ORIG = '/workspace/executable'
d = tempfile.mkdtemp(dir='/tmp/fmt')

def run(b, src):
    p = os.path.join(d, 'in.lini')
    with open(p, 'wb') as f: f.write(src.encode('utf-8'))
    try:
        r = subprocess.run([b] + extra + ['in.lini'], capture_output=True, cwd=d, timeout=20)
    except subprocess.TimeoutExpired:
        return b'TIMEOUT'
    return r.stdout + b'\n--stderr--\n' + r.stderr + b'\n--exit %d--' % r.returncode

def lines_of(s): return s.split('\n')

COMMENTS = ['// note', '// a — b', '//x', '// trailing  ', '// [ ] { } ;']

def m_reindent(s, rnd):
    out = []
    for l in lines_of(s):
        st = l.lstrip(' ')
        k = rnd.choice([0, 0, 1, 2, 3, 4, 8])
        out.append(' ' * k + st)
    return '\n'.join(out)

def m_spaces(s, rnd):
    # widen some existing single spaces outside strings/comments
    out = []
    for l in lines_of(s):
        res = []; instr = False; i = 0
        while i < len(l):
            c = l[i]
            if c == '"' and (i == 0 or l[i-1] != '\\'): instr = not instr
            if not instr and l.startswith('//', i):
                res.append(l[i:]); break
            if c == ' ' and not instr and rnd.random() < 0.3:
                res.append(' ' * rnd.randint(1, 4))
            else:
                res.append(c)
            i += 1
        out.append(''.join(res))
    return '\n'.join(out)

def m_blank(s, rnd):
    ls = lines_of(s); out = []
    for l in ls:
        if rnd.random() < 0.15: out.append('')
        if rnd.random() < 0.05: out.append('   ')
        out.append(l)
    return '\n'.join(out)

def m_noblank(s, rnd):
    return '\n'.join(l for l in lines_of(s) if l.strip() != '' or rnd.random() < 0.3)

def m_comment(s, rnd):
    ls = lines_of(s); out = []
    for l in ls:
        if rnd.random() < 0.15:
            out.append(' ' * rnd.randint(0, 4) + rnd.choice(COMMENTS))
        if rnd.random() < 0.2 and '//' not in l and l.strip():
            l = l + ' ' * rnd.randint(0, 3) + rnd.choice(COMMENTS)
        out.append(l)
    return '\n'.join(out)

def m_uncomment(s, rnd):
    out = []
    for l in lines_of(s):
        i = l.find('//')
        if i >= 0 and l.count('"') % 2 == 0 and rnd.random() < 0.7:
            l = l[:i].rstrip()
        out.append(l)
    return '\n'.join(out)

def m_semis(s, rnd):
    # drop '; }' -> ' }' and ';\n' before '}' randomly
    s = re.sub(r';(\s*)\}', lambda m: (m.group(1) + '}') if rnd.random() < 0.5 else m.group(0), s)
    return s

def m_join(s, rnd):
    # join some lines inside blocks
    ls = lines_of(s); out = []
    i = 0
    while i < len(ls):
        l = ls[i]
        if i + 1 < len(ls) and rnd.random() < 0.2 and '//' not in l:
            nxt = ls[i+1].strip()
            if l.rstrip().endswith(('{', '[', ';')) or nxt.startswith(('}', ']')):
                out.append(l.rstrip() + ' ' + nxt); i += 2; continue
        out.append(l); i += 1
    return '\n'.join(out)

def m_split(s, rnd):
    # break after '{' / '[' / ';' and before '}' / ']'
    res = []; instr = False; incom = False
    for i, c in enumerate(s):
        if c == '\n': incom = False
        if not incom and c == '"' and (i == 0 or s[i-1] != '\\'): instr = not instr
        if not instr and not incom and s.startswith('//', i): incom = True
        if not instr and not incom and c in '}]' and rnd.random() < 0.3:
            res.append('\n')
        res.append(c)
        if not instr and not incom and c in '{[;' and rnd.random() < 0.3:
            res.append('\n')
    return ''.join(res)

def m_delline(s, rnd):
    ls = lines_of(s)
    if not ls: return s
    k = rnd.randrange(len(ls))
    del ls[k]
    return '\n'.join(ls)

def m_dupline(s, rnd):
    ls = lines_of(s)
    if not ls: return s
    k = rnd.randrange(len(ls))
    ls.insert(k, ls[k])
    return '\n'.join(ls)

def m_truncate(s, rnd):
    if not s: return s
    return s[:rnd.randrange(len(s))]

def m_delchar(s, rnd):
    if not s: return s
    k = rnd.randrange(len(s))
    return s[:k] + s[k+1:]

def m_inschar(s, rnd):
    k = rnd.randrange(len(s) + 1)
    return s[:k] + rnd.choice(list('{}[]();:,.|#"-><&=*/ \n')) + s[k:]

def m_trailing_ws(s, rnd):
    return '\n'.join(l + (' ' * rnd.randint(0, 3) if rnd.random() < 0.3 else '') for l in lines_of(s))

def m_crlf(s, rnd):
    return s.replace('\n', '\r\n')

def m_endnl(s, rnd):
    s = s.rstrip('\n')
    return s + rnd.choice(['', '\n', '\n\n', '\n\n\n', '\n  \n'])

KINDS = {
    'reindent': m_reindent, 'spaces': m_spaces, 'blank': m_blank, 'noblank': m_noblank,
    'comment': m_comment, 'uncomment': m_uncomment, 'semis': m_semis, 'join': m_join,
    'split': m_split, 'delline': m_delline, 'dupline': m_dupline, 'truncate': m_truncate,
    'delchar': m_delchar, 'inschar': m_inschar, 'trailws': m_trailing_ws, 'crlf': m_crlf, 'endnl': m_endnl,
}
kinds = kinds or list(KINDS)
rnd = random.Random(seed)
bad = []
total = 0
for f in files:
    src = open(f, encoding='utf-8').read()
    for v in range(nvar):
        k = rnd.choice(kinds)
        s2 = KINDS[k](src, rnd)
        if rnd.random() < 0.3:
            k2 = rnd.choice(kinds); s2 = KINDS[k2](s2, rnd); k = k + '+' + k2
        total += 1
        o1 = run(ORIG, s2); o2 = run(mine, s2)
        if o1 != o2:
            bad.append((len(s2), f, k, s2, o1, o2))
bad.sort(key=lambda x: x[0])
for i, (n, f, k, s2, o1, o2) in enumerate(bad):
    with open(os.path.join(outdir, 'case%03d.lini' % i), 'w') as fh: fh.write(s2)
    with open(os.path.join(outdir, 'case%03d.orig' % i), 'wb') as fh: fh.write(o1)
    with open(os.path.join(outdir, 'case%03d.mine' % i), 'wb') as fh: fh.write(o2)
print('mismatches %d / %d' % (len(bad), total))
for i, (n, f, k, s2, o1, o2) in enumerate(bad[:40]):
    print('  case%03d %s %s (%d bytes)' % (i, os.path.basename(f), k, n))

