226	            }
227	            let s = self.tok().s;
228	            let st = self.parse_stmt(Ctx::Top)?;
229	            let was_text = matches!(st, Stmt::Text(_));
230	            items.push((s, self.last_end(), Some(st)));
231	            self.after_stmt(was_text)?;
232	        }
233	        let end = self.src.len();
234	        let blk = self.build_block(0, items, end);
235	        let mut entries = blk.entries.into_iter();
236	        let mut sheet_lead = Vec::new();
237	        let mut sheet_trail = None;
238	        let mut stmts = Vec::new();
239	        if sheet.is_some() {
240	            let e = entries.next().unwrap();
241	            sheet_lead = e.lead;
242	            sheet_trail = e.trail;
243	        }
244	        for e in entries {
245	            stmts.push(Entry { lead: e.lead, item: e.item.unwrap(), trail: e.trail });
246	        }
247	        let stmts = Block { entries: stmts, close: blk.close, any_comment: blk.any_comment, comment_among: blk.comment_among };
248	        Ok(Doc { sheet, sheet_lead, sheet_trail, stmts })
249	    }
250	
251	    // separator after a statement: ';' (then more may follow on the line),
252	    // a newline, a closing bracket, or the end; bare strings share a line
253	    fn after_stmt(&mut self, was_text: bool) -> R<()> {
254	        match self.peek() {
255	            K::Semi => {
