    fn build_block<T>(&self, open: Option<usize>, items: Vec<(usize, usize, T)>, close: usize) -> Block<T> {
        let o = open.unwrap_or(0);
        let any_trivia = match open {
            Some(o) => self.any_trivia(o, close),
            None => !self.trivia_range(None, close).is_empty(),
