                let mut depth = 0usize;
                loop {
                    match self.peek() {
                        K::Eof => return Err(self.err_here("expected ')'")),
                        K::LParen => depth += 1,
                        K::RParen if depth == 0 => break,
                        K::RParen => depth -= 1,
                        K::Comma if depth == 0 => break,
                        K::Newline => {
                            self.bump();
                            continue;
                        }
                        _ => {}
                    }
                    end = self.bump().e;
                }
                if args.is_empty() {
