118	                    toks.push(Tok { k: K::Newline, s: off(i), e: off(i + 1), sp, v: 0.0, text: String::new(), pre });
119	                    in_nl_run = true;
120	                }
121	                i += 1;
122	                sp = true;
123	                line_start = true;
124	                continue;
125	            }
126	            '/' if at(i + 1) == '/' => {
