1	// Recursive-descent parser for `lini fmt`. It follows the compiler's grammar
2	// (and its error messages) and builds the concrete tree the printer walks.
3	
4	use super::cst::*;
5	use super::expr;
6	use super::lex::{Tok, K};
7	use crate::diag::{Diag, Span};
8	use std::collections::{HashMap, HashSet};
9	
10	type R<T> = Result<T, Diag>;
11	
12	pub const SEP_ERR: &str = "expected a newline, ';', or a closing bracket";
13	const NODE_ERR: &str = "a node leads with bars — write '|box#X|' (a bare name is a link endpoint)";
14	use super::lex::MATH_ERR;
15	const GROUP_ERR: &str = "to compute here, wrap the math in a group — e.g. (a - b)";
16	const LABEL_FIRST: &str = "a label comes before classes — write '|box| \"X\" .hot'";
17	const CLASS_GLUE: &str = "classes glue into a chain — write '.hot.loud', no space";
18	const ONE_LABEL: &str = "one inline label — put two or more in a '[ ]'";
19	const CLASS_FIRST: &str = "a class comes before the style block — write '|box| .hot { … }'";
20	
21	fn perr(msg: &str, t: &Tok) -> Diag {
22	    Diag::error(family_of(msg), msg, Span::new(t.s, t.e))
23	}
24	
25	// the diagnostic family (and so the code) a parse message belongs to
26	pub fn family_of(msg: &str) -> &'static str {
27	    if msg.starts_with("expected ") {
28	        "expected-token"
29	    } else if msg.starts_with("'| |' needs") {
30	        "empty-bars"
31	    } else if msg.contains("is not a valid id") {
32	        "invalid-id"
33	    } else if msg.starts_with("a declaration belongs in") {
34	        "declaration-outside-block"
35	    } else if msg.starts_with("the stylesheet '{ }' must come first") {
36	        "stylesheet-after-canvas"
37	    } else if msg.starts_with("text content takes no") {
38	        "text-carries-children"
39	    } else if msg.starts_with("a call's '('") {
40	        "spaced-call-paren"
41	    } else {
42	        "parse"
43	    }
44	}
45	
46	struct Term {
47	    text: String,
48	    call: bool,
49	    tracks: i64,      // grid tracks this term stands for in `columns:`
50	    num: Option<f64>, // a plain number literal
51	}
52	
53	#[derive(Clone, Copy, PartialEq)]
54	enum Ctx {
55	    Top,
56	    Children,
57	    Define,
58	    Labels,
59	}
60	
61	pub struct Parser<'a> {
62	    src: &'a str,
63	    toks: &'a [Tok],
64	    pos: usize,
65	    defines: Vec<(String, String)>,
66	    // how deep inside '[ ]' blocks the parser is
67	    brackets: usize,
68	}
69	
70	pub fn render_number(v: f64) -> String {
71	    if v == 0.0 {
72	        return "0".to_string();
73	    }
74	    format!("{}", v)
75	}
76	
77	pub fn render_string(s: &str) -> String {
78	    let t = s.trim();
79	    let mut o = String::with_capacity(t.len() + 2);
80	    o.push('"');
81	    for c in t.chars() {
82	        match c {
83	            '"' => o.push_str("\\\""),
84	            '\\' => o.push_str("\\\\"),
85	            '\n' => o.push_str("\\n"),
86	            '\t' => o.push_str("\\t"),
87	            c => o.push(c),
88	        }
89	    }
90	    o.push('"');
91	    o
92	}
93	
94	impl<'a> Parser<'a> {
95	    pub fn new(src: &'a str, toks: &'a [Tok]) -> Self {
96	        Parser { src, toks, pos: 0, defines: Vec::new(), brackets: 0 }
97	    }
98	
99	    fn peek(&self) -> K {
100	        self.toks[self.pos].k
101	    }
102	    fn peek_at(&self, k: usize) -> K {
103	        let i = (self.pos + k).min(self.toks.len() - 1);
104	        self.toks[i].k
105	    }
106	    fn tok(&self) -> &Tok {
107	        &self.toks[self.pos]
108	    }
109	    fn tok_at(&self, k: usize) -> &Tok {
110	        let i = (self.pos + k).min(self.toks.len() - 1);
111	        &self.toks[i]
112	    }
113	    fn bump(&mut self) -> Tok {
114	        let t = self.toks[self.pos].clone();
115	        if self.pos < self.toks.len() - 1 {
116	            self.pos += 1;
117	        }
118	        t
119	    }
120	    // end offset of the last consumed token
121	    fn last_end(&self) -> usize {
122	        if self.pos == 0 {
123	            0
124	        } else {
125	            self.toks[self.pos - 1].e
126	        }
127	    }
128	    fn skip_newlines(&mut self) {
129	        while self.peek() == K::Newline {
130	            self.bump();
131	        }
132	    }
133	    fn err_here(&self, msg: &str) -> Diag {
134	        perr(msg, self.tok())
135	    }
136	    fn decl_msg(&self) -> &'static str {
137	        if self.brackets > 0 {
138	            "declarations go in '{ }', not '[ ]'"
139	        } else {
140	            "a declaration belongs in a '{ }' block"
141	        }
142	    }
143	    // two glued bars: the '||' (flush) operator
144	    fn at_barbar(&self) -> bool {
145	        self.peek() == K::Bar && self.peek_at(1) == K::Bar && !self.tok_at(1).sp
146	    }
147	
148	    // ------------------------------------------------------------- trivia
149	    // Trivia rides on tokens (`Tok::pre`). An entry's leading trivia is all
150	    // the trivia from just after the previous entry's last token up to and
151	    // including its own first token; what falls inside an entry stays there.
152	    fn trivia_range(&self, after: Option<usize>, upto: usize) -> Vec<Triv> {
153	        let from = match after {
154	            Some(a) => a + 1,
155	            None => 0,
156	        };
157	        let mut out = Vec::new();
158	        for k in from..=upto.min(self.toks.len() - 1) {
159	            out.extend(self.toks[k].pre.iter().cloned());
160	        }
161	        out
162	    }
163	
164	    fn any_trivia(&self, after: usize, upto: usize) -> bool {
165	        (after + 1..=upto.min(self.toks.len() - 1)).any(|k| !self.toks[k].pre.is_empty())
166	    }
167	
168	    fn any_comment(&self, after: usize, upto: usize) -> bool {
169	        (after + 1..=upto.min(self.toks.len() - 1))
170	            .any(|k| self.toks[k].pre.iter().any(|t| matches!(t, Triv::Comment { .. })))
171	    }
172	
173	    // items: (first token, last token, item)
174	    fn build_block<T>(&self, open: Option<usize>, items: Vec<(usize, usize, T)>, close: usize) -> Block<T> {
175	        let o = open.unwrap_or(0);
176	        let any_trivia = match open {
177	            Some(o) => self.any_trivia(o, close),
178	            None => !self.trivia_range(None, close).is_empty(),
179	        };
180	        let any_comment = match open {
181	            Some(o) => self.any_comment(o, close),
182	            None => self.trivia_range(None, close).iter().any(|t| matches!(t, Triv::Comment { .. })),
183	        };
184	        let trivia_among = match (items.first(), items.last()) {
185	            (Some(f), Some(l)) => self.any_trivia(f.0, l.1),
186	            _ => false,
187	        };
188	        let _ = o;
189	        let mut entries: Vec<Entry<T>> = Vec::new();
190	        let mut prev = open;
191	        for (f, l, item) in items {
192	            let lead = self.trivia_range(prev, f);
193	            entries.push(Entry { lead, item });
194	            prev = Some(l);
195	        }
196	        let close = self.trivia_range(prev, close);
197	        Block { entries, close, any_trivia, any_comment, trivia_among }
198	    }
199	
200	    // ------------------------------------------------------------ document
201	    pub fn parse_doc(&mut self) -> R<Doc> {
202	        self.skip_newlines();
203	        let mut items: Vec<(usize, usize, Option<Stmt>)> = Vec::new();
204	        let mut sheet = None;
205	        if self.peek() == K::LBrace {
206	            let f = self.pos;
207	            let b = self.parse_sheet()?;
208	            sheet = Some(b);
209	            items.push((f, self.pos - 1, None));
210	        }
211	        loop {
212	            self.skip_newlines();
213	            if self.peek() == K::Eof {
214	                break;
215	            }
216	            if self.peek() == K::LBrace {
217	                return Err(Diag::error(
218	                    "stylesheet-after-canvas",
219	                    "the stylesheet '{ }' must come first, before any instance",
220	                    Span::new(self.tok().s, self.tok().e),
221	                ));
222	            }
223	            let f = self.pos;
224	            let st = self.parse_stmt(Ctx::Top)?;
225	            items.push((f, self.pos - 1, Some(st)));
226	            self.after_stmt()?;
227	        }
228	        let eof = self.pos;
229	        let blk = self.build_block(None, items, eof);
230	        let mut entries = blk.entries.into_iter();
231	        let mut sheet_lead = Vec::new();
232	        let mut stmts = Vec::new();
233	        if sheet.is_some() {
234	            let e = entries.next().unwrap();
235	            sheet_lead = e.lead;
236	        }
237	        for e in entries {
238	            stmts.push(Entry { lead: e.lead, item: e.item.unwrap() });
239	        }
240	        let stmts = Block {
241	            entries: stmts,
242	            close: blk.close,
243	            any_trivia: blk.any_trivia,
244	            any_comment: blk.any_comment,
245	            trivia_among: blk.trivia_among,
246	        };
247	        let types = resolve_types(&self.defines);
248	        Ok(Doc { sheet, sheet_lead, stmts, types })
249	    }
250	
251	    // separator after a statement: ';' (then more may follow on the line),
252	    // a newline, a closing bracket, or the end; bare strings share a line
253	    fn after_stmt(&mut self) -> R<()> {
254	        match self.peek() {
255	            K::Semi => {
256	                self.bump();
257	                Ok(())
258	            }
259	            K::Newline | K::Eof | K::RBrack | K::RBrace => Ok(()),
260	            K::Str => Ok(()),

