#!/usr/bin/env python3
# Look for panics/timeouts in MINE on random and pathological inputs (no comparison).
import subprocess, os, tempfile, random, sys
mine = sys.argv[1]; n = int(sys.argv[2])
d = tempfile.mkdtemp(dir='/tmp/fmt')
ALPH = '{}[]();:,.|#"-><&=*/+~^%!?\' \n\t\rabcxyz019_éo\\'
bad = 0
for i in range(n):
    r = random.Random(i)
    L = r.randint(0, 200)
    src = ''.join(r.choice(ALPH) for _ in range(L))
    p = os.path.join(d, 'in.lini'); open(p, 'w', encoding='utf-8').write(src)
    for args in (['fmt', '--stdout', 'in.lini'], ['in.lini']):
        try:
            res = subprocess.run([mine] + args, capture_output=True, cwd=d, timeout=10)
        except subprocess.TimeoutExpired:
            print('TIMEOUT', args, repr(src)); bad += 1; continue
        if res.returncode not in (0, 1, 2, 3):
            print('CRASH', res.returncode, args, repr(src), res.stderr[-300:]); bad += 1
print('problems:', bad)

