#!/usr/bin/env python3
# Differential test of declaration values.
import subprocess, os, tempfile, random, sys
mine = sys.argv[1]; n = int(sys.argv[2]); seed0 = int(sys.argv[3]) if len(sys.argv) > 3 else 0
d = tempfile.mkdtemp(dir='/tmp/fmt')
NUMS = ['0', '1', '-1', '+1', '1.50', '.5', '-.5', '007', '1e3', '2E2', '1.0', '100', '0.000001', '123456789012', '-0']
WORDS = ['red', 'auto', 'a-b', 'x_y', 'none', 'e', 'top', 'move', 'right']
def sp(r):
    return r.choice(['', ' ', '  '])
def term(r, depth, inargs):
    k = r.randint(0, 12)
    if k < 3: return r.choice(NUMS) + (r.choice(['%', '']) if r.random() < 0.2 else '')
    if k < 5: return r.choice(WORDS)
    if k == 5: return r.choice(['"s"', '" t "', '"a\\"b"', '"x\\ny"', '""'])
    if k == 6: return r.choice(['#fff', '#0a84ff', '#FFFF', '#12345678'])
    if k == 7: return r.choice(['--v', '--teal-ink'])
    if k == 8: return '(' + sp(r) + r.choice(['1+2', '1 + 2', 'a*b', 'x', '(y)', 'u * 300, 20 * sin(u)', '-1']) + sp(r) + ')'
    if k <= 11 and depth < 2:
        name = r.choice(['f', 'g', 'rgb', 'min', 'repeat', 'move', 'gradient', 'hatch'])
        args = []
        for _ in range(r.randint(0, 3)):
            if r.random() < 0.25:
                args.append(term(r, depth + 1, True) + r.choice([' + ', '*', ' - ', '-', ' / ']) + term(r, depth + 1, True))
            else:
                args.append(' '.join(term(r, depth + 1, True) for _ in range(r.randint(1, 2))))
        return name + '(' + sp(r) + (sp(r) + ',' + sp(r)).join(args) + sp(r) + ')'
    return r.choice(NUMS)
def value(r):
    groups = []
    for _ in range(r.randint(1, 3)):
        groups.append(r.choice([' ', '  ', '\n  ']).join(term(r, 0, False) for _ in range(r.randint(1, 3))))
    return (sp(r) + ',' + sp(r)).join(groups)
bad = []
for i in range(n):
    r = random.Random(seed0 + i)
    prop = r.choice(['fill', 'data', 'columns', 'draw', 'points', 'stroke'])
    v = value(r)
    end = r.choice([';', '', ';\n'])
    src = r.choice(['|box| { %s: %s%s }\n', '{\n  %s: %s%s\n}\n', '|table| { %s: %s%s } [ "a" "b" "c" "d" ]\n']) % (prop, v, end)
    p = os.path.join(d, 'in.lini'); open(p, 'w').write(src)
    outs = []
    for b in ('/workspace/executable', mine):
        res = subprocess.run([b, 'fmt', '--stdout', 'in.lini'], capture_output=True, cwd=d, timeout=10)
        outs.append((res.stdout, res.stderr, res.returncode))
    if outs[0] != outs[1]:
        bad.append((src, outs))
for src, outs in bad[:10]:
    print('====', src.strip())
    print('  orig:', outs[0][0] or outs[0][1])
    print('  mine:', outs[1][0] or outs[1][1])
print('mismatches %d / %d' % (len(bad), n))

