#!/usr/bin/env python3
# Differential test of link statements.
import subprocess, os, tempfile, random, sys
mine = sys.argv[1]; n = int(sys.argv[2]); seed0 = int(sys.argv[3]) if len(sys.argv) > 3 else 0
d = tempfile.mkdtemp(dir='/tmp/fmt')
OPS = ['->', '<-', '<->', '-', '--', '---', '-->', '<--', '~>', '<~', '~', '-o<', '>o-', '+-o<', '>o-o<', '-+', '+-+', '*-', '-*',
       '*-*', '>-', '-<', '||', '(-)', '(o)', '(<)', '++-', '-++', '-<>', '<>-']
def sp(r): return r.choice([' ', ' ', '  ', ''])
def endpoint(r, first):
    k = r.randint(0, 9)
    if k < 5:
        e = r.choice(['a', 'b', 'api', 'db', 'n1', 'x_y', 'k-2'])
        for _ in range(r.randint(0, 2)):
            e += '.' + r.choice(['c', 'port', 'in'])
        if r.random() < 0.15: e += '.' + r.choice(['1', '2', '02'])
        if r.random() < 0.3: e += r.choice([':', ': ', ' :', ' : ']) + r.choice(['top', 'left', 'right', 'bottom', 'west-in'])
        return e
    if k < 8:
        h = '|' + r.choice(['box', 'cyl', 'gnd', 'group#g', '#x', 'box#b2']) + '|'
        if r.random() < 0.3: h += '.' + r.choice(['child', 'a.b'])
        if r.random() < 0.2: h += ':' + r.choice(['left', 'top'])
        return h
    return r.choice(['a', 'b'])
def fan(r, first):
    eps = [endpoint(r, first)]
    for _ in range(0 if r.random() < 0.7 else r.randint(1, 2)):
        eps.append(endpoint(r, False))
    return (sp(r) + '&' + sp(r)).join(eps)
def text(r):
    s = r.choice(['"x"', '"label text"', '"é²"', '" pad "', '"a\\nb"'])
    if r.random() < 0.2: s += ' .' + r.choice(['hot', 'k'])
    if r.random() < 0.15: s += ' { translate: 0 -6; }'
    return s
def link(r):
    op = r.choice(OPS)
    s = fan(r, True) + sp(r) + op
    if r.random() < 0.9:
        s += sp(r) + fan(r, False)
        for _ in range(0 if r.random() < 0.8 else r.randint(1, 2)):
            s += ' ' + (op if r.random() < 0.8 else r.choice(OPS)) + ' ' + fan(r, False)
    if r.random() < 0.5: s += sp(r) + text(r).split(' .')[0].split(' {')[0]
    if r.random() < 0.2: s += sp(r) + '.' + r.choice(['hot', 'loud']) + (('.' + 'x') if r.random() < 0.3 else '')
    if r.random() < 0.3: s += ' { ' + r.choice(['stroke: red;', 'side: top', 'along: 0.3, 0.7; stroke: blue;', 'gap: -6']) + ' }'
    if r.random() < 0.25:
        items = [text(r) for _ in range(r.randint(1, 3))]
        if r.random() < 0.2: items.append('|box| "n"')
        s += ' [' + r.choice([' ', '\n  ']) + r.choice([' ', '\n  ']).join(items) + r.choice([' ', '\n']) + ']'
    if r.random() < 0.15: s += '  // c'
    return s
bad = []
for i in range(n):
    r = random.Random(seed0 + i)
    lines = []
    if r.random() < 0.3: lines.append('|box#a| "A"')
    for _ in range(r.randint(1, 4)):
        lines.append(link(r))
    if r.random() < 0.2: lines.insert(r.randrange(len(lines) + 1), '|group#g| [ |box#child| ]')
    src = '\n'.join(lines) + '\n'
    if r.random() < 0.2:
        src = '|group#w| [\n' + ''.join('  ' + l + '\n' for l in lines) + ']\n'
    p = os.path.join(d, 'in.lini'); open(p, 'w').write(src)
    outs = []
    for b in ('/workspace/executable', mine):
        res = subprocess.run([b, 'fmt', '--stdout', 'in.lini'], capture_output=True, cwd=d, timeout=10)
        outs.append((res.stdout, res.stderr, res.returncode))
    if outs[0] != outs[1]:
        bad.append((src, outs))
bad.sort(key=lambda x: len(x[0]))
for src, outs in bad[:10]:
    print('====', src.strip())
    print('  orig:', outs[0][0] or outs[0][1])
    print('  mine:', outs[1][0] or outs[1][1])
print('mismatches %d / %d' % (len(bad), n))

