#!/usr/bin/env python3
# Differential test of node children blocks (rows, inline lists, one-per-line), with trivia.
import subprocess, os, tempfile, random, sys
mine = sys.argv[1]; n = int(sys.argv[2]); seed0 = int(sys.argv[3]) if len(sys.argv) > 3 else 0
d = tempfile.mkdtemp(dir='/tmp/fmt')
STRS = ['"a"', '"bb"', '"Item"', '"USB cable"', '"é²"', '""', '" pad "', '"x\\ny"', '"q\\"q"', '"a longer label text"']
def cell(r):
    s = r.choice(STRS)
    if r.random() < 0.08: s += ' .' + r.choice(['k', 'hot.loud'])
    if r.random() < 0.06: s += ' { color: --red-ink; }'
    if r.random() < 0.02: s += ' { color: --red-ink; font-weight: bold; fill: --amber-wash; stroke: --amber-ink; }'
    return s
def block(r, indent):
    items = []
    k = r.randint(0, 3)
    for _ in range(r.randint(0, 10)):
        if r.random() < 0.08:
            items.append('|box| "n"' + (' [ "x" "y" ]' if r.random() < 0.3 else ''))
        else:
            items.append(cell(r))
    out = '['
    first = True
    for it in items:
        sep = r.choice([' ', ' ', ' ', '\n' + ' ' * (indent + 2), '\n\n' + ' ' * (indent + 2), '; ' if not first else ' '])
        if r.random() < 0.05: sep = '  // c\n' + ' ' * (indent + 2)
        if r.random() < 0.03: sep = '\n' + ' ' * (indent + 2) + '// own\n' + ' ' * (indent + 2)
        out += sep + it
        first = False
    out += r.choice([' ', '\n' + ' ' * indent, '\n\n' + ' ' * indent, '  // end\n' + ' ' * indent])
    out += ']'
    return out
def node(r):
    t = r.choice(['|entity|', '|table|', '|box|', '|row|', '|entity#e|', '|tt|', '|t2|'])
    s = t
    if r.random() < 0.4: s += ' ' + r.choice(STRS)
    if r.random() < 0.15: s += ' .c'
    if r.random() < 0.6:
        cols = r.choice(['1, 1', '80, 140, 80', 'repeat(3)', 'repeat(2) 1', 'auto', '3', '1 1 1 1', 'repeat( 4 )', 'repeat((2))'])
        extra = r.choice(['', ' fill: red;', ' align: start, center, end;', ' fill: --amber-wash; stroke: --amber-ink; color: --amber-ink;'])
        s += ' { columns: ' + cols + ';' + extra + ' }'
    elif r.random() < 0.1:
        s += ' { // c\n}'
    return s + ' ' + block(r, 0)
bad = []
for i in range(n):
    r = random.Random(seed0 + i)
    pre = ''
    if r.random() < 0.3:
        pre = '{\n  |tt::entity|\n  |t2::table|\n' + ('  |tt::box|\n' if r.random() < 0.2 else '') + '}\n'
    src = pre + '\n'.join(node(r) for _ in range(r.randint(1, 3))) + '\n'
    p = os.path.join(d, 'in.lini'); open(p, 'w').write(src)
    outs = []
    for b in ('/workspace/executable', mine):
        res = subprocess.run([b, 'fmt', '--stdout', 'in.lini'], capture_output=True, cwd=d, timeout=10)
        outs.append((res.stdout, res.stderr, res.returncode))
    if outs[0] != outs[1]:
        bad.append((src, outs))
bad.sort(key=lambda x: len(x[0]))
for src, outs in bad[:8]:
    print('====\n' + src.rstrip())
    print('--- orig:\n' + (outs[0][0] or outs[0][1]).decode())
    print('--- mine:\n' + (outs[1][0] or outs[1][1]).decode())
print('mismatches %d / %d' % (len(bad), n))

