166	pub fn measure_grid(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
167	    let c = ctx.comp[i].clone();
168	    let pad = c.padding;
169	    let _ = avail;
170	    let props = ctx.nodes[i].props.clone();
171	    let cols = props.get("columns").map(|v| parse_tracks(ctx, v)).unwrap_or_else(|| vec![Track::Auto]);
172	    let row_specs = props.get("rows").map(|v| parse_tracks(ctx, v)).unwrap_or_default();
173	    let ncols = cols.len().max(1);
174	    let children = ctx.nodes[i].children.clone();
175	    let mut flow = Vec::new();
176	    let mut pinned = Vec::new();
177	    for &ch in &children {
178	        if ctx.comp[ch].pin.is_some() {
179	            pinned.push(ch);
180	        } else {
181	            flow.push(ch);
182	        }
183	    }
184	    for &ch in &children {
185	        measure(ctx, ch, None);
186	    }
187	    // placement: (col, row, colspan, rowspan)
188	    let env = ctx.sheet.env.clone();
189	    let mut occupied: Vec<Vec<bool>> = Vec::new();
190	    let mut place: Vec<(usize, usize, usize, usize)> = Vec::new();
191	    let mut cur_r = 0usize;
192	    let mut cur_c = 0usize;
193	    let ensure = |occ: &mut Vec<Vec<bool>>, r: usize| {
194	        while occ.len() <= r {
195	            occ.push(vec![false; ncols]);
196	        }
197	    };
198	    for &ch in &flow {
199	        let p = &ctx.nodes[ch].props;
200	        let span: Vec<f64> = p.get("span").map(|v| crate::style::value_nums(&env, v)).unwrap_or_default();
201	        let cs = span.first().map(|x| *x as usize).unwrap_or(1).max(1).min(ncols);
202	        let rs = span.get(1).map(|x| *x as usize).unwrap_or(1).max(1);
203	        if let Some(cell) = p.get("cell").map(|v| crate::style::value_nums(&env, v)) {
204	            if cell.len() >= 2 {
205	                let cc = (cell[0] as usize).max(1) - 1;
206	                let rr = (cell[1] as usize).max(1) - 1;
207	                ensure(&mut occupied, rr + rs - 1);
208	                for r in rr..rr + rs {
209	                    for k in cc..(cc + cs).min(ncols) {
210	                        occupied[r][k] = true;
211	                    }
212	                }
213	                place.push((cc, rr, cs, rs));
214	                continue;
215	            }
216	        }
217	        loop {
218	            ensure(&mut occupied, cur_r + rs - 1);
219	            if cur_c + cs > ncols {
220	                cur_c = 0;
221	                cur_r += 1;
222	                continue;
223	            }
224	            let mut free = true;
225	            for r in cur_r..cur_r + rs {
226	                ensure(&mut occupied, r);
227	                for k in cur_c..cur_c + cs {
228	                    if occupied[r][k] {
229	                        free = false;
230	                    }
231	                }
232	            }
233	            if free {
234	                break;
235	            }
236	            cur_c += 1;
237	        }
238	        for r in cur_r..cur_r + rs {
239	            for k in cur_c..cur_c + cs {
240	                occupied[r][k] = true;
241	            }
242	        }
243	        place.push((cur_c, cur_r, cs, rs));
244	        cur_c += cs;
245	    }
246	    let nrows = occupied.len();
247	    let (gr, gc) = c.gap;
248	    let mut colw: Vec<f64> = vec![0.0; ncols];
249	    let mut rowh: Vec<f64> = vec![0.0; nrows];
250	    let col_fixed: Vec<Option<f64>> = (0..ncols).map(|k| match cols.get(k) { Some(Track::Fixed(x)) => Some(*x), _ => None }).collect();
251	    let row_fixed: Vec<Option<f64>> = (0..nrows).map(|k| match row_specs.get(k) { Some(Track::Fixed(x)) => Some(*x), _ => None }).collect();
252	    for k in 0..ncols {
253	        if let Some(x) = col_fixed[k] {
254	            colw[k] = x;
255	        }
256	    }
257	    for k in 0..nrows {
258	        if let Some(x) = row_fixed[k] {
259	            rowh[k] = x;
260	        }
261	    }
262	    let sizes: Vec<(f64, f64)> = flow.iter().map(|&ch| outer(ctx, ch)).collect();
263	    for (idx, &(cc, rr, cs, rs)) in place.iter().enumerate() {
264	        let (w, h) = sizes[idx];
265	        if cs == 1 && col_fixed[cc].is_none() {
266	            colw[cc] = colw[cc].max(w);
267	        }
268	        if rs == 1 && row_fixed[rr].is_none() {
269	            rowh[rr] = rowh[rr].max(h);
270	        }
271	    }
272	    for (idx, &(cc, rr, cs, rs)) in place.iter().enumerate() {
273	        let (w, h) = sizes[idx];
274	        if cs > 1 {
275	            let cur: f64 = colw[cc..cc + cs].iter().sum::<f64>() + gc * (cs as f64 - 1.0);
276	            if w > cur {
277	                let autos: Vec<usize> = (cc..cc + cs).filter(|k| col_fixed[*k].is_none()).collect();
278	                if !autos.is_empty() {
279	                    let extra = (w - cur) / autos.len() as f64;
280	                    for k in autos {
281	                        colw[k] += extra;
282	                    }
283	                }
284	            }
285	        }
286	        if rs > 1 {
287	            let cur: f64 = rowh[rr..rr + rs].iter().sum::<f64>() + gr * (rs as f64 - 1.0);
288	            if h > cur {
289	                let autos: Vec<usize> = (rr..rr + rs).filter(|k| row_fixed[*k].is_none()).collect();
290	                if !autos.is_empty() {
291	                    let extra = (h - cur) / autos.len() as f64;
292	                    for k in autos {
293	                        rowh[k] += extra;
294	                    }
295	                }
296	            }
297	        }
298	    }
299	    let cw: f64 = colw.iter().sum::<f64>() + gc * (ncols as f64 - 1.0).max(0.0);
300	    let chh: f64 = rowh.iter().sum::<f64>() + gr * (nrows as f64 - 1.0).max(0.0);
301	    let mut w = cw + pad[1] + pad[3];
302	    let mut h = chh + pad[0] + pad[2];
303	    if let Some(fw) = c.width {
304	        w = w.max(fw);
305	    }
306	    if let Some(fh) = c.height {
307	        h = h.max(fh);
308	    }
309	    ctx.nodes[i].w = w;
310	    ctx.nodes[i].h = h;
311	    let x0 = -w / 2.0 + pad[3] + (w - pad[1] - pad[3] - cw) / 2.0;
312	    let y0 = -h / 2.0 + pad[0] + (h - pad[0] - pad[2] - chh) / 2.0;
313	    let mut colx = vec![0.0; ncols];
314	    let mut acc = x0;
315	    for k in 0..ncols {
316	        colx[k] = acc;
317	        acc += colw[k] + gc;
318	    }
319	    let mut rowy = vec![0.0; nrows];
320	    let mut acc = y0;
321	    for k in 0..nrows {
322	        rowy[k] = acc;
323	        acc += rowh[k] + gr;
324	    }
325	    if ctx.nodes[i].props.contains_key("gap-fill") {
326	        let mut g = Vec::new();
327	        if gc > 0.0 {
328	            for k in 0..ncols.saturating_sub(1) {
329	                g.push((colx[k] + colw[k], -h / 2.0, gc, h));
330	            }
331	        }
332	        if gr > 0.0 {
333	            for k in 0..nrows.saturating_sub(1) {
334	                g.push((-w / 2.0, rowy[k] + rowh[k], w, gr));
335	            }
336	        }
337	        ctx.nodes[i].gutters = g;
338	    }
339	    for (idx, &ch) in flow.iter().enumerate() {
340	        let (cc, rr, cs, rs) = place[idx];
341	        let (ow, oh) = sizes[idx];
342	        let cx0 = colx[cc];
343	        let cwid: f64 = colw[cc..cc + cs].iter().sum::<f64>() + gc * (cs as f64 - 1.0);
344	        let ry0 = rowy[rr];
345	        let rhei: f64 = rowh[rr..(rr + rs).min(nrows)].iter().sum::<f64>() + gr * (rs as f64 - 1.0);
346	        let x = match c.align {
347	            Align::Start => cx0 + ow / 2.0,
348	            Align::End => cx0 + cwid - ow / 2.0,
349	            _ => cx0 + cwid / 2.0,
350	        };
351	        let y = match c.justify {
352	            Align::Start => ry0 + oh / 2.0,
353	            Align::End => ry0 + rhei - oh / 2.0,
354	            _ => ry0 + rhei / 2.0,
355	        };
356	        ctx.nodes[ch].x = x;
357	        ctx.nodes[ch].y = y;
358	    }
359	    for &p in &pinned {
360	        place_pinned(ctx, i, p);
361	    }
362	}
363	
364	pub fn measure_flow(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
365	    let c = ctx.comp[i].clone();
366	    let pad = c.padding;
367	    let mut inner_avail = avail.map(|a| a - pad[1] - pad[3]);
368	    if let Some(m) = c.max_width {
369	        let a = m - pad[1] - pad[3];
370	        inner_avail = Some(inner_avail.map_or(a, |x: f64| x.min(a)));
371	    }
372	    let children = ctx.nodes[i].children.clone();
373	    let mut flow = Vec::new();
374	    let mut pinned = Vec::new();
375	    for &ch in &children {
376	        if ctx.comp[ch].pin.is_some() {
377	            pinned.push(ch);
378	        } else {
379	            flow.push(ch);
380	        }
381	    }
382	    for &ch in &children {
383	        measure(ctx, ch, if ctx.comp[ch].pin.is_some() { None } else { inner_avail });
384	    }
385	    let sizes: Vec<(f64, f64)> = flow.iter().map(|&ch| outer(ctx, ch)).collect();
386	    let (gap_main, row) = match c.direction {
387	        Dir::Row => (c.gap.1, true),
388	        Dir::Column => (c.gap.0, false),
389	    };
390	    let n = sizes.len();
391	    let mut main: f64 = 0.0;
392	    let mut cross: f64 = 0.0;
393	    for &(w, h) in &sizes {
394	        if row {
395	            main += w;
396	            cross = cross.max(h);
397	        } else {
398	            main += h;
399	            cross = cross.max(w);
400	        }
401	    }
402	    if n > 1 {
403	        main += gap_main * (n as f64 - 1.0);
404	    }
405	    let (cw, ch) = if row { (main, cross) } else { (cross, main) };
406	    let mut w = cw + pad[1] + pad[3];
407	    let mut h = ch + pad[0] + pad[2];
408	    if let Some(fw) = c.width {
409	        w = w.max(fw);
410	    }
411	    if let Some(fh) = c.height {
412	        h = h.max(fh);
413	    }
414	    ctx.nodes[i].w = w;
415	    ctx.nodes[i].h = h;
416	    // place flow children
417	    let inner_l = -w / 2.0 + pad[3];
418	    let inner_t = -h / 2.0 + pad[0];
419	    let inner_w = w - pad[1] - pad[3];
420	    let inner_h = h - pad[0] - pad[2];
421	    let free = if row { inner_w - main } else { inner_h - main };
422	    let start = match c.justify {
423	        Align::Start | Align::Stretch => 0.0,
424	        Align::Center => free / 2.0,
425	        Align::End => free,
426	    };
427	    let mut cursor = start;
428	    for (k, &chi) in flow.iter().enumerate() {
429	        let (ow, oh) = sizes[k];
430	        if row {
431	            let x = inner_l + cursor + ow / 2.0;
432	            let y = match c.align {
433	                Align::Start => inner_t + oh / 2.0,
434	                Align::End => inner_t + inner_h - oh / 2.0,
435	                _ => inner_t + inner_h / 2.0,
436	            };
437	            ctx.nodes[chi].x = x;
438	            ctx.nodes[chi].y = y;
439	            cursor += ow + gap_main;
440	        } else {
441	            let y = inner_t + cursor + oh / 2.0;
442	            let x = match c.align {
443	                Align::Start => inner_l + ow / 2.0,
444	                Align::End => inner_l + inner_w - ow / 2.0,
445	                _ => inner_l + inner_w / 2.0,
446	            };
447	            ctx.nodes[chi].x = x;
448	            ctx.nodes[chi].y = y;
449	            cursor += oh + gap_main;
450	        }
451	    }
452	    if ctx.nodes[i].props.contains_key("gap-fill") && n > 1 && gap_main > 0.0 {
453	        let mut g = Vec::new();
454	        let mut cur = start;
455	        for k in 0..n - 1 {
456	            let (ow, oh) = sizes[k];
457	            cur += if row { ow } else { oh };
458	            if row {
459	                g.push((inner_l + cur, -h / 2.0, gap_main, h));
460	            } else {
461	                g.push((-w / 2.0, inner_t + cur, w, gap_main));
462	            }
463	            cur += gap_main;
464	        }
465	        ctx.nodes[i].gutters = g;
466	    }
467	    if ctx.nodes[i].prim == Prim::Cyl {
468	        let (_, oh) = outer(ctx, i);
469	        let dy = 0.03 * oh;
470	        for &chi in &flow {
471	            ctx.nodes[chi].y += dy;
472	        }
473	    }
474	    for &p in &pinned {
475	        place_pinned(ctx, i, p);
476	    }
477	}
478	
479	pub fn place_pinned(ctx: &mut Ctx, parent: usize, i: usize) {
480	    let pin = ctx.comp[i].pin.clone().unwrap_or_default();
481	    let pw = ctx.nodes[parent].w;
482	    let ph = ctx.nodes[parent].h;
483	    let (cw, chh) = outer(ctx, i);
484	    let words: Vec<&str> = pin.split_whitespace().collect();
485	    let mut x = 0.0;
486	    let mut y = 0.0;
487	    for w in &words {
488	        match *w {
489	            "top" => y = -ph / 2.0 + chh / 2.0,
490	            "bottom" => y = ph / 2.0 - chh / 2.0,
491	            "left" => x = -pw / 2.0 + cw / 2.0,
492	            "right" => x = pw / 2.0 - cw / 2.0,
493	            _ => {}
494	        }
495	    }
496	    ctx.nodes[i].x = x;
497	    ctx.nodes[i].y = y;
498	}
499	
500	pub fn eval_points(ctx: &Ctx, i: usize) -> Vec<(f64, f64)> {
501	    use crate::ast::Term;
502	    use crate::eval::EV;
503	    let env = &ctx.sheet.env;
504	    let v = match ctx.nodes[i].props.get("points") {
505	        Some(v) => v.clone(),
506	        None => return vec![],
507	    };
508	    let samples = ctx.nodes[i].props.get("samples").and_then(|s| crate::style::value_num(env, s)).unwrap_or(2.0).max(2.0) as usize;
509	    let mut pts = Vec::new();
510	    for g in &v.groups {
511	        let nums: Vec<f64> = g.iter().filter_map(|t| crate::style::term_num(env, t)).collect();
512	        if g.len() == 2 && nums.len() == 2 {
513	            pts.push((nums[0], nums[1]));
514	            continue;
515	        }
516	        if g.len() == 1 {
517	            // a parametric point: sample u over [0, 1]
518	            let t = &g[0];
519	            for k in 0..samples {
520	                let u = k as f64 / (samples as f64 - 1.0);
521	                let mut locals = std::collections::HashMap::new();
522	                locals.insert("u".to_string(), EV::Num(u));
523	                let r = match t {
524	                    Term::Group(e, _) => env.eval(e, &locals),
525	                    Term::Call(..) => env.eval_term(t, &locals),
526	                    _ => continue,
527	                };
528	                if let Ok(EV::Tuple(xs)) = r {
529	                    if xs.len() >= 2 {
530	                        pts.push((xs[0].num().unwrap_or(0.0), xs[1].num().unwrap_or(0.0)));
531	                    }
532	                }
533	            }
534	        }
535	    }
536	    pts
537	}
538	
539	pub fn measure_geo(ctx: &mut Ctx, i: usize) {
540	    use crate::geom::{path_bbox, BBox};
541	    use crate::scene::Geo;
542	    let prim = ctx.nodes[i].prim;
543	    let mut bb = BBox::empty();
544	    let geo = if prim == Prim::Path {
545	        let d = match ctx.nodes[i].props.get("path").and_then(crate::style::single_term) {
546	            Some(crate::ast::Term::Str(s, _)) => s.clone(),
547	            _ => String::new(),
548	        };
549	        bb = path_bbox(&d);
550	        Geo::Path(d)
551	    } else {
552	        let pts = eval_points(ctx, i);
553	        for &(x, y) in &pts {
554	            bb.add(x, y);
555	        }
556	        Geo::Points(pts)
557	    };
558	    let n = &mut ctx.nodes[i];
559	    n.w = bb.w();
560	    n.h = bb.h();
561	    n.geo_off = (-bb.cx(), -bb.cy());
562	    n.geo = Some(geo);
563	}
