281	pub fn root_decls_node(sheet: &SheetModel) -> Node {
282	    let mut n = Node::new(Prim::Block, vec![], Span::default());
283	    let defaults = parse_decls("layout: flow; padding: 20; gap: 36; font-size: 15;");
284	    let mut inline = defaults;
285	    for d in &sheet.root {
286	        if let Some(e) = inline.iter_mut().find(|e| e.name == d.name) {
287	            *e = d.clone();
288	        } else {
289	            inline.push(d.clone());
290	        }
291	    }
292	    n.inline = inline;
293	    n
294	}
