    Block,
    Oval,
    Hex,
    Slant,
    Cyl,
    Diamond,
    Poly,
    Path,
    Sketch,
    Line,
    Icon,
    Image,
    Text,
}

impl Prim {
    pub fn name(self) -> &'static str {
        match self {
            Prim::Block => "block",
            Prim::Oval => "oval",
            Prim::Hex => "hex",
            Prim::Slant => "slant",
            Prim::Cyl => "cyl",
            Prim::Diamond => "diamond",
            Prim::Poly => "poly",
            Prim::Path => "path",
            Prim::Sketch => "sketch",
            Prim::Line => "line",
            Prim::Icon => "icon",
            Prim::Image => "image",
            Prim::Text => "text",
        }
    }
}

pub struct TypeDef {
    pub name: &'static str,
    pub prim: Prim,
    pub base: Option<&'static str>,
    pub defaults: &'static str,
}

