435	fn node_classes(ctx: &Ctx, i: usize, out: &mut Out) -> String {
436	    let n = &ctx.nodes[i];
437	    let mut cls = vec!["lini-node".to_string()];
438	    for t in &n.chain {
439	        cls.push(format!("lini-{}", t));
440	        if !out.used_types.contains(t) {
441	            out.used_types.push(t.clone());
442	        }
443	    }
444	    for c in &n.classes {
445	        cls.push(format!("lini-style-{}", c));
446	        if !out.used_classes.contains(c) {
447	            out.used_classes.push(c.clone());
448	        }
449	    }
450	    cls.join(" ")
451	}
