import sys; sys.path.insert(0,'/tmp/scripts')
from ttf import TTF
fonts={w:TTF('/tmp/font_Lini_Sans_%d.ttf'%w) for w in (400,500,600,700)}
def tw(s,size=15,w=500):
    t=fonts[w]
    return sum(t.adv[t.cmap[ord(c)]] if ord(c) in t.cmap else 600 for c in s)*size/1000
if __name__=='__main__':
    for s in sys.argv[1:]: print(repr(s), tw(s))

// Phosphor icons. `|icon| { symbol: … }` paints like a node — `fill` is the body,
// `stroke` the line, `stroke-width` (default 2) counter-scaled to stay even at any
// size. `|sign|` is a larger preset and an ordinary wireable node. Source for
// assets/icons.png.
{
  direction: column; gap: 16; padding: 8 28 24 28; align: center; clearance: 14;
