// The scene: the stylesheet model plus the node tree built from statements.

use crate::ast::*;
use crate::diag::{Diag, Span};
use crate::eval::{Env, Func, EV};
use crate::types::{self, Prim};
use std::collections::HashMap;

#[derive(Clone, Debug)]
pub struct DefineModel {
    pub name: String,
    pub base: String,
    pub decls: Vec<Decl>,
    pub body: Option<Vec<Stmt>>,
    pub span: Span,
}

#[derive(Clone, Debug)]
pub struct ClassRule {
    pub name: String,
    pub decls: Vec<Decl>,
    pub span: Span,
    pub used: bool,
}

#[derive(Default)]
pub struct SheetModel {
    pub root: Vec<Decl>,
    pub vars: Vec<Decl>,
    pub env: Env,
    pub type_rules: Vec<(String, Vec<Decl>)>,
    pub defines: Vec<DefineModel>,
    pub classes: Vec<ClassRule>,
    pub id_rules: Vec<(String, Vec<Decl>)>,
    pub link_rules: Vec<Decl>,
    pub scoped_link_rules: Vec<(String, Vec<Decl>)>,
}

impl SheetModel {
    pub fn define(&self, name: &str) -> Option<&DefineModel> {
        self.defines.iter().find(|d| d.name == name)
    }
    pub fn type_rule(&self, name: &str) -> Vec<&Decl> {
        let mut out = Vec::new();
        for (n, ds) in &self.type_rules {
            if n == name {
                out.extend(ds.iter());
            }
        }
        out
    }
    pub fn class(&self, name: &str) -> Option<&ClassRule> {
        self.classes.iter().find(|c| c.name == name)
    }
}

#[derive(Clone, Debug)]
pub struct Node {
    pub prim: Prim,
    pub chain: Vec<String>, // most-derived first
    pub id: Option<String>,
    pub auto: bool,
    pub classes: Vec<String>,
    pub inline: Vec<Decl>,
    pub text: Option<String>,
    pub children: Vec<usize>,
    pub parent: Option<usize>,
    pub span: Span,
    pub props: HashMap<String, Value>,
    pub inline_props: HashMap<String, Value>,
    // layout results: rect size and centre relative to the parent's centre
    pub w: f64,
    pub h: f64,
    pub x: f64,
    pub y: f64,
    pub lines: Vec<String>,
    pub gutters: Vec<(f64, f64, f64, f64)>,
    pub scope: usize,
    pub geo: Option<Geo>,
    pub geo_off: (f64, f64),
}

#[derive(Clone, Debug)]
pub enum Geo {
    Points(Vec<(f64, f64)>),
    Path(String),
}

impl Node {
    pub fn new(prim: Prim, chain: Vec<String>, span: Span) -> Node {
        Node {
            prim,
            chain,
            id: None,
            auto: false,
            classes: vec![],
            inline: vec![],
            text: None,
            children: vec![],
            parent: None,
            span,
            props: HashMap::new(),
            inline_props: HashMap::new(),
            w: 0.0,
            h: 0.0,
            x: 0.0,
            y: 0.0,
            lines: vec![],
            gutters: vec![],
            scope: 0,
            geo: None,
            geo_off: (0.0, 0.0),
        }
    }
    pub fn is(&self, t: &str) -> bool {
        self.chain.iter().any(|c| c == t)
    }
}

#[derive(Clone, Debug)]
pub struct Link {
    pub from: usize,
    pub to: usize,
    pub op: String,
    pub label: Option<String>,
    pub labels: Vec<Stmt>,
    pub classes: Vec<String>,
    pub style: Vec<Decl>,
    pub from_anchor: Option<String>,
    pub to_anchor: Option<String>,
    pub from_index: Option<u32>,
    pub to_index: Option<u32>,
    pub span: Span,
    pub stmt_index: usize,
    // the container the statement was written in
    pub container: usize,
}

pub struct Scene {
    pub sheet: SheetModel,
    pub nodes: Vec<Node>,
    pub root: usize,
    pub links: Vec<Link>,
    pub warnings: Vec<Diag>,
}

pub fn decls_to_map(decls: &[Decl]) -> Vec<(String, Value)> {
    decls.iter().map(|d| (d.name.clone(), d.value.clone())).collect()
}

pub fn build_sheet(doc: &Doc) -> Result<SheetModel, Diag> {
    let mut m = SheetModel::default();
    if let Some(sheet) = &doc.sheet {
        for item in &sheet.items {
            match item {
                SheetItem::Decl(d) => m.root.push(d.clone()),
                SheetItem::Var(d) => m.vars.push(d.clone()),
                SheetItem::Binding(b) => {
                    if let Some(params) = &b.params {
                        m.env.funcs.insert(b.name.clone(), Func { params: params.clone(), body: b.expr.clone() });
                    } else {
                        let v = m.env.eval_term(&b.expr, &HashMap::new())?;
                        m.env.vars.insert(b.name.clone(), v);
                    }
                }
                SheetItem::Rule(r) => {
                    // classify selector
                    if r.selector.len() == 1 {
                        let c = &r.selector[0];
                        if c.bars && c.type_name.as_deref() == Some("-") && c.id.is_none() && c.classes.is_empty() {
                            m.link_rules.extend(r.decls.iter().cloned());
                            continue;
                        }
                        if c.bars && c.id.is_none() && c.classes.is_empty() {
                            if let Some(t) = &c.type_name {
                                m.type_rules.push((t.clone(), r.decls.clone()));
                                continue;
                            }
                        }
                        if !c.bars && c.id.is_none() && c.classes.len() == 1 {
                            m.classes.push(ClassRule { name: c.classes[0].clone(), decls: r.decls.clone(), span: r.span, used: false });
                            continue;
                        }
                        if c.id.is_some() && c.classes.is_empty() {
                            m.id_rules.push((c.id.clone().unwrap(), r.decls.clone()));
                            continue;
                        }
                    }
                    if r.selector.len() == 2 {
                        let a = &r.selector[0];
                        let b = &r.selector[1];
                        if a.id.is_some() && !a.bars && b.bars && b.type_name.as_deref() == Some("-") {
                            m.scoped_link_rules.push((a.id.clone().unwrap(), r.decls.clone()));
                            continue;
                        }
                    }
                }
                SheetItem::Define(d) => {
                    m.defines.push(DefineModel {
                        name: d.name.clone(),
                        base: d.base.clone(),
                        decls: d.decls.clone(),
                        body: d.body.clone(),
                        span: d.span,
                    });
                }
            }
        }
    }
    Ok(m)
}

// The type chain of a (possibly user-defined) type, most-derived first.
pub fn type_chain(sheet: &SheetModel, name: &str) -> Option<(Prim, Vec<String>)> {
    let mut chain = Vec::new();
    let mut cur = name.to_string();
    let mut guard = 0;
    loop {
        guard += 1;
        if guard > 50 {
            return None;
        }
        if let Some(d) = sheet.define(&cur) {
            chain.push(cur.clone());
            cur = d.base.clone();
            continue;
        }
        let t = types::find(&cur)?;
        if t.name == "text" {
            return None;
        }
        chain.push(cur.clone());
        match t.base {
            Some(b) => cur = b.to_string(),
            None => return Some((t.prim, chain)),
        }
    }
}

pub struct Builder<'a> {
    pub sheet: &'a SheetModel,
    pub src: &'a str,
    pub nodes: Vec<Node>,
    pub links: Vec<Link>,
    pub pending_links: Vec<(usize, LinkStmt, usize)>, // (container node, stmt, stmt index)
    pub warnings: Vec<Diag>,
    pub ids: HashMap<(usize, String), usize>,
    pub cap_counter: usize,
    pub stmt_counter: usize,
}

pub fn unknown_type(name: &str, span: Span) -> Diag {
    Diag::error("unknown-type", &format!("unknown type '{}'", name), span)
}

impl<'a> Builder<'a> {
    pub fn new(sheet: &'a SheetModel, src: &'a str) -> Self {
        Builder { sheet, src, nodes: vec![], links: vec![], pending_links: vec![], warnings: vec![], ids: HashMap::new(), cap_counter: 0, stmt_counter: 0 }
    }

    // The id scope children of `p` live in: `p` itself when it has an id, else p's scope.
    pub fn child_scope(&self, p: usize) -> usize {
        if p == 0 || self.nodes[p].id.is_some() {
            p
        } else {
            self.nodes[p].scope
        }
    }

    pub fn add(&mut self, mut n: Node, parent: Option<usize>) -> usize {
        n.parent = parent;
        if let Some(p) = parent {
            n.scope = self.child_scope(p);
        }
        let i = self.nodes.len();
        self.nodes.push(n);
        if let Some(p) = parent {
            self.nodes[p].children.push(i);
        }
        i
    }

    pub fn text_node(&mut self, text: &str, classes: &[String], style: Option<&Vec<Decl>>, span: Span, parent: usize) -> usize {
        let mut n = Node::new(Prim::Text, vec![], span);
        n.text = Some(text.to_string());
        n.classes = classes.to_vec();
        if let Some(s) = style {
            n.inline = s.clone();
        }
        self.add(n, Some(parent))
    }

    pub fn build_stmts(&mut self, stmts: &[Stmt], parent: usize) -> Result<(), Diag> {
        for s in stmts {
            match s {
                Stmt::Node(ns) => {
                    self.build_node(ns, parent)?;
                }
                Stmt::Text(t) => {
                    self.check_classes(&t.classes, t.span)?;
                    self.text_node(&t.text, &t.classes, t.style.as_ref(), t.span, parent);
                }
                Stmt::Link(l) => {
                    // capsule endpoints are declared in statement order
                    let idx = self.stmt_counter;
                    self.stmt_counter += 1;
                    let mut l2 = l.clone();
                    for g in l2.groups.iter_mut() {
                        for ep in g.iter_mut() {
                            if let Endpoint::Node(ns) = ep {
                                let id = match &ns.id {
                                    Some(id) => id.clone(),
                                    None => {
                                        self.cap_counter += 1;
                                        format!("lini-cap-{}", self.cap_counter)
                                    }
                                };
                                let mut ns2 = (**ns).clone();
                                ns2.id = Some(id.clone());
                                let ni = self.build_node(&ns2, parent)?;
                                if ns.id.is_none() {
                                    self.nodes[ni].auto = false;
                                }
                                *ep = Endpoint::Path(PathRef { parts: vec![id], index: None, anchor: None, span: ns.span });
                            }
                        }
                    }
                    self.pending_links.push((parent, l2, idx));
                }
            }
        }
        Ok(())
    }

    pub fn check_classes(&mut self, classes: &[String], span: Span) -> Result<(), Diag> {
        for c in classes {
            if self.sheet.class(c).is_none() {
                return Err(Diag::error("unknown-class", &format!("unknown class '.{}'", c), span));
            }
        }
        Ok(())
    }

    pub fn build_node(&mut self, ns: &NodeStmt, parent: usize) -> Result<usize, Diag> {
        let tname = match &ns.type_name {
            Some(t) => t.clone(),
            None => "box".to_string(),
        };
        if tname == "link" {
            return Err(Diag::error("resolve", "links are drawn by operators, not the '|link|' type", ns.head_span));
        }
        let (prim, chain) = match type_chain(self.sheet, &tname) {
            Some(x) => x,
            None => return Err(unknown_type(&tname, ns.span)),
        };
        self.check_classes(&ns.classes, ns.span)?;
        let mut n = Node::new(prim, chain.clone(), ns.span);
        n.id = ns.id.clone();
        n.classes = ns.classes.clone();
        if let Some(st) = &ns.style {
            n.inline = st.clone();
        }
        let scope = self.child_scope(parent);
        if let Some(id) = &ns.id {
            if let Some(&prev) = self.ids.get(&(scope, id.clone())) {
                let (pl, pc) = crate::diag::line_col(self.src, self.nodes[prev].span.start);
                return Err(Diag::error(
                    "duplicate-id",
                    &format!("duplicate id '{}' (previously at {}:{})", id, pl, pc),
                    ns.span,
                ));
            }
        }
        let i = self.add(n, Some(parent));
        if let Some(id) = &ns.id {
            self.ids.insert((scope, id.clone()), i);
        }
        // the label
        let is_group = chain.iter().any(|c| c == "group") && !chain.iter().any(|c| c == "table");
        if let Some((label, lspan)) = &ns.label {
            if is_group {
                let cchain = vec!["caption".to_string(), "block".to_string()];
                let mut cn = Node::new(Prim::Block, cchain, *lspan);
                cn.span = *lspan;
                let ci = self.add(cn, Some(i));
                self.text_node(label, &[], None, *lspan, ci);
            } else {
                match prim {
                    Prim::Block | Prim::Oval | Prim::Hex | Prim::Slant | Prim::Cyl | Prim::Diamond => {
                        self.text_node(label, &[], None, *lspan, i);
                    }
                    _ => {}
                }
            }
        }
        // a define's body is materialised per instance
        for t in chain.iter().rev() {
            if let Some(d) = self.sheet.define(t) {
                if let Some(body) = d.body.clone() {
                    self.build_stmts(&body, i)?;
                }
            }
        }
        if let Some(ch) = &ns.children {
            self.build_stmts(ch, i)?;
        }
        Ok(i)
    }
}

impl<'a> Builder<'a> {
    // Dotted id path of a node from the root ("g.c").
    pub fn path_of(&self, i: usize) -> String {
        let mut parts = Vec::new();
        let mut cur = i;
        loop {
            if let Some(id) = &self.nodes[cur].id {
                parts.push(id.clone());
            }
            if cur == 0 {
                break;
            }
            let sc = self.nodes[cur].scope;
            if sc == cur {
                break;
            }
            cur = sc;
        }
        parts.reverse();
        parts.join(".")
    }

    fn scope_name(&self, scope: usize) -> String {
        if scope == 0 {
            "scene root".to_string()
        } else {
            self.path_of(scope)
        }
    }

    pub fn lookup(&self, scope: usize, parts: &[String]) -> Option<usize> {
        let mut cur = scope;
        for p in parts {
            cur = *self.ids.get(&(cur, p.clone()))?;
        }
        Some(cur)
    }

    // First node with this id anywhere below `scope` (depth-first, document order).
    fn find_deep(&self, scope: usize, id: &str) -> Option<usize> {
        let mut stack: Vec<usize> = self.nodes[scope].children.iter().rev().cloned().collect();
        while let Some(n) = stack.pop() {
            if self.nodes[n].id.as_deref() == Some(id) && self.nodes[n].scope != scope {
                return Some(n);
            }
            for &c in self.nodes[n].children.iter().rev() {
                stack.push(c);
            }
        }
        None
    }

    // Resolve one endpoint, auto-creating a bare name as |box#name| "name".
    fn endpoint(&mut self, container: usize, p: &PathRef) -> Result<usize, Diag> {
        let scope = self.child_scope(container);
        if let Some(n) = self.lookup(scope, &p.parts) {
            return Ok(n);
        }
        if p.parts.len() > 1 {
            let msg = if scope == 0 {
                format!("link endpoint '{}' not found at scene root", p.parts.join("."))
            } else {
                format!("link endpoint '{}' not found in '{}'", p.parts.join("."), self.path_of(scope))
            };
            return Err(Diag::error("unknown-endpoint", &msg, p.span));
        }
        let name = p.parts[0].clone();
        if let Some(other) = self.find_deep(scope, &name) {
            let msg = format!(
                "endpoint '{}' auto-created at {} — a node '{}' also exists at '{}'",
                name,
                self.scope_name(scope),
                name,
                self.path_of(other)
            );
            self.warnings.push(Diag::warning("validate", &msg, p.span));
        }
        let chain = vec!["box".to_string(), "block".to_string()];
        let mut n = Node::new(Prim::Block, chain, p.span);
        n.id = Some(name.clone());
        n.auto = true;
        let i = self.add(n, Some(container));
        self.ids.insert((scope, name.clone()), i);
        self.text_node(&name, &[], None, p.span, i);
        Ok(i)
    }

    pub fn resolve_links(&mut self) -> Result<(), Diag> {
        let pending = std::mem::take(&mut self.pending_links);
        for (container, l, idx) in pending {
            for c in &l.classes {
                if self.sheet.class(c).is_none() {
                    return Err(Diag::error("unknown-class", &format!("unknown class '.{}'", c), l.span));
                }
            }
            let mut groups: Vec<Vec<(usize, Option<String>, Option<u32>)>> = Vec::new();
            for g in &l.groups {
                let mut v = Vec::new();
                for ep in g {
                    match ep {
                        Endpoint::Path(p) => {
                            let n = self.endpoint(container, p)?;
                            v.push((n, p.anchor.clone(), p.index));
                        }
                        Endpoint::Node(_) | Endpoint::Text(..) => {}
                    }
                }
                groups.push(v);
            }
            if groups.len() < 2 {
                return Err(Diag::error("chain-too-short", "link requires at least two endpoints", l.span));
            }
            for k in 0..groups.len() - 1 {
                let op = l.ops.get(k).map(|o| o.0.clone()).unwrap_or_default();
                for a in &groups[k] {
                    for b in &groups[k + 1] {
                        self.links.push(Link {
                            from: a.0,
                            to: b.0,
                            op: op.clone(),
                            label: l.label.as_ref().map(|x| x.0.clone()),
                            labels: l.labels.clone().unwrap_or_default(),
                            classes: l.classes.clone(),
                            style: l.style.clone().unwrap_or_default(),
                            from_anchor: a.1.clone(),
                            to_anchor: b.1.clone(),
                            from_index: a.2,
                            to_index: b.2,
                            span: l.span,
                            stmt_index: idx,
                            container,
                        });
                    }
                }
            }
        }
        Ok(())
    }
}

impl<'a> Builder<'a> {
    pub fn unworn_class_warnings(&mut self) {
        for c in &self.sheet.classes {
            let worn = self.nodes.iter().any(|n| n.classes.contains(&c.name)) || self.links.iter().any(|l| l.classes.contains(&c.name));
            if !worn {
                self.warnings.push(Diag::warning("class-never-worn", &format!("class '.{}' is never worn", c.name), c.span));
            }
        }
    }
}

// Lini's wordmark, built the way a CAD model of it is: one datum — the
// baseline, on the centreline through the `n` — and every station measured out
// from it, so each x in the file reads ± one named distance. Two dimensions
// drive the whole letterform and the other eighteen derive from them
// [SPEC 10.7]; the parts that are true reflections are drawn once and folded
// with `mirror: y-axis` [SPEC 15.3]; the dotted stem is one dash under a linear
// `pattern:` [SPEC 15.4]. Root `layout: stack` [SPEC 12] puts every pen on that
// one datum — the placement a drawing uses, without a drawing's drafting — and
// `unit: mm` + `density: 10` render the model's millimetres at 10 px each. The
// output is assets/logo/lini.svg.
{
  layout: stack; unit: mm; density: 10; padding: 25;

  --coral: #e9536c;
  --lilac: #9c8cee;

  |sketch| { fill: --coral; stroke: none; }

  // The two driving dimensions: half the stroke — which is every round end's
  // radius — and the centreline radius every hook and arch is swept on. From
  // them, the stroke itself (1.8, which is also the gap between letters) and
  // the inside (1.6) and outside (3.4) radius of a hook.
  cap = 0.9;
  bowl = 2.5;
  weight = (2 * cap);
  inner = (bowl - cap);
  outer = (bowl + cap);

  // x, measured out from the centreline and so worn ± by both sides: the `n`'s
  // legs stand at the bowl radius, the `l`'s tail and the `i`'s stem at 6.1,
  // both hooks' centres at 8.6, the `l`'s stem and the `i`'s dotted one at
  // 11.1, and the silhouette at 12 — half the wordmark wide.
  tail = (outer + weight + cap);
  hook = (tail + bowl);
  stem = (hook + bowl);
  edge = (stem + cap);

  // y, measured up from the baseline: the feet and the `i`'s tail end sit a cap
  // above it, the springing line every arch and hook rises from at 3.4, the
  // short caps at 5.9, the `n`'s crown at 6.8, the tall stem's 9.7 run to its
  // cap centre at 13.1, and the cap height at 14. A tittle's centre splits the
  // last two — 4.05 above, 4.05 below, the pair of equals the sketch carries.
  shoulder = outer;
  tail_y = (shoulder + bowl);
  arch = (shoulder + outer);
  run = (bowl + 8 * cap);
  crown = (shoulder + run);
  capline = (crown + cap);
  brow = ((capline + tail_y) / 2);

  // The dotted stem: a dash a third of the bowl long, at the pitch that makes
  // three of them span the tall stem's run exactly.
  dash = (bowl / 3);
  pitch = ((run - dash) / 2);

  // A tittle is a 2·cap dome, a cap-radius bite lifting it off the stem below,
  // and a cap/2 fillet blending the two on each side. All four tangent points
  // land on one line, `notch_y`, spaced a quarter chord apart — so those two
  // numbers place every one of them.
  quarter = (cap * sqrt(5) / 3);
  notch_y = (brow - 4 * cap / 3);
}

// The `n` — half a letter, crown of its arch round to crown of its bowl, both
// ends on the axis: an open subpath under `mirror:` is fused, so the half comes
// back whole. A drawing would mark that axis with a centreline; a stack draws
// only what is asked for. The pen opens on a two-point arc because a tangent
// one has no heading yet to continue.
|sketch#n| {
  draw: move(0, -arch) arc(outer, outer, outer) down(bowl) arc(cap, 180)
        up(bowl) arc(inner, -90);
  mirror: y-axis;
}

// The `l` — a stem the full height of the mark, a hook, a tail that stops short.
|sketch#l| {
  draw: move(-edge, -crown) down(run) arc(outer, -180) up(bowl) arc(cap, -180)
        down(bowl) arc(inner, 180) up(run) arc(cap, -180) close();
}

// The `i`'s tail — the `l`'s hook across the centreline, cut a quarter turn
// short so it ends in a round cap standing on the baseline.
|sketch#i| {
  draw: move(tail - cap, -tail_y) down(bowl) arc(outer, -90) arc(cap, -180)
        arc(inner, 90) up(bowl) arc(cap, -180) close();
}

// The two tittles — one drawn, both had: a closed subpath under `mirror:` is
// duplicated across the axis rather than fused. Bite, fillet, dome over the
// top, fillet back.
|sketch#brow| {
  draw: move(-tail - quarter, -notch_y) arc(2 * quarter, 0, cap)
        arc(quarter, 0, -cap / 2) arc(-2 * quarter, -10 * cap / 3, -2 * cap)
        arc(-2 * quarter, 10 * cap / 3, -2 * cap) arc(quarter, 0, -cap / 2)
        close();
  mirror: y-axis; fill: --lilac;
}

// The `i`'s stem, dotted — one dash, then three of it. It stands on the `l`'s
// stem station mirrored, and fills the same run.
|sketch#dots| {
  draw: move(stem - cap, -crown) down(dash) arc(cap, -180) up(dash)
        arc(cap, -180) close();
  pattern: grid(1, 3, 0, pitch); opacity: 0.75;
}
// The sketch pen [SPEC 15.3] as a specimen board — nine captioned tiles, one
// feature each. Corner modifiers (`chamfer` / `fillet`) and an even-odd
// `circle()` bore; `angle(deg, n)`'s bearing — 0 up, clockwise — walked round a
// hexagon in 60° steps, the sixth edge left to `close()`; the two-point
// `arc(dx, dy, r)` at its tightest legal radius, `r` exactly half the chord.
// Both readings of `mirror:`: an open subpath **fuses** end-to-end and generates
// its axis `|centerline|`, a closed one is **duplicated**. `pattern:`
// [SPEC 15.4] in both forms — `grid()` located by its first hole, `radial()` by
// the ring centre, which generates its `|pitch-circle|`. The line conventions
// [SPEC 15.7]: a dashed `|hidden|` cut, a manual `|centerline|` overhanging the
// profile, `stroke-style: phantom` for an alternate position. What repeats
// states once — `|view::drawing| { scale: 0.5 }` is the 1 : 2 ratio for all
// nine, `|arm::sketch|` the curve both positions wear — and `justify: end`
// bottoms every tile in its row, so the captions share a baseline. Lini's own
// wordmark drew this pen's first showcase; it lives in `logo.lini` now.
{
  layout: grid; columns: repeat(3); gap: 30 34; justify: end; padding: 30;

  |tile::column| { gap: 10; align: center; }
  |cap::block| { font-size: 12; color: --muted; }
  |view::drawing| { scale: 0.5; }
  |arm::sketch| {
    draw: move(-30, 8) right(16) curve(10, 0, 14, -14, 26, -16) right(18);
    fill: none;
  }
}

|tile| [
  |view| [
    |sketch#plate| {
      draw: move(0, 0) right(52) chamfer(9) down(30) left(52) fillet(9) close()
            move(26, 15) circle(7);
    }
  ]
  |cap| "chamfer · fillet · bore"
]

|tile| [
  |view| [
    |sketch#nut| {
      draw: move(-12, -20.78) angle(90, 24) angle(150, 24) angle(210, 24)
            angle(270, 24) angle(330, 24) close();
    }
  ]
  |cap| "angle — 0 up, clockwise"
]

|tile| [
  |view| [
    |sketch#slot| {
      draw: move(-16, -11) right(32) arc(0, 22, 11) left(32) arc(0, -22, 11)
            close();
    }
  ]
  |cap| "arc — the two-point form"
]

|tile| [
  |view| [
    // Draw the half, get the whole — and the axis centreline with it.
    |sketch#pin| {
      draw: move(-25, 0) up(9) right(20):collar down(4) right(30) down(5);
      mirror: x-axis;
    }
  ]
  |cap| "mirror — fused"
]

|tile| [
  |view| [
    // A closed subpath reflects as a second copy.
    |sketch#clip| {
      draw: move(-24, -10) right(16) down(20) left(16) close();
      mirror: y-axis;
    }
  ]
  |cap| "mirror — twinned"
]

|tile| [
  |view| [
    |sketch#strap| { draw: move(-30, -12) right(60) down(24) left(60) close(); } [
      |hole#bolt| { width: 8; translate: -21 0; pattern: grid(4, 1, 14, 0); }
    ]
  ]
  |cap| "pattern — grid"
]

|tile| [
  |view| [
    |sketch#flange| { draw: move(0, 0) circle(22) circle(7); } [
      |hole#bolt| { width: 6; pattern: radial(6, 14.5); }
    ]
  ]
  |cap| "pattern — radial"
]

|tile| [
  |view| [
    |sketch#body| { draw: move(-26, -14) right(52) down(28) left(52) close(); }
    |hidden#vee| { draw: move(-11, 14) line(11, -15) line(11, 15); }
    |centerline| { points: 0 -20, 0 20; }
  ]
  |cap| "hidden · centre line"
]

|tile| [
  |view| [
    |arm|
    |arm#raised| { translate: 0 -20; stroke-style: phantom; }
  ]
  |cap| "curve · alternate position"
]

1	// SVG serialisation: the stylesheet, defs, scene, and links.
2	
3	use crate::ast::{Term, Value};
4	use crate::compile::{get, Ctx};
5	use crate::diag::Diag;
6	use crate::style::*;
7	use crate::types::{self, Prim};
8	use crate::util::{f4, hash8, xml_escape};
9	
10	pub struct Out {
11	    pub body: String,
12	    pub vars: Vec<String>,
13	    pub used_types: Vec<String>,
14	    pub used_classes: Vec<String>,
15	    pub any_text: bool,
16	    pub defs: Vec<String>,
17	    pub markers: bool,
18	    pub gutters: bool,
19	    // extra stylesheet rules registered by families: (slot, rule text)
20	    pub extra_rules: Vec<(String, String)>,
21	}
22	
23	fn ind(n: usize) -> String {
24	    " ".repeat(n)
25	}
26	
27	// CSS declarations for one property list, in canonical order.
28	pub fn css_decls(
29	    ctx: &Ctx,
30	    props: &[(String, Value)],
31	    vars: &mut Vec<String>,
32	    stroke_width_ctx: f64,
33	    text: bool,
34	) -> Result<Vec<(String, String)>, Diag> {
35	    let env = &ctx.sheet.env;
36	    let mut out = Vec::new();
37	    for &k in CSS_ORDER {
38	        let v = match get(props, k) {
39	            Some(v) => v,
40	            None => continue,
41	        };
42	        let span = v.span;
43	        match k {
44	            "fill" | "stroke" => {
45	                if let Some(t) = single_term(v) {
46	                    out.push((k.to_string(), color_css(t, vars, span)?));
47	                }
48	            }
49	            "color" => {
50	                if let Some(t) = single_term(v) {
51	                    let name = if text { "fill" } else { "color" };
52	                    out.push((name.to_string(), color_css(t, vars, span)?));
53	                }
54	            }
55	            "stroke-width" | "opacity" => {
56	                if let Some(x) = value_num(env, v) {
57	                    out.push((k.to_string(), f4(x)));
58	                }
59	            }
60	            "font-family" => out.push((k.to_string(), font_family_css(v))),
61	            "font-size" => {
62	                if let Some(x) = value_num(env, v) {
63	                    out.push((k.to_string(), format!("{}px", f4(x))));
64	                }
65	            }
66	            "font-weight" => out.push((k.to_string(), weight_css(v, vars, span)?)),
67	            "font-style" | "text-decoration" => {
68	                if let Some(s) = ident_of(v) {
69	                    out.push((k.to_string(), s.to_string()));
70	                }
71	            }
72	            "text-shadow" => out.push((k.to_string(), text_shadow_css(env, v, vars, span)?)),
73	            "stroke-style" => {
74	                if let Some(s) = ident_of(v) {
75	                    let sw = get(props, "stroke-width").and_then(|w| value_num(env, w)).unwrap_or(stroke_width_ctx);
76	                    if let Some(d) = dasharray(s, sw) {
77	                        out.push(("stroke-dasharray".to_string(), d));
78	                    }
79	                }
80	            }
81	            _ => {}
82	        }
83	    }
84	    Ok(out)
85	}
86	
87	fn join_decls(d: &[(String, String)]) -> String {
88	    d.iter().map(|(k, v)| format!("{}: {}", k, v)).collect::<Vec<_>>().join("; ")
89	}
90	
91	fn font_scale_size(ctx: &Ctx, props: &[(String, Value)]) -> Option<f64> {
92	    let v = get(props, "font-scale")?;
93	    let xs = value_nums(&ctx.sheet.env, v);
94	    if xs.len() == 2 {
95	        Some(xs[0] * ctx.root_font_size / xs[1])
96	    } else {
97	        None
98	    }
99	}
100	
101	// The CSS rule body of one type, from its own defaults plus user rules.
102	fn type_rule_props(ctx: &Ctx, t: &str) -> Vec<(String, Value)> {
103	    let mut props: Vec<(String, Value)> = Vec::new();
104	    let mut set = |k: &str, v: &Value| {
105	        if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
106	            e.1 = v.clone();
107	        } else {
108	            props.push((k.to_string(), v.clone()));
109	        }
110	    };
111	    for d in type_defaults(t) {
112	        set(&d.name, &d.value);
113	    }
114	    if let Some(df) = ctx.sheet.define(t) {
115	        for d in &df.decls {
116	            set(&d.name, &d.value);
117	        }
118	    }
119	    for d in ctx.sheet.type_rule(t) {
120	        set(&d.name, &d.value);
121	    }
122	    props
123	}
124	
125	fn mk_value(t: Term) -> Value {
126	    let sp = t.span();
127	    Value { groups: vec![vec![t]], span: sp }
128	}
129	
130	pub fn render(ctx: &Ctx, opts: &crate::Options) -> Result<String, Diag> {
131	    let mut out = Out { body: String::new(), vars: vec![], used_types: vec![], used_classes: vec![], any_text: false, defs: vec![], markers: false, gutters: false, extra_rules: vec![] };
132	    let root = 0;
133	    // scene body
134	    let mut scene = String::new();
135	    let children = ctx.nodes[root].children.clone();
136	    let ordered = paint_order(ctx, &children);
137	    for ch in ordered {
138	        render_node(ctx, ch, 4, &mut scene, &mut out)?;
139	    }
140	    // stylesheet
141	    let theme = crate::theme::resolve(opts.theme.as_deref().unwrap_or("default")).unwrap();
142	    let mut slots: Vec<(String, String)> = Vec::new();
143	    let type_names: Vec<String> = out.used_types.clone();
144	    for t in &type_names {
145	        let mut props = type_rule_props(ctx, t);
146	        if let Some(sz) = font_scale_size(ctx, &props) {
147	            if get(&props, "font-size").is_none() {
148	                props.push(("font-size".into(), mk_value(Term::Num(sz, f4(sz), Default::default()))));
149	            }
150	        }
151	        let is_prim = types::find(t).map(|d| d.base.is_none()).unwrap_or(false);
152	        if is_prim && get(&props, "stroke-style").is_none() {
153	            props.push(("stroke-style".into(), mk_value(Term::Ident("solid".into(), Default::default()))));
154	        }
155	        let sw = get(&props, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(2.0);
156	        let decls = css_decls(ctx, &props, &mut out.vars, sw, false)?;
157	        if !decls.is_empty() {
158	            let slot = if types::find(t).is_some() {
159	                t.clone()
160	            } else {
161	                format!("@define:{:04}", ctx.sheet.defines.iter().position(|d| &d.name == t).unwrap_or(0))
162	            };
163	            slots.push((slot, format!(".lini-{} {{ {}; }}", t, join_decls(&decls))));
164	        }
165	    }
166	    if out.any_text {
167	        slots.push(("text".into(), ".lini-text { fill: currentColor; stroke: none; text-anchor: middle; }".to_string()));
168	    }
169	    if out.gutters {
170	        slots.push(("gutter".into(), ".lini-gutter { stroke: none; }".to_string()));
171	    }
172	    if out.markers {
173	        slots.push(("marker".into(), ".lini-marker { fill: var(--lini-stroke); stroke: none; }".to_string()));
174	        use_var(&mut out.vars, "stroke");
175	    }
176	    let canvas_fill = match ctx.sheet.root.iter().rev().find(|d| d.name == "fill") {
177	        Some(d) => match single_term(&d.value) {
178	            Some(t) => Some(color_css(t, &mut out.vars, d.value.span)?),
179	            None => None,
180	        },
181	        None => None,
182	    };
183	    if let Some(f) = &canvas_fill {
184	        slots.push(("canvas".into(), format!(".lini-canvas {{ fill: {}; }}", f)));
185	    }
186	    for (k, c) in ctx.sheet.classes.iter().enumerate() {
187	        if out.used_classes.contains(&c.name) {
188	            let props: Vec<(String, Value)> = c.decls.iter().map(|d| (d.name.clone(), d.value.clone())).collect();
189	            let decls = css_decls(ctx, &props, &mut out.vars, 2.0, false)?;
190	            if !decls.is_empty() {
191	                slots.push((format!("@class:{:04}", k), format!(".lini-style-{} {{ {}; }}", c.name, join_decls(&decls))));
192	            }
193	        }
194	    }
195	    for (slot, rule) in &out.extra_rules {
196	        slots.push((slot.clone(), rule.clone()));
197	    }
198	    slots.sort_by(|a, b| slot_rank(&a.0).cmp(&slot_rank(&b.0)));
199	    let mut rules: Vec<String> = Vec::new();
200	    for (_, r) in slots {
201	        if !rules.contains(&r) {
202	            rules.push(r);
203	        }
204	    }
205	    // root variables
206	    let mut vars = out.vars.clone();
207	    for v in ["fg", "font-family", "font-weight", "text-color"] {
208	        crate::style::use_var(&mut vars, v);
209	    }
210	    let mut decl_vars: Vec<(String, String)> = Vec::new();
211	    let mut k = 0;
212	    while k < vars.len() {
213	        let v = vars[k].clone();
214	        k += 1;
215	        let user = ctx.sheet.vars.iter().rev().find(|d| d.name == v);
216	        let val = if let Some(d) = user {
217	            let mut vv = Vec::new();
218	            let s = value_css_text(ctx, &d.value, &mut vv);
219	            for x in vv {
220	                if !vars.contains(&x) {
221	                    vars.push(x);
222	                }
223	            }
224	            Some(s)
225	        } else {
226	            theme.css_value(&v)
227	        };
228	        if let Some(val) = val {
229	            // nested var() references pull their targets in too
230	            let mut rest = val.as_str();
231	            while let Some(p) = rest.find("var(--lini-") {
232	                let after = &rest[p + 11..];
233	                let end = after.find(')').unwrap_or(after.len());
234	                let name = after[..end].to_string();
235	                if !vars.contains(&name) {
236	                    vars.push(name);
237	                }
238	                rest = &after[end..];
239	            }
240	            decl_vars.push((v, val));
241	        }
242	    }
243	    decl_vars.sort_by(|a, b| a.0.cmp(&b.0));
244	    let mut css = String::new();
245	    css.push_str("    @layer lini.defaults {\n");
246	    let mut root_line = String::from("      :root, .lini {");
247	    if theme.pair {
248	        root_line.push_str(" color-scheme: light dark;");
249	    }
250	    for (k, v) in &decl_vars {
251	        root_line.push_str(&format!(" --lini-{}: {};", k, v));
252	    }
253	    root_line.push_str(" }\n");
254	    css.push_str(&root_line);
255	    if theme.pair {
256	        css.push_str("      .lini[data-theme=\"dark\"], [data-theme=\"dark\"] .lini { color-scheme: dark; }\n");
257	        css.push_str("      .lini[data-theme=\"light\"], [data-theme=\"light\"] .lini { color-scheme: light; }\n");
258	    }
259	    css.push_str("    }\n");
260	    css.push_str("    .lini, .lini text { font-family: var(--lini-font-family); }\n");
261	    css.push_str(&format!(
262	        "    .lini {{ font-size: {}px; font-weight: var(--lini-font-weight); color: var(--lini-text-color); }}\n",
263	        f4(ctx.root_font_size)
264	    ));
265	    for r in &rules {
266	        css.push_str(&format!("    .lini {}\n", r));
267	    }
268	    let hash = hash8(&css);
269	    let scope = format!("lini-scope-{}", hash);
270	    let css_scoped = scope_css(&css, &scope);
271	    // the frame
272	    let (vx, vy, vw, vh) = viewbox(ctx);
273	    let mut s = String::new();
274	    s.push_str(&format!(
275	        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"{} {} {} {}\" width=\"{}\" height=\"{}\" class=\"lini {}\">\n",
276	        f4(vx),
277	        f4(vy),
278	        f4(vw),
279	        f4(vh),
280	        f4(vw),
281	        f4(vh),
282	        scope
283	    ));
284	    s.push_str("  <style>\n");
285	    s.push_str(&css_scoped);
286	    s.push_str("  </style>\n");
287	    if out.defs.is_empty() {
288	        s.push_str("  <defs/>\n");
289	    } else {
290	        s.push_str("  <defs>\n");
291	        for d in &out.defs {
292	            s.push_str(&format!("    {}\n", d));
293	        }
294	        s.push_str("  </defs>\n");
295	    }
296	    if canvas_fill.is_some() {
297	        s.push_str(&format!(
298	            "  <rect class=\"lini-canvas\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"/>\n",
299	            f4(vx),
300	            f4(vy),
301	            f4(vw),
302	            f4(vh)
303	        ));
304	    }
305	    s.push_str("  <g class=\"lini-scene\">\n");
306	    s.push_str(&scene);
307	    s.push_str("  </g>\n");
308	    s.push_str("  <g class=\"lini-links\"/>\n");
309	    s.push_str("</svg>\n");
310	    Ok(s)
311	}
