551	impl<'a> Builder<'a> {
552	    pub fn unworn_class_warnings(&mut self) {
553	        for c in &self.sheet.classes {
554	            let worn = self.nodes.iter().any(|n| n.classes.contains(&c.name)) || self.links.iter().any(|l| l.classes.contains(&c.name));
555	            if !worn {
556	                self.warnings.push(Diag::warning("class-never-worn", &format!("class '.{}' is never worn", c.name), c.span));
557	            }
558	        }
559	    }
