#!/usr/bin/env python3
# usage: r.py 'lini source' [-a args] [-f] [-s]  run original; print warnings + node transforms + links
import subprocess,sys,os,re,tempfile
src=sys.argv[1]
full='-f' in sys.argv
scene='-s' in sys.argv
bin_='/workspace/executable'
if '-m' in sys.argv: bin_='/tmp/bin-link/executable'
d=tempfile.mkdtemp(prefix='/tmp/link/rr.')
open(d+'/r_in.lini','w').write(src)
r=subprocess.run([bin_,'r_in.lini'],capture_output=True,cwd=d)
o=r.stdout.decode(); e=r.stderr.decode()
if e: print(e,end='')
if full: print(o); sys.exit()
lines=o.split('\n')
if lines and lines[0].startswith('<svg'):
    m=re.search(r'viewBox="([^"]*)"',lines[0]); print('viewBox',m.group(1) if m else '')
inl=False
for l in lines:
    if 'lini-links' in l: inl=True
    if scene and not inl and ('transform=' in l or '<rect' in l or '<ellipse' in l):
        print(l)
    if inl: print(l)
    if '.lini-link' in l or 'lini-marker' in l and l.strip().startswith('.') or 'lini-cut' in l and l.strip().startswith('.'):
        if not inl: print(l.strip())
print('[exit %d]'%r.returncode)

