            s.push_str(t);
        }
        if let Some(i) = &id {
            s.push('#');
            s.push_str(i);
        }
        s.push('|');
        Ok((s, ty))
    }

    fn parse_classes(&mut self) -> R<String> {
        let mut out = String::new();
