arguments.content:
import subprocess,sys,os,re,tempfile
# scan L-shape port position vs dy for clearances
def run(src):
    d=tempfile.mkdtemp(prefix='/tmp/link/rr.')
    open(d+'/r_in.lini','w').write(src)
    r=subprocess.run(['/workspace/executable','r_in.lini'],capture_output=True,cwd=d)
    return r.stdout.decode(), r.stderr.decode()
op=sys.argv[1] if len(sys.argv)>1 else '--'
for K in [int(x) for x in (sys.argv[2].split(',') if len(sys.argv)>2 else ['12','16','18','19','20','21','22','24'])]:
    res=[]
    for dy in range(30,62):
        o,e=run('{ clearance: %d }\n|box#a| "A"\n|box#b| "B" {translate: 0 %d}\na %s b'%(K,dy,op))
        p=re.findall(r'<path d="([^"]*)"',o)[0]
        t=p.split()
        if t[1]=='-17.43' and len([x for x in t if x=='A'])==1: res.append('%d:L%s'%(dy,t[2]))
