use crate::diag::{Diag, Span};
use crate::eval::Env;
use crate::scene::{Builder, Node};
use crate::types::Prim;

pub fn is_table(chain: &[String]) -> bool {
    chain.iter().any(|c| c == "table")
}

fn has(chain: &[String], t: &str) -> bool {
    chain.iter().any(|c| c == t)
}

