        Ok(l) => l,
        Err(_) => return vec![],
    };
    let mut p = crate::parser::Parser::new(&lexed.tokens, &full);
    match p.parse_style_block() {
        Ok((decls, _)) => decls
            .into_iter()
            .map(|mut d| {
                d.span = Span::default();
                d.name_span = Span::default();
                d.value.span = Span::default();
                d
            })
            .collect(),
        Err(_) => vec![],
    }
