    Some(match name {
        "a0" => (1189.0, 841.0),
        "a1" => (841.0, 594.0),
        "a2" => (594.0, 420.0),
        "a3" => (420.0, 297.0),
        "a4" => (210.0, 297.0),
        "a5" => (148.0, 210.0),
        "a" => (215.9, 279.4),
        "b" => (431.8, 279.4),
        "c" => (558.8, 431.8),
        "d" => (863.6, 558.8),
        "e" => (1117.6, 863.6),
        _ => return None,
    })
}

// Zones per edge: an even count of roughly 50 mm zones (round half down).
pub fn zone_count(len_mm: f64) -> usize {
    let n = (len_mm / 100.0 - 0.5).ceil();
    2 * (n.max(1.0) as usize)
}

fn idents(v: &Value) -> Vec<String> {
