#!/usr/bin/env python3
# Recover the exact f64 artwork bbox sizes: observe `fit: stretch` scales at several
# huge sizes and keep the float candidates that reproduce every printed value.
import subprocess, re, json, math
from concurrent.futures import ThreadPoolExecutor

ORIG = '/workspace/executable'
names = open('/tmp/icon/disc/valid.txt').read().split()
SIZES = ['1000000000000000', '1100000000000000', '1300000000000000', '1700000000000000', '1900000000000000', '2300000000000000', '700000000000000']

def run(src):
    r = subprocess.run([ORIG, '-'], input=src.encode(), capture_output=True)
    assert r.returncode == 0, r.stderr.decode()
    return r.stdout.decode()

def f4(v):
    s = '%.4f' % v
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    if s == '-0':
        s = '0'
    return s

def batch(args):
    S, chunk = args
    src = '{ direction: column; }\n' + '\n'.join('|icon#i%d| { symbol: "%s"; fit: stretch; width: %s; height: %s; }' % (k, n, S, S) for k, n in chunk)
    o = run(src)
    res = {}
    for m in re.finditer(r'data-id="i(\d+)"[^>]*>\n\s*<g transform="scale\(([^ )]*)(?: ([^)]*))?\)', o):
        k = int(m.group(1))
        res[names[k]] = (m.group(2), m.group(3) or m.group(2))
    return S, res

items = list(enumerate(names))
chunks = [items[i:i + 60] for i in range(0, len(items), 60)]
obs = {n: {} for n in names}
with ThreadPoolExecutor(16) as ex:
    for S, res in ex.map(batch, [(S, c) for S in SIZES for c in chunks]):
        for n, v in res.items():
            obs[n][S] = v

def neighbours(x, k):
    out = [x]
    a = b = x
    for _ in range(k):
        a = math.nextafter(a, -math.inf); b = math.nextafter(b, math.inf)
        out += [a, b]
    return out

result = {}
amb = 0
for n in names:
    dims = []
    for d in range(2):
        est = float(SIZES[0]) / float(obs[n][SIZES[0]][d])
        cands = []
        for b in neighbours(est, 64):
            if all(f4(float(S) / b) == obs[n][S][d] for S in SIZES):
                cands.append(b)
        if len(cands) != 1:
            amb += 1
            print('AMBIGUOUS', n, d, est, cands)
        dims.append(cands[0] if cands else est)
    result[n] = dims
json.dump(result, open('/tmp/icon/disc/exact.json', 'w'))
print('done, ambiguous:', amb)

