340	// coordinates) sits relative to its centre. Plain nodes are their own
341	// centre; the drawing family hooks in here once it lays views out.
342	pub fn origin_of(ctx: &Ctx, i: usize) -> (f64, f64) {
343	    let _ = (ctx, i);
344	    (0.0, 0.0)
345	}
346	
347	pub fn measure(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
348	    let (w_mm, h_mm) = page_size(&ctx.sheet, &ctx.nodes[i]);
349	    let k = ppu(&ctx.sheet);
350	    let (pw, ph) = (w_mm * k, h_mm * k);
351	    let user_dir = user_value(&ctx.sheet, &ctx.nodes[i], "direction").is_some();
352	    {
353	        let c = &mut ctx.comp[i];
354	        c.width = Some(pw);
355	        c.height = Some(ph);
356	        let inset = 15.0 * k;
357	        for p in c.padding.iter_mut() {
358	            *p += inset;
359	        }
360	        if !user_dir {
361	            c.direction = if w_mm > h_mm { Dir::Row } else { Dir::Column };
362	        }
363	    }
364	    scale_subtree(ctx, i, k);
365	    if ctx.comp[i].layout == "grid" {
366	        crate::layout::measure_grid(ctx, i, avail);
367	    } else {
368	        crate::layout::measure_flow(ctx, i, avail);
369	        // `align: origin`: the views' datums share the cross-axis centre line
370	        if ctx.nodes[i].props.get("align").and_then(crate::style::ident_of) == Some("origin") {
371	            let pad = ctx.comp[i].padding;
372	            let row = ctx.comp[i].direction == Dir::Row;
373	            for ch in ctx.nodes[i].children.clone() {
374	                if ctx.comp[ch].pin.is_some() {
375	                    continue;
376	                }
377	                let (ox, oy) = origin_of(ctx, ch);
378	                if row {
379	                    ctx.nodes[ch].y = (pad[0] - pad[2]) / 2.0 - oy;
380	                } else {
381	                    ctx.nodes[ch].x = (pad[3] - pad[1]) / 2.0 - ox;
382	                }
383	            }
384	        }
385	    }
386	    ctx.nodes[i].w = pw;
387	    ctx.nodes[i].h = ph;
388	    // the chrome
389	    let (hw, hh) = (pw / 2.0, ph / 2.0);
390	    let (fw, fh) = (hw - 10.0 * k, hh - 10.0 * k);
391	    let (nx, ny) = (zone_count(w_mm), zone_count(h_mm));
392	    let (zx, zy) = (pw / nx as f64, ph / ny as f64);
