fn inherited_scale(ctx: &Ctx, i: usize) -> f64 {
    let mut cur = Some(i);
    while let Some(k) = cur {
        if let Some(v) = ctx.nodes[k].props.get("scale") {
            if let Some(x) = value_num(&ctx.sheet.env, v) {
                return x;
            }
        }
        cur = ctx.nodes[k].parent;
    }
    1.0
}

