pub fn measure(ctx: &mut Ctx, i: usize, _avail: Option<f64>) {
    if ctx.sk.chrome.contains_key(&i) {
        return;
    }
    match frame_kind(ctx, i) {
        Some("drawing") => return measure_frame(ctx, i, true),
        Some(_) => return measure_frame(ctx, i, false),
        None => {}
