import random, os, sys
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 40
outdir = '/tmp/table/rnd'
os.makedirs(outdir, exist_ok=True)
words = ['a', 'Bb', 'Item', 'Qty', 'Price', '$9.50', 'Keyboard', 'x', 'long cell text', 'id', 'int', 'varchar', 'PK', 'FK', '', '12', 'fresh', 'Mango']

def cols():
    k = random.choice([1, 2, 2, 3, 3, 4])
    opts = []
    for _ in range(k):
        opts.append(random.choice(['auto', 'auto', '40', '60', '90', '24']))
    if random.random() < 0.15:
        return 'repeat(%d)' % k, k
    return ', '.join(opts), k

def kw_list(k, opts):
    n = random.choice([1, 1, 2, 3])
    return ', '.join(random.choice(opts) for _ in range(n))

def cell(k):
    r = random.random()
    w = random.choice(words)
    if r < 0.7:
        s = '"%s"' % w
        if random.random() < 0.1:
            s += ' { color: --red-ink; }'
        return s
    if r < 0.8:
        extra = []
        if random.random() < 0.4:
            extra.append('span: %d 1' % random.randint(1, k))
        if random.random() < 0.3:
            extra.append('align: %s' % random.choice(['start', 'end', 'center']))
        if random.random() < 0.3:
            extra.append('height: %d' % random.choice([30, 40]))
        if random.random() < 0.2:
            extra.append('cell: %d %d' % (random.randint(1, k), random.randint(1, 3)))
        st = (' { %s; }' % '; '.join(extra)) if extra else ''
        return '|cell| "%s"%s' % (w, st)
    if r < 0.88:
        return '|box| "%s"' % w
    return '""'

def table():
    kind = random.choice(['table', 'table', 'table', 'entity'])
    c, k = cols()
    props = []
    if kind == 'table' or random.random() < 0.5:
        props.append('columns: ' + c)
    else:
        k = 2
    if random.random() < 0.3:
        props.append('align: ' + kw_list(k, ['start', 'center', 'end']))
    if random.random() < 0.15:
        props.append('justify: ' + kw_list(k, ['start', 'center', 'end']))
    if random.random() < 0.15:
        props.append(random.choice(['stroke: --teal', 'fill: --sky-wash', 'font-size: 12', 'gap: 2', 'radius: 2', 'padding: 4']))
    label = ''
    if random.random() < 0.4:
        label = ' "%s"' % random.choice(['Users', 'Invoice', 'T'])
    n = random.randint(1, 3 * k + 2)
    body = '; '.join(cell(k) for _ in range(n))
    idp = '#t%d' % random.randint(1, 99)
    return '|%s%s|%s { %s; } [ %s ]' % (kind, idp, label, '; '.join(props), body)

for t in range(N):
    src = table()
    if random.random() < 0.3:
        src = '|row| { gap: 10; } [ %s\n%s ]' % (src, table())
    open(os.path.join(outdir, 'r%03d.lini' % t), 'w').write(src + '\n')

