fn seg_hits_box(a: (f64, f64), b: (f64, f64), bx: &[f64; 4]) -> bool {
    // Liang–Barsky clip of the segment against the box
    let (dx, dy) = (b.0 - a.0, b.1 - a.1);
    let mut t0 = 0.0f64;
    let mut t1 = 1.0f64;
    for (p, q) in [(-dx, a.0 - bx[0]), (dx, bx[2] - a.0), (-dy, a.1 - bx[1]), (dy, bx[3] - a.1)] {
        if p == 0.0 {
            if q < 0.0 {
                return false;
            }
        } else {
            let r = q / p;
            if p < 0.0 {
                if r > t1 {
                    return false;
                }
                if r > t0 {
                    t0 = r;
                }
            } else {
                if r < t0 {
                    return false;
                }
                if r < t1 {
                    t1 = r;
                }
            }
        }
    }
    t0 <= t1
}

fn place_label(l: &Lab, w: f64, geo: &Geo, c: f64, obstacles: &[Vec<(f64, f64)>], placed: &mut Vec<[f64; 4]>, always: bool) -> Option<(f64, f64)> {
    let h = FS;
    let d = l.r + c;
    let (x, y) = (l.x, l.y);
    let ax = d + w / 2.0;
    let ay = d + h / 2.0;
    let cands = [(x, y - ay), (x, y + ay), (x + ax, y), (x - ax, y), (x + ax, y - ay), (x + ax, y + ay), (x - ax, y - ay), (x - ax, y + ay)];
