        if ok {
            for p in placed.iter() {
                if bx[0] < p[2] && p[0] < bx[2] && bx[1] < p[3] && p[1] < bx[3] {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            placed.push(bx);
            return Some((cx, cy));
        }
    }
    if always {
        let (cx, cy) = cands[0];
        placed.push([cx - w / 2.0 - m, cy - h / 2.0 - m, cx + w / 2.0 + m, cy + h / 2.0 + m]);
