import random, os, sys
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 40
outdir = '/tmp/table/rnd2'
os.makedirs(outdir, exist_ok=True)
words = ['a', 'Bb', 'Item', 'Qty', 'Price', '$9.50', 'Keyboard', 'x', 'long cell text here', 'id', 'int', 'varchar', 'PK', 'FK', '12', 'fresh', 'Mango', 'Ünïcode', 'A & B', '<tag>']

def kw_list(opts):
    n = random.choice([1, 1, 2, 3])
    return ', '.join(random.choice(opts) for _ in range(n))

def cols():
    k = random.choice([1, 2, 2, 3, 3, 4])
    return ', '.join(random.choice(['auto', 'auto', '40', '60', '90', '24']) for _ in range(k)), k

def cell(k, depth):
    r = random.random()
    w = random.choice(words)
    if r < 0.55:
        s = '"%s"' % w
        x = random.random()
        if x < 0.08:
            s += ' { color: --red-ink; }'
        elif x < 0.12:
            s += ' { font-weight: bold; }'
        elif x < 0.15:
            s += ' .hot'
        return s
    if r < 0.7:
        extra = []
        if random.random() < 0.3:
            extra.append('span: %d %d' % (random.randint(1, k), random.choice([1, 1, 2])))
        if random.random() < 0.3:
            extra.append('align: %s' % random.choice(['start', 'end', 'center']))
        if random.random() < 0.2:
            extra.append('justify: %s' % random.choice(['start', 'end', 'center']))
        if random.random() < 0.2:
            extra.append('height: %d' % random.choice([30, 40]))
        if random.random() < 0.15:
            extra.append('width: %d' % random.choice([30, 70]))
        if random.random() < 0.1:
            extra.append('fill: --amber-wash')
        if random.random() < 0.1:
            extra.append('max-width: 60')
        st = (' { %s; }' % '; '.join(extra)) if extra else ''
        if random.random() < 0.2:
            return '|cell|%s [ "%s" "%s" ]' % (st, w, random.choice(words))
        return '|cell| "%s"%s' % (w, st)
    if r < 0.78:
        return '|box| "%s"' % w
    if r < 0.83 and depth == 0:
        return table(1)
    if r < 0.87:
        return '|badge| "n"'
    if r < 0.9:
        return '|cell| "%s" { pin: top right; }' % w
    return '""'

def table(depth=0):
    kind = random.choice(['table', 'table', 'table', 'entity'])
    c, k = cols()
    props = []
    if kind == 'table' or random.random() < 0.5:
        props.append('columns: ' + c)
    else:
        k = 2
    if random.random() < 0.3:
        props.append('align: ' + kw_list(['start', 'center', 'end']))
    if random.random() < 0.2:
        props.append('justify: ' + kw_list(['start', 'center', 'end']))
    if random.random() < 0.15:
        props.append('rows: ' + ', '.join(random.choice(['auto', '30', '50']) for _ in range(random.randint(1, 3))))
    if random.random() < 0.2:
        props.append(random.choice(['stroke: --teal', 'fill: --sky-wash', 'font-size: 12', 'gap: 2', 'radius: 2', 'padding: 4', 'width: 200', 'height: 120', 'gap: 0', 'stroke: none', 'font-weight: bold']))
    label = ''
    if random.random() < 0.4:
        label = ' "%s"' % random.choice(['Users', 'Invoice', 'T', 'A long caption title'])
    n = random.randint(1, 3 * k + 2)
    body = '; '.join(cell(k, depth) for _ in range(n))
    idp = '#t%d' % random.randint(1, 999)
    return '|%s%s|%s { %s; } [ %s ]' % (kind, idp, label, '; '.join(props), body)

for t in range(N):
    src = table()
    r = random.random()
    if r < 0.2:
        src = '|row| { gap: 10; align: %s; } [ %s\n%s ]' % (random.choice(['start', 'end', 'center']), src, table())
    elif r < 0.3:
        src = '|column| { gap: 10; } [ %s\n%s ]' % (src, table())
    elif r < 0.4:
        src = '|group| "G" [ %s ]' % src
    src = '{ .hot { color: --red; } }\n' + src + '\n|box#zz| "z" .hot'
    open(os.path.join(outdir, 'r%03d.lini' % t), 'w').write(src + '\n')

