python3 - <<'EOF'
p='/workspace/.claude/worktrees/agent-ad2150fa1d2782cee/src/route.rs'
s=open(p).read()
start=s.index('// Natural routing: an S-curve between the two port stubs.')
s=s[:start]+'''// Natural routing: an S-curve between two facing side centres (the
// dominant axis between the centres picks the sides).
pub fn natural(a: &Rect, b: &Rect, req: &LinkReq) -> (Vec<(f64, f64)>, [(f64, f64); 4], Side, Side) {
    let dx = b.cx() - a.cx();
    let dy = b.cy() - a.cy();
    let (sa, sb) = if dx.abs() >= dy.abs() {
        if dx >= 0.0 {
            (Side::Right, Side::Left)
        } else {
            (Side::Left, Side::Right)
        }
    } else if dy >= 0.0 {
        (Side::Bottom, Side::Top)
    } else {
        (Side::Top, Side::Bottom)
    };
    let s = side_point(a, sa, 0.0);
    let e = side_point(b, sb, 0.0);
    let ds = sa.dir();
    let de = sb.dir();
    let stub_s = if req.mark_len_s > 0.0 { req.mark_len_s } else { 2.0 };
    let stub_e = if req.mark_len_e > 0.0 { req.mark_len_e } else { 2.0 };
    let s1 = (s.0 + ds.0 * stub_s, s.1 + ds.1 * stub_s);
