FIELDS = ['title', 'drawing-number', 'revision', 'sheet-number', 'date', 'author', 'approved', 'department', 'document-type', 'reference', 'status']
VALS = ['Socket cap screw', 'DIN 912 — M8 × 40', 'A', '1/1', '2026-07-08', 'AM', 'RB', 'Engineering', 'Drawing', 'REF-001', 'Released', 'A much longer value for a field']

def child():
    r = random.random()
    if r < 0.35:
        props = []
        if random.random() < 0.3: props.append('width: %d' % random.choice([10, 20, 40]))
        if random.random() < 0.3: props.append('height: %d' % random.choice([10, 20, 40]))
        if random.random() < 0.2: props.append('translate: %d %d' % (random.choice([0, 5, -5]), random.choice([0, 5])))
        if random.random() < 0.1: props.append('pin: %s' % random.choice(['top left', 'bottom', 'right']))
        st = (' { %s; }' % '; '.join(props)) if props else ''
        return '|box| "%s"%s' % (random.choice(['a', 'Box', 'Part']), st)
    if r < 0.5:
        return '|table| "%s" { columns: auto, auto; } [ "#" "Part"; "1" "Bolt"; "2" "Nut" ]' % random.choice(['Parts', 'BOM'])
    if r < 0.6:
        return '|group| "G" [ |box| "in" ]'
    if r < 0.7:
        return '"plain text"'
    if r < 0.8:
        return '|entity#e%d| "E" [ "id" "int" ]' % random.randint(1, 99)
    return '|oval| { width: %d; height: %d; }' % (random.choice([10, 30]), random.choice([10, 30]))

def title_block():
    fields = random.sample(FIELDS, random.randint(1, 7))
    props = ['%s: "%s"' % (f, random.choice(VALS)) for f in fields]
    if random.random() < 0.15:
        props.append('columns: auto, auto')
    if random.random() < 0.1:
        props.append('translate: 5 5')
    return '|title-block| { %s; }' % '; '.join(props)

for t in range(N):
    props = []
    sheet = random.choice(['a3', 'a4', 'a5', 'a', 'b', 'a4 landscape', 'a5 landscape', 'a landscape', 'a3 portrait', None])
    if sheet:
        props.append('sheet: ' + sheet)
    if random.random() < 0.3: props.append('gap: %d' % random.choice([10, 20, 50]))
    if random.random() < 0.3: props.append('align: %s' % random.choice(['start', 'end', 'center', 'origin']))
    if random.random() < 0.3: props.append('justify: %s' % random.choice(['start', 'end', 'center']))
    if random.random() < 0.2: props.append('padding: %s' % random.choice(['0', '10', '5 20']))
    if random.random() < 0.15: props.append('direction: %s' % random.choice(['row', 'column']))
    if random.random() < 0.1: props.append('fill: --amber-wash')
    kids = [child() for _ in range(random.randint(0, 4))]
    if random.random() < 0.7:
        kids.insert(random.randint(0, len(kids)), title_block())
    label = (' "%s"' % 'Sheet') if random.random() < 0.15 else ''
    src = '|page|%s { %s; } [\n  %s\n]' % (label, '; '.join(props), '\n  '.join(kids))
    if random.random() < 0.2:
        src = '{ density: %s; }\n' % random.choice(['2', '3', '5']) + src
    open(os.path.join(outdir, 'r%03d.lini' % t), 'w').write(src + '\n')

