        Y=ys(pl,pr,pt,pb,lo,hi,vals,yv)
        m,h=tangents(X,Y,0)
        got=[(X[0],Y[0])]
        for k in range(n-1):
            x0,y0,x1,y1=X[k],Y[k],X[k+1],Y[k+1]; hh=x1-x0
            for j in range(1,17):
                if tmode==0: x=x0+hh*(j/16); t=(x-x0)/hh
                elif tmode==1: x=x0+(x1-x0)*j/16; t=(x-x0)/(x1-x0)
                elif tmode==2: x=x0+hh*j/16; t=(x-x0)/hh
                else: x=x0+hh*(j/16); t=j/16
                u=1-t
                if cv==0: c1=y0+m[k]*hh/3; c2=y1-m[k+1]*hh/3
                else: c1=y0+(hh/3)*m[k]; c2=y1-(hh/3)*m[k+1]
                if ev==0: y=u*u*u*y0+3*u*u*t*c1+3*u*t*t*c2+t*t*t*y1
                elif ev==1:
                    t2=t*t;t3=t2*t
                    y=(2*t3-3*t2+1)*y0+(t3-2*t2+t)*hh*m[k]+(-2*t3+3*t2)*y1+(t3-t2)*hh*m[k+1]
                elif ev==2:
                    a=y0+(c1-y0)*t; b=c1+(c2-c1)*t; c=c2+(y1-c2)*t; d=a+(b-a)*t; e=b+(c-b)*t; y=d+(e-d)*t
                else:
                    dy=y1-y0; a_=m[k]*hh; b_=m[k+1]*hh
                    y=y0+t*(a_+t*((3*dy-2*a_-b_)+t*(a_+b_-2*dy)))
                got.append((x,y))
        gs=['%s,%s'%(f4(x),f4(y)) for x,y in got]
        for i,(a,b) in enumerate(zip(gs,exp)):
            if a!=b: bad+=1; badlist.append((ci,i,a,b))
    return bad,badlist
