arguments.content:
// Schematics: components (pin rows and columns, stubs, numbers, value and
// reference labels), parts (drawn symbols with pin stations), net labels and
// symbols, and — inside a `layout: schematic` scope — the wires: chains pass
// through two-pin parts, text ends become net labels, and every part and
// label takes the pose the wiring gives it.

use super::lower::{err, Cx, R};
use super::out::{Item, OLink, ONode};
use super::sch_geo::{self, PartGeo};
use super::syntax::{Decl, Endpoint, Link, Node, Stmt};
use crate::diag::{Diag, Span};
use crate::format::parse::render_number;
use std::collections::HashMap;

// ------------------------------------------------------------------ poses
#[derive(Clone, Copy, Debug, PartialEq, Default)]
pub struct Pose {
    pub rot: u32,              // 0, 90, 180, 270 (clockwise)
    pub mirror: Option<char>, // 'x' (about the x-axis) or 'y'
}

impl Pose {
    pub fn is_zero(&self) -> bool {
        self.rot == 0 && self.mirror.is_none()
    }
    pub fn classes(&self) -> Vec<String> {
        let mut v = Vec::new();
        if self.rot != 0 {
            v.push(format!("lini-pose-{}", self.rot));
        }
        if let Some(m) = self.mirror {
            v.push(format!("lini-mirror-{}", m));
        }
        v
    }
    pub fn vertical(&self) -> bool {
        self.rot == 90 || self.rot == 270
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Dir {
    L,
    R,
    U,
    D,
}

impl Dir {
    pub fn opposite(self) -> Dir {
        match self {
            Dir::L => Dir::R,
            Dir::R => Dir::L,
            Dir::U => Dir::D,
            Dir::D => Dir::U,
        }
    }
    pub fn horizontal(self) -> bool {
        matches!(self, Dir::L | Dir::R)
    }
    fn of_side(s: &str) -> Option<Dir> {
        Some(match s {
            "left" => Dir::L,
            "right" => Dir::R,
            "top" => Dir::U,
            "bottom" => Dir::D,
            _ => return None,
        })
    }
    fn of_vec(dx: f64, dy: f64) -> Dir {
        if dx.abs() >= dy.abs() {
            if dx < 0.0 {
                Dir::L
            } else {
                Dir::R
            }
        } else if dy < 0.0 {
            Dir::U
        } else {
            Dir::D
        }
    }
}

fn num(v: f64) -> String {
    let r = (v * 10000.0).round() / 10000.0;
    let r = if r == 0.0 { 0.0 } else { r };
    render_number(r)
}

// a point of the symbol's frame (w x h) under the pose: mirror first, then
// the clockwise turn
fn map_pt(x: f64, y: f64, w: f64, h: f64, p: Pose) -> (f64, f64) {
    let (mut x, mut y) = (x, y);
    match p.mirror {
        Some('x') => y = h - y,
        Some('y') => x = w - x,
        _ => {}
    }
    match p.rot {
        90 => (h - y, x),
        180 => (w - x, h - y),
        270 => (y, w - x),
        _ => (x, y),
    }
}

pub fn map_vec(dx: f64, dy: f64, p: Pose) -> (f64, f64) {
    let (mut dx, mut dy) = (dx, dy);
    match p.mirror {
        Some('x') => dy = -dy,
        Some('y') => dx = -dx,
        _ => {}
    }
    match p.rot {
        90 => (-dy, dx),
        180 => (-dx, -dy),
        270 => (dy, -dx),
        _ => (dx, dy),
    }
}

// transform an SVG path ("M 0 0 M w h …" frame first)
pub fn map_path(path: &str, p: Pose) -> String {
    if p.is_zero() {
        return path.to_string();
    }
    let toks: Vec<&str> = path.split_whitespace().collect();
    // the frame: M 0 0 M w h
    let w: f64 = toks.get(4).and_then(|s| s.parse().ok()).unwrap_or(0.0);
    let h: f64 = toks.get(5).and_then(|s| s.parse().ok()).unwrap_or(0.0);
    let mut out: Vec<String> = Vec::new();
    let mut i = 0;
    let f = |s: &str| s.parse::<f64>().unwrap_or(0.0);
    while i < toks.len() {
        let t = toks[i];
        match t {
            "M" | "L" if i + 2 < toks.len() + 0 && i + 2 <= toks.len() - 1 => {
                let (x, y) = map_pt(f(toks[i + 1]), f(toks[i + 2]), w, h, p);
                out.push(t.to_string());
                out.push(num(x));
                out.push(num(y));
                i += 3;
            }
            "Q" if i + 4 < toks.len() => {
                let (x1, y1) = map_pt(f(toks[i + 1]), f(toks[i + 2]), w, h, p);
                let (x, y) = map_pt(f(toks[i + 3]), f(toks[i + 4]), w, h, p);
                out.push("Q".into());
                out.push(num(x1));
                out.push(num(y1));
                out.push(num(x));
                out.push(num(y));
                i += 5;
            }
            "A" if i + 7 < toks.len() => {
                let rx = toks[i + 1];
                let ry = toks[i + 2];
                let mut rot = f(toks[i + 3]);
                let large = toks[i + 4];
                let mut sweep = toks[i + 5].to_string();
                if p.mirror.is_some() {
                    rot = -rot;
                    sweep = if sweep == "1" { "0".into() } else { "1".into() };
                }
                rot += p.rot as f64;
                let rot = ((rot % 360.0) + 360.0) % 360.0;
                let (x, y) = map_pt(f(toks[i + 6]), f(toks[i + 7]), w, h, p);
                out.push("A".into());
                out.push(rx.to_string());
                out.push(ry.to_string());
                out.push(num(rot));
                out.push(large.to_string());
                out.push(sweep);
                out.push(num(x));
                out.push(num(y));
                i += 8;
            }
            _ => {
                out.push(t.to_string());
                i += 1;
            }
        }
    }
    out.join(" ")
}

fn own(n: &[Decl], name: &str) -> Option<String> {
    n.iter().rev().find(|d| d.name == name).and_then(|d| d.first().map(|s| s.to_string()))
}

// the pose written on a node (rotate:, mirror:), validated
pub fn written_pose(n: &Node) -> R<Pose> {
    let mut p = Pose::default();
    if let Some(r) = own(&n.style, "rotate") {
        p.rot = match r.as_str() {
            "0" => 0,
            "90" => 90,
            "180" => 180,
            "270" => 270,
            _ => return Err(err("a schematic part rotates in 90° steps — 0, 90, 180, or 270", n.span)),
        };
    }
    if let Some(m) = own(&n.style, "mirror") {
        p.mirror = match m.as_str() {
            "x-axis" => Some('x'),
            "y-axis" => Some('y'),
            "none" => None,
            _ => return Err(err("a schematic part mirrors about its own axis — x-axis, y-axis, or none", n.span)),
        };
    }
    Ok(p)
}

pub fn is_part(chain: &[String]) -> bool {
    chain.iter().any(|c| sch_geo::part_types().any(|t| t == c))
}

pub fn part_type(chain: &[String]) -> Option<String> {
    chain.iter().find(|c| sch_geo::part_types().any(|t| t == c.as_str())).cloned()
}

pub fn is_label(chain: &[String]) -> bool {
    chain.iter().any(|c| c == "label")
}

pub fn is_component(chain: &[String]) -> bool {
    chain.iter().any(|c| c == "component") && !is_part(chain)
}

// the prefix a reference designator counts with
fn prefix(cx: &Cx, n: &Node, chain: &[String]) -> String {
    if let Some(p) = n.style.iter().rev().find(|d| d.name == "prefix") {
        if let Some(s) = p.first().and_then(super::page::unquote) {
            return s;
        }
    }
    for t in chain {
        if let Some(d) = cx.define(t) {
            if let Some(p) = d.decls.iter().rev().find(|d| d.name == "prefix") {
                if let Some(s) = p.first().and_then(super::page::unquote) {
                    return s;
                }
            }
        }
        if let Some(td) = crate::types::find(t) {
            for d in Decl::list(td.defaults) {
                if d.name == "prefix" {
                    if let Some(s) = d.first().and_then(super::page::unquote) {
                        return s;
                    }
                }
            }
        }
        if sch_geo::part_types().any(|p| p == t.as_str()) && t != "opamp" {
            return t.clone();
        }
    }
    "U".to_string()
}

fn ref_text(cx: &mut Cx, n: &Node, chain: &[String]) -> String {
    match &n.id {
        Some(id) => id.clone(),
        None => {
            let p = prefix(cx, n, chain);
            let k = cx.sch_counter(&p);
            format!("{}{}", p, k)
        }
    }
}

fn block_with(cx: &mut Cx, ty: &str, decls: &str, text: Option<&str>) -> Item {
    let mut b = cx.typed(ty);
    b.decls = Decl::list(decls);
    if let Some(t) = text {
        b.children.push(Cx::text_item(t));
    }
    Item::Node(b)
}

// -------------------------------------------------------------- components
struct Slot {
    pin: Option<Node>, // None: a space
    space: Option<Node>,
    side: Option<String>, // explicit and valid
    generated: bool,
}

fn side_name(d: Dir) -> &'static str {
    match d {
        Dir::L => "left",
        Dir::R => "right",
        Dir::U => "top",
        Dir::D => "bottom",
    }
}

pub fn component(cx: &mut Cx, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    let pose = written_pose(n)?;
    o.classes.extend(pose.classes());
    let r = ref_text(cx, n, chain);
    o.decls.push(Decl::val("direction", "column"));
    o.decls.push(Decl::val("gap", "0"));
    // the pins: generated (a connector's `pins: N`) then the children
    let mut slots: Vec<Slot> = Vec::new();
    if chain.iter().any(|c| c == "J") {
        if let Some(k) = own(&n.style, "pins").and_then(|s| s.parse::<f64>().ok()) {
            for i in 1..=(k.max(0.0) as usize) {
                let pn = Node {
                    ty: Some("pin".into()),
                    id: Some(format!("p{}", i)),
                    label: None,
                    classes: vec![],
                    style: vec![Decl::val("number", &i.to_string()), Decl::val("side", "left")],
                    children: None,
                    span: n.span,
                    head_span: n.span,
                    ty_span: n.span,
                };
                slots.push(Slot { pin: Some(pn), space: None, side: Some("left".into()), generated: true });
            }
        }
    }
    let mut extra: Vec<&Stmt> = Vec::new();
    for s in n.children.as_deref().unwrap_or(&[]) {
        match s {
            Stmt::Node(c) if c.ty.as_deref() == Some("pin") => {
                let side = own(&c.style, "side").filter(|s| Dir::of_side(s).is_some());
                slots.push(Slot { pin: Some(c.clone()), space: None, side, generated: false });
            }
            Stmt::Node(c) if c.ty.as_deref() == Some("space") => {
                slots.push(Slot { pin: None, space: Some(c.clone()), side: None, generated: false });
            }
            other => extra.push(other),
        }
    }
    // auto pins split left / right, spaces ride with their pin
    let autos: Vec<usize> = (0..slots.len()).filter(|&i| slots[i].pin.is_some() && slots[i].side.is_none()).collect();
    let half = (autos.len() + 1) / 2;
    let mut sides: Vec<String> = vec![String::new(); slots.len()];
    for (k, &i) in autos.iter().enumerate() {
        sides[i] = if k < half { "left".into() } else { "right".into() };
    }
    for i in 0..slots.len() {
        if let Some(s) = &slots[i].side {
            sides[i] = s.clone();
        }
    }
    for i in 0..slots.len() {
        if slots[i].pin.is_none() {
            let prev = (0..i).rev().find(|&j| slots[j].pin.is_some()).map(|j| sides[j].clone());
            let next = (i + 1..slots.len()).find(|&j| slots[j].pin.is_some()).map(|j| sides[j].clone());
            sides[i] = prev.or(next).unwrap_or_else(|| "left".into());
        }
    }
    // group by side (left/right top→bottom, top/bottom left→right), then pose
    let mut by: HashMap<&str, Vec<usize>> = HashMap::new();
    for (i, s) in sides.iter().enumerate() {
        by.entry(match s.as_str() {
            "right" => "right",
            "top" => "top",
            "bottom" => "bottom",
            _ => "left",
        })
        .or_default()
        .push(i);
    }
    let get = |by: &HashMap<&str, Vec<usize>>, k: &str| by.get(k).cloned().unwrap_or_default();
    let (mut left, mut right, mut top, mut bottom) = (get(&by, "left"), get(&by, "right"), get(&by, "top"), get(&by, "bottom"));
    let rev = |v: &Vec<usize>| v.iter().rev().cloned().collect::<Vec<usize>>();
    match pose.mirror {
        Some('x') => {
            let (t, b) = (top.clone(), bottom.clone());
            top = b;
            bottom = t;
            left = rev(&left);
            right = rev(&right);
        }
        Some('y') => {
            let (l, r) = (left.clone(), right.clone());
            left = r;
            right = l;
            top = rev(&top);
            bottom = rev(&bottom);
        }
        _ => {}
    }
    for _ in 0..(pose.rot / 90) {
        let (l, r, t, b) = (left.clone(), right.clone(), top.clone(), bottom.clone());
        top = rev(&l);
        right = t;
        bottom = rev(&r);
        left = b;
    }
    let mut children: Vec<Item> = Vec::new();
    let mut lower_pins = |cx: &mut Cx, idx: &[usize], side: &str| -> R<Vec<Item>> {
        let mut v = Vec::new();
        for &i in idx {
            let s = &slots[i];
            if let Some(sp) = &s.space {
                let mut b = cx.typed("space");
                b.id = sp.id.clone();
                b.classes.extend(sp.classes.iter().cloned());
                b.decls = sp.style.clone();
                if let Some(k) = own(&sp.style, "span").and_then(|s| s.parse::<f64>().ok()) {
                    if k != 1.0 {
                        let along = if side == "left" || side == "right" { "height" } else { "width" };
                        b.decls.push(Decl::val(along, &num(20.0 * k)));
                    }
                }
                v.push(Item::Node(b));
                continue;
            }
            let pn = s.pin.as_ref().unwrap();
            v.push(pin_node(cx, pn, side, s.side.is_some() || s.generated)?);
        }
        Ok(v)
    };
    let slots_of = |idx: &[usize]| -> f64 {
        idx.iter()
            .map(|&i| match &slots[i].space {
                Some(sp) => own(&sp.style, "span").and_then(|s| s.parse::<f64>().ok()).unwrap_or(1.0),
                None => 1.0,
            })
            .sum()
    };
    let middle = !left.is_empty() || !right.is_empty();
    if !top.is_empty() {
        let even = slots_of(&top) % 2.0 == 0.0;
        let mut row = cx.typed("row");
        row.decls = Decl::list(&format!(
            "gap: 0; align: start;{} height: 20;",
            if even { " padding: 0 20 0 0;" } else { "" }
        ));
        row.children = lower_pins(cx, &top, "top")?;
        children.push(Item::Node(row));
    } else if middle && !bottom.is_empty() {
        let mut row = cx.typed("row");
        row.decls = Decl::list("height: 20;");
        children.push(Item::Node(row));
    }
    if middle {
        let mut cols = Vec::new();
        for (idx, side, align) in [(&left, "left", "start"), (&right, "right", "end")] {
            if idx.is_empty() {
                continue;
            }
            let even = slots_of(idx) % 2.0 == 0.0;
            let mut col = cx.typed("column");
            col.decls = Decl::list(&format!(
                "gap: 0; align: {};{}",
                align,
                if even { " padding: 0 0 20 0;" } else { "" }
            ));
            col.children = lower_pins(cx, idx, side)?;
            cols.push(Item::Node(col));
        }
        if cols.len() == 2 {
            let mut row = cx.typed("row");
            row.decls = Decl::list("gap: 24; align: center;");
            row.children = cols;
            children.push(Item::Node(row));
        } else {
            children.extend(cols);
        }
    }
    if !bottom.is_empty() {
        let even = slots_of(&bottom) % 2.0 == 0.0;
        let mut row = cx.typed("row");
        row.decls = Decl::list(&format!(
            "gap: 0; align: end;{} height: 20;",
            if even { " padding: 0 20 0 0;" } else { "" }
        ));
        row.children = lower_pins(cx, &bottom, "bottom")?;
        children.push(Item::Node(row));
    } else if middle && !top.is_empty() {
        let mut row = cx.typed("row");
        row.decls = Decl::list("height: 20;");
        children.push(Item::Node(row));
    }
    let lift = if top.is_empty() { 0.0 } else { 20.0 };
    if let Some(l) = n.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty()) {
        children.push(block_with(cx, "part-value", &format!("pin: top; translate: 0 {};", num(-20.0 - lift)), Some(&l)));
    }
    children.push(block_with(cx, "ref", &format!("pin: top; translate: 0 {};", num(-36.0 - lift)), Some(&r)));
    for s in extra {
        cx.stmts(std::slice::from_ref(s), &mut children)?;
    }
    o.children = children;
    Ok(o)
}

fn pin_node(cx: &mut Cx, pn: &Node, side: &str, rewrite: bool) -> R<Item> {
    let mut p = cx.typed("pin");
    p.id = pn.id.clone();
    p.classes.extend(pn.classes.iter().cloned());
    p.decls = pn.style.clone();
    if rewrite {
        for d in p.decls.iter_mut() {
            if d.name == "side" {
                *d = Decl::val("side", side);
            }
        }
    }
    let vertical = side == "top" || side == "bottom";
    if vertical {
        p.decls.push(Decl::val("width", "20"));
        p.decls.push(Decl::val("height", "auto"));
    }
    let label = pn.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty());
    if label.is_none() {
        if let Some(id) = &pn.id {
            p.children.push(Cx::text_item(id));
        }
    }
    let (stub, numpos) = match side {
        "right" => ("points: 0 0, 20 0; pin: right; translate: 28 0;", "pin: right; translate: 28 -9; width: 20;"),
        "top" => ("points: 0 0, 0 20; pin: top; translate: 0 -28;", "pin: top; translate: 9 -28; height: 20;"),
        "bottom" => ("points: 0 0, 0 20; pin: bottom; translate: 0 28;", "pin: bottom; translate: 9 28; height: 20;"),
        _ => ("points: 0 0, 20 0; pin: left; translate: -28 0;", "pin: left; translate: -28 -9; width: 20;"),
    };
    let mut st = cx.typed("pin-stub");
    st.decls = Decl::list(stub);
    p.children.push(Item::Node(st));
    if let Some(nm) = pn.style.iter().rev().find(|d| d.name == "number") {
        let t = nm.value_text();
        let t = super::page::unquote(&t).unwrap_or(t);
        p.children.push(block_with(cx, "pin-number", numpos, Some(&t)));
    }
    if let Some(l) = label {
        p.children.push(Cx::text_item(&l));
    }
    // a pin's own children follow
    if let Some(ch) = &pn.children {
        let mut v = Vec::new();
        cx.stmts(ch, &mut v)?;
        p.children.extend(v);
    }
    Ok(Item::Node(p))
}

// ------------------------------------------------------------------- parts
pub fn part_geo(n: &Node, ty: &str) -> R<&'static PartGeo> {
    let sym = own(&n.style, "symbol");
    if ty == "opamp" {
        return Ok(sch_geo::geo("opamp", None).unwrap());
    }
    match sym {
        None => Ok(sch_geo::geo(ty, None).unwrap()),
        Some(s) => match sch_geo::geo(ty, Some(&s)) {
            Some(g) => Ok(g),
            None => Err(err(
                &format!("unknown symbol '{}' on '|{}|' — its variants are {}", s, ty, sch_geo::variants(ty).join(", ")),
                n.span,
            )),
        },
    }
}

pub fn part(cx: &mut Cx, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    let ty = part_type(chain).unwrap();
    let g = part_geo(n, &ty)?;
    let mut pose = written_pose(n)?;
    if pose.is_zero() {
        if let Some(id) = &n.id {
            if let Some(p) = cx.sch_pose(id) {
                pose = p;
            }
        }
    }
    o.classes.extend(pose.classes());
    let r = ref_text(cx, n, chain);
    let mut children = Vec::new();
    let mut line = cx.typed("sch-line");
    line.decls = vec![Decl::new("path", &format!("\"{}\"", map_path(g.line, pose)))];
    children.push(Item::Node(line));
    if let Some(s) = g.solid {
        let mut solid = cx.typed("sch-solid");
        solid.decls = vec![Decl::new("path", &format!("\"{}\"", map_path(s, pose))), Decl::val("pin", "center")];
        children.push(Item::Node(solid));
    }
    let vertical = pose.vertical();
    if let Some(l) = n.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty()) {
        let d = if vertical { "pin: center; translate: 24 8;" } else { "pin: bottom; translate: 0 20;" };
        children.push(block_with(cx, "part-value", d, Some(&l)));
    }
    if n.id.is_some() {
        for (pin, dx, dy) in g.pins {
            let (x, y) = map_vec(*dx, *dy, pose);
            let mut b = cx.typed("block");
            b.id = Some(pin.to_string());
            b.decls = Decl::list(&format!("pin: center; translate: {} {};", num(x), num(y)));
            children.push(Item::Node(b));
        }
    }
    let d = if vertical { "pin: center; translate: 24 -8;" } else { "pin: top; translate: 0 -20;" };
    children.push(block_with(cx, "ref", d, Some(&r)));
    if let Some(ch) = &n.children {
        cx.stmts(ch, &mut children)?;
    }
    o.children = children;
    Ok(o)
}

// ------------------------------------------------------------------ labels
pub static SHAPES: &[&str] = &["plain", "left", "right", "both", "round"];

pub fn symbol_of(cx: &Cx, n: &Node, chain: &[String]) -> Option<String> {
    if let Some(s) = own(&n.style, "symbol") {
        return Some(s);
    }
    for t in chain {
        if let Some(d) = cx.define(t) {
            if let Some(s) = own(&d.decls, "symbol") {
                return Some(s);
            }
        }
        if let Some(td) = crate::types::find(t) {
            if let Some(s) = own(&Decl::list(td.defaults), "symbol") {
                return Some(s);
            }
        }
    }
    None
}

fn suggest(s: &str, options: &[&str]) -> Option<String> {
    let mut best: Option<(usize, &str)> = None;
    for o in options {
        let d = crate::util::levenshtein(s, o);
        if d <= 2 && best.map_or(true, |b| d < b.0) {
            best = Some((d, o));
        }
    }
    best.map(|b| b.1.to_string())
}

pub fn label(cx: &mut Cx, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    let mut pose = written_pose(n)?;
    let wired = n.id.as_ref().and_then(|id| cx.sch_pose(id));
    if pose.is_zero() {
        if let Some(p) = wired {
            pose = p;
        }
    }
    let sym = symbol_of(cx, n, chain);
    let shape = own(&n.style, "shape").unwrap_or_else(|| "plain".to_string());
    let mut lead: Vec<String> = Vec::new();
    let mut children = Vec::new();
    let label = n.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty());
    let bodies = cx.bodies(chain)?;
    match &sym {
        Some(s) => {
            let path = match sch_geo::SYMBOLS.iter().find(|(k, _)| k == s) {
                Some((_, p)) => *p,
                None => {
                    let names: Vec<&str> = sch_geo::SYMBOLS.iter().map(|(k, _)| *k).collect();
                    let msg = match suggest(s, &names) {
                        Some(h) => format!("unknown symbol '{}'; did you mean '{}'?", s, h),
                        None => format!("unknown symbol '{}'", s),
                    };
                    return Err(err(&msg, n.span));
                }
            };
            o.decls.insert(0, Decl::val("direction", "row"));
            let mut t = cx.typed("sch-tag-line");
            t.decls = vec![Decl::new("path", &format!("\"{}\"", map_path(path, pose)))];
            children.push(Item::Node(t));
        }
        None => {
            if !SHAPES.contains(&shape.as_str()) {
                return Err(err(&format!("'shape' takes plain, left, right, both, or round — not '{}'", shape), n.span));
            }
            match shape.as_str() {
                "left" | "right" | "both" => {
                    lead.push(format!("lini-tag-flag-{}", shape));
                    cx.mark(&format!("tag-flag-{}", shape));
                    let mut t = cx.typed("sch-tag-line");
                    t.decls = Decl::list(&format!("chrome: tag {}; pin: center; path: \"M 0 0\";", shape));
                    children.push(Item::Node(t));
                }
                "round" => {
                    lead.push("lini-tag-outline".into());
                    lead.push("lini-tag-round".into());
                    cx.mark("tag-outline");
                    cx.mark("tag-round");
                }
                _ => {
                    let turned = pose.vertical();
                    let c = if turned { "net-run-turned" } else { "net-run" };
                    lead.push(format!("lini-{}", c));
                    cx.mark(c);
                }
            }
        }
    }
    let mut classes = lead;
    classes.extend(o.classes.drain(..));
    classes.extend(pose.classes());
    o.classes = classes;
    children.extend(bodies);
    if let Some(l) = label {
        children.push(Cx::text_item(&l));
    }
    if let Some(ch) = &n.children {
        cx.stmts(ch, &mut children)?;
    }
    o.children = children;
    Ok(o)
}

// ------------------------------------------------------------------ wiring
#[derive(Clone, Debug, PartialEq)]
enum Kind {
    // a device: its pins' rest directions (after a written pose) and count
    Device { pins: Vec<(String, f64, f64)>, two_pin_part: bool, fixed_pose: bool, part: bool },
    Label { sym: Option<String> },
    Other,
}

#[derive(Clone, Debug)]
struct Elem {
    kind: Kind,
}

// one end of a wire
#[derive(Clone, Debug, PartialEq)]
enum Term {
    Pin(String, String),
    Label(String),
    Other(String),
}

impl Term {
    fn text(&self) -> String {
        match self {
            Term::Pin(d, p) => format!("{}.{}", d, p),
            Term::Label(l) | Term::Other(l) => l.clone(),
        }
    }
}

// a planned link statement: its hops, the labels it brings, the label nodes
#[derive(Clone, Debug, Default)]
pub struct Planned {
    pub hops: Vec<(String, String)>,
    // generated label nodes: (id, after the hops?), the statement that makes them
    pub before: Vec<Node>,
    pub after: Vec<Node>,
}

#[derive(Default, Debug)]
pub struct Plan {
    pub poses: HashMap<String, Pose>,
    pub links: Vec<Planned>, // by link statement order in the scope
    pub next: usize,
}

fn gnd_like(s: &Option<String>) -> bool {
    matches!(s.as_deref(), Some("gnd") | Some("earth") | Some("chassis"))
}
fn power_like(s: &Option<String>) -> bool {
    matches!(s.as_deref(), Some("power") | Some("antenna"))
}

impl<'a> Cx<'a> {
    pub fn sch_counter(&mut self, prefix: &str) -> usize {
        let key = (self.sch_scope_key(), prefix.to_string());
        let e = self.sch_counters.entry(key).or_insert(0);
        *e += 1;
        *e
    }

    fn sch_scope_key(&self) -> usize {
        // the nearest schematic scope frame (or the root)
        for (i, f) in self.stack.iter().enumerate().rev() {
            if f.sch.is_some() {
                return i + 1;
            }
        }
        0
    }

    pub fn sch_pose(&self, id: &str) -> Option<Pose> {
        let plan = match self.stack.iter().rev().skip(1).find_map(|f| f.sch.as_ref()) {
            Some(p) => p,
            None => self.root_sch.as_ref()?,
        };
        plan.poses.get(id).cloned()
    }

    fn elem_of(&self, n: &Node) -> Option<(String, Elem)> {
        let id = n.id.clone()?;
        let ty = n.ty.clone().unwrap_or_else(|| "box".into());
        let (_, chain) = self.chain(&ty)?;
        let kind = if is_part(&chain) {
            let pt = part_type(&chain).unwrap();
            let g = part_geo(n, &pt).ok()?;
            let pose = written_pose(n).unwrap_or_default();
            let pins: Vec<(String, f64, f64)> = g
                .pins
                .iter()
                .map(|(p, x, y)| {
                    let (a, b) = map_vec(*x, *y, pose);
                    (p.to_string(), a, b)
                })
                .collect();
            let two = g.pins.len() == 2;
            Kind::Device { pins, two_pin_part: two, fixed_pose: !pose.is_zero(), part: true }
        } else if is_component(&chain) {
            // pins after the pose, with their sides
            let pose = written_pose(n).unwrap_or_default();
            let mut pins = Vec::new();
            let mut list: Vec<(String, Option<String>)> = Vec::new();
            if chain.iter().any(|c| c == "J") {
                if let Some(k) = own(&n.style, "pins").and_then(|s| s.parse::<f64>().ok()) {
                    for i in 1..=(k.max(0.0) as usize) {
                        list.push((format!("p{}", i), Some("left".into())));
                    }
                }
            }
            for s in n.children.as_deref().unwrap_or(&[]) {
                if let Stmt::Node(c) = s {
                    if c.ty.as_deref() == Some("pin") {
                        if let Some(pid) = &c.id {
                            list.push((pid.clone(), own(&c.style, "side").filter(|s| Dir::of_side(s).is_some())));
                        }
                    }
                }
            }
            let autos = list.iter().filter(|(_, s)| s.is_none()).count();
            let half = (autos + 1) / 2;
            let mut k = 0;
            for (pid, side) in &list {
                let s = match side {
                    Some(s) => s.clone(),
                    None => {
                        k += 1;
                        if k <= half {
                            "left".into()
                        } else {
                            "right".into()
                        }
                    }
                };
                let (dx, dy) = match s.as_str() {
                    "left" => (-1.0, 0.0),
                    "right" => (1.0, 0.0),
                    "top" => (0.0, -1.0),
                    _ => (0.0, 1.0),
                };
                let (a, b) = map_vec(dx, dy, pose);
                pins.push((pid.clone(), a, b));
            }
            Kind::Device { pins, two_pin_part: false, fixed_pose: true, part: false }
        } else if is_label(&chain) {
            Kind::Label { sym: symbol_of(self, n, &chain) }
        } else {
            Kind::Other
        };
        Some((id, Elem { kind }))
    }

    // plan a schematic scope: the wires of its link statements and the poses
    pub fn sch_plan(&mut self, stmts: &[Stmt]) -> R<Plan> {
        let mut elems: HashMap<String, Elem> = HashMap::new();
        for s in stmts {
            if let Stmt::Node(n) = s {
                if let Some((id, e)) = self.elem_of(n) {
                    elems.insert(id, e);
                }
            }
        }
        let mut plan = Plan::default();
        let mut used: HashMap<String, Vec<String>> = HashMap::new();
        let mut caps = 0usize;
        let mut labels = 0usize;
        // every hop: (from, to)
        let mut hops: Vec<(Term, Term)> = Vec::new();
        let mut label_syms: HashMap<String, Option<String>> = HashMap::new();
        for (id, e) in &elems {
            if let Kind::Label { sym } = &e.kind {
                label_syms.insert(id.clone(), sym.clone());
            }
        }
        for s in stmts {
            let l = match s {
                Stmt::Link(l) => l,
                _ => continue,
            };
            let mut planned = Planned::default();
            self.sch_link(l, &elems, &mut used, &mut caps, &mut labels, &mut planned, &mut hops, &mut label_syms)?;
            plan.links.push(planned);
        }
        // poses: walk from anchors
        let mut poses: HashMap<String, Pose> = HashMap::new();
        solve(&elems, &hops, &label_syms, &mut poses);
        plan.poses = poses;
        Ok(plan)
    }

    #[allow(clippy::too_many_arguments)]
    fn sch_link(
        &mut self,
        l: &Link,
        elems: &HashMap<String, Elem>,
        used: &mut HashMap<String, Vec<String>>,
        caps: &mut usize,
        labels: &mut usize,
        planned: &mut Planned,
        hops: &mut Vec<(Term, Term)>,
        label_syms: &mut HashMap<String, Option<String>>,
    ) -> R<()> {
        for op in &l.ops {
            if op != "-" && !(l.groups.len() == 1 && (op == "->" || op == "-<")) {
                return Err(err("a schematic wire is plain — markers shape a text label's tag; write 'a -> \"NET\"'", l.span));
            }
        }
        // the elements of the chain: (entry term, exit term)
        let n = l.groups.len();
        let mut seq: Vec<(Term, Term)> = Vec::new();
        for (gi, g) in l.groups.iter().enumerate() {
            let ep = match g.first() {
                Some(e) => e,
                None => continue,
            };
            let middle = gi > 0 && gi + 1 < n;
            match ep {
                Endpoint::Path { parts, text, span } => {
                    let name = &parts[0];
                    let pin_named = parts.len() > 1;
                    match elems.get(name).map(|e| &e.kind) {
                        Some(Kind::Device { pins, two_pin_part, .. }) => {
                            if pin_named {
                                let p = parts[1].clone();
                                if middle && *two_pin_part {
                                    let other = pins.iter().find(|(q, _, _)| *q != p).map(|x| x.0.clone()).unwrap_or_default();
                                    used.entry(name.clone()).or_default().push(p.clone());
                                    used.entry(name.clone()).or_default().push(other.clone());
                                    seq.push((Term::Pin(name.clone(), p), Term::Pin(name.clone(), other)));
                                } else {
                                    used.entry(name.clone()).or_default().push(p.clone());
                                    let t = Term::Pin(name.clone(), p);
                                    seq.push((t.clone(), t));
                                }
                            } else if *two_pin_part {
                                let u = used.entry(name.clone()).or_default();
                                let free: Vec<String> =
                                    pins.iter().map(|x| x.0.clone()).filter(|p| !u.contains(p)).collect();
                                if middle {
                                    let a = free.first().cloned().unwrap_or_else(|| pins[0].0.clone());
                                    let b = pins.iter().map(|x| x.0.clone()).find(|p| *p != a).unwrap_or_default();
                                    u.push(a.clone());
                                    u.push(b.clone());
                                    seq.push((Term::Pin(name.clone(), a), Term::Pin(name.clone(), b)));
                                } else {
                                    let a = match free.first() {
                                        Some(a) => a.clone(),
                                        None => {
                                            return Err(err(
                                                &format!(
                                                    "both pins of '{}' are wired — name one ('{}.{}')",
                                                    name, name, pins[0].0
                                                ),
                                                *span,
                                            ))
                                        }
                                    };
                                    u.push(a.clone());
                                    let t = Term::Pin(name.clone(), a);
                                    seq.push((t.clone(), t));
                                }
                            } else {
                                let t = Term::Other(text.clone());
                                seq.push((t.clone(), t));
                            }
                        }
                        Some(Kind::Label { .. }) if !pin_named => {
                            let t = Term::Label(name.clone());
                            seq.push((t.clone(), t));
                        }
                        Some(_) => {
                            let t = Term::Other(text.clone());
                            seq.push((t.clone(), t));
                        }
                        None => {
                            if !pin_named {
                                return Err(err(
                                    &format!(
                                        "'{}' is unknown — a schematic never invents a box; did you mean '- \"{}\"' (a net label)?",
                                        name, name
                                    ),
                                    *span,
                                ));
                            }
                            let t = Term::Other(text.clone());
                            seq.push((t.clone(), t));
                        }
                    }
                }
                Endpoint::Capsule { node, tail } => {
                    let id = match &node.id {
                        Some(id) => id.clone(),
                        None => {
                            *caps += 1;
                            format!("lini-cap-{}", caps)
                        }
                    };
                    let mut nn = node.clone();
                    nn.id = Some(id.clone());
                    let ty = nn.ty.clone().unwrap_or_else(|| "box".into());
                    let chain = self.chain(&ty).map(|c| c.1).unwrap_or_default();
                    let t = if is_label(&chain) {
                        label_syms.insert(id.clone(), symbol_of(self, &nn, &chain));
                        Term::Label(id.clone())
                    } else {
                        Term::Other(format!("{}{}", id, tail))
                    };
                    if gi == 0 {
                        planned.before.push(nn);
                    } else {
                        planned.after.push(nn);
                    }
                    seq.push((t.clone(), t));
                }
                Endpoint::Text(_) => {}
            }
        }
        // a one-ended wire to text: a net label
        if l.groups.len() == 1 {
            if let Some(text) = &l.label {
                *labels += 1;
                let id = format!("lini-label-{}", labels);
                let shape = match l.ops.first().map(|s| s.as_str()) {
                    Some("->") => Some("right"),
                    Some("-<") => Some("left"),
                    _ => None,
                };
                let mut style = Vec::new();
                if let Some(s) = shape {
                    style.push(Decl::val("shape", s));
                }
                let nn = Node {
                    ty: Some("label".into()),
                    id: Some(id.clone()),
                    label: Some(text.clone()),
                    classes: vec![],
                    style,
                    children: None,
                    span: l.span,
                    head_span: l.span,
                    ty_span: l.span,
                };
                label_syms.insert(id.clone(), None);
                planned.after.push(nn);
                let t = Term::Label(id);
                seq.push((t.clone(), t));
            }
        }
        for w in seq.windows(2) {
            let a = &w[0].1;
            let b = &w[1].0;
            planned.hops.push((a.text(), b.text()));
            hops.push((a.clone(), b.clone()));
        }
        // the internal hop of a pass-through part
        for (a, b) in &seq {
            if a != b {
                hops.push((Term::Other(String::from("\u{0}through")), Term::Other(String::new())));
                hops.pop();
                let _ = (a, b);
            }
        }
        let _ = Diag::error;
        let _ = Span::default;
        Ok(())
    }
}

// ------------------------------------------------------------- the solver
fn pin_dir(elems: &HashMap<String, Elem>, poses: &HashMap<String, Pose>, dev: &str, pin: &str) -> Option<Dir> {
    if let Some(Elem { kind: Kind::Device { pins, part, .. } }) = elems.get(dev) {
        let (_, x, y) = pins.iter().find(|p| p.0 == pin)?;
        let (x, y) = match (part, poses.get(dev)) {
            (true, Some(p)) => map_vec(*x, *y, *p),
            _ => (*x, *y),
        };
        return Some(Dir::of_vec(x, y));
    }
    None
}

fn is_anchor(elems: &HashMap<String, Elem>, dev: &str) -> bool {
    matches!(elems.get(dev), Some(Elem { kind: Kind::Device { pins, .. } }) if pins.len() >= 3)
}

// the pose turning a two-pin part so its pin `entry` faces `toward`
fn pose_for(elems: &HashMap<String, Elem>, dev: &str, entry: &str, toward: Dir) -> Pose {
    if let Some(Elem { kind: Kind::Device { pins, .. } }) = elems.get(dev) {
        if let Some((_, x, y)) = pins.iter().find(|p| p.0 == entry) {
            for rot in [0, 90, 180, 270] {
                let p = Pose { rot, mirror: None };
                let (a, b) = map_vec(*x, *y, p);
                if Dir::of_vec(a, b) == toward {
                    return p;
                }
            }
        }
    }
    Pose::default()
}

fn label_pose(sym: &Option<String>, d: Dir) -> Pose {
    let rot = match sym.as_deref() {
        Some("gnd") | Some("earth") | Some("chassis") => {
            if d == Dir::U {
                180
            } else {
                0
            }
        }
        Some("power") | Some("antenna") => {
            if d == Dir::D {
                180
            } else {
                0
            }
        }
        Some("nc") => {
            if d == Dir::L {
                180
            } else {
                0
            }
        }
        Some(_) => 0,
        None => match d {
            Dir::L => 0,
            Dir::R => 180,
            Dir::U => 90,
            Dir::D => 270,
        },
    };
    Pose { rot, mirror: None }
}

fn other_pin(elems: &HashMap<String, Elem>, dev: &str, pin: &str) -> Option<String> {
    if let Some(Elem { kind: Kind::Device { pins, two_pin_part: true, .. } }) = elems.get(dev) {
        return pins.iter().find(|p| p.0 != pin).map(|p| p.0.clone());
    }
    None
}

fn solve(elems: &HashMap<String, Elem>, hops: &[(Term, Term)], syms: &HashMap<String, Option<String>>, poses: &mut HashMap<String, Pose>) {
    // neighbours of a term along the wires
    let neighbours = |t: &Term| -> Vec<Term> {
        let mut v = Vec::new();
        for (a, b) in hops {
            if a == t {
                v.push(b.clone());
            } else if b == t {
                v.push(a.clone());
            }
        }
        v
    };
    // where a path from `t` (entering a part at `t`) ends: the symbol of the
    // label it reaches through free two-pin parts
    let end_sym = |start: &Term, from: &Term, poses: &HashMap<String, Pose>| -> Option<Option<String>> {
        let mut cur = start.clone();
        let mut prev = from.clone();
        for _ in 0..64 {
            match &cur {
                Term::Pin(d, p) => {
                    let fixed = matches!(elems.get(d), Some(Elem { kind: Kind::Device { fixed_pose: true, .. } }));
                    let o = other_pin(elems, d, p)?;
                    if fixed || poses.contains_key(d.as_str()) && false {
                        return None;
                    }
                    let exit = Term::Pin(d.clone(), o);
                    let next: Vec<Term> = neighbours(&exit).into_iter().filter(|t| *t != prev).collect();
                    let n = next.first()?.clone();
                    prev = exit;
                    cur = n;
                }
                Term::Label(l) => return Some(syms.get(l).cloned().unwrap_or(None)),
                Term::Other(_) => return None,
            }
        }
        None
    };
    let mut done_labels: Vec<String> = Vec::new();
    let mut visited_parts: Vec<String> = Vec::new();
    // walk from a term leaving in direction `d`
    fn walk(
        elems: &HashMap<String, Elem>,
        syms: &HashMap<String, Option<String>>,
        poses: &mut HashMap<String, Pose>,
        from: &Term,
        d: Dir,
        neighbours: &dyn Fn(&Term) -> Vec<Term>,
        end_sym: &dyn Fn(&Term, &Term, &HashMap<String, Pose>) -> Option<Option<String>>,
        visited_parts: &mut Vec<String>,
        done_labels: &mut Vec<String>,
        depth: usize,
    ) {
        if depth > 200 {
            return;
        }
        for t in neighbours(from) {
            match &t {
                Term::Pin(dev, pin) => {
                    if is_anchor(elems, dev) || visited_parts.contains(dev) {
                        continue;
                    }
                    let two = matches!(elems.get(dev), Some(Elem { kind: Kind::Device { two_pin_part: true, .. } }));
                    if !two {
                        continue;
                    }
                    visited_parts.push(dev.clone());
                    let fixed = matches!(elems.get(dev), Some(Elem { kind: Kind::Device { fixed_pose: true, .. } }));
                    if !fixed {
                        let mut want = d.opposite();
                        if d.horizontal() {
                            match end_sym(&t, from, poses) {
                                Some(s) if gnd_like(&s) => want = Dir::U,
                                Some(s) if power_like(&s) => want = Dir::D,
                                _ => {}
                            }
                        }
                        let p = pose_for(elems, dev, pin, want);
                        poses.insert(dev.clone(), p);
                    }
                    if let Some(o) = other_pin(elems, dev, pin) {
                        if let Some(nd) = pin_dir(elems, poses, dev, &o) {
                            let exit = Term::Pin(dev.clone(), o);
                            walk(elems, syms, poses, &exit, nd, neighbours, end_sym, visited_parts, done_labels, depth + 1);
                        }
                    }
                }
                Term::Label(l) => {
                    let sym = syms.get(l).cloned().unwrap_or(None);
                    poses.insert(l.clone(), label_pose(&sym, d));
                    if !done_labels.contains(l) {
                        done_labels.push(l.clone());
                        walk(elems, syms, poses, &t, d, neighbours, end_sym, visited_parts, done_labels, depth + 1);
                    }
                }
                Term::Other(_) => {}
            }
        }
    }
    // anchors in wire order
    let mut starts: Vec<(Term, Dir)> = Vec::new();
    for (a, b) in hops {
        for t in [a, b] {
            if let Term::Pin(dev, pin) = t {
                if is_anchor(elems, dev) {
                    if let Some(d) = pin_dir(elems, poses, dev, pin) {
                        if !starts.iter().any(|s| s.0 == *t) {
                            starts.push((t.clone(), d));
                        }
                    }
                }
            }
        }
    }
    for (t, d) in starts {
        walk(elems, syms, poses, &t, d, &neighbours, &end_sym, &mut visited_parts, &mut done_labels, 0);
    }
}

raw_arguments.content:
// Schematics: components (pin rows and columns, stubs, numbers, value and
// reference labels), parts (drawn symbols with pin stations), net labels and
// symbols, and — inside a `layout: schematic` scope — the wires: chains pass
// through two-pin parts, text ends become net labels, and every part and
// label takes the pose the wiring gives it.

use super::lower::{err, Cx, R};
use super::out::{Item, OLink, ONode};
use super::sch_geo::{self, PartGeo};
use super::syntax::{Decl, Endpoint, Link, Node, Stmt};
use crate::diag::{Diag, Span};
use crate::format::parse::render_number;
use std::collections::HashMap;

// ------------------------------------------------------------------ poses
#[derive(Clone, Copy, Debug, PartialEq, Default)]
pub struct Pose {
    pub rot: u32,              // 0, 90, 180, 270 (clockwise)
    pub mirror: Option<char>, // 'x' (about the x-axis) or 'y'
}

impl Pose {
    pub fn is_zero(&self) -> bool {
        self.rot == 0 && self.mirror.is_none()
    }
    pub fn classes(&self) -> Vec<String> {
        let mut v = Vec::new();
        if self.rot != 0 {
            v.push(format!("lini-pose-{}", self.rot));
        }
        if let Some(m) = self.mirror {
            v.push(format!("lini-mirror-{}", m));
        }
        v
    }
    pub fn vertical(&self) -> bool {
        self.rot == 90 || self.rot == 270
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Dir {
    L,
    R,
    U,
    D,
}

impl Dir {
    pub fn opposite(self) -> Dir {
        match self {
            Dir::L => Dir::R,
            Dir::R => Dir::L,
            Dir::U => Dir::D,
            Dir::D => Dir::U,
        }
    }
    pub fn horizontal(self) -> bool {
        matches!(self, Dir::L | Dir::R)
    }
    fn of_side(s: &str) -> Option<Dir> {
        Some(match s {
            "left" => Dir::L,
            "right" => Dir::R,
            "top" => Dir::U,
            "bottom" => Dir::D,
            _ => return None,
        })
    }
    fn of_vec(dx: f64, dy: f64) -> Dir {
        if dx.abs() >= dy.abs() {
            if dx < 0.0 {
                Dir::L
            } else {
                Dir::R
            }
        } else if dy < 0.0 {
            Dir::U
        } else {
            Dir::D
        }
    }
}

fn num(v: f64) -> String {
    let r = (v * 10000.0).round() / 10000.0;
    let r = if r == 0.0 { 0.0 } else { r };
    render_number(r)
}

// a point of the symbol's frame (w x h) under the pose: mirror first, then
// the clockwise turn
fn map_pt(x: f64, y: f64, w: f64, h: f64, p: Pose) -> (f64, f64) {
    let (mut x, mut y) = (x, y);
    match p.mirror {
        Some('x') => y = h - y,
        Some('y') => x = w - x,
        _ => {}
    }
    match p.rot {
        90 => (h - y, x),
        180 => (w - x, h - y),
        270 => (y, w - x),
        _ => (x, y),
    }
}

pub fn map_vec(dx: f64, dy: f64, p: Pose) -> (f64, f64) {
    let (mut dx, mut dy) = (dx, dy);
    match p.mirror {
        Some('x') => dy = -dy,
        Some('y') => dx = -dx,
        _ => {}
    }
    match p.rot {
        90 => (-dy, dx),
        180 => (-dx, -dy),
        270 => (dy, -dx),
        _ => (dx, dy),
    }
}

// transform an SVG path ("M 0 0 M w h …" frame first)
pub fn map_path(path: &str, p: Pose) -> String {
    if p.is_zero() {
        return path.to_string();
    }
    let toks: Vec<&str> = path.split_whitespace().collect();
    // the frame: M 0 0 M w h
    let w: f64 = toks.get(4).and_then(|s| s.parse().ok()).unwrap_or(0.0);
    let h: f64 = toks.get(5).and_then(|s| s.parse().ok()).unwrap_or(0.0);
    let mut out: Vec<String> = Vec::new();
    let mut i = 0;
    let f = |s: &str| s.parse::<f64>().unwrap_or(0.0);
    while i < toks.len() {
        let t = toks[i];
        match t {
            "M" | "L" if i + 2 < toks.len() + 0 && i + 2 <= toks.len() - 1 => {
                let (x, y) = map_pt(f(toks[i + 1]), f(toks[i + 2]), w, h, p);
                out.push(t.to_string());
                out.push(num(x));
                out.push(num(y));
                i += 3;
            }
            "Q" if i + 4 < toks.len() => {
                let (x1, y1) = map_pt(f(toks[i + 1]), f(toks[i + 2]), w, h, p);
                let (x, y) = map_pt(f(toks[i + 3]), f(toks[i + 4]), w, h, p);
                out.push("Q".into());
                out.push(num(x1));
                out.push(num(y1));
                out.push(num(x));
                out.push(num(y));
                i += 5;
            }
            "A" if i + 7 < toks.len() => {
                let rx = toks[i + 1];
                let ry = toks[i + 2];
                let mut rot = f(toks[i + 3]);
                let large = toks[i + 4];
                let mut sweep = toks[i + 5].to_string();
                if p.mirror.is_some() {
                    rot = -rot;
                    sweep = if sweep == "1" { "0".into() } else { "1".into() };
                }
                rot += p.rot as f64;
                let rot = ((rot % 360.0) + 360.0) % 360.0;
                let (x, y) = map_pt(f(toks[i + 6]), f(toks[i + 7]), w, h, p);
                out.push("A".into());
                out.push(rx.to_string());
                out.push(ry.to_string());
                out.push(num(rot));
                out.push(large.to_string());
                out.push(sweep);
                out.push(num(x));
                out.push(num(y));
                i += 8;
            }
            _ => {
                out.push(t.to_string());
                i += 1;
            }
        }
    }
    out.join(" ")
}

fn own(n: &[Decl], name: &str) -> Option<String> {
    n.iter().rev().find(|d| d.name == name).and_then(|d| d.first().map(|s| s.to_string()))
}

// the pose written on a node (rotate:, mirror:), validated
pub fn written_pose(n: &Node) -> R<Pose> {
    let mut p = Pose::default();
    if let Some(r) = own(&n.style, "rotate") {
        p.rot = match r.as_str() {
            "0" => 0,
            "90" => 90,
            "180" => 180,
            "270" => 270,
            _ => return Err(err("a schematic part rotates in 90° steps — 0, 90, 180, or 270", n.span)),
        };
    }
    if let Some(m) = own(&n.style, "mirror") {
        p.mirror = match m.as_str() {
            "x-axis" => Some('x'),
            "y-axis" => Some('y'),
            "none" => None,
            _ => return Err(err("a schematic part mirrors about its own axis — x-axis, y-axis, or none", n.span)),
        };
    }
    Ok(p)
}

pub fn is_part(chain: &[String]) -> bool {
    chain.iter().any(|c| sch_geo::part_types().any(|t| t == c))
}

pub fn part_type(chain: &[String]) -> Option<String> {
    chain.iter().find(|c| sch_geo::part_types().any(|t| t == c.as_str())).cloned()
}

pub fn is_label(chain: &[String]) -> bool {
    chain.iter().any(|c| c == "label")
}

pub fn is_component(chain: &[String]) -> bool {
    chain.iter().any(|c| c == "component") && !is_part(chain)
}

// the prefix a reference designator counts with
fn prefix(cx: &Cx, n: &Node, chain: &[String]) -> String {
    if let Some(p) = n.style.iter().rev().find(|d| d.name == "prefix") {
        if let Some(s) = p.first().and_then(super::page::unquote) {
            return s;
        }
    }
    for t in chain {
        if let Some(d) = cx.define(t) {
            if let Some(p) = d.decls.iter().rev().find(|d| d.name == "prefix") {
                if let Some(s) = p.first().and_then(super::page::unquote) {
                    return s;
                }
            }
        }
        if let Some(td) = crate::types::find(t) {
            for d in Decl::list(td.defaults) {
                if d.name == "prefix" {
                    if let Some(s) = d.first().and_then(super::page::unquote) {
                        return s;
                    }
                }
            }
        }
        if sch_geo::part_types().any(|p| p == t.as_str()) && t != "opamp" {
            return t.clone();
        }
    }
    "U".to_string()
}

fn ref_text(cx: &mut Cx, n: &Node, chain: &[String]) -> String {
    match &n.id {
        Some(id) => id.clone(),
        None => {
            let p = prefix(cx, n, chain);
            let k = cx.sch_counter(&p);
            format!("{}{}", p, k)
        }
    }
}

fn block_with(cx: &mut Cx, ty: &str, decls: &str, text: Option<&str>) -> Item {
    let mut b = cx.typed(ty);
    b.decls = Decl::list(decls);
    if let Some(t) = text {
        b.children.push(Cx::text_item(t));
    }
    Item::Node(b)
}

// -------------------------------------------------------------- components
struct Slot {
    pin: Option<Node>, // None: a space
    space: Option<Node>,
    side: Option<String>, // explicit and valid
    generated: bool,
}

fn side_name(d: Dir) -> &'static str {
    match d {
        Dir::L => "left",
        Dir::R => "right",
        Dir::U => "top",
        Dir::D => "bottom",
    }
}

pub fn component(cx: &mut Cx, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    let pose = written_pose(n)?;
    o.classes.extend(pose.classes());
    let r = ref_text(cx, n, chain);
    o.decls.push(Decl::val("direction", "column"));
    o.decls.push(Decl::val("gap", "0"));
    // the pins: generated (a connector's `pins: N`) then the children
    let mut slots: Vec<Slot> = Vec::new();
    if chain.iter().any(|c| c == "J") {
        if let Some(k) = own(&n.style, "pins").and_then(|s| s.parse::<f64>().ok()) {
            for i in 1..=(k.max(0.0) as usize) {
                let pn = Node {
                    ty: Some("pin".into()),
                    id: Some(format!("p{}", i)),
                    label: None,
                    classes: vec![],
                    style: vec![Decl::val("number", &i.to_string()), Decl::val("side", "left")],
                    children: None,
                    span: n.span,
                    head_span: n.span,
                    ty_span: n.span,
                };
                slots.push(Slot { pin: Some(pn), space: None, side: Some("left".into()), generated: true });
            }
        }
    }
    let mut extra: Vec<&Stmt> = Vec::new();
    for s in n.children.as_deref().unwrap_or(&[]) {
        match s {
            Stmt::Node(c) if c.ty.as_deref() == Some("pin") => {
                let side = own(&c.style, "side").filter(|s| Dir::of_side(s).is_some());
                slots.push(Slot { pin: Some(c.clone()), space: None, side, generated: false });
            }
            Stmt::Node(c) if c.ty.as_deref() == Some("space") => {
                slots.push(Slot { pin: None, space: Some(c.clone()), side: None, generated: false });
            }
            other => extra.push(other),
        }
    }
    // auto pins split left / right, spaces ride with their pin
    let autos: Vec<usize> = (0..slots.len()).filter(|&i| slots[i].pin.is_some() && slots[i].side.is_none()).collect();
    let half = (autos.len() + 1) / 2;
    let mut sides: Vec<String> = vec![String::new(); slots.len()];
    for (k, &i) in autos.iter().enumerate() {
        sides[i] = if k < half { "left".into() } else { "right".into() };
    }
    for i in 0..slots.len() {
        if let Some(s) = &slots[i].side {
            sides[i] = s.clone();
        }
    }
    for i in 0..slots.len() {
        if slots[i].pin.is_none() {
            let prev = (0..i).rev().find(|&j| slots[j].pin.is_some()).map(|j| sides[j].clone());
            let next = (i + 1..slots.len()).find(|&j| slots[j].pin.is_some()).map(|j| sides[j].clone());
            sides[i] = prev.or(next).unwrap_or_else(|| "left".into());
        }
    }
    // group by side (left/right top→bottom, top/bottom left→right), then pose
    let mut by: HashMap<&str, Vec<usize>> = HashMap::new();
    for (i, s) in sides.iter().enumerate() {
        by.entry(match s.as_str() {
            "right" => "right",
            "top" => "top",
            "bottom" => "bottom",
            _ => "left",
        })
        .or_default()
        .push(i);
    }
    let get = |by: &HashMap<&str, Vec<usize>>, k: &str| by.get(k).cloned().unwrap_or_default();
    let (mut left, mut right, mut top, mut bottom) = (get(&by, "left"), get(&by, "right"), get(&by, "top"), get(&by, "bottom"));
    let rev = |v: &Vec<usize>| v.iter().rev().cloned().collect::<Vec<usize>>();
    match pose.mirror {
        Some('x') => {
            let (t, b) = (top.clone(), bottom.clone());
            top = b;
            bottom = t;
            left = rev(&left);
            right = rev(&right);
        }
        Some('y') => {
            let (l, r) = (left.clone(), right.clone());
            left = r;
            right = l;
            top = rev(&top);
            bottom = rev(&bottom);
        }
        _ => {}
    }
    for _ in 0..(pose.rot / 90) {
        let (l, r, t, b) = (left.clone(), right.clone(), top.clone(), bottom.clone());
        top = rev(&l);
        right = t;
        bottom = rev(&r);
        left = b;
    }
    let mut children: Vec<Item> = Vec::new();
    let mut lower_pins = |cx: &mut Cx, idx: &[usize], side: &str| -> R<Vec<Item>> {
        let mut v = Vec::new();
        for &i in idx {
            let s = &slots[i];
            if let Some(sp) = &s.space {
                let mut b = cx.typed("space");
                b.id = sp.id.clone();
                b.classes.extend(sp.classes.iter().cloned());
                b.decls = sp.style.clone();
                if let Some(k) = own(&sp.style, "span").and_then(|s| s.parse::<f64>().ok()) {
                    if k != 1.0 {
                        let along = if side == "left" || side == "right" { "height" } else { "width" };
                        b.decls.push(Decl::val(along, &num(20.0 * k)));
                    }
                }
                v.push(Item::Node(b));
                continue;
            }
            let pn = s.pin.as_ref().unwrap();
            v.push(pin_node(cx, pn, side, s.side.is_some() || s.generated)?);
        }
        Ok(v)
    };
    let slots_of = |idx: &[usize]| -> f64 {
        idx.iter()
            .map(|&i| match &slots[i].space {
                Some(sp) => own(&sp.style, "span").and_then(|s| s.parse::<f64>().ok()).unwrap_or(1.0),
                None => 1.0,
            })
            .sum()
    };
    let middle = !left.is_empty() || !right.is_empty();
    if !top.is_empty() {
        let even = slots_of(&top) % 2.0 == 0.0;
        let mut row = cx.typed("row");
        row.decls = Decl::list(&format!(
            "gap: 0; align: start;{} height: 20;",
            if even { " padding: 0 20 0 0;" } else { "" }
        ));
        row.children = lower_pins(cx, &top, "top")?;
        children.push(Item::Node(row));
    } else if middle && !bottom.is_empty() {
        let mut row = cx.typed("row");
        row.decls = Decl::list("height: 20;");
        children.push(Item::Node(row));
    }
    if middle {
        let mut cols = Vec::new();
        for (idx, side, align) in [(&left, "left", "start"), (&right, "right", "end")] {
            if idx.is_empty() {
                continue;
            }
            let even = slots_of(idx) % 2.0 == 0.0;
            let mut col = cx.typed("column");
            col.decls = Decl::list(&format!(
                "gap: 0; align: {};{}",
                align,
                if even { " padding: 0 0 20 0;" } else { "" }
            ));
            col.children = lower_pins(cx, idx, side)?;
            cols.push(Item::Node(col));
        }
        if cols.len() == 2 {
            let mut row = cx.typed("row");
            row.decls = Decl::list("gap: 24; align: center;");
            row.children = cols;
            children.push(Item::Node(row));
        } else {
            children.extend(cols);
        }
    }
    if !bottom.is_empty() {
        let even = slots_of(&bottom) % 2.0 == 0.0;
        let mut row = cx.typed("row");
        row.decls = Decl::list(&format!(
            "gap: 0; align: end;{} height: 20;",
            if even { " padding: 0 20 0 0;" } else { "" }
        ));
        row.children = lower_pins(cx, &bottom, "bottom")?;
        children.push(Item::Node(row));
    } else if middle && !top.is_empty() {
        let mut row = cx.typed("row");
        row.decls = Decl::list("height: 20;");
        children.push(Item::Node(row));
    }
    let lift = if top.is_empty() { 0.0 } else { 20.0 };
    if let Some(l) = n.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty()) {
        children.push(block_with(cx, "part-value", &format!("pin: top; translate: 0 {};", num(-20.0 - lift)), Some(&l)));
    }
    children.push(block_with(cx, "ref", &format!("pin: top; translate: 0 {};", num(-36.0 - lift)), Some(&r)));
    for s in extra {
        cx.stmts(std::slice::from_ref(s), &mut children)?;
    }
    o.children = children;
    Ok(o)
}

fn pin_node(cx: &mut Cx, pn: &Node, side: &str, rewrite: bool) -> R<Item> {
    let mut p = cx.typed("pin");
    p.id = pn.id.clone();
    p.classes.extend(pn.classes.iter().cloned());
    p.decls = pn.style.clone();
    if rewrite {
        for d in p.decls.iter_mut() {
            if d.name == "side" {
                *d = Decl::val("side", side);
            }
        }
    }
    let vertical = side == "top" || side == "bottom";
    if vertical {
        p.decls.push(Decl::val("width", "20"));
        p.decls.push(Decl::val("height", "auto"));
    }
    let label = pn.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty());
    if label.is_none() {
        if let Some(id) = &pn.id {
            p.children.push(Cx::text_item(id));
        }
    }
    let (stub, numpos) = match side {
        "right" => ("points: 0 0, 20 0; pin: right; translate: 28 0;", "pin: right; translate: 28 -9; width: 20;"),
        "top" => ("points: 0 0, 0 20; pin: top; translate: 0 -28;", "pin: top; translate: 9 -28; height: 20;"),
        "bottom" => ("points: 0 0, 0 20; pin: bottom; translate: 0 28;", "pin: bottom; translate: 9 28; height: 20;"),
        _ => ("points: 0 0, 20 0; pin: left; translate: -28 0;", "pin: left; translate: -28 -9; width: 20;"),
    };
    let mut st = cx.typed("pin-stub");
    st.decls = Decl::list(stub);
    p.children.push(Item::Node(st));
    if let Some(nm) = pn.style.iter().rev().find(|d| d.name == "number") {
        let t = nm.value_text();
        let t = super::page::unquote(&t).unwrap_or(t);
        p.children.push(block_with(cx, "pin-number", numpos, Some(&t)));
    }
    if let Some(l) = label {
        p.children.push(Cx::text_item(&l));
    }
    // a pin's own children follow
    if let Some(ch) = &pn.children {
        let mut v = Vec::new();
        cx.stmts(ch, &mut v)?;
        p.children.extend(v);
    }
    Ok(Item::Node(p))
}

// ------------------------------------------------------------------- parts
pub fn part_geo(n: &Node, ty: &str) -> R<&'static PartGeo> {
    let sym = own(&n.style, "symbol");
    if ty == "opamp" {
        return Ok(sch_geo::geo("opamp", None).unwrap());
    }
    match sym {
        None => Ok(sch_geo::geo(ty, None).unwrap()),
        Some(s) => match sch_geo::geo(ty, Some(&s)) {
            Some(g) => Ok(g),
            None => Err(err(
                &format!("unknown symbol '{}' on '|{}|' — its variants are {}", s, ty, sch_geo::variants(ty).join(", ")),
                n.span,
            )),
        },
    }
}

pub fn part(cx: &mut Cx, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    let ty = part_type(chain).unwrap();
    let g = part_geo(n, &ty)?;
    let mut pose = written_pose(n)?;
    if pose.is_zero() {
        if let Some(id) = &n.id {
            if let Some(p) = cx.sch_pose(id) {
                pose = p;
            }
        }
    }
    o.classes.extend(pose.classes());
    let r = ref_text(cx, n, chain);
    let mut children = Vec::new();
    let mut line = cx.typed("sch-line");
    line.decls = vec![Decl::new("path", &format!("\"{}\"", map_path(g.line, pose)))];
    children.push(Item::Node(line));
    if let Some(s) = g.solid {
        let mut solid = cx.typed("sch-solid");
        solid.decls = vec![Decl::new("path", &format!("\"{}\"", map_path(s, pose))), Decl::val("pin", "center")];
        children.push(Item::Node(solid));
    }
    let vertical = pose.vertical();
    if let Some(l) = n.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty()) {
        let d = if vertical { "pin: center; translate: 24 8;" } else { "pin: bottom; translate: 0 20;" };
        children.push(block_with(cx, "part-value", d, Some(&l)));
    }
    if n.id.is_some() {
        for (pin, dx, dy) in g.pins {
            let (x, y) = map_vec(*dx, *dy, pose);
            let mut b = cx.typed("block");
            b.id = Some(pin.to_string());
            b.decls = Decl::list(&format!("pin: center; translate: {} {};", num(x), num(y)));
            children.push(Item::Node(b));
        }
    }
    let d = if vertical { "pin: center; translate: 24 -8;" } else { "pin: top; translate: 0 -20;" };
    children.push(block_with(cx, "ref", d, Some(&r)));
    if let Some(ch) = &n.children {
        cx.stmts(ch, &mut children)?;
    }
    o.children = children;
    Ok(o)
}

// ------------------------------------------------------------------ labels
pub static SHAPES: &[&str] = &["plain", "left", "right", "both", "round"];

pub fn symbol_of(cx: &Cx, n: &Node, chain: &[String]) -> Option<String> {
    if let Some(s) = own(&n.style, "symbol") {
        return Some(s);
    }
    for t in chain {
        if let Some(d) = cx.define(t) {
            if let Some(s) = own(&d.decls, "symbol") {
                return Some(s);
            }
        }
        if let Some(td) = crate::types::find(t) {
            if let Some(s) = own(&Decl::list(td.defaults), "symbol") {
                return Some(s);
            }
        }
    }
    None
}

fn suggest(s: &str, options: &[&str]) -> Option<String> {
    let mut best: Option<(usize, &str)> = None;
    for o in options {
        let d = crate::util::levenshtein(s, o);
        if d <= 2 && best.map_or(true, |b| d < b.0) {
            best = Some((d, o));
        }
    }
    best.map(|b| b.1.to_string())
}

pub fn label(cx: &mut Cx, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    let mut pose = written_pose(n)?;
    let wired = n.id.as_ref().and_then(|id| cx.sch_pose(id));
    if pose.is_zero() {
        if let Some(p) = wired {
            pose = p;
        }
    }
    let sym = symbol_of(cx, n, chain);
    let shape = own(&n.style, "shape").unwrap_or_else(|| "plain".to_string());
    let mut lead: Vec<String> = Vec::new();
    let mut children = Vec::new();
    let label = n.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty());
    let bodies = cx.bodies(chain)?;
    match &sym {
        Some(s) => {
            let path = match sch_geo::SYMBOLS.iter().find(|(k, _)| k == s) {
                Some((_, p)) => *p,
                None => {
                    let names: Vec<&str> = sch_geo::SYMBOLS.iter().map(|(k, _)| *k).collect();
                    let msg = match suggest(s, &names) {
                        Some(h) => format!("unknown symbol '{}'; did you mean '{}'?", s, h),
                        None => format!("unknown symbol '{}'", s),
                    };
                    return Err(err(&msg, n.span));
                }
            };
            o.decls.insert(0, Decl::val("direction", "row"));
            let mut t = cx.typed("sch-tag-line");
            t.decls = vec![Decl::new("path", &format!("\"{}\"", map_path(path, pose)))];
            children.push(Item::Node(t));
        }
        None => {
            if !SHAPES.contains(&shape.as_str()) {
                return Err(err(&format!("'shape' takes plain, left, right, both, or round — not '{}'", shape), n.span));
            }
            match shape.as_str() {
                "left" | "right" | "both" => {
                    lead.push(format!("lini-tag-flag-{}", shape));
                    cx.mark(&format!("tag-flag-{}", shape));
                    let mut t = cx.typed("sch-tag-line");
                    t.decls = Decl::list(&format!("chrome: tag {}; pin: center; path: \"M 0 0\";", shape));
                    children.push(Item::Node(t));
                }
                "round" => {
                    lead.push("lini-tag-outline".into());
                    lead.push("lini-tag-round".into());
                    cx.mark("tag-outline");
                    cx.mark("tag-round");
                }
                _ => {
                    let turned = pose.vertical();
                    let c = if turned { "net-run-turned" } else { "net-run" };
                    lead.push(format!("lini-{}", c));
                    cx.mark(c);
                }
            }
        }
    }
    let mut classes = lead;
    classes.extend(o.classes.drain(..));
    classes.extend(pose.classes());
    o.classes = classes;
    children.extend(bodies);
    if let Some(l) = label {
        children.push(Cx::text_item(&l));
    }
    if let Some(ch) = &n.children {
        cx.stmts(ch, &mut children)?;
    }
    o.children = children;
    Ok(o)
}

// ------------------------------------------------------------------ wiring
#[derive(Clone, Debug, PartialEq)]
enum Kind {
    // a device: its pins' rest directions (after a written pose) and count
    Device { pins: Vec<(String, f64, f64)>, two_pin_part: bool, fixed_pose: bool, part: bool },
    Label { sym: Option<String> },
    Other,
}

#[derive(Clone, Debug)]
struct Elem {
    kind: Kind,
}

// one end of a wire
#[derive(Clone, Debug, PartialEq)]
enum Term {
    Pin(String, String),
    Label(String),
    Other(String),
}

impl Term {
    fn text(&self) -> String {
        match self {
            Term::Pin(d, p) => format!("{}.{}", d, p),
            Term::Label(l) | Term::Other(l) => l.clone(),
        }
    }
}

// a planned link statement: its hops, the labels it brings, the label nodes
#[derive(Clone, Debug, Default)]
pub struct Planned {
    pub hops: Vec<(String, String)>,
    // generated label nodes: (id, after the hops?), the statement that makes them
    pub before: Vec<Node>,
    pub after: Vec<Node>,
}

#[derive(Default, Debug)]
pub struct Plan {
    pub poses: HashMap<String, Pose>,
    pub links: Vec<Planned>, // by link statement order in the scope
    pub next: usize,
}

fn gnd_like(s: &Option<String>) -> bool {
    matches!(s.as_deref(), Some("gnd") | Some("earth") | Some("chassis"))
}
fn power_like(s: &Option<String>) -> bool {
    matches!(s.as_deref(), Some("power") | Some("antenna"))
}

impl<'a> Cx<'a> {
    pub fn sch_counter(&mut self, prefix: &str) -> usize {
        let key = (self.sch_scope_key(), prefix.to_string());
        let e = self.sch_counters.entry(key).or_insert(0);
        *e += 1;
        *e
    }

    fn sch_scope_key(&self) -> usize {
        // the nearest schematic scope frame (or the root)
        for (i, f) in self.stack.iter().enumerate().rev() {
            if f.sch.is_some() {
                return i + 1;
            }
        }
        0
    }

    pub fn sch_pose(&self, id: &str) -> Option<Pose> {
        let plan = match self.stack.iter().rev().skip(1).find_map(|f| f.sch.as_ref()) {
            Some(p) => p,
            None => self.root_sch.as_ref()?,
        };
        plan.poses.get(id).cloned()
    }

    fn elem_of(&self, n: &Node) -> Option<(String, Elem)> {
        let id = n.id.clone()?;
        let ty = n.ty.clone().unwrap_or_else(|| "box".into());
        let (_, chain) = self.chain(&ty)?;
        let kind = if is_part(&chain) {
            let pt = part_type(&chain).unwrap();
            let g = part_geo(n, &pt).ok()?;
            let pose = written_pose(n).unwrap_or_default();
            let pins: Vec<(String, f64, f64)> = g
                .pins
                .iter()
                .map(|(p, x, y)| {
                    let (a, b) = map_vec(*x, *y, pose);
                    (p.to_string(), a, b)
                })
                .collect();
            let two = g.pins.len() == 2;
            Kind::Device { pins, two_pin_part: two, fixed_pose: !pose.is_zero(), part: true }
        } else if is_component(&chain) {
            // pins after the pose, with their sides
            let pose = written_pose(n).unwrap_or_default();
            let mut pins = Vec::new();
            let mut list: Vec<(String, Option<String>)> = Vec::new();
            if chain.iter().any(|c| c == "J") {
                if let Some(k) = own(&n.style, "pins").and_then(|s| s.parse::<f64>().ok()) {
                    for i in 1..=(k.max(0.0) as usize) {
                        list.push((format!("p{}", i), Some("left".into())));
                    }
                }
            }
            for s in n.children.as_deref().unwrap_or(&[]) {
                if let Stmt::Node(c) = s {
                    if c.ty.as_deref() == Some("pin") {
                        if let Some(pid) = &c.id {
                            list.push((pid.clone(), own(&c.style, "side").filter(|s| Dir::of_side(s).is_some())));
                        }
                    }
                }
            }
            let autos = list.iter().filter(|(_, s)| s.is_none()).count();
            let half = (autos + 1) / 2;
            let mut k = 0;
            for (pid, side) in &list {
                let s = match side {
                    Some(s) => s.clone(),
                    None => {
                        k += 1;
                        if k <= half {
                            "left".into()
                        } else {
                            "right".into()
                        }
                    }
                };
                let (dx, dy) = match s.as_str() {
                    "left" => (-1.0, 0.0),
                    "right" => (1.0, 0.0),
                    "top" => (0.0, -1.0),
                    _ => (0.0, 1.0),
                };
                let (a, b) = map_vec(dx, dy, pose);
                pins.push((pid.clone(), a, b));
            }
            Kind::Device { pins, two_pin_part: false, fixed_pose: true, part: false }
        } else if is_label(&chain) {
            Kind::Label { sym: symbol_of(self, n, &chain) }
        } else {
            Kind::Other
        };
        Some((id, Elem { kind }))
    }

    // plan a schematic scope: the wires of its link statements and the poses
    pub fn sch_plan(&mut self, stmts: &[Stmt]) -> R<Plan> {
        let mut elems: HashMap<String, Elem> = HashMap::new();
        for s in stmts {
            if let Stmt::Node(n) = s {
                if let Some((id, e)) = self.elem_of(n) {
                    elems.insert(id, e);
                }
            }
        }
        let mut plan = Plan::default();
        let mut used: HashMap<String, Vec<String>> = HashMap::new();
        let mut caps = 0usize;
        let mut labels = 0usize;
        // every hop: (from, to)
        let mut hops: Vec<(Term, Term)> = Vec::new();
        let mut label_syms: HashMap<String, Option<String>> = HashMap::new();
        for (id, e) in &elems {
            if let Kind::Label { sym } = &e.kind {
                label_syms.insert(id.clone(), sym.clone());
            }
        }
        for s in stmts {
            let l = match s {
                Stmt::Link(l) => l,
                _ => continue,
            };
            let mut planned = Planned::default();
            self.sch_link(l, &elems, &mut used, &mut caps, &mut labels, &mut planned, &mut hops, &mut label_syms)?;
            plan.links.push(planned);
        }
        // poses: walk from anchors
        let mut poses: HashMap<String, Pose> = HashMap::new();
        solve(&elems, &hops, &label_syms, &mut poses);
        plan.poses = poses;
        Ok(plan)
    }

    #[allow(clippy::too_many_arguments)]
    fn sch_link(
        &mut self,
        l: &Link,
        elems: &HashMap<String, Elem>,
        used: &mut HashMap<String, Vec<String>>,
        caps: &mut usize,
        labels: &mut usize,
        planned: &mut Planned,
        hops: &mut Vec<(Term, Term)>,
        label_syms: &mut HashMap<String, Option<String>>,
    ) -> R<()> {
        for op in &l.ops {
            if op != "-" && !(l.groups.len() == 1 && (op == "->" || op == "-<")) {
                return Err(err("a schematic wire is plain — markers shape a text label's tag; write 'a -> \"NET\"'", l.span));
            }
        }
        // the elements of the chain: (entry term, exit term)
        let n = l.groups.len();
        let mut seq: Vec<(Term, Term)> = Vec::new();
        for (gi, g) in l.groups.iter().enumerate() {
            let ep = match g.first() {
                Some(e) => e,
                None => continue,
            };
            let middle = gi > 0 && gi + 1 < n;
            match ep {
                Endpoint::Path { parts, text, span } => {
                    let name = &parts[0];
                    let pin_named = parts.len() > 1;
                    match elems.get(name).map(|e| &e.kind) {
                        Some(Kind::Device { pins, two_pin_part, .. }) => {
                            if pin_named {
                                let p = parts[1].clone();
                                if middle && *two_pin_part {
                                    let other = pins.iter().find(|(q, _, _)| *q != p).map(|x| x.0.clone()).unwrap_or_default();
                                    used.entry(name.clone()).or_default().push(p.clone());
                                    used.entry(name.clone()).or_default().push(other.clone());
                                    seq.push((Term::Pin(name.clone(), p), Term::Pin(name.clone(), other)));
                                } else {
                                    used.entry(name.clone()).or_default().push(p.clone());
                                    let t = Term::Pin(name.clone(), p);
                                    seq.push((t.clone(), t));
                                }
                            } else if *two_pin_part {
                                let u = used.entry(name.clone()).or_default();
                                let free: Vec<String> =
                                    pins.iter().map(|x| x.0.clone()).filter(|p| !u.contains(p)).collect();
                                if middle {
                                    let a = free.first().cloned().unwrap_or_else(|| pins[0].0.clone());
                                    let b = pins.iter().map(|x| x.0.clone()).find(|p| *p != a).unwrap_or_default();
                                    u.push(a.clone());
                                    u.push(b.clone());
                                    seq.push((Term::Pin(name.clone(), a), Term::Pin(name.clone(), b)));
                                } else {
                                    let a = match free.first() {
                                        Some(a) => a.clone(),
                                        None => {
                                            return Err(err(
                                                &format!(
                                                    "both pins of '{}' are wired — name one ('{}.{}')",
                                                    name, name, pins[0].0
                                                ),
                                                *span,
                                            ))
                                        }
                                    };
                                    u.push(a.clone());
                                    let t = Term::Pin(name.clone(), a);
                                    seq.push((t.clone(), t));
                                }
                            } else {
                                let t = Term::Other(text.clone());
                                seq.push((t.clone(), t));
                            }
                        }
                        Some(Kind::Label { .. }) if !pin_named => {
                            let t = Term::Label(name.clone());
                            seq.push((t.clone(), t));
                        }
                        Some(_) => {
                            let t = Term::Other(text.clone());
                            seq.push((t.clone(), t));
                        }
                        None => {
                            if !pin_named {
                                return Err(err(
                                    &format!(
                                        "'{}' is unknown — a schematic never invents a box; did you mean '- \"{}\"' (a net label)?",
                                        name, name
                                    ),
                                    *span,
                                ));
                            }
                            let t = Term::Other(text.clone());
                            seq.push((t.clone(), t));
                        }
                    }
                }
                Endpoint::Capsule { node, tail } => {
                    let id = match &node.id {
                        Some(id) => id.clone(),
                        None => {
                            *caps += 1;
                            format!("lini-cap-{}", caps)
                        }
                    };
                    let mut nn = node.clone();
                    nn.id = Some(id.clone());
                    let ty = nn.ty.clone().unwrap_or_else(|| "box".into());
                    let chain = self.chain(&ty).map(|c| c.1).unwrap_or_default();
                    let t = if is_label(&chain) {
                        label_syms.insert(id.clone(), symbol_of(self, &nn, &chain));
                        Term::Label(id.clone())
                    } else {
                        Term::Other(format!("{}{}", id, tail))
                    };
                    if gi == 0 {
                        planned.before.push(nn);
                    } else {
                        planned.after.push(nn);
                    }
                    seq.push((t.clone(), t));
                }
                Endpoint::Text(_) => {}
            }
        }
        // a one-ended wire to text: a net label
        if l.groups.len() == 1 {
            if let Some(text) = &l.label {
                *labels += 1;
                let id = format!("lini-label-{}", labels);
                let shape = match l.ops.first().map(|s| s.as_str()) {
                    Some("->") => Some("right"),
                    Some("-<") => Some("left"),
                    _ => None,
                };
                let mut style = Vec::new();
                if let Some(s) = shape {
                    style.push(Decl::val("shape", s));
                }
                let nn = Node {
                    ty: Some("label".into()),
                    id: Some(id.clone()),
                    label: Some(text.clone()),
                    classes: vec![],
                    style,
                    children: None,
                    span: l.span,
                    head_span: l.span,
                    ty_span: l.span,
                };
                label_syms.insert(id.clone(), None);
                planned.after.push(nn);
                let t = Term::Label(id);
                seq.push((t.clone(), t));
            }
        }
        for w in seq.windows(2) {
            let a = &w[0].1;
            let b = &w[1].0;
            planned.hops.push((a.text(), b.text()));
            hops.push((a.clone(), b.clone()));
        }
        // the internal hop of a pass-through part
        for (a, b) in &seq {
            if a != b {
                hops.push((Term::Other(String::from("\u{0}through")), Term::Other(String::new())));
                hops.pop();
                let _ = (a, b);
            }
        }
        let _ = Diag::error;
        let _ = Span::default;
        Ok(())
    }
}

// ------------------------------------------------------------- the solver
fn pin_dir(elems: &HashMap<String, Elem>, poses: &HashMap<String, Pose>, dev: &str, pin: &str) -> Option<Dir> {
    if let Some(Elem { kind: Kind::Device { pins, part, .. } }) = elems.get(dev) {
        let (_, x, y) = pins.iter().find(|p| p.0 == pin)?;
        let (x, y) = match (part, poses.get(dev)) {
            (true, Some(p)) => map_vec(*x, *y, *p),
            _ => (*x, *y),
        };
        return Some(Dir::of_vec(x, y));
    }
    None
}

fn is_anchor(elems: &HashMap<String, Elem>, dev: &str) -> bool {
    matches!(elems.get(dev), Some(Elem { kind: Kind::Device { pins, .. } }) if pins.len() >= 3)
}

// the pose turning a two-pin part so its pin `entry` faces `toward`
fn pose_for(elems: &HashMap<String, Elem>, dev: &str, entry: &str, toward: Dir) -> Pose {
    if let Some(Elem { kind: Kind::Device { pins, .. } }) = elems.get(dev) {
        if let Some((_, x, y)) = pins.iter().find(|p| p.0 == entry) {
            for rot in [0, 90, 180, 270] {
                let p = Pose { rot, mirror: None };
                let (a, b) = map_vec(*x, *y, p);
                if Dir::of_vec(a, b) == toward {
                    return p;
                }
            }
        }
    }
    Pose::default()
}

fn label_pose(sym: &Option<String>, d: Dir) -> Pose {
    let rot = match sym.as_deref() {
        Some("gnd") | Some("earth") | Some("chassis") => {
            if d == Dir::U {
                180
            } else {
                0
            }
        }
        Some("power") | Some("antenna") => {
            if d == Dir::D {
                180
            } else {
                0
            }
        }
        Some("nc") => {
            if d == Dir::L {
                180
            } else {
                0
            }
        }
        Some(_) => 0,
        None => match d {
            Dir::L => 0,
            Dir::R => 180,
            Dir::U => 90,
            Dir::D => 270,
        },
    };
    Pose { rot, mirror: None }
}

fn other_pin(elems: &HashMap<String, Elem>, dev: &str, pin: &str) -> Option<String> {
    if let Some(Elem { kind: Kind::Device { pins, two_pin_part: true, .. } }) = elems.get(dev) {
        return pins.iter().find(|p| p.0 != pin).map(|p| p.0.clone());
    }
    None
}

fn solve(elems: &HashMap<String, Elem>, hops: &[(Term, Term)], syms: &HashMap<String, Option<String>>, poses: &mut HashMap<String, Pose>) {
    // neighbours of a term along the wires
    let neighbours = |t: &Term| -> Vec<Term> {
        let mut v = Vec::new();
        for (a, b) in hops {
            if a == t {
                v.push(b.clone());
            } else if b == t {
                v.push(a.clone());
            }
        }
        v
    };
    // where a path from `t` (entering a part at `t`) ends: the symbol of the
    // label it reaches through free two-pin parts
    let end_sym = |start: &Term, from: &Term, poses: &HashMap<String, Pose>| -> Option<Option<String>> {
        let mut cur = start.clone();
        let mut prev = from.clone();
        for _ in 0..64 {
            match &cur {
                Term::Pin(d, p) => {
                    let fixed = matches!(elems.get(d), Some(Elem { kind: Kind::Device { fixed_pose: true, .. } }));
                    let o = other_pin(elems, d, p)?;
                    if fixed || poses.contains_key(d.as_str()) && false {
                        return None;
                    }
                    let exit = Term::Pin(d.clone(), o);
                    let next: Vec<Term> = neighbours(&exit).into_iter().filter(|t| *t != prev).collect();
                    let n = next.first()?.clone();
                    prev = exit;
                    cur = n;
                }
                Term::Label(l) => return Some(syms.get(l).cloned().unwrap_or(None)),
                Term::Other(_) => return None,
            }
        }
        None
    };
    let mut done_labels: Vec<String> = Vec::new();
    let mut visited_parts: Vec<String> = Vec::new();
    // walk from a term leaving in direction `d`
    fn walk(
        elems: &HashMap<String, Elem>,
        syms: &HashMap<String, Option<String>>,
        poses: &mut HashMap<String, Pose>,
        from: &Term,
        d: Dir,
        neighbours: &dyn Fn(&Term) -> Vec<Term>,
        end_sym: &dyn Fn(&Term, &Term, &HashMap<String, Pose>) -> Option<Option<String>>,
        visited_parts: &mut Vec<String>,
        done_labels: &mut Vec<String>,
        depth: usize,
    ) {
        if depth > 200 {
            return;
        }
        for t in neighbours(from) {
            match &t {
                Term::Pin(dev, pin) => {
                    if is_anchor(elems, dev) || visited_parts.contains(dev) {
                        continue;
                    }
                    let two = matches!(elems.get(dev), Some(Elem { kind: Kind::Device { two_pin_part: true, .. } }));
                    if !two {
                        continue;
                    }
                    visited_parts.push(dev.clone());
                    let fixed = matches!(elems.get(dev), Some(Elem { kind: Kind::Device { fixed_pose: true, .. } }));
                    if !fixed {
                        let mut want = d.opposite();
                        if d.horizontal() {
                            match end_sym(&t, from, poses) {
                                Some(s) if gnd_like(&s) => want = Dir::U,
                                Some(s) if power_like(&s) => want = Dir::D,
                                _ => {}
                            }
                        }
                        let p = pose_for(elems, dev, pin, want);
                        poses.insert(dev.clone(), p);
                    }
                    if let Some(o) = other_pin(elems, dev, pin) {
                        if let Some(nd) = pin_dir(elems, poses, dev, &o) {
                            let exit = Term::Pin(dev.clone(), o);
                            walk(elems, syms, poses, &exit, nd, neighbours, end_sym, visited_parts, done_labels, depth + 1);
                        }
                    }
                }
                Term::Label(l) => {
                    let sym = syms.get(l).cloned().unwrap_or(None);
                    poses.insert(l.clone(), label_pose(&sym, d));
                    if !done_labels.contains(l) {
                        done_labels.push(l.clone());
                        walk(elems, syms, poses, &t, d, neighbours, end_sym, visited_parts, done_labels, depth + 1);
                    }
                }
                Term::Other(_) => {}
            }
        }
    }
    // anchors in wire order
    let mut starts: Vec<(Term, Dir)> = Vec::new();
    for (a, b) in hops {
        for t in [a, b] {
            if let Term::Pin(dev, pin) = t {
                if is_anchor(elems, dev) {
                    if let Some(d) = pin_dir(elems, poses, dev, pin) {
                        if !starts.iter().any(|s| s.0 == *t) {
                            starts.push((t.clone(), d));
                        }
                    }
                }
            }
        }
    }
    for (t, d) in starts {
        walk(elems, syms, poses, &t, d, &neighbours, &end_sym, &mut visited_parts, &mut done_labels, 0);
    }
}

