1	// Tables: |table|, |entity| and |title-block| — grid blocks whose bare
2	// strings flow into `|cell|`s. The label is a caption (table), a header band
3	// spanning the first row (entity) or dropped (title-block); a plain table's
4	// first row of text cells becomes the `.lini-header` band; `align:` /
5	// `justify:` lists read one value per column as `.lini-align-*` /
6	// `.lini-justify-*` classes on every auto-placed cell; a title-block grows
7	// one `field` cell per ISO 7200 property.
8	
9	use crate::ast::*;
10	use crate::diag::{Diag, Span};
11	use crate::eval::Env;
12	use crate::scene::{Builder, Node};
13	use crate::types::Prim;
14	
15	pub fn is_table(chain: &[String]) -> bool {
16	    chain.iter().any(|c| c == "table")
17	}
18	
19	fn has(chain: &[String], t: &str) -> bool {
20	    chain.iter().any(|c| c == t)
21	}
22	
23	// The pseudo-type classes tables put on their cells: (property, value).
24	// They cascade below everything else (a user's |block| rule still wins).
25	pub fn pseudo_class(t: &str) -> Option<(&'static str, &'static str)> {
26	    match t {
27	        "align-start" => Some(("align", "start")),
28	        "align-end" => Some(("align", "end")),
29	        "justify-start" => Some(("justify", "start")),
30	        "justify-end" => Some(("justify", "end")),
31	        _ => None,
32	    }
33	}
34	
35	pub fn pseudo_value(v: &str) -> Value {
36	    Value { groups: vec![vec![Term::Ident(v.to_string(), Span::default())]], span: Span::default() }
37	}
38	
39	// Parse a declaration list written by the lowering (not user text).
40	pub fn parse_decls(src: &str) -> Vec<Decl> {
41	    let full = format!("{{{}}}", src);
42	    let lexed = match crate::lexer::lex(&full) {
43	        Ok(l) => l,
44	        Err(_) => return vec![],
45	    };
46	    let mut p = crate::parser::Parser::new(&lexed.tokens, &full);
47	    match p.parse_style_block() {
48	        Ok((decls, _)) => decls
49	            .into_iter()
50	            .map(|mut d| {
51	                d.span = Span::default();
52	                d.name_span = Span::default();
53	                d.value.span = Span::default();
54	                d
55	            })
56	            .collect(),
57	        Err(_) => vec![],
58	    }
59	}
60	
61	fn set_decl(decls: &mut Vec<Decl>, d: Decl) {
62	    decls.retain(|e| e.name != d.name);
63	    decls.push(d);
64	}
65	
66	// Number of column tracks a `columns:` value declares.
67	pub fn track_count(env: &Env, v: &Value) -> usize {
68	    let mut n = 0usize;
69	    for g in &v.groups {
70	        for t in g {
71	            match t {
72	                Term::Ident(s, _) if s == "auto" => n += 1,
73	                Term::Call(name, args, _) if name == "repeat" => {
74	                    let k = args
75	                        .first()
76	                        .and_then(|a| env.eval(a, &Default::default()).ok())
77	                        .and_then(|x| x.num())
78	                        .unwrap_or(1.0);
79	                    n += k.max(0.0) as usize;
80	                }
81	                _ => {
82	                    if crate::style::term_num(env, t).is_some() {
83	                        n += 1;
84	                    }
85	                }
86	            }
87	        }
88	    }
89	    n
90	}
91	
92	fn get<'a>(props: &'a [(String, Value)], k: &str) -> Option<&'a Value> {
93	    props.iter().rev().find(|e| e.0 == k).map(|e| &e.1)
94	}
95	
96	// The keyword list of an `align:` / `justify:` value, one entry per group.
97	fn keyword_list(v: &Value) -> Vec<String> {
98	    v.groups
99	        .iter()
100	        .map(|g| match g.first() {
101	            Some(Term::Ident(s, _)) => s.clone(),
102	            _ => String::new(),
103	        })
104	        .collect()
105	}
106	
107	// ISO 7200 title-block fields: (property, caption), in grid order.
108	pub const FIELDS: &[(&str, &str)] = &[
109	    ("title", "Title"),
110	    ("drawing-number", "Dwg No."),
111	    ("revision", "Rev"),
112	    ("sheet-number", "Sheet"),
113	    ("date", "Date"),
114	    ("author", "Drawn"),
115	    ("approved", "Approved"),
116	    ("department", "Dept"),
117	    ("reference", "Reference"),
118	    ("document-type", "Type"),
119	    ("status", "Status"),
120	];
121	
122	// A cell lowered from a bare string: |block| .lini-cell.lini-block [ "text" ].
123	fn string_cell(b: &mut Builder, t: &TextStmt, parent: usize) -> Result<usize, Diag> {
124	    b.check_classes(&t.classes, t.span)?;
125	    let cell = Node::new(Prim::Block, vec!["cell".to_string(), "block".to_string()], t.span);
126	    let ci = b.add(cell, Some(parent));
127	    if !t.text.is_empty() {
128	        b.text_node(&t.text, &t.classes, t.style.as_ref(), t.span, ci);
129	    }
130	    Ok(ci)

