exec(open('/tmp/chart/smoothfit2.py').read().split('cases = json.load')[0])
import json
cases = json.load(open('/tmp/chart/smoothruns.json'))
def herm(y0,y1,m0,m1,hh,t):
    t2=t*t; t3=t2*t
    return (2*t3-3*t2+1)*y0+(t3-2*t2+t)*hh*m0+(-2*t3+3*t2)*y1+(t3-t2)*hh*m1
def ymap(v,lo,hi,pt,pb,k):
    f=(v-lo)/(hi-lo)
    if k==0: return pb-f*(pb-pt)
    if k==1: return pb-(v-lo)*(pb-pt)/(hi-lo)
    if k==2: return pb+f*(pt-pb)
def xmap(v,lo,hi,pl,pr,k):
    if k==0: return pl+(v-lo)/(hi-lo)*(pr-pl)
    if k==1: return pl+(v-lo)*(pr-pl)/(hi-lo)
eps=1e-9
for mode in range(3):
 for yk in range(3):
  for xk in range(2):
    bad=0; badl=[]
    for ci,c in enumerate(cases):
        xs,ys=c['xs'],c['ys']; pl,pr,pt,pb=c['pl'],c['pr'],c['pt'],c['pb']
        lo,hi=min(xs),max(xs); mx=max(ys); st=nice_step(mx); yhi=math.ceil(snap(mx/st))*st
        XD=[float(x) for x in xs]; YD=[float(y) for y in ys]
        X=[xmap(x,lo,hi,pl,pr,xk) for x in xs]; Y=[ymap(y,0,yhi,pt,pb,yk) for y in ys]
        if mode==0:
            m,h=tangents(XD,YD)
            pts=[(X[0],Y[0])]
            for k in range(len(X)-1):
                for j in range(1,17):
                    t=j/16
                    xd=XD[k]+h[k]*t
                    yd=herm(YD[k],YD[k+1],m[k],m[k+1],h[k],t)
                    pts.append((xmap(xd,lo,hi,pl,pr,xk), ymap(yd,0,yhi,pt,pb,yk)))
        elif mode==1:
            m,h=tangents(X,Y)
            pts=[(X[0],Y[0])]
            for k in range(len(X)-1):
                for j in range(1,17):
                    t=j/16
                    xd=XD[k]+(XD[k+1]-XD[k])*t
                    pts.append((xmap(xd,lo,hi,pl,pr,xk), herm(Y[k],Y[k+1],m[k],m[k+1],h[k],t)))
        else:
            m,h=tangents(X,Y)
            pts=[(X[0],Y[0])]
            for k in range(len(X)-1):
                for j in range(1,17):
                    t=j/16
                    pts.append((X[k]+(X[k+1]-X[k])*t, herm(Y[k],Y[k+1],m[k],m[k+1],h[k],t)))
        runs=[len(r) for r in clip_runs(pts,[pl-eps,pt-eps,pr+eps,pb+eps])]
        if runs!=c['runs']: bad+=1; badl.append(ci)
    print(mode,yk,xk,'bad',bad,badl[:12])
"

