#!/usr/bin/env python3
# random pen programs: compare original vs ours
import random, subprocess, os, tempfile, sys
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 200
ctxs = ['plain', 'drawing', 'stack']
def num(lo, hi, dec=2):
    return round(random.uniform(lo, hi), dec)
def prog():
    cmds = ['move(%s, %s)' % (num(-20, 20), num(-20, 20))]
    k = random.randint(1, 7)
    closed = False
    for _ in range(k):
        c = random.choice(['up', 'down', 'left', 'right', 'line', 'angle', 'arc2', 'arc3', 'curve', 'circle', 'chamfer', 'fillet'])
        if c in ('up', 'down', 'left', 'right'):
            cmds.append('%s(%s)' % (c, num(1, 30)))
        elif c == 'line':
            cmds.append('line(%s, %s)' % (num(-20, 20), num(-20, 20)))
        elif c == 'angle':
            cmds.append('angle(%s, %s)' % (random.choice([0, 30, 45, 60, 90, 120, 135, 180, 210, 270, 300, 315, num(0, 360, 1)]), num(1, 20)))
        elif c == 'arc2':
            cmds.append('arc(%s, %s)' % (num(1, 15), random.choice([90, -90, 45, -45, 180, 135, -135, num(-300, 300, 1)])))
        elif c == 'arc3':
            dx, dy = num(-15, 15), num(-15, 15)
            r = ((dx * dx + dy * dy) ** 0.5) / 2 + num(0, 10)
            cmds.append('arc(%s, %s, %s)' % (dx, dy, round(r * random.choice([1, -1]), 2)))
        elif c == 'curve':
            cmds.append('curve(%s, %s, %s, %s, %s, %s)' % tuple(num(-15, 15) for _ in range(6)))
        elif c == 'circle':
            cmds.append('circle(%s)' % num(1, 8))
        elif c == 'chamfer':
            cmds.append('chamfer(%s)' % num(0.5, 3))
        elif c == 'fillet':
            cmds.append('fillet(%s)' % num(0.5, 3))
    if random.random() < 0.5:
        cmds.append('close()')
        if random.random() < 0.3:
            cmds.append(random.choice(['chamfer(1)', 'fillet(1)']))
    return ' '.join(cmds)
def src():
    d = prog()
    extra = ''
    r = random.random()
    if r < 0.25:
        extra = ' mirror: %s;' % random.choice(['x-axis', 'y-axis', 'x-axis y-axis', '45', '30'])
    elif r < 0.35:
        extra = ' revolve: x-axis;'
    ctx = random.choice(ctxs)
    node = '|sketch| { draw: %s;%s }' % (d, extra)
    if ctx == 'drawing':
        return '|drawing| [ %s ]' % node
    if ctx == 'stack':
        return '{ layout: stack }\n' + node
    return node
tmp = tempfile.mkdtemp(prefix='fz_')
bad = 0
for n in range(N):
    s = src()
    p = os.path.join(tmp, 'r_in.lini')
    open(p, 'w').write(s + '\n')
    r1 = subprocess.run(['/workspace/executable', 'r_in.lini'], capture_output=True, cwd=tmp)
    r2 = subprocess.run(['/tmp/bin-sketch/executable', 'r_in.lini'], capture_output=True, cwd=tmp)
    if (r1.stdout, r1.stderr, r1.returncode) != (r2.stdout, r2.stderr, r2.returncode):
        bad += 1
        if bad <= 8:
            print('### MISMATCH', s)
            a = (r1.stderr + r1.stdout).decode().split('\n')
            b = (r2.stderr + r2.stdout).decode().split('\n')
            import difflib
            for line in list(difflib.unified_diff(a, b, n=0, lineterm=''))[2:10]:
                if '.lini-scope' in line and 'lini-node' not in line:
                    continue
                print('   ', line[:250])
print('mismatches %d / %d' % (bad, N))

