use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
fn main() {
    let mut h = DefaultHasher::new();
    h.write(b"");
    println!("{:x}", h.finish());
    let mut h = DefaultHasher::new();
    "abc".hash(&mut h);
    println!("{:x}", h.finish());
    let mut h = DefaultHasher::new();
    (1.5f64).to_bits().hash(&mut h);
    println!("{:x}", h.finish());
}

