import sys,struct,itertools
sys.path.insert(0,'/tmp/link')
from sip import Sip13
T=int('05ddd672',16)
T4=int('61ec26de',16)
def outs(h):
    return {'lo':h&0xffffffff,'hi':h>>32,'fold':((h>>32)^h)&0xffffffff}
def check(h,label):
    for k,v in outs(h).items():
        if v==T: print('FOUND',label,k)
def fb(v): return struct.pack('<d',float(v))
def ub(v): return struct.pack('<Q',v)
items={'B':(-20,-2,40,4),'C':(-3,-6.5,6,13),'P':(-18,0,18,0),'S':(2,),'F':(10,),'L':(0,0),'Bx':(-20,-2,20,2),'Cx':(-3,-6.5,3,6.5),'W':(0,),'A':(0.5,)}
keys=list(items)
n=0
# raw f64 sequences, with/without length prefixes
for r in (1,2,3):
    for combo in itertools.permutations(keys,r):
        vals=[x for k in combo for x in items[k]]
        for mode in ('raw','lenpre','perlen'):
            h=Sip13()
            if mode=='raw':
                for x in vals: h.write(fb(x))
            elif mode=='lenpre':
                h.write(ub(len(vals)))
                for x in vals: h.write(fb(x))
            else:
                for k in combo:
                    h.write(ub(len(items[k])))
                    for x in items[k]: h.write(fb(x))
            n+=1
            check(h.finish(),(combo,mode))
# strings
def disp(v):
    v=float(v)
    return '%d'%v if v==int(v) else repr(v)
def dbg(v): return repr(float(v))
def f4(v):
    s='%.4f'%v
    s=s.rstrip('0').rstrip('.') if '.' in s else s
    return '0' if s=='-0' else s
inner='<rect class="lini-cut-bg" x="-20" y="-2" width="40" height="4"/><rect class="lini-cut" x="-3" y="-6.5" width="6" height="13"/>'
strs=[inner]
for f in (disp,dbg,f4):
    for s1 in [',',' ',';','|',':','']:
        tok={k:s1.join(f(x) for x in v) for k,v in items.items()}
        for r in (1,2,3):
            for combo in itertools.permutations(keys,r):
                for s2 in [',',' ',';','|',':','','\n','/']:
                    strs.append(s2.join(tok[k] for k in combo))
for s in strs:
    for term in (True,False):
        h=Sip13(); h.write(s.encode())
        if term: h.write(b'\xff')
        n+=1
        check(h.finish(),(s,term))
print('tried',n)

