#!/usr/bin/env python3
# random drawing / stack layouts: compare original vs ours
import random, subprocess, os, tempfile, sys, difflib
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 100
def num(lo, hi, dec=1):
    return round(random.uniform(lo, hi), dec)
def part(depth=0):
    k = random.choice(['rect', 'hole', 'sketch', 'hidden', 'oval', 'box', 'centerline', 'textbox'])
    tr = '' if random.random() < 0.5 else ' translate: %s %s;' % (num(-20, 20), num(-20, 20))
    pat = ''
    if random.random() < 0.2:
        if random.random() < 0.5:
            pat = ' pattern: grid(%d, %d, %s, %s);' % (random.randint(1, 3), random.randint(1, 3), num(2, 10), num(2, 10))
        else:
            pat = ' pattern: radial(%d, %s);' % (random.randint(2, 6), num(2, 10))
    if k == 'rect':
        kids = ''
        if depth < 1 and random.random() < 0.5:
            kids = ' [\n' + '\n'.join(part(depth + 1) for _ in range(random.randint(1, 2))) + '\n]'
        return '|rect| { width: %s; height: %s;%s%s }%s' % (num(5, 40), num(5, 30), tr, pat, kids)
    if k == 'hole':
        th = '' if random.random() < 0.7 else ' thread: %s;' % num(0.5, 2)
        return '|hole| { width: %s;%s%s%s }' % (num(2, 8), tr, pat, th)
    if k == 'oval':
        return '|oval| { width: %s; height: %s;%s%s }' % (num(2, 20), num(2, 20), tr, pat)
    if k == 'box':
        return '|box| "%s" {%s%s }' % (random.choice(['a', 'bb', 'label']), tr, pat)
    if k == 'textbox':
        return '"%s" {%s }' % (random.choice(['note', 'x']), tr)
    if k == 'centerline':
        return '|centerline| { points: %s %s, %s %s; }' % (num(-20, 0), num(-20, 20), num(0, 20), num(-20, 20))
    t = 'sketch' if k == 'sketch' else 'hidden'
    x0, y0 = num(-20, 0), num(-10, 0)
    d = 'move(%s, %s) right(%s) down(%s)' % (x0, y0, num(5, 30), num(3, 15))
    extra = ''
    r = random.random()
    if r < 0.2:
        d += ' close()'
    elif r < 0.4:
        extra = ' mirror: %s;' % random.choice(['x-axis', 'y-axis'])
    kids = ''
    if depth < 1 and random.random() < 0.4:
        kids = ' [\n' + '\n'.join(part(depth + 1) for _ in range(random.randint(1, 2))) + '\n]'
    return '|%s| { draw: %s;%s%s%s }%s' % (t, d, extra, tr, pat, kids)
def src():
    parts = '\n'.join(part() for _ in range(random.randint(1, 3)))
    r = random.random()
    if r < 0.3:
        return '{ layout: drawing%s }\n%s' % (random.choice(['', '; scale: 0.5', '; density: 2', '; padding: 5']), parts)
    if r < 0.5:
        return '{ layout: stack%s }\n%s' % (random.choice(['', '; unit: mm', '; unit: cm; density: 1']), parts)
    if r < 0.8:
        lab = random.choice(['', ' "VIEW"'])
        return '|drawing|%s {%s } [\n%s\n]\n|box| "after"' % (lab, random.choice(['', ' scale: 2;', ' unit: cm; scale: 0.2;']), parts)
    return '|stack| {%s } [\n%s\n]' % (random.choice(['', ' unit: mm;']), parts)
tmp = tempfile.mkdtemp(prefix='fz2_')
bad = 0
for n in range(N):
    s = src()
    p = os.path.join(tmp, 'r_in.lini')
    open(p, 'w').write(s + '\n')
    r1 = subprocess.run(['/workspace/executable', 'r_in.lini'], capture_output=True, cwd=tmp)
    r2 = subprocess.run(['/tmp/bin-sketch/executable', 'r_in.lini'], capture_output=True, cwd=tmp)
    if (r1.stdout, r1.stderr, r1.returncode) != (r2.stdout, r2.stderr, r2.returncode):
        bad += 1
        if bad <= 6:
            print('### MISMATCH\n' + s)
            a = (r1.stderr + r1.stdout).decode().split('\n')
            b = (r2.stderr + r2.stdout).decode().split('\n')
            for line in list(difflib.unified_diff(a, b, n=0, lineterm=''))[2:14]:
                if '.lini-scope' in line and 'lini-node' not in line:
                    continue
                print('   ', line[:250])
print('mismatches %d / %d' % (bad, N))

