fn emit_link(&mut self, p: Pending, scope: usize, sc: &mut Scopes, out: &mut Vec<Item>) {
        let mut before = Vec::new();
        let mut after = Vec::new();
        let mut first = true;
        for g in &p.groups {
            for ep in g {
                let decl = match ep {
                    Ep::Path { name, bare, .. } => {
                        let bare = *bare;
                        let known = sc.ids.get(&scope).map_or(false, |s| s.contains(name));
                        if bare && !known && !p.in_drawing {
                            sc.ids.entry(scope).or_default().insert(name.clone());
                            Some(self.auto_box(name))
                        } else {
                            None
                        }
                    }
                    Ep::Capsule { node, .. } => {
                        let mut n = node.clone();
                        n.gen = true;
                        Some(n)
                    }
                };
                if let Some(d) = decl {
                    if first {
                        before.push(Item::Node(d));
                    } else {
                        after.push(Item::Node(d));
                    }
                }
                first = false;
            }
        }
        out.extend(before);
        let gtext = |g: &Vec<Ep>| g.iter().map(|e| e.text().to_string()).collect::<Vec<_>>().join(" & ");
        let link_op = p.ops.first().map_or(false, |o| !(o.starts_with('(') || o == "||"));
        if p.groups.len() < 2 || !link_op {
            // one-ended, or a dimension / flush chain: one statement
            let mut head = gtext(&p.groups[0]);
            for (k, op) in p.ops.iter().enumerate() {
                head.push(' ');
                head.push_str(op);
                if let Some(g) = p.groups.get(k + 1) {
                    head.push(' ');
                    head.push_str(&gtext(g));
                }
            }
            out.push(Item::Link(OLink { head, classes: p.classes.clone(), decls: p.decls.clone(), labels: p.labels.clone() }));
        } else if p.groups.len() < 2 {
            let mut head = gtext(&p.groups[0]);
            if let Some(op) = p.ops.first() {
                head.push(' ');
                head.push_str(op);
            }
            out.push(Item::Link(OLink { head, classes: p.classes.clone(), decls: p.decls.clone(), labels: p.labels.clone() }));
        } else {
            for k in 0..p.groups.len() - 1 {
                let op = p.ops.get(k).cloned().unwrap_or_default();
                let head = format!("{} {} {}", gtext(&p.groups[k]), op, gtext(&p.groups[k + 1]));
                out.push(Item::Link(OLink {
                    head,
                    classes: p.classes.clone(),
                    decls: p.decls.clone(),
                    labels: p.labels.clone(),
                }));
            }
        }
        out.extend(after);
    }
}

_ => pts.to_vec(),
    }
}

// Monotone cubic through the points, 16 samples per segment.
pub fn smooth(pts: &[(f64, f64)]) -> Vec<(f64, f64)> {
    let n = pts.len();
    if n < 3 {
        return pts.to_vec();
    }
    let mut sl = vec![0.0; n - 1];
    let mut hs = vec![0.0; n - 1];
    for k in 0..n - 1 {
        hs[k] = pts[k + 1].0 - pts[k].0;
        sl[k] = if hs[k] != 0.0 { (pts[k + 1].1 - pts[k].1) / hs[k] } else { 0.0 };
    }
    let mut m = vec![0.0; n];
    m[0] = sl[0];
    m[n - 1] = sl[n - 2];
    for k in 1..n - 1 {
        let (s0, s1) = (sl[k - 1], sl[k]);
        if s0 * s1 <= 0.0 {
            m[k] = 0.0;
        } else {
            let (h0, h1) = (hs[k - 1], hs[k]);
            let p = (s0 * h1 + s1 * h0) / (h0 + h1);
            m[k] = (s0.signum() + s1.signum()) * s0.abs().min(s1.abs()).min(0.5 * p.abs());
        }
    }
    let mut out = vec![pts[0]];
    for k in 0..n - 1 {
        let (x0, y0) = pts[k];
        let (x1, y1) = pts[k + 1];
        let h = x1 - x0;
        let c1 = (x0 + h / 3.0, y0 + m[k] * h / 3.0);
        let c2 = (x1 - h / 3.0, y1 - m[k + 1] * h / 3.0);
        let _ = (c1.0, c2.0);
        for j in 1..=16 {
            let t = j as f64 / 16.0;
            let u = 1.0 - t;
            let x = x0 + h * t;
            let y = u * u * u * y0 + 3.0 * u * u * t * c1.1 + 3.0 * u * t * t * c2.1 + t * t * t * y1;
            out.push((x, y));
        }
    }
    out
}

