new='''// Monotone cubic (Fritsch–Carlson) through the points, 16 samples per
// segment, evaluated in Hermite form.
pub fn smooth(pts: &[(f64, f64)]) -> Vec<(f64, f64)> {
    let n = pts.len();
    if n < 3 {
        return pts.to_vec();
    }
    let mut d = vec![0.0; n - 1];
    let mut hs = vec![0.0; n - 1];
    for k in 0..n - 1 {
        hs[k] = pts[k + 1].0 - pts[k].0;
        d[k] = (pts[k + 1].1 - pts[k].1) / hs[k];
    }
    let mut m = vec![0.0; n];
    m[0] = d[0];
    m[n - 1] = d[n - 2];
    for k in 1..n - 1 {
        m[k] = if d[k - 1] * d[k] <= 0.0 { 0.0 } else { (d[k - 1] + d[k]) / 2.0 };
    }
    for k in 0..n - 1 {
        if d[k] == 0.0 {
            m[k] = 0.0;
            m[k + 1] = 0.0;
            continue;
        }
        let a = m[k] / d[k];
        let b = m[k + 1] / d[k];
        let s = a * a + b * b;
        if s > 9.0 {
            let t = 3.0 / s.sqrt();
            m[k] = t * a * d[k];
            m[k + 1] = t * b * d[k];
        }
    }
    let mut out = vec![pts[0]];
    for k in 0..n - 1 {
        let (x0, y0) = pts[k];
        let (_, y1) = pts[k + 1];
        let h = hs[k];
        for j in 1..=16 {
            let t = j as f64 / 16.0;
            let t2 = t * t;
            let t3 = t2 * t;
            let x = x0 + h * t;
            let y = (2.0 * t3 - 3.0 * t2 + 1.0) * y0 + (t3 - 2.0 * t2 + t) * h * m[k] + (-2.0 * t3 + 3.0 * t2) * y1 + (t3 - t2) * h * m[k + 1];
            out.push((x, y));
        }
    }
    out
}
