import sys,itertools,struct
sys.path.insert(0,'/tmp/link')
from sip import Sip13
def fnv64(s):
    h=0xcbf29ce484222325
    for b in s:
        h^=b; h=(h*0x100000001b3)&0xffffffffffffffff
    return h
T=0x05ddd672
def outs(b):
    h=fnv64(b); r=[((h>>32)^h)&0xffffffff,h&0xffffffff,h>>32]
    s=Sip13(); s.write(b); h=s.finish(); r+=[((h>>32)^h)&0xffffffff,h&0xffffffff,h>>32]
    return r
def disp(v):
    v=float(v)
    if v==0: return '0' if str(v)[0]!='-' else '-0'
    return '%d'%v if v==int(v) else repr(v)
def d(v): return repr(float(v))
items={
 'bg':(-20,-2,40,4),'bgx':(-20,-2,20,2),'bgc':(0,0,40,4),'bgch':(0,0,20,2),
 'cut':(-3,-6.5,6,13),'cutx':(-3,-6.5,3,6.5),'cutc':(0,0,6,13),'cutch':(0,0,3,6.5),
 'tb':(0,-5,0,10),'tbx':(0,-5,0,5),'tbc':(0,0,0,10),'lab':(0,0),'labw':(0,0,0),'labwf':(0,0,0,10),
 'pts':(-18,0,18,0),'m':(2,),'sw':(2,),'fs':(10,),'pad':(3,6.5),'n':(1,),
}
keys=list(items)
n=0
for fn in (disp,d):
    for s1 in [',',' ',';','|',':','']:
        tok={k:s1.join(fn(v) for v in vals) for k,vals in items.items()}
        for r in (1,2,3):
            for combo in itertools.permutations(keys,r):
                for s2 in [',',' ',';','|',':','','\n','/']:
                    s=s2.join(tok[k] for k in combo)
                    n+=1
                    if T in outs(s.encode()): print('FOUND',combo,repr(s))
print('tried',n)

