p='/workspace/.claude/worktrees/agent-ad2150fa1d2782cee/src/route.rs'
s=open(p).read()
i=s.index('// Centre staircase segments in their channel.')
j=s.index('// Natural routing: an S-curve between two facing side centres')
new='''// The interval a free segment can slide in, measured where it starts: its
// neighbours' far ends bound it, and so do the inflated obstacles beside its
// starting point. Infinite where nothing bounds it.
pub fn free_interval(solids: &[Rect], pts: &[(f64, f64)], j: usize) -> (f64, f64) {
    let p = pts[j];
    let q = pts[j + 1];
    let vertical = (p.0 - q.0).abs() < 1e-9;
    let pos = if vertical { p.0 } else { p.1 };
    let mut lo = f64::NEG_INFINITY;
    let mut hi = f64::INFINITY;
    for far in [pts[j - 1], pts[j + 2]] {
        let f = if vertical { far.0 } else { far.1 };
        if f < pos - 1e-9 && f > lo {
            lo = f;
        }
        if f > pos + 1e-9 && f < hi {
            hi = f;
        }
    }
    let at = if vertical { p.1 } else { p.0 };
    for r in solids {
        let (a0, a1, b0, b1) = if vertical { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
        if !(at > a0 + EPS && at < a1 - EPS) {
            continue;
        }
        if b1 <= pos + EPS && b1 > lo {
            lo = b1;
        }
        if b0 >= pos - EPS && b0 < hi {
            hi = b0;
        }
    }
    (lo, hi)
}

// Free segments settle midway in their channel when it is closed on both
// sides where they start; otherwise they keep hugging what they go around.
pub fn centre_staircases(env: &Env, pts: &mut Vec<(f64, f64)>) {
    let solids = env.solids();
    let n = pts.len();
    if n < 4 {
        return;
    }
    for i in 1..n - 2 {
        let (lo, hi) = free_interval(&solids, pts, i);
        if !lo.is_finite() || !hi.is_finite() {
            continue;
        }
        let m = (lo + hi) / 2.0;
        let vertical = (pts[i].0 - pts[i + 1].0).abs() < 1e-9;
        if vertical {
            pts[i].0 = m;
            pts[i + 1].0 = m;
        } else {
            pts[i].1 = m;
            pts[i + 1].1 = m;
        }
    }
}

'''
s=s[:i]+new+s[j:]
open(p,'w').write(s)
print('ok')

