chars=string.ascii_lowercase+string.ascii_uppercase+string.digits
w={c:round(tw(c,11,400),6) for c in chars}
pairs={}
for a,b in itertools.combinations_with_replacement(chars,2):
    s=round(w[a]+w[b],6)
    pairs.setdefault(s,[]).append(a+b)
n=0
for s,l in pairs.items():
    # need two pairs with no shared multiset
    if len(l)>=2:
        print(s,l[:6]); n+=1
    if n>8: break
"

