seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
show = int(sys.argv[3]) if len(sys.argv) > 3 else 3
rnd = random.Random(seed)
d = '/tmp/desugar/drawfuzz'
os.makedirs(d, exist_ok=True)

def draw():
    segs = []
    for _ in range(rnd.randint(1, 3)):
        seg = 'move(%d, %d)' % (rnd.randint(-20, 20), rnd.randint(-20, 20))
        for _ in range(rnd.randint(1, 4)):
            seg += ' ' + rnd.choice(['up(5)', 'right(10)', 'down(3)', 'left(4)', 'fillet(2)', 'chamfer(1)', 'right(8):a', 'circle(4)'])
        if rnd.random() < 0.4:
            seg += ' close()'
        segs.append(seg)
    return ' '.join(segs)

def part(depth, ids):
    t = rnd.choice(['sketch', 'sketch', 'hidden', 'hole', 'rect', 'oval', 'plane', 'magnifier', 'centerline', 'box', 'note', 'balloon', 'feature-control', 'datum', 'surface-finish', 'pitch-circle'])
    i = 'p%d' % len(ids)
    ids.append(i)
    decls = []
    if t in ('sketch', 'hidden'):
        decls.append('draw: %s;' % draw())
        for opt in ['revolve: x-axis;', 'mirror: x-axis;', 'mirror: y-axis;', 'thread: m8 1.25;', 'break: -5 5;']:
            if rnd.random() < 0.25:
                decls.append(opt)
    elif t == 'hole':
        decls.append('width: %d;' % rnd.choice([4, 8]))
        if rnd.random() < 0.4:
            decls.append(rnd.choice(['pattern: radial(6, 14);', 'pattern: grid(2, 2, 10, 10);', 'thread: 1.25;', 'thread: m6;']))
    elif t in ('rect', 'oval', 'box'):
        decls.append('width: %d; height: %d;' % (rnd.randint(10, 60), rnd.randint(10, 40)))
    elif t == 'plane':
        decls.append('at: 0;')
    lab = ' "%s"' % rnd.choice(['A', 'B', 'pos']) if rnd.random() < 0.4 else ''
    s = '|%s#%s|%s { %s }' % (t, i, lab, ' '.join(decls)) if decls else '|%s#%s|%s' % (t, i, lab)
    if depth < 2 and t in ('rect', 'sketch', 'box') and rnd.random() < 0.3:
        s += ' [ ' + '; '.join(part(depth + 1, ids) for _ in range(rnd.randint(1, 2))) + ' ]'
    return s

def drawing(ids, nested=False):
    t = rnd.choice(['drawing', 'drawing', 'floorplan'])
    decls = []
    if rnd.random() < 0.3:
        decls.append('unit: %s;' % rnd.choice(['mm', 'cm', 'm', 'in', 'px']))
    if rnd.random() < 0.2:
        decls.append('scale: 0.5;')
    if rnd.random() < 0.15:
        decls.append('of: p0;')
    lab = ' "VIEW"' if rnd.random() < 0.3 else ''
    body = []
    if t == 'floorplan':
        if rnd.random() < 0.3:
            decls.append('thickness: 150;')
        for k in range(rnd.randint(1, 3)):
            w = 'w%d' % k
            kids = []
            for _ in range(rnd.randint(0, 2)):
                kind = rnd.choice(['door', 'window', 'door'])
                ex = rnd.choice(['', ' symbol: double;', ' symbol: sliding;', ' swing: right;'])
                kids.append('|%s| { on: run; at: 1;%s }' % (kind, ex))
            wt = rnd.choice(['wall', 'wall', 'partition'])
            body.append('|%s#%s| { draw: move(0, %d) right(4):run; }%s' % (wt, w, k, (' [ ' + '; '.join(kids) + ' ]') if kids else ''))
        for _ in range(rnd.randint(0, 2)):
            body.append(rnd.choice(['|stairs| { steps: %d; }' % rnd.randint(0, 6), '|bed| "queen"', '|bath| { symbol: tub; }', '|appliance| "F" { symbol: fridge; }', '|sofa|']))
    else:
        for _ in range(rnd.randint(1, 4)):
            body.append(part(0, ids))
        if len(ids) >= 2 and rnd.random() < 0.6:
            a, b = rnd.sample(ids, 2)
            body.append(rnd.choice(['%s:left (-) %s:right { side: bottom; }' % (a, b), '%s (o)' % a, '%s:top <- "note"' % a, '%s -> %s' % (a, b), 'zz -> %s' % a]))
    head = '|%s|%s' % (t, lab)
    if decls:
        head += ' { ' + ' '.join(decls) + ' }'
    return head + ' [\n  ' + '\n  '.join(body) + '\n]'

def gen():
    ids = []
    sheet = []
    if rnd.random() < 0.3:
        sheet.append(rnd.choice(['layout: drawing;', 'density: 5;', 'unit: cm;', 'layout: floorplan;']))
    src = ('{ ' + ' '.join(sheet) + ' }\n') if sheet else ''
    if rnd.random() < 0.3:
        tb = '|title-block| { title: "T"; author: "A"; }' if rnd.random() < 0.5 else ''
        sh = rnd.choice(['', ' { sheet: a3; }', ' { sheet: a4 landscape; }'])
        src += '|page|%s [\n' % sh + drawing(ids) + '\n' + tb + '\n]\n'
    else:
        if sheet and 'layout' in sheet[0] and rnd.random() < 0.5:
            for _ in range(rnd.randint(1, 3)):
                src += part(0, ids) + '\n'
        else:
            src += drawing(ids) + '\n'
    return src

ok = 0; bad = []
for i in range(n):
    src = gen()
    p = os.path.join(d, 'g.lini')
    open(p, 'w').write(src)
    r1 = subprocess.run(['/workspace/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run(['/tmp/bin-desugar/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    if (r1.stdout, r1.stderr, r1.returncode) == (r2.stdout, r2.stderr, r2.returncode):
        ok += 1
    else:
        o1 = (r1.stdout + r1.stderr).decode().split('\n'); o2 = (r2.stdout + r2.stderr).decode().split('\n')
        dl = list(difflib.unified_diff(o1, o2, 'orig', 'mine', lineterm='', n=1))
        bad.append((src, dl, r1.returncode))
print('OK', ok, '/', n, ' (orig errors among fails: %d)' % sum(1 for b in bad if b[2] != 0))
for src, dl, rc in bad[:show]:
    print('=' * 30)
    print(src)
    print('\n'.join(dl[2:30]))

