                    let mut p0 = at(0.0);
                    for k in 1..=n {
                        let t1 = k as f64 / n as f64;
                        let p1 = if k == n { g.end() } else { at(t1) };
                        let (x0, x1) = (ax(p0), ax(p1));
                        let (lo, hi) = (x0.min(x1), x0.max(x1));
                        if lo < hi && lo <= v && v < hi {
                            let (mut a0, mut a1) = ((k - 1) as f64 / n as f64, t1);
                            let up = x1 > x0;
                            for _ in 0..60 {
                                let m = (a0 + a1) / 2.0;
                                if (ax(at(m)) < v) == up {
                                    a0 = m;
                                } else {
                                    a1 = m;
                                }
                            }
                            let q = if x0 == v { p0 } else { at((a0 + a1) / 2.0) };
                            out.push(other(q));
                        }
                        p0 = p1;
                    }
                }
            }
        }
    }
    out
}

