import subprocess,sys,os,re,tempfile
def run(src):
    d=tempfile.mkdtemp(prefix='/tmp/link/rr.')
    open(d+'/r_in.lini','w').write(src)
    r=subprocess.run(['/workspace/executable','r_in.lini'],capture_output=True,cwd=d)
    return r.stdout.decode(), r.stderr.decode()
tpl=sys.argv[1]
for v in sys.argv[2:]:
    o,e=run(tpl.replace('{}',v))
    ps=re.findall(r'<path d="M ([^ ]*) ([^ ]*)',o)
    tr=dict(re.findall(r'data-id="([^"]*)"[^>]*transform="translate\(([^)]*)\)',o))
    ax,ay=map(float,tr['a'].split(','))
    sides=[]
    for x,y in ps:
        x=float(x); y=float(y)
        if abs(y-ay)<0.01 and x>ax: sides.append('R')
        elif abs(y-ay)<0.01 and x<ax: sides.append('L')
        elif y>ay: sides.append('B%+g'%(x-ax))
        else: sides.append('T%+g'%(x-ax))
    print(v, ' '.join(sides), e.strip()[:80])

