// Brute force: Debug-formatted structs / tuples / vecs of rects for the mask key.
use std::collections::hash_map::DefaultHasher;
use std::hash::Hasher;

fn fnv1a64(b: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &c in b {
        h ^= c as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}
fn check(b: &[u8], t: u32) -> bool {
    let h = fnv1a64(b);
    if ((h >> 32) ^ h) as u32 == t || h as u32 == t || (h >> 32) as u32 == t {
        return true;
    }
    for term in [false, true] {
        let mut s = DefaultHasher::new();
        s.write(b);
        if term {
            s.write_u8(0xff);
        }
        let h = s.finish();
        if ((h >> 32) ^ h) as u32 == t || h as u32 == t || (h >> 32) as u32 == t {
            return true;
        }
    }
    false
}

fn main() {
    let t: u32 = 0x05ddd672;
    // rect variants: (name, [values])
    let bg_vars: Vec<[f64; 4]> = vec![[-20.0, -2.0, 40.0, 4.0], [-20.0, -2.0, 20.0, 2.0], [0.0, 0.0, 40.0, 4.0], [0.0, 0.0, 20.0, 2.0]];
    let cut_vars: Vec<[f64; 4]> = vec![[-3.0, -6.5, 6.0, 13.0], [-3.0, -6.5, 3.0, 6.5], [0.0, 0.0, 6.0, 13.0], [0.0, 0.0, 3.0, 6.5], [0.0, -5.0, 0.0, 10.0], [0.0, 0.0, 0.0, 10.0]];
    let names = ["Rect", "Box", "BBox", "Bounds", "Aabb", "Cut", "Mask", "Area", "Frame", "R", "Rectangle", "LabelBox", "Hole", "Window", "Region", "Extent", "Bbox"];
    let fieldsets: Vec<[&str; 4]> = vec![
        ["x0", "y0", "x1", "y1"],
        ["x", "y", "w", "h"],
        ["x", "y", "width", "height"],
        ["left", "top", "right", "bottom"],
        ["min_x", "min_y", "max_x", "max_y"],
        ["cx", "cy", "w", "h"],
        ["x", "y", "hw", "hh"],
        ["l", "t", "r", "b"],
        ["minx", "miny", "maxx", "maxy"],
        ["xmin", "ymin", "xmax", "ymax"],
        ["x_min", "y_min", "x_max", "y_max"],
        ["x1", "y1", "x2", "y2"],
        ["left", "top", "width", "height"],
    ];
    let mut n: u64 = 0;
    let st = |name: &str, f: &[&str; 4], v: &[f64; 4]| -> String { format!("{} {{ {}: {:?}, {}: {:?}, {}: {:?}, {}: {:?} }}", name, f[0], v[0], f[1], v[1], f[2], v[2], f[3], v[3]) };
    let tup = |v: &[f64; 4]| -> String { format!("({:?}, {:?}, {:?}, {:?})", v[0], v[1], v[2], v[3]) };
    let arr = |v: &[f64; 4]| -> String { format!("[{:?}, {:?}, {:?}, {:?}]", v[0], v[1], v[2], v[3]) };
    let mut reps_bg: Vec<String> = Vec::new();
    let mut reps_cut: Vec<String> = Vec::new();
    for b in &bg_vars {
        reps_bg.push(tup(b));
        reps_bg.push(arr(b));
        for nm in names.iter() {
            for f in &fieldsets {
                reps_bg.push(st(nm, f, b));
            }
        }
    }
    for c in &cut_vars {
        reps_cut.push(tup(c));
        reps_cut.push(arr(c));
        for nm in names.iter() {
            for f in &fieldsets {
                reps_cut.push(st(nm, f, c));
            }
        }
    }
    let wraps_two = [
        "({}, [{}])", "({}, {})", "[{}, {}]", "{}{}", "{} {}", "{}, [{}]", "{}[{}]", "{}|{}", "{};{}", "{}\n{}", "{},{}", "({}, vec![{}])",
        "Mask {{ bg: {}, cuts: [{}] }}", "Mask {{ rect: {}, cuts: [{}] }}", "Mask {{ bounds: {}, cuts: [{}] }}", "Mask {{ area: {}, holes: [{}] }}",
        "Mask {{ bbox: {}, cuts: [{}] }}", "Mask {{ frame: {}, cuts: [{}] }}", "Mask {{ r: {}, cuts: [{}] }}", "Mask {{ rect: {}, holes: [{}] }}",
        "Cut {{ bg: {}, cuts: [{}] }}", "({}, [{}], 2.0)", "(2.0, {}, [{}])",
    ];
    for b in &reps_bg {
        for c in &reps_cut {
            for w in wraps_two.iter() {
                // first {} = bg, second = cut ; also swapped
                let s1 = w.replacen("{}", b, 1).replacen("{}", c, 1).replace("{{", "{").replace("}}", "}");
                let s2 = w.replacen("{}", c, 1).replacen("{}", b, 1).replace("{{", "{").replace("}}", "}");
                n += 2;
                if check(s1.as_bytes(), t) {
                    println!("FOUND {:?}", s1);
                }
                if check(s2.as_bytes(), t) {
                    println!("FOUND {:?}", s2);
                }
            }
        }
    }
    for c in &reps_cut {
        for w in ["{}", "[{}]", "({},)", "vec![{}]"].iter() {
            let s = w.replacen("{}", c, 1);
            n += 1;
            if check(s.as_bytes(), t) {
                println!("FOUND {:?}", s);
            }
        }
    }
    eprintln!("tried {}", n);
}

