import subprocess, re, sys, os, glob
def f4(v):
    s = '%.4f' % v
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    if s == '-0':
        s = '0'
    return s
catpos = {
    'mine': lambda pl, pr, n, k: pl + (pr - pl) * ((k + 0.5) / n),
    'bandw': lambda pl, pr, n, k: pl + (pr - pl) / n * (k + 0.5),
    'bandw2': lambda pl, pr, n, k: pl + (k + 0.5) * ((pr - pl) / n),
    'mul': lambda pl, pr, n, k: pl + (pr - pl) * (k + 0.5) / n,
    'half': lambda pl, pr, n, k: pl + (pr - pl) / n * k + (pr - pl) / n / 2,
    'half2': lambda pl, pr, n, k: pl + (pr - pl) / n / 2 + (pr - pl) / n * k,
    'twok': lambda pl, pr, n, k: pl + (pr - pl) * (2 * k + 1) / (2 * n),
    'twok2': lambda pl, pr, n, k: pl + (pr - pl) * ((2 * k + 1) / (2 * n)),
    'lerp': lambda pl, pr, n, k: pl * (1 - (k + 0.5) / n) + pr * ((k + 0.5) / n),
}
interp = {
    'x0+h*t': lambda x0, x1, t: x0 + (x1 - x0) * t,
    'lerp': lambda x0, x1, t: (1 - t) * x0 + t * x1,
}
tot = {}
files = sys.argv[1:]
for f in files:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    orig = subprocess.run(['/workspace/executable', b], capture_output=True, cwd=d).stdout.decode()
    dbg = subprocess.run(['/tmp/bin-chart/executable', b], capture_output=True, cwd=d, env=dict(os.environ, LINI_DBG_SMOOTH='1')).stderr.decode()
    geo = [l.split()[1:] for l in dbg.splitlines() if l.startswith('GEO')]
    if not geo:
        continue
    pt, pb, lo, hi, pl, pr = [float(x) for x in geo[0][:6]]
    n = int(geo[0][6])
    polys = re.findall(r'<polyline points="([^"]*)"', orig)
    # the smooth series polyline has 16*(n-1)+1 points
    cand = [p for p in polys if len(p.split(' ')) == 16 * (n - 1) + 1]
    if not cand:
        continue
    opts = [p.split(',') for p in cand[0].split(' ')]
    for cn, cf in catpos.items():
        for iname, ifn in interp.items():
            key = cn + '|' + iname
            bad = 0
            xs = [cf(pl, pr, n, k) for k in range(n)]
            for k in range(n - 1):
                for j in range(0, 17):
                    if k > 0 and j == 0:
                        continue
                    t = j / 16
                    x = ifn(xs[k], xs[k + 1], t) if j > 0 else xs[k]
                    if f4(x) != opts[k * 16 + j][0]:
                        bad += 1
            tot[key] = tot.get(key, 0) + bad
for k, v in sorted(tot.items(), key=lambda e: e[1]):
    print(v, k)

