       """            let fixed = n.style.iter().any(|d| d.name == "rotate");
            let two = pins.len() == 2;
            Kind::Device { pins, two_pin_part: two, fixed_pose: fixed, part: false }""")
# C. the destination walk
sub(p, """    // the way a path through free two-pin parts must travel into its end:
    // down onto a ground, up into a supply, against a fixed pin's facing
    fn dest_dir(&self, entry: &Term, via: usize) -> Option<Dir> {
        let mut cur = entry.clone();
        let mut skip = via;
        let mut first = true;
        for _ in 0..64 {
            match &cur {
                Term::Pin(d, p) => {
                    if !first && (self.anchor(d) || self.fixed(d) || !self.two_pin(d)) {
                        // a tie back to the device the chain left hugs it
                        if self.origin.as_deref() == Some(d.as_str()) {
                            return None;
                        }
                        return self.pin_dir(d, p).map(|f| f.opposite());
                    }
                    first = false;
                    let o = self.other_pin(d, p)?;
                    let exit = Term::Pin(d.clone(), o);
                    let (i, next) = self.at(&exit, None).into_iter().find(|(i, _)| *i != skip)?;
                    skip = i;
                    cur = next;
                }
                Term::Label(l) => {
                    let s = self.syms.get(l).cloned().unwrap_or(None);
                    return if gnd_like(&s) {
                        Some(Dir::D)
                    } else if power_like(&s) {
                        Some(Dir::U)
                    } else {
                        None
                    };
                }
                Term::Other(_) => return None,
            }
        }
        None
    }""", """    fn stops(&self, dev: &str) -> bool {
        self.anchor(dev) || self.fixed(dev) || !self.two_pin(dev)
    }

    // the way a run must travel into its end, walking on from `t` (reached
    // over hop `via`) through free devices and plain labels: down onto a
    // ground, up into a supply, against a fixed pin's facing. At a junction
    // the latest wire leads; a tie back to the device the run left is no end.
    fn dest_dir(&self, t: &Term, via: usize) -> Option<Dir> {
        let mut cur = t.clone();
        let mut skip = via;
        for _ in 0..64 {
            let from = match &cur {
                Term::Pin(d, p) => Term::Pin(d.clone(), self.other_pin(d, p)?),
                Term::Label(_) => cur.clone(),
                Term::Other(_) => return None,
            };
            let mut next = None;
            for (i, n) in self.at(&from, Some(skip)).into_iter().rev() {
                if let Term::Pin(d, _) = &n {
                    if self.origin.as_deref() == Some(d.as_str()) && self.stops(d) {
                        continue;
                    }
                }
                next = Some((i, n));
                break;
            }
            let (i, n) = next?;
            match &n {
                Term::Pin(d, p) => {
                    if self.stops(d) {
                        return self.pin_dir(d, p).map(|f| f.opposite());
                    }
                }
                Term::Label(l) => {
                    let s = self.syms.get(l).cloned().unwrap_or(None);
                    if gnd_like(&s) {
                        return Some(Dir::D);
                    }
                    if power_like(&s) {
                        return Some(Dir::U);
                    }
                    if s.is_some() {
                        return None;
                    }
                }
                Term::Other(_) => return None,
            }
            skip = i;
            cur = n;
        }
        None
    }""")
