    1: lambda cb, g: (cb - 10.8) - 6.0 - g + 0.4,
    2: lambda cb, g: cb - (10.8 + 6.0 + g - 0.4),
    5: lambda cb, g: (cb - 10.8) - (6.0 + g - 0.4),
