    12: lambda cb, g: cb - (16.4 + g),
    14: lambda cb, g: (cb - 16.4) - g,
    15: lambda cb, g: cb - (10.8 + (6.0 + g - 0.4)),
    16: lambda cb, g: cb - (10.8 + (5.6 + g)),
}
# configs: heights and gaps
hs = [160, 180, 200, 220, 260, 270, 300, 157, 213, 240, 250, 280, 320, 330, 350, 400]
gs = [15.0, 7.3, 4.0, 21.7, 9.9, 0.0, 10.0, 12.0, 20.0, 5.0, 8.0, 3.3]
