    2: lambda cb, g: cb - (10.8 + 6.0 + g - 0.4),
    5: lambda cb, g: (cb - 10.8) - (6.0 + g - 0.4),
    11: lambda cb, g: (cb - 10.8) - (5.6 + g),
    12: lambda cb, g: cb - (16.4 + g),
    14: lambda cb, g: (cb - 16.4) - g,
    15: lambda cb, g: cb - (10.8 + (6.0 + g - 0.4)),
    16: lambda cb, g: cb - (10.8 + (5.6 + g)),
}
# configs: heights and gaps
hs = [160, 180, 200, 220, 260, 270, 300, 157, 213, 240, 250, 280, 320, 330, 350, 400]
gs = [15.0, 7.3, 4.0, 21.7, 9.9, 0.0, 10.0, 12.0, 20.0, 5.0, 8.0, 3.3]
for h in hs:
    for g in gs:
        cb = h / 2
        vals = {k: f(cb, g) for k, f in RB.items()}
        groups = {}
        for k, v in vals.items():
            groups.setdefault(v, []).append(k)
        if len(groups) > 1:
            print(h, g, {repr(v): ks for v, ks in groups.items()})

