// Mask-id key search: key = template(bg_rep, cut_rep) with many rect representations.
use std::collections::hash_map::DefaultHasher;
use std::hash::Hasher;

fn fnv(b: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &c in b {
        h ^= c as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}
fn outs(b: &[u8]) -> [u32; 9] {
    let h = fnv(b);
    let mut s = DefaultHasher::new();
    s.write(b);
    let g = s.finish();
    let mut s2 = DefaultHasher::new();
    s2.write(b);
    s2.write_u8(0xff);
    let k = s2.finish();
    [((h >> 32) ^ h) as u32, h as u32, (h >> 32) as u32, ((g >> 32) ^ g) as u32, g as u32, (g >> 32) as u32, ((k >> 32) ^ k) as u32, k as u32, (k >> 32) as u32]
}

type R = [f64; 4];
fn forms(r: &R) -> Vec<(&'static str, Vec<f64>)> {
    let (x, y, w, h) = (r[0], r[1], r[2], r[3]);
    vec![
        ("xywh", vec![x, y, w, h]),
        ("xyxy", vec![x, y, x + w, y + h]),
        ("xxyy", vec![x, x + w, y, y + h]),
        ("cwh", vec![x + w / 2.0, y + h / 2.0, w, h]),
        ("chh", vec![x + w / 2.0, y + h / 2.0, w / 2.0, h / 2.0]),
        ("whxy", vec![w, h, x, y]),
        ("yxhw", vec![y, x, h, w]),
        ("pts", vec![x, y, x + w, y, x + w, y + h, x, y + h]),
    ]
}
const NAMES: &[&str] = &["Rect", "BBox", "Bbox", "Box", "Bounds", "Aabb", "AABB", "R", "Rectangle", "Frame", "Cut", "Hole", "Area", "Extent", "Region", "RectF", "Rc", "B", "Bounds2", "Rect2", "Bound", "BoundingBox", "Window"];
fn fieldsets(form: &str) -> Vec<[&'static str; 4]> {
    match form {
        "xywh" => vec![["x", "y", "w", "h"], ["x", "y", "width", "height"], ["left", "top", "width", "height"], ["x0", "y0", "w", "h"], ["x", "y", "wd", "ht"]],
        "xyxy" => vec![
            ["x0", "y0", "x1", "y1"],
            ["min_x", "min_y", "max_x", "max_y"],
            ["left", "top", "right", "bottom"],
            ["l", "t", "r", "b"],
            ["x1", "y1", "x2", "y2"],
            ["minx", "miny", "maxx", "maxy"],
            ["xmin", "ymin", "xmax", "ymax"],
            ["x_min", "y_min", "x_max", "y_max"],
            ["x", "y", "x2", "y2"],
            ["ax", "ay", "bx", "by"],
        ],
        "xxyy" => vec![["x0", "x1", "y0", "y1"], ["left", "right", "top", "bottom"], ["min_x", "max_x", "min_y", "max_y"], ["xmin", "xmax", "ymin", "ymax"], ["l", "r", "t", "b"]],
        "cwh" => vec![["cx", "cy", "w", "h"], ["x", "y", "w", "h"], ["cx", "cy", "width", "height"], ["x", "y", "width", "height"]],
        "chh" => vec![["cx", "cy", "hw", "hh"], ["x", "y", "hw", "hh"], ["cx", "cy", "rx", "ry"], ["x", "y", "rx", "ry"], ["cx", "cy", "half_w", "half_h"]],
        _ => vec![],
    }
}
fn reps(r: &R, f: &dyn Fn(f64) -> String) -> Vec<String> {
    let mut out = Vec::new();
    for (name, v) in forms(r) {
        let s: Vec<String> = v.iter().map(|x| f(*x)).collect();
        out.push(format!("({})", s.join(", ")));
        out.push(format!("[{}]", s.join(", ")));
        out.push(format!("({})", s.join(",")));
        out.push(format!("[{}]", s.join(",")));
        for sep in [",", " ", ";", "|", "x", ":", "/", "_", ", ", "\t", "\n"] {
            out.push(s.join(sep));
        }
        for fs in fieldsets(name) {
            let body: Vec<String> = fs.iter().zip(s.iter()).map(|(k, v)| format!("{}: {}", k, v)).collect();
            let body = body.join(", ");
            for nm in NAMES {
                out.push(format!("{} {{ {} }}", nm, body));
            }
            out.push(format!("{{ {} }}", body));
            let js: Vec<String> = fs.iter().zip(s.iter()).map(|(k, v)| format!("\"{}\":{}", k, v)).collect();
            out.push(format!("{{{}}}", js.join(",")));
            let kv: Vec<String> = fs.iter().zip(s.iter()).map(|(k, v)| format!("{}={}", k, v)).collect();
            out.push(kv.join(" "));
            out.push(kv.join(","));
            out.push(kv.join(";"));
            let attr: Vec<String> = fs.iter().zip(s.iter()).map(|(k, v)| format!("{}=\"{}\"", k, v)).collect();
            out.push(attr.join(" "));
        }
    }
    out
}

fn main() {
    let cases: Vec<(R, R, u32)> = vec![
        ([-20.0, -2.0, 40.0, 4.0], [-3.0, -6.5, 6.0, 13.0], 0x05ddd672),
        ([-42.0, -2.0, 84.0, 4.0], [-3.0, -6.5, 6.0, 13.0], 0xb89626e2),
        ([-21.0, -3.0, 42.0, 6.0], [-3.0, -6.5, 6.0, 13.0], 0x61ec26de),
    ];
    let mut tops: Vec<String> = vec![
        "({b}, [{c}])", "({b}, {c})", "{b}{c}", "{b} {c}", "{b},{c}", "{b};{c}", "{b}|{c}", "{b}\n{c}", "[{b}, {c}]", "{b}, [{c}]", "{b}[{c}]", "{b}:{c}", "{b}/{c}", "{b} [{c}]",
        "{b} - {c}", "{b}-{c}", "{b}#{c}", "{b}@{c}", "{b}+{c}", "{b}_{c}", "{b}::{c}", "{b}=>{c}", "{b};{c};", "{b}|{c}|", "{b},{c},", "[{b}, [{c}]]", "[{b},[{c}]]", "[{b},{c}]", "{b} | {c}", "{b}; {c}",
        "{b}\n{c}\n", "{b};\n{c};\n", "{b},[{c}]", "({b},[{c}])", "{b} {c} ", "[{c}]", "{c}", "[{b}]", "{b}",
        "{{\"bg\":{b},\"cuts\":[{c}]}}", "{{\"rect\":{b},\"cuts\":[{c}]}}", "{{\"bg\":{b},\"holes\":[{c}]}}",
    ]
    .iter()
    .map(|s| s.to_string())
    .collect();
    for pre in ["Mask", "LabelCut", "Cut", "CutMask", "MaskSpec", "LabelMask", "Knockout", "MaskDef", "M", "LabelCuts", "Cuts", "MaskKey", "Key"] {
        for f1 in ["bg", "rect", "bounds", "area", "bbox", "frame", "r", "outer", "base", "extent", "window", "clip", "b", "back", "background", "canvas", "region", "x"] {
            for f2 in ["cuts", "holes", "labels", "rects", "boxes", "cut", "windows", "knockouts", "cutouts", "label_boxes", "label_rects", "items", "inner"] {
                tops.push(format!("{} {{{{ {}: {{b}}, {}: [{{c}}] }}}}", pre, f1, f2));
            }
        }
    }
    // pre-split templates
    let parts: Vec<(String, String, String, bool)> = tops
        .iter()
        .map(|t| {
            let t = t.replace("{{", "\u{1}").replace("}}", "\u{2}");
            let ib = t.find("{b}");
            let ic = t.find("{c}").unwrap();
            let un = |s: &str| s.replace('\u{1}', "{").replace('\u{2}', "}");
            match ib {
                Some(ib) if ib < ic => (un(&t[..ib]), un(&t[ib + 3..ic]), un(&t[ic + 3..]), true),
                Some(ib) => (un(&t[..ic]), un(&t[ic + 3..ib]), un(&t[ib + 3..]), false),
                None => (un(&t[..ic]), String::new(), un(&t[ic + 3..]), false),
            }
        })
        .collect();
    let fmts: Vec<(&str, Box<dyn Fn(f64) -> String>)> = vec![("D", Box::new(|v: f64| format!("{:?}", v))), ("S", Box::new(|v: f64| format!("{}", v)))];
    let mut n: u64 = 0;
    for (fname, f) in &fmts {
        let all: Vec<(Vec<String>, Vec<String>)> = cases.iter().map(|(b, c, _)| (reps(b, f.as_ref()), reps(c, f.as_ref()))).collect();
        let nr = all[0].0.len();
        for (ti, tpl) in tops.iter().enumerate() {
            let (p0, p1, p2, bfirst) = &parts[ti];
            let has_b = tpl.contains("{b}");
            for kb in 0..nr {
                for kc in 0..nr {
                    if !has_b && kb > 0 {
                        continue;
                    }
                    for swap in [false, true] {
                        let build = |ci: usize| -> String {
                            let (bb, cc) = if swap { (&all[ci].1[kc], &all[ci].0[kb]) } else { (&all[ci].0[kb], &all[ci].1[kc]) };
                            if !has_b {
                                format!("{}{}{}", p0, cc, p2)
                            } else if *bfirst {
                                format!("{}{}{}{}{}", p0, bb, p1, cc, p2)
                            } else {
                                format!("{}{}{}{}{}", p0, cc, p1, bb, p2)
                            }
                        };
                        let s = build(0);
                        n += 1;
                        let o = outs(s.as_bytes());
                        if let Some(pos) = o.iter().position(|&x| x == cases[0].2) {
                            let mut ok = true;
                            for ci in 1..cases.len() {
                                let s1 = build(ci);
                                let o1 = outs(s1.as_bytes());
                                if o1[pos] != cases[ci].2 {
                                    ok = false;
                                }
                            }
                            println!("{} {} pos={} {:?}", if ok { "FOUND" } else { "cand" }, fname, pos, s);
                        }
                    }
                }
            }
        }
    }
    eprintln!("tried {}", n);
}

