# all ways to sum a sequence of terms with all bracketings (via recursive splits), all permutations
def all_sums(names):
    if len(names) == 1:
        yield names[0], terms[names[0]]
        return
    for i in range(1, len(names)):
        for ln, lv in all_sums(names[:i]):
            for rn, rv in all_sums(names[i:]):
                yield '(%s+%s)' % (ln, rn), lv + rv
results = []
seen = set()
names = ['L', 'g', 'R', 'm2', 'c']
for perm in itertools.permutations(names):
    for expr, _ in all_sums(list(perm)):
        if expr in seen:
            continue
        seen.add(expr)
        # evaluate per cb
        for base in ['(cb-8)-S', 'cb-(8+S)', 'cb-(S+8)']:
            ok = 0
            fails = []
            for h, ks in good.items():
                cb = h / 2
                # recompute the sum for this expression (independent of cb)
                S = eval(expr.replace('L', 'terms["L"]').replace('g', 'terms["g"]').replace('R', 'terms["R"]').replace('m2', 'terms["m2"]').replace('c', 'terms["c"]'))
                if base == '(cb-8)-S':
                    v = (cb - 8.0) - S
                elif base == 'cb-(8+S)':
                    v = cb - (8.0 + S)
                else:
