import subprocess, os, random, difflib, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
show = int(sys.argv[3]) if len(sys.argv) > 3 else 3
rnd = random.Random(seed)
d = '/tmp/desugar/seqfuzz'
os.makedirs(d, exist_ok=True)
NAMES = ['a', 'b', 'c', 'd', 'u', 'db']
OPS = ['->', '-->', '<-', '<->', '-', '--', '->>', '-x']

def msg():
    a, b = rnd.choice(NAMES), rnd.choice(NAMES)
    s = '%s %s %s' % (a, rnd.choice(OPS), b)
    r = rnd.random()
    if r < 0.3:
        s += ' "%s"' % rnd.choice(['call', 'ok', 'x y'])
    elif r < 0.4:
        s += ' [ "m1" "m2" ]'
    if rnd.random() < 0.1:
        s += ' { stroke: red; }'
    return s

def frag(depth):
    t = rnd.choice(['loop', 'alt', 'opt'])
    idp = '#f%d' % rnd.randint(0, 9) if rnd.random() < 0.3 else ''
    lab = ' "%s"' % rnd.choice(['each', 'if ok', '']) if rnd.random() < 0.7 else ''
    body = stmts(depth + 1, rnd.randint(1, 3))
    if t == 'alt' and rnd.random() < 0.5:
        body.append('|else| "no" [ %s ]' % '; '.join(stmts(depth + 1, rnd.randint(1, 2))))
    return '|%s%s|%s [\n%s\n]' % (t, idp, lab, '\n'.join(body))

def stmts(depth, k):
    out = []
    for _ in range(k):
        r = rnd.random()
        if r < 0.55 or depth > 2:
            out.append(msg())
        elif r < 0.8:
            out.append(frag(depth))
        elif r < 0.9:
            out.append('|note| "%s"' % rnd.choice(['hint', 'n']))
        else:
            nm = rnd.choice(NAMES)
            out.append('|box#%s| "%s"' % (nm, nm.upper()))
    return out

def gen():
    lines = []
    if rnd.random() < 0.5:
        lines.append('{ layout: sequence; }')
        lines.extend(stmts(0, rnd.randint(2, 6)))
    else:
        body = stmts(1, rnd.randint(2, 6))
        lines.append('|sequence%s| [\n%s\n]' % ('#s' if rnd.random() < 0.3 else '', '\n'.join(body)))
        if rnd.random() < 0.3:
            lines.append(msg())
    return '\n'.join(lines) + '\n'

ok = 0
fails = []
for i in range(n):
    src = gen()
    p = os.path.join(d, 'g.lini')
    open(p, 'w').write(src)
    r1 = subprocess.run(['/workspace/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run(['/tmp/bin-desugar/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    if (r1.stdout, r1.stderr, r1.returncode) == (r2.stdout, r2.stderr, r2.returncode):
        ok += 1
    else:
        fails.append((src, r1, r2))
print('OK %d / %d' % (ok, n))
for src, r1, r2 in fails[:show]:
    print('=' * 30)
    print(src)
    a = (r1.stdout + r1.stderr).decode().splitlines()
    b = (r2.stdout + r2.stderr).decode().splitlines()
    for l in list(difflib.unified_diff(a, b, lineterm='', n=1))[2:40]:
        print(l)

