import subprocess, os, random, difflib, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
show = int(sys.argv[3]) if len(sys.argv) > 3 else 3
rnd = random.Random(seed)
d = '/tmp/desugar/treefuzz'
os.makedirs(d, exist_ok=True)

def style(kind):
    opts = []
    if rnd.random() < 0.15:
        opts.append('side: %s;' % rnd.choice(['left', 'right', 'left', 'up']))
    if rnd.random() < 0.1:
        opts.append('direction: %s;' % rnd.choice(['row', 'column', 'bilateral']))
    if rnd.random() < 0.1:
        opts.append('fill: red;')
    return (' { ' + ' '.join(opts) + ' }') if opts else ''

def topic(depth, ty='topic'):
    idp = '#t%d' % rnd.randint(0, 20) if rnd.random() < 0.2 else ''
    s = '|%s%s| "%s"%s' % (ty, idp, rnd.choice(['A', 'B c', 'Root', '']), style(ty))
    kids = []
    if depth < 3:
        for _ in range(rnd.choice([0, 0, 1, 2, 3])):
            r = rnd.random()
            if r < 0.8:
                kids.append(topic(depth + 1))
            elif r < 0.9:
                kids.append('|box| "note"')
            else:
                kids.append('"text"')
    if kids:
        s += ' [\n' + '\n'.join(kids) + '\n]'
    return s

def gen():
    r = rnd.random()
    lines = []
    if r < 0.3:
        sheet = ['layout: tree;']
        if rnd.random() < 0.5:
            sheet.append('direction: %s;' % rnd.choice(['row', 'column', 'bilateral']))
        lines.append('{ ' + ' '.join(sheet) + ' }')
        lines.append(topic(0))
        if rnd.random() < 0.2:
            lines.append(topic(0, 'mindmap'))
    elif r < 0.55:
        if rnd.random() < 0.3:
            lines.append('{ direction: %s; }' % rnd.choice(['row', 'column', 'bilateral']))
        for _ in range(rnd.randint(1, 2)):
            lines.append(topic(0, 'mindmap'))
    elif r < 0.8:
        st = ' { layout: tree;%s }' % (' direction: %s;' % rnd.choice(['row', 'column', 'bilateral']) if rnd.random() < 0.5 else '')
        lines.append('|box#c|%s [\n%s\n]' % (st, topic(1)))
    else:
        st = (' { direction: %s; }' % rnd.choice(['row', 'column'])) if rnd.random() < 0.4 else ''
        body = [topic(1, 'mindmap') for _ in range(rnd.randint(1, 2))]
        cont = rnd.choice(['box', 'group', 'page', 'column'])
        lines.append('|%s#c|%s [\n%s\n]' % (cont, st, '\n'.join(body)))
    if rnd.random() < 0.2:
        lines.append('|box#z| "Z"')
        lines.append('z -> t1')
    return '\n'.join(lines) + '\n'

ok = 0
fails = []
for i in range(n):
    src = gen()
    p = os.path.join(d, 'g.lini')
    open(p, 'w').write(src)
    r1 = subprocess.run(['/workspace/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run(['/tmp/bin-desugar/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    if (r1.stdout, r1.stderr, r1.returncode) == (r2.stdout, r2.stderr, r2.returncode):
        ok += 1
    else:
        fails.append((src, r1, r2))
print('OK %d / %d' % (ok, n))
for src, r1, r2 in fails[:show]:
    print('=' * 30)
    print(src)
    a = (r1.stdout + r1.stderr).decode().splitlines()
    b = (r2.stdout + r2.stderr).decode().splitlines()
    for l in list(difflib.unified_diff(a, b, lineterm='', n=1))[2:40]:
        print(l)

