import sys,pickle,itertools,ast
sys.path.insert(0,'/tmp/link')
from mk import h8,rd
pairs=pickle.load(open('/tmp/link/mk_pairs.pkl','rb'))
def parse(dm):
    parts=dm[5:].split(' | ')
    a=parts[0].split()
    x0,y0,x1,y1,sw=[float(t) for t in a[:5]]; wavy=a[5]=='true'
    labs=[]
    for p in parts[1:]:
        t=p.split(' ',5)
        lx,ly,tw,fs,upem=[float(v) for v in t[:5]]
        units=ast.literal_eval(t[5])
        labs.append((lx,ly,tw,fs,upem,units))
    return x0,y0,x1,y1,sw,wavy,labs
def tup(c): return '('+', '.join(rd(v) for v in c)+')'
def sumf(xs):
    s=0.0
    for x in xs: s+=x
    return s
TW={
 'e':lambda u,S,U: sumf(u)*S/U,
 'a':lambda u,S,U: sumf(u)*(S/U),
 'b':lambda u,S,U: sumf([x*S/U for x in u]),
 'c':lambda u,S,U: sumf([x/U*S for x in u]),
 'd':lambda u,S,U: sumf(u)/U*S,
 'f':lambda u,S,U: sumf([x*(S/U) for x in u]),
 'g':lambda u,S,U: sumf([x/U for x in u])*S,
}
CUTW={
 'w1':lambda tw,fs: tw+0.6*fs,
 'w2':lambda tw,fs: tw+2*(0.3*fs),
 'w3':lambda tw,fs: (tw+0.3*fs)+0.3*fs,
}
CUTX={
 'x1':lambda lx,tw,fs,w: lx-w/2,
 'x2':lambda lx,tw,fs,w: lx-tw/2-0.3*fs,
 'x3':lambda lx,tw,fs,w: lx-(tw/2+0.3*fs),
}
CUTH={'h1':lambda fs:1.3*fs,'h2':lambda fs: fs+2*(0.15*fs),'h3':lambda fs: fs+0.3*fs}
CUTY={'y1':lambda ly,fs,h: ly-h/2,'y2':lambda ly,fs,h: ly-fs/2-0.15*fs,'y3':lambda ly,fs,h: ly-(fs/2+0.15*fs)}
res=[]
for tk,tf in TW.items():
  for wk,wf in CUTW.items():
    for xk,xf in CUTX.items():
      for hk,hf in CUTH.items():
        for yk,yf in CUTY.items():
          ok=0; fails=[]
          for dm,idv in pairs:
            x0,y0,x1,y1,sw,wv,labs=parse(dm)
            m=sw*0.5+1+(1.4 if wv else 0)
            bx=x0-m; by=y0-m; bw=(x1+m)-(x0-m); bh=(y1+m)-(y0-m)
            cuts=[]
            for lx,ly,tw0,fs,U,u in labs:
                tw=tf(u,fs,U) if u else 0.0
                w=wf(tw,fs); h=hf(fs)
                cuts.append((xf(lx,tw,fs,w),yf(ly,fs,h),w,h))
            key='%s %s %s %s [%s]'%(rd(bx),rd(by),rd(bw),rd(bh),', '.join(tup(c) for c in cuts))
            if h8(key)==idv: ok+=1
            else: fails.append((idv,key,dm))
          res.append((ok,tk,wk,xk,hk,yk,fails))
res.sort(key=lambda r:-r[0])
for r in res[:8]: print(r[:6])
print('of',len(pairs))
if '-v' in sys.argv:
    for f in res[0][6]: print(f)

