    a=parts[0].split()
    x0,y0,x1,y1,sw=[float(t) for t in a[:5]]; wavy=a[5]=='true'
    labs=[]
    for p in parts[1:]:
        t=p.split(' ',5)
        lx,ly,tw,fs,upem=[float(v) for v in t[:5]]
        units=ast.literal_eval(t[5])
        labs.append((lx,ly,tw,fs,upem,units))
    return x0,y0,x1,y1,sw,wavy,labs
def tup(c): return '('+', '.join(rd(v) for v in c)+')'
def sumf(xs):
    s=0.0
    for x in xs: s+=x
    return s
TW={
 'e':lambda u,S,U: sumf(u)*S/U,
 'a':lambda u,S,U: sumf(u)*(S/U),
 'b':lambda u,S,U: sumf([x*S/U for x in u]),
 'c':lambda u,S,U: sumf([x/U*S for x in u]),
 'd':lambda u,S,U: sumf(u)/U*S,
 'f':lambda u,S,U: sumf([x*(S/U) for x in u]),
 'g':lambda u,S,U: sumf([x/U for x in u])*S,
}
CUTW={
 'w1':lambda tw,fs: tw+0.6*fs,
 'w2':lambda tw,fs: tw+2*(0.3*fs),
 'w3':lambda tw,fs: (tw+0.3*fs)+0.3*fs,
}
CUTX={
