n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
show = int(sys.argv[3]) if len(sys.argv) > 3 else 3
rnd = random.Random(seed)
d = '/tmp/desugar/tabfuzz'
os.makedirs(d, exist_ok=True)

def cellish():
    r = rnd.random()
    if r < 0.4:
        return '"%s"' % rnd.choice(['a', 'Name', 'x y', '1', ''])
    if r < 0.55:
        return '|cell| "%s"%s' % (rnd.choice(['c', 'D']), rnd.choice(['', ' { span: 2 1; }', ' { cell: 1 2; }', ' { align: end; }']))
    if r < 0.65:
        return '|header| "%s"' % rnd.choice(['H', 'Head'])
    if r < 0.72:
        return '|footer| "%s"' % rnd.choice(['F', 'total'])
    if r < 0.8:
        return '|box| "%s"' % rnd.choice(['b', 'B'])
    if r < 0.85:
        return '"%s" .k' % rnd.choice(['k', 'K'])
    if r < 0.9:
        return '|field| "%s"' % rnd.choice(['f'])
    return '"%s" { fill: red; }' % rnd.choice(['s'])

def table():
    t = rnd.choice(['table', 'table', 'entity', 'title-block', 'grid'])
    idp = '#t%d' % rnd.randint(0, 3) if rnd.random() < 0.3 else ''
    lab = ' "%s"' % rnd.choice(['T', 'Users', '']) if rnd.random() < 0.6 else ''
    st = []
    if rnd.random() < 0.4:
        st.append('columns: %s;' % rnd.choice(['2', 'repeat(2)', '3', '80 1fr', 'auto auto auto']))
    if rnd.random() < 0.2:
        st.append('rows: %s;' % rnd.choice(['2', 'repeat(3)']))
    if t == 'title-block' and rnd.random() < 0.7:
        for k in rnd.sample(['title', 'number', 'revision', 'date', 'drawn', 'checked', 'scale', 'sheet', 'company', 'material'], rnd.randint(1, 4)):
            st.append('%s: "%s";' % (k, k.upper()))
    if rnd.random() < 0.15:
        st.append('align: %s;' % rnd.choice(['start', 'end', 'center']))
    if rnd.random() < 0.15:
        st.append('justify: %s;' % rnd.choice(['start', 'end']))
    s = '|%s%s|%s%s' % (t, idp, lab, (' { ' + ' '.join(st) + ' }') if st else '')
    if rnd.random() < 0.85:
        kids = [cellish() for _ in range(rnd.randint(0, 7))]
        s += ' [\n' + '\n'.join(kids) + '\n]'
    return s

def gen():
    lines = []
    if rnd.random() < 0.3:
        lines.append('{ .k { fill: red; }%s }' % (' |tbl::table| { stroke: blue; } [ |header| "H" ]' if rnd.random() < 0.5 else ''))
    for _ in range(rnd.randint(1, 3)):
        r = rnd.random()
        if r < 0.15:
            lines.append('|page| { sheet: %s; } [\n%s\n]' % (rnd.choice(['a4', 'a3 landscape', 'a5']), table()))
        elif r < 0.25 and 'tbl' in ''.join(lines):
            lines.append('|tbl| "X" [ "a"; "b" ]')
        else:
            lines.append(table())
    return '\n'.join(lines) + '\n'

ok = 0
fails = []
for i in range(n):
    src = gen()
    p = os.path.join(d, 'g.lini')
    open(p, 'w').write(src)
    r1 = subprocess.run(['/workspace/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run(['/tmp/bin-desugar/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    if (r1.stdout, r1.stderr, r1.returncode) == (r2.stdout, r2.stderr, r2.returncode):
        ok += 1
    else:
        fails.append((src, r1, r2))
print('OK %d / %d' % (ok, n))
for src, r1, r2 in fails[:show]:
    print('=' * 30)
    print(src)
    a = (r1.stdout + r1.stderr).decode().splitlines()
    b = (r2.stdout + r2.stderr).decode().splitlines()
    for l in list(difflib.unified_diff(a, b, lineterm='', n=1))[2:40]:
        print(l)

