import subprocess, re, sys
def run(h, data):
    src = '|chart| { height: %d; categories: %s; } [ |axis| { side: left; scale: log; }; |bars| { data: %s; } ]\n' % (h, ', '.join('"c%d"' % i for i in range(len(data))), ', '.join(str(d) for d in data))
    open('/tmp/chart/t1/lg.lini', 'w').write(src)
    out = subprocess.run(['/workspace/executable', 'lg.lini'], capture_output=True, cwd='/tmp/chart/t1').stdout.decode()
    labs = re.findall(r'class="lini-text lini-chart-text" x="([-0-9.]+)" y="([-0-9.]+)" dy="0.358em" style="fill: var\(--lini-muted\)">([^<]*)<', out)
    ys = [(float(y), t) for x, y, t in labs if not t.startswith('c')]
    return ys
def kind(ys):
    ts = [t for _, t in ys]
    if '2' in ts or '20' in ts or '200' in ts or '0.2' in ts:
        return '125'
    vals = [float(t) for t in ts]
    if len(vals) >= 2 and vals[1] / vals[0] > 10.5:
        return 'skip'
    return 'dec'
datas = {1: [2, 9], 2: [5, 45], 3: [5, 450], 4: [5, 4500], 5: [5, 45000], 6: [5, 450000], 7: [5, 4500000]}
for D, data in datas.items():
    prev = None
    for h in range(60, 600, 2):
        ys = run(h, data)
        k = kind(ys) if ys else 'none'
        if k != prev:
            # plot height from the full domain: pb-pt from first/last label positions if they are 1 and 10^D
            print('D=%d h=%d %s labels=%s' % (D, h, k, ' '.join(t for _, t in ys)), flush=True)
            prev = k

