700	}
701	
702	// Extra radius per corner (added to the base radius). Corners turning the
703	// same way whose wires run side by side nest: the inner one keeps the base
704	// radius, outer ones grow by half their offsets so the arcs stay parallel.
705	fn nest_corners(wires: &[W]) -> Vec<Vec<f64>> {
706	    struct C {
707	        w: usize,
708	        c: usize,
709	        u: usize,
710	        v: usize,
711	        p: (f64, f64),
712	        a: (f64, f64),
713	        b: (f64, f64),
714	    }
715	    let mut cs: Vec<C> = Vec::new();
716	    for (wi, w) in wires.iter().enumerate() {
717	        if w.straight || w.pts.len() < 3 {
718	            continue;
719	        }
720	        for c in 1..w.pts.len() - 1 {
721	            let u = seg_dir(w.pts[c - 1], w.pts[c]);
722	            let v = seg_dir(w.pts[c], w.pts[c + 1]);
723	            cs.push(C { w: wi, c, u, v, p: w.pts[c], a: w.pts[c - 1], b: w.pts[c + 1] });
724	        }
725	    }
726	    let span_overlap = |a0: f64, a1: f64, b0: f64, b1: f64| a0.min(a1) < b0.max(b1) - 1e-9 && b0.min(b1) < a0.max(a1) - 1e-9;
727	    // is corner y wrapped round corner x (same turn, outside it, side by side)?
728	    let outside = |x: &C, y: &C| -> bool {
729	        if x.u != y.u || x.v != y.v {
730	            return false;
731	        }
732	        let uv = dvec(x.u);
733	        let vv = dvec(x.v);
734	        let d = (y.p.0 - x.p.0, y.p.1 - x.p.1);
735	        let du = d.0 * uv.0 + d.1 * uv.1;
736	        let dv = d.0 * vv.0 + d.1 * vv.1;
737	        // strictly outside on both axes (a trunk sibling sharing the leg is not)
738	        if du < 1e-9 || dv > -1e-9 {
739	            return false;
740	        }
741	        // neighbours only: a few tracks apart at most
742	        let k = wires[x.w].k;
743	        if du > 4.0 * k + 1e-9 || -dv > 4.0 * k + 1e-9 {
744	            return false;
745	        }
746	        // the legs run side by side
747	        let horiz_in = uv.1.abs() < 0.5;
