749	            (span_overlap(x.a.0, x.p.0, y.a.0, y.p.0), span_overlap(x.p.1, x.b.1, y.p.1, y.b.1))
750	        } else {
751	            (span_overlap(x.a.1, x.p.1, y.a.1, y.p.1), span_overlap(x.p.0, x.b.0, y.p.0, y.b.0))
752	        };
753	        in_ok && out_ok
754	    };
755	    let mut wants: Vec<Vec<f64>> = wires.iter().map(|w| vec![0.0; w.pts.len().saturating_sub(2)]).collect();
756	    for y in 0..cs.len() {
757	        // innermost corner of y's nest: wrapped by y, wrapping nothing
758	        let mut inner: Option<usize> = None;
759	        for x in 0..cs.len() {
760	            if x == y || !outside(&cs[x], &cs[y]) {
