import subprocess, re, itertools, sys
def f4(v):
    s = '%.4f' % v
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    if s == '-0':
        s = '0'
    return s
FS = 12.0; c = 6.0; g = 15.0
R = FS * 1.4; L = FS * 0.7
mode = sys.argv[1]
obs = []
for i in range(1, 60):
    h = 200 + i * 0.0002 + 0.0001
    hs = '%.4f' % h
    xt = '|axis| "X" { side: bottom; }; ' if 'x' in mode else ''
    ser = '|bars| "p" { data: 1, 2; }; |bars| "q" { data: 2, 1; }' if 'l' in mode else '|bars| { data: 1, 2; }'
    src = '|chart| { height: %s; categories: "a", "b"; } [ %s%s ]\n' % (hs, xt, ser)
    open('/tmp/chart/t1/tf4.lini', 'w').write(src)
    out = subprocess.run(['/workspace/executable', 'tf4.lini'], capture_output=True, cwd='/tmp/chart/t1').stdout.decode()
    labs = re.findall(r'class="lini-text lini-chart-text" x="([-0-9.]+)" y="([-0-9.]+)" dy="0.358em" style="fill: var\(--lini-muted\)">([^<]*)<', out)
    ty = [y for x, y, t in labs if t == 'a'][0]
    xty = [y for x, y, t in labs if t == 'X']
    grid = re.findall(r'<line x1="[-0-9.]+" y1="([-0-9.]+)" x2="[-0-9.]+" y2="\1"/>', out)
    obs.append((float(hs), ty, xty[0] if xty else None, grid[0]))
print(mode, obs[:3])
# model families
def models():
    # stack from (cb - 8)
    for order in itertools.permutations(['L', 'T', 'X']):
        yield ('stack:' + ''.join(order), order)
res = []
for name, order in models():
    for tick_var in ['Rc-2', 'R-2c', 'cR-2']:
        bad = 0
        for h, ty, xty, gy in obs:
            cb = h / 2
            st = None
            def add(v):
                global st
            vals = []
            for o in order:
                if o == 'L' and 'l' in mode:
                    vals.append(L + g)
                if o == 'T':
                    if tick_var == 'Rc-2':
                        vals += [R, c, -2.0]
                    elif tick_var == 'R-2c':
                        vals += [R, -2.0, c]
                    else:
                        vals += [c, R, -2.0]
                if o == 'X' and 'x' in mode:
                    vals += [R, c]
            acc = vals[0]
            for v in vals[1:]:
                acc += v
            pb = (cb - 8.0) - acc
            bad += f4(pb) != gy
            bad += f4((pb + c) + L) != ty
        res.append((bad, name, tick_var))
res.sort()
for r in res[:8]:
    print(r)

