892	pub fn slot_rank(slot: &str) -> (usize, String) {
893	    if let Some(rest) = slot.strip_prefix("@define:") {
894	        let p = SLOT_ORDER.iter().position(|s| *s == "@define").unwrap();
895	        return (p, rest.to_string());
896	    }
897	    if let Some(rest) = slot.strip_prefix("@class:") {
898	        let p = SLOT_ORDER.iter().position(|s| *s == "@class").unwrap();
