def fams(colw):
    ncol=len(colw)
    cw_a=S(colw)+GAP*(ncol-1)
    cw_b=0.0
    for k,c in enumerate(colw):
        cw_b+=c
        if k<ncol-1: cw_b+=GAP
    out={}
    for cwn,cw in (('cwA',cw_a),('cwB',cw_b)):
        W=cw+PAD+PAD
        for start_n,start,shift in (('tl',PAD,W/2),('cl',0.0,cw/2),('cc',-cw/2,0.0),('dc',-W/2+PAD,0.0),('cc2',-(cw/2),0.0)):
            for accn in ('acc','acc2','prefix'):
