                if accn=='acc':
                    a=start
                    for c in colw: lefts.append(a); a+=c+GAP
                elif accn=='acc2':
                    a=start
                    for c in colw: lefts.append(a); a+=c; a+=GAP
                else:
                    for k in range(ncol): lefts.append(start+(S(colw[:k])+GAP*k))
                for cen in ('l+c/2','(l+r)/2','r-c/2','l+c*0.5'):
                    xs=[]
                    for k in range(ncol):
                        l=lefts[k]; c=colw[k]; r=l+c
                        v={'l+c/2':l+c/2,'(l+r)/2':(l+r)/2,'r-c/2':r-c/2,'l+c*0.5':l+c*0.5}[cen]
                        if shift: v=v-shift
