    pub lines: Vec<String>,
    pub gutters: Vec<(f64, f64, f64, f64)>,
    pub scope: usize,
    pub geo: Option<Geo>,
    pub geo_off: (f64, f64),
    // the statement's label ("…" after the head), whatever the primitive
    pub label: Option<String>,
}

#[derive(Clone, Debug)]
pub enum Geo {
    Points(Vec<(f64, f64)>),
    Path(String),
}

impl Node {
    pub fn new(prim: Prim, chain: Vec<String>, span: Span) -> Node {
        Node {
            prim,
            chain,
            id: None,
            auto: false,
            classes: vec![],
            inline: vec![],
            text: None,
            children: vec![],
            parent: None,
            span,
            props: HashMap::new(),
            inline_props: HashMap::new(),
            w: 0.0,
            h: 0.0,
            x: 0.0,
            y: 0.0,
            lines: vec![],
            gutters: vec![],
            scope: 0,
            geo: None,
            geo_off: (0.0, 0.0),
