14	#[derive(Clone, Debug, Default)]
15	pub struct LStyle {
16	    // full cascade (rules, classes, scoped rules, inline)
17	    pub props: Vec<(String, Value)>,
18	    // scoped rules + inline: rendered as the link's inline style
19	    pub own: Vec<(String, Value)>,
20	    // classes + own: label inline style
21	    pub label_props: Vec<(String, Value)>,
22	    pub sw: f64,
23	    pub line: String,
24	    pub start: Option<String>,
25	    pub end: Option<String>,
26	    pub k: f64,
27	    pub radius: Option<f64>,
