73	    pub li: usize,
74	    pub stray: bool,
75	    // orthogonal polyline, boundary point to boundary point
76	    pub pts: Vec<(f64, f64)>,
77	    // natural routing: cubic between the two stubs
78	    pub curve: Option<[(f64, f64); 4]>,
79	    pub radii: Vec<f64>,
80	    pub style: LStyle,
81	    pub labels: Vec<Label>,
82	    // global label indices whose cut-outs fall in this link's mask
83	    pub cuts: Vec<(usize, usize)>,
84	    pub sa: Option<Side>,
85	    pub sb: Option<Side>,
86	}
