216	fn right_marker(s: &str) -> Option<String> {
217	    Some(
218	        match s {
219	            ">" => "arrow",
220	            "*" => "dot",
221	            "<" => "crow",
222	            "+" => "one",
223	            "+<" => "one-or-many",
224	            "o<" => "zero-or-many",
225	            "o+" => "zero-or-one",
226	            _ => return None,
227	        }
228	        .to_string(),
229	    )
