1124	            let exact: Vec<(f64, f64, f64, f64)> = g.cuts.iter().map(|&(ggi, k)| geos[ggi].labels[k].cut_exact()).collect();
1125	            let id = format!("lini-label-cut-{}", hash8(&mask_key(&mb, &exact)));
1126	            s.push_str(&format!(
1127	                "      <mask id=\"{}\" maskUnits=\"userSpaceOnUse\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\">{}</mask>\n",
1128	                id,
1129	                f4(mb.x0),
1130	                f4(mb.y0),
1131	                f4(mb.w()),
1132	                f4(mb.h()),
1133	                inner
