201	// Wall bands: a container that holds an endpoint may be crossed, but only
202	// head-on; nothing runs along or turns within the clearance of its border.
203	pub struct Band {
204	    // the band region (open): the ring just outside a wall's border
205	    r: Rect,
206	    // true: the border is horizontal (top/bottom edge) — vertical crossing allowed
207	    horiz: bool,
208	    // crossings must fall within this span (along the border)
209	    lo: f64,
210	    hi: f64,
211	}
212	
213	fn wall_bands(env: &Env) -> Vec<Band> {
214	    let k = env.k;
215	    let mut v = Vec::new();
216	    for o in &env.obs {
217	        if o.kind != ObKind::WallBoth {
218	            continue;
219	        }
220	        let r = o.r;
221	        v.push(Band { r: Rect::new(r.x0 - k, r.y0 - k, r.x1 + k, r.y0), horiz: true, lo: r.x0 + k, hi: r.x1 - k });
222	        v.push(Band { r: Rect::new(r.x0 - k, r.y1, r.x1 + k, r.y1 + k), horiz: true, lo: r.x0 + k, hi: r.x1 - k });
223	        v.push(Band { r: Rect::new(r.x0 - k, r.y0 - k, r.x0, r.y1 + k), horiz: false, lo: r.y0 + k, hi: r.y1 - k });
224	        v.push(Band { r: Rect::new(r.x1, r.y0 - k, r.x1 + k, r.y1 + k), horiz: false, lo: r.y0 + k, hi: r.y1 - k });
225	    }
226	    v
227	}
228	
229	fn in_band(bands: &[Band], x: f64, y: f64) -> bool {
230	    bands.iter().any(|b| b.r.contains_open(x, y))
231	}
232	
233	// A segment may cross a band only perpendicular to its border, away from
234	// the border's ends.
235	fn seg_band_ok(bands: &[Band], p: (f64, f64), q: (f64, f64)) -> bool {
236	    let horiz_seg = (p.1 - q.1).abs() < EPS;
237	    let (x0, x1) = if p.0 < q.0 { (p.0, q.0) } else { (q.0, p.0) };
238	    let (y0, y1) = if p.1 < q.1 { (p.1, q.1) } else { (q.1, p.1) };
239	    for b in bands {
240	        let r = &b.r;
241	        let inter = if horiz_seg {
242	            y0 > r.y0 + EPS && y0 < r.y1 - EPS && x0 < r.x1 - EPS && x1 > r.x0 + EPS
243	        } else {
244	            x0 > r.x0 + EPS && x0 < r.x1 - EPS && y0 < r.y1 - EPS && y1 > r.y0 + EPS
245	        };
246	        if !inter {
247	            continue;
248	        }
249	        // a horizontal border is crossed by vertical segments only
250	        if b.horiz == horiz_seg {
251	            return false;
252	        }
253	        let at = if horiz_seg { y0 } else { x0 };
254	        if at < b.lo - EPS || at > b.hi + EPS {
255	            return false;
256	        }
257	    }
258	    true
259	}
