641	// The interval a U-turn segment could slide in, judged beside its starting
642	// point: inflated obstacles bound it, a container border holding both ends
643	// leaves that side open. Infinite where open.
644	pub fn u_interval(env: &Env, solids: &[Rect], pts: &[(f64, f64)], j: usize) -> (f64, f64) {
645	    let p = pts[j];
646	    let q = pts[j + 1];
647	    let vertical = (p.0 - q.0).abs() < 1e-9;
648	    let pos = if vertical { p.0 } else { p.1 };
649	    let at = if vertical { p.1 } else { p.0 };
650	    let mut lo = f64::NEG_INFINITY;
651	    let mut hi = f64::INFINITY;
652	    for r in solids {
653	        let (a0, a1, b0, b1) = if vertical { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
654	        if !(at > a0 + EPS && at < a1 - EPS) {
655	            continue;
656	        }
657	        if b1 <= pos + EPS && b1 > lo {
658	            lo = b1;
659	        }
660	        if b0 >= pos - EPS && b0 < hi {
661	            hi = b0;
662	        }
663	    }
664	    for o in &env.obs {
665	        if o.kind != ObKind::WallBoth {
666	            continue;
667	        }
668	        let r = o.r;
669	        let (a0, a1, b0, b1) = if vertical { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
670	        if !(at > a0 + EPS && at < a1 - EPS) {
671	            continue;
672	        }
673	        // a border between the segment and a bound opens that side
674	        if b0 < pos && b0 > lo {
675	            lo = f64::NEG_INFINITY;
676	        }
677	        if b1 > pos && b1 < hi {
678	            hi = f64::INFINITY;
679	        }
680	    }
681	    (lo, hi)
682	}
683	
684	pub fn is_u(pts: &[(f64, f64)], j: usize) -> bool {
685	    let d0 = seg_dir(pts[j - 1], pts[j]);
686	    let d2 = seg_dir(pts[j + 1], pts[j + 2]);
687	    d0 == (d2 + 2) % 4
688	}
689	
690	// Free segments settle in their channel: staircases midway across their
691	// span; U-turns midway when boxed in beside their start, else they keep
692	// hugging what they go around.
693	pub fn centre_staircases(env: &Env, pts: &mut Vec<(f64, f64)>) {
694	    let solids = env.solids();
695	    let n = pts.len();
696	    if n < 4 {
697	        return;
698	    }
699	    for i in 1..n - 2 {
700	        // a simple U between the two end stubs always hugs
701	        if is_u(pts, i) && n == 4 {
702	            continue;
703	        }
704	        let (lo, hi) = if is_u(pts, i) { u_interval(env, &solids, pts, i) } else { stair_interval(&solids, pts, i) };
705	        if !lo.is_finite() || !hi.is_finite() {
706	            continue;
707	        }
708	        let m = (lo + hi) / 2.0;
709	        let vertical = (pts[i].0 - pts[i + 1].0).abs() < 1e-9;
710	        if vertical {
711	            pts[i].0 = m;
712	            pts[i + 1].0 = m;
713	        } else {
714	            pts[i].1 = m;
715	            pts[i + 1].1 = m;
716	        }
717	    }
718	}
