902	// Spread every side's wire ends: ordered so wires do not cross, centred,
903	// pitch the clearance (squeezed down to fit the side).
904	fn plan_ports(ctx: &Ctx, world: &World, bundles: &[Bundle], wires: &mut [W]) {
905	    use std::collections::BTreeMap;
906	    // a straight wire leaving a container takes its port among the ends on
907	    // the side of the child it lines up with
908	    let port_node = |node: usize, side: Side, w: &W| -> usize {
909	        let Some(id) = w.ideal else { return node };
910	        for &c in &ctx.nodes[node].children {
911	            if !crate::links::is_obstacle_kind(ctx, c) || ctx.nodes[c].is("caption") {
912	                continue;
913	            }
914	            let (c0, c1) = side_span(&world.rects[c], side);
915	            if id >= c0 + w.k - 1e-9 && id <= c1 - w.k + 1e-9 {
916	                return c;
917	            }
918	        }
919	        node
920	    };
921	    let mut sides: BTreeMap<(usize, usize), Vec<(usize, usize)>> = BTreeMap::new();
922	    for (wi, w) in wires.iter().enumerate() {
923	        sides.entry((w.from, w.sa.idx())).or_default().push((wi, 0));
924	        sides.entry((w.to, w.sb.idx())).or_default().push((wi, 1));
925	    }
926	    // (only when that child's side has ends of its own)
927	    let mut moves: Vec<((usize, usize), (usize, usize), (usize, usize))> = Vec::new();
928	    for (wi, w) in wires.iter().enumerate() {
929	        for (e, node, side) in [(0, w.from, w.sa), (1, w.to, w.sb)] {
930	            let c = port_node(node, side, w);
931	            if c != node && sides.get(&(c, side.idx())).map_or(false, |v| !v.is_empty()) {
932	                moves.push(((node, side.idx()), (c, side.idx()), (wi, e)));
933	            }
934	        }
935	    }
936	    for (from_key, to_key, end) in moves {
937	        if let Some(v) = sides.get_mut(&from_key) {
938	            v.retain(|x| *x != end);
939	        }
940	        sides.entry(to_key).or_default().push(end);
941	    }
942	    sides.retain(|_, v| !v.is_empty());
943	    // straight wires keep one position on both sides: the busier side decides
944	    let mut straight_pos: std::collections::HashMap<usize, f64> = std::collections::HashMap::new();
945	    let mut entries: Vec<((usize, usize), Vec<(usize, usize)>)> = sides.into_iter().collect();
946	    // busier sides first so straight wires take their positions there; an
947	    // inner node's side goes before its container's
948	    let inner_side = |ends: &Vec<(usize, usize)>| ends.iter().any(|&(wi, e)| wires[wi].inner_end == Some(e));
949	    entries.sort_by(|a, b| inner_side(&b.1).cmp(&inner_side(&a.1)).then(b.1.len().cmp(&a.1.len())).then(a.0.cmp(&b.0)));
950	    for ((node, sidx), mut ends) in entries {
951	        let side = [Side::Top, Side::Right, Side::Bottom, Side::Left][sidx];
952	        let r = world.rects[node];
953	        let k = wires[ends[0].0].k;
954	        // fan members sharing this node and side travel as one trunk port
955	        let fan_key = |w: &W, e: usize| if e == 0 { w.fan_s } else { w.fan_e };
956	        // ends wanting a line of their own come in its order along the side
957	        let tg = tangent(side);
958	        let tsg = if side.horizontal() { tg.0 } else { tg.1 };
959	        let mid = if side.horizontal() { r.cx() } else { r.cy() };
960	        let line_of = |wi: usize| -> f64 { straight_pos.get(&wi).copied().or(if wires[wi].straight { wires[wi].ideal } else { None }).unwrap_or(mid) * tsg };
961	        ends.sort_by(|&(wa, ea), &(wb, eb)| {
962	            let la = line_of(wa);
963	            let lb = line_of(wb);
964	            if (la - lb).abs() > 1e-9 {
965	                return la.partial_cmp(&lb).unwrap_or(std::cmp::Ordering::Equal);
966	            }
967	            let (ca, da) = end_shape(&wires[wa], ea);
968	            let (cb, db) = end_shape(&wires[wb], eb);
969	            let ka = if ca == -1 { da } else if ca == 1 { -da } else { 0.0 };
970	            let kb = if cb == -1 { db } else if cb == 1 { -db } else { 0.0 };
971	            // a wire turning into an inner track turns first
972	            let ua = u_key(&wires[wa], ea);
973	            let ub = u_key(&wires[wb], eb);
974	            let inner = match (ua, ub) {
975	                (Some(x), Some(y)) if ca == cb && ca != 0 => {
976	                    let o = x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal).then(y.1.partial_cmp(&x.1).unwrap_or(std::cmp::Ordering::Equal));
977	                    if ca == 1 {
978	                        o.reverse()
979	                    } else {
980	                        o
981	                    }
982	                }
983	                _ => std::cmp::Ordering::Equal,
984	            };
985	            let ba = wires[wa].bundle;
986	            let bb = wires[wb].bundle;
987	            // within a bundle: slot order on the start side, reversed on the far side
988	            let sa = if ea == 0 { wires[wa].slot as i64 } else { -(wires[wa].slot as i64) };
989	            let sb = if eb == 0 { wires[wb].slot as i64 } else { -(wires[wb].slot as i64) };
990	            ca.cmp(&cb)
991	                .then(ka.partial_cmp(&kb).unwrap_or(std::cmp::Ordering::Equal))
992	                .then(if ba == bb { std::cmp::Ordering::Equal } else { inner })
993	                .then(ba.cmp(&bb))
994	                .then(sa.cmp(&sb))
995	        });
996	        // slots: trunk members collapse onto their group's first slot
997	        let mut slot_of: Vec<usize> = Vec::new();
998	        let mut groups_seen: Vec<(usize, usize)> = Vec::new();
999	        let mut nslots = 0;
1000	        for &(wi, e) in &ends {
1001	            match fan_key(&wires[wi], e) {
1002	                Some(g) => {
1003	                    if let Some(&(_, sl)) = groups_seen.iter().find(|(gg, _)| *gg == g) {
1004	                        slot_of.push(sl);
1005	                    } else {
1006	                        groups_seen.push((g, nslots));
1007	                        slot_of.push(nslots);
1008	                        nslots += 1;
1009	                    }
1010	                }
1011	                None => {
1012	                    slot_of.push(nslots);
1013	                    nslots += 1;
1014	                }
1015	            }
1016	        }
1017	        let n = nslots;
1018	        let len = if side.horizontal() { r.w() } else { r.h() };
1019	        let pitch = if n <= 1 { 0.0 } else { k.min((len - 2.0 * k) / (n as f64 - 1.0)) };
1020	        let t = tangent(side);
1021	        let centre = if side.horizontal() { r.cx() } else { r.cy() };
1022	        let sgn = if side.horizontal() { t.0 } else { t.1 };
1023	        // each slot wants a line: the side's centre, or a straight wire's
1024	        // own line (fixed once its other side placed it)
1025	        let mut want: Vec<Option<(f64, bool)>> = vec![None; n];
1026	        for (ii, &(wi, _)) in ends.iter().enumerate() {
1027	            let i = slot_of[ii];
1028	            let w = &wires[wi];
1029	            if let Some(&sp) = straight_pos.get(&wi) {
1030	                want[i] = Some((sp, true));
1031	            } else if let (true, Some(id)) = (w.straight, w.ideal) {
1032	                if want[i].is_none() {
1033	                    want[i] = Some((id, false));
1034	                }
1035	            }
1036	        }
1037	        let standard = want.iter().all(|x| x.is_none());
1038	        // slots in axis order, at least a pitch apart, as near their lines
1039	        // as possible (pooled where they would crowd), inside the side
1040	        let (s0, s1) = side_span(&r, side);
1041	        let pos_of: Vec<f64> = {
1042	            let axis = |i: usize| if sgn > 0.0 { i } else { n - 1 - i };
1043	            let mut tgt = vec![0.0; n];
1044	            let mut wt = vec![1.0; n];
1045	            for i in 0..n {
1046	                let (t0, fixed) = want[i].unwrap_or((centre, false));
1047	                tgt[axis(i)] = t0;
1048	                wt[axis(i)] = if fixed { 1e9 } else { 1.0 };
1049	            }
1050	            // blocks: (first, last, weight sum, weighted target sum, weighted index sum)
1051	            let mut blocks: Vec<(usize, usize, f64, f64, f64)> = Vec::new();
1052	            let val = |b: &(usize, usize, f64, f64, f64)| b.3 / b.2 - pitch * (b.4 / b.2);
1053	            for j in 0..n {
1054	                blocks.push((j, j, wt[j], wt[j] * tgt[j], wt[j] * j as f64));
1055	                while blocks.len() >= 2 && val(&blocks[blocks.len() - 2]) > val(&blocks[blocks.len() - 1]) + 1e-12 {
1056	                    let b2 = blocks.pop().unwrap();
1057	                    let b1 = blocks.pop().unwrap();
1058	                    blocks.push((b1.0, b2.1, b1.2 + b2.2, b1.3 + b2.3, b1.4 + b2.4));
