        Node {
            prim,
            chain,
            id: None,
            auto: false,
            classes: vec![],
            inline: vec![],
            text: None,
            children: vec![],
            parent: None,
            span,
            props: HashMap::new(),
            inline_props: HashMap::new(),
            w: 0.0,
            h: 0.0,
            x: 0.0,
            y: 0.0,
            lines: vec![],
            gutters: vec![],
            scope: 0,
            geo: None,
            geo_off: (0.0, 0.0),
            label: None,
        }
    }
    pub fn is(&self, t: &str) -> bool {
        self.chain.iter().any(|c| c == t)
    }
}

