132	    let root = 0;
133	    // scene body
134	    let mut scene = String::new();
135	    let children = ctx.nodes[root].children.clone();
136	    let ordered = paint_order(ctx, &children);
137	    for ch in ordered {
138	        render_node(ctx, ch, 4, &mut scene, &mut out)?;
139	    }
140	    // links (registers their stylesheet rules)
141	    let links_layer = crate::links::render(ctx, &mut out)?;
142	    if scene.contains("lini-marker-open") && !out.extra_rules.iter().any(|(k, _)| k == "marker-open") {
143	        out.extra_rules.push((
144	            "marker-open".into(),
145	            ".lini-marker.lini-marker-open { fill: none; stroke: inherit; stroke-linecap: round; stroke-dasharray: none; }".to_string(),
146	        ));
147	    }
148	    // stylesheet
149	    let theme = crate::theme::resolve(opts.theme.as_deref().unwrap_or("default")).unwrap();
150	    let mut slots: Vec<(String, String)> = Vec::new();
151	    let type_names: Vec<String> = out.used_types.clone();
152	    for t in &type_names {
153	        if t == "image" {
154	            continue; // an image's paint never reaches its pixels: no rule
155	        }
156	        let mut props = type_rule_props(ctx, t);
157	        if let Some(sz) = font_scale_size(ctx, &props) {
158	            if get(&props, "font-size").is_none() {
159	                props.push(("font-size".into(), mk_value(Term::Num(sz, f4(sz), Default::default()))));
160	            }
161	        }
162	        let is_prim = types::find(t).map(|d| d.base.is_none()).unwrap_or(false);
163	        if is_prim && get(&props, "stroke-style").is_none() {
164	            props.push(("stroke-style".into(), mk_value(Term::Ident("solid".into(), Default::default()))));
165	        }
166	        let sw = get(&props, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(2.0);
167	        let decls = css_decls(ctx, &props, &mut out.vars, sw, false)?;
168	        if !decls.is_empty() {
169	            let slot = if types::find(t).is_some() {
170	                t.clone()
171	            } else {
172	                format!("@define:{:04}", ctx.sheet.defines.iter().position(|d| &d.name == t).unwrap_or(0))
173	            };
174	            slots.push((slot, format!(".lini-{} {{ {}; }}", t, join_decls(&decls))));
175	        }
176	    }
177	    if out.any_text {
178	        slots.push(("text".into(), ".lini-text { fill: currentColor; stroke: none; text-anchor: middle; }".to_string()));
179	    }
180	    if out.gutters {
181	        slots.push(("gutter".into(), ".lini-gutter { stroke: none; }".to_string()));
182	    }
183	    if out.markers {
184	        slots.push(("marker".into(), ".lini-marker { fill: var(--lini-stroke); stroke: none; }".to_string()));
185	        use_var(&mut out.vars, "stroke");
186	    }
187	    let canvas_fill = match ctx.sheet.root.iter().rev().find(|d| d.name == "fill") {
188	        Some(d) => match single_term(&d.value) {
189	            Some(t) => Some(color_css(t, &mut out.vars, d.value.span)?),
190	            None => None,
191	        },
192	        None => None,
193	    };
194	    if let Some(f) = &canvas_fill {
195	        slots.push(("canvas".into(), format!(".lini-canvas {{ fill: {}; }}", f)));
196	    }
197	    for (k, c) in ctx.sheet.classes.iter().enumerate() {
198	        if out.used_classes.contains(&c.name) {
199	            let props: Vec<(String, Value)> = c.decls.iter().map(|d| (d.name.clone(), d.value.clone())).collect();
200	            let decls = css_decls(ctx, &props, &mut out.vars, 2.0, false)?;
201	            if !decls.is_empty() {
202	                slots.push((format!("@class:{:04}", k), format!(".lini-style-{} {{ {}; }}", c.name, join_decls(&decls))));
203	            }
204	        }
205	    }
206	    for (slot, rule) in &out.extra_rules {
207	        // a family's fallback rule for a primitive yields to the real type rule
208	        if type_names.contains(slot) {
209	            continue;
210	        }
211	        slots.push((slot.clone(), rule.clone()));
212	    }
213	    slots.sort_by(|a, b| slot_rank(&a.0).cmp(&slot_rank(&b.0)));
214	    let mut rules: Vec<String> = Vec::new();
215	    for (_, r) in slots {
216	        if !rules.contains(&r) {
217	            rules.push(r);
218	        }
219	    }
220	    // root variables
221	    let mut vars = out.vars.clone();
222	    for v in ["fg", "font-family", "font-weight", "text-color"] {
223	        crate::style::use_var(&mut vars, v);
224	    }
225	    let mut decl_vars: Vec<(String, String)> = Vec::new();
226	    let mut k = 0;
227	    while k < vars.len() {
228	        let v = vars[k].clone();
229	        k += 1;
230	        let user = ctx.sheet.vars.iter().rev().find(|d| d.name == v);
231	        let val = if let Some(d) = user {
232	            let mut vv = Vec::new();
233	            let s = value_css_text(ctx, &d.value, &mut vv);
234	            for x in vv {
235	                if !vars.contains(&x) {
236	                    vars.push(x);
237	                }
238	            }
239	            Some(s)
240	        } else {
241	            theme.css_value(&v)
242	        };
243	        if let Some(val) = val {
244	            // nested var() references pull their targets in too
245	            let mut rest = val.as_str();
246	            while let Some(p) = rest.find("var(--lini-") {
247	                let after = &rest[p + 11..];
248	                let end = after.find(')').unwrap_or(after.len());
249	                let name = after[..end].to_string();
250	                if !vars.contains(&name) {
251	                    vars.push(name);
252	                }
253	                rest = &after[end..];
254	            }
255	            decl_vars.push((v, val));
256	        }
257	    }
258	    decl_vars.sort_by(|a, b| a.0.cmp(&b.0));
259	    let mut css = String::new();
260	    css.push_str("    @layer lini.defaults {\n");
261	    let mut root_line = String::from("      :root, .lini {");
262	    if theme.pair {
263	        root_line.push_str(" color-scheme: light dark;");
264	    }
265	    for (k, v) in &decl_vars {
266	        root_line.push_str(&format!(" --lini-{}: {};", k, v));
267	    }
268	    root_line.push_str(" }\n");
269	    css.push_str(&root_line);
270	    if theme.pair {
271	        css.push_str("      .lini[data-theme=\"dark\"], [data-theme=\"dark\"] .lini { color-scheme: dark; }\n");
272	        css.push_str("      .lini[data-theme=\"light\"], [data-theme=\"light\"] .lini { color-scheme: light; }\n");
273	    }
274	    css.push_str("    }\n");
275	    css.push_str("    .lini, .lini text { font-family: var(--lini-font-family); }\n");
276	    css.push_str(&format!(
277	        "    .lini {{ font-size: {}px; font-weight: var(--lini-font-weight); color: var(--lini-text-color); }}\n",
278	        f4(ctx.root_font_size)
279	    ));
280	    for r in &rules {
281	        css.push_str(&format!("    .lini {}\n", r));
282	    }
283	    let hash = hash8(&css);
284	    let scope = format!("lini-scope-{}", hash);
285	    let css_scoped = scope_css(&css, &scope);
286	    // the frame
287	    let (vx, vy, vw, vh) = viewbox(ctx);
288	    // a bare sheet document states its paper size in mm
289	    let (sw, sh) = match crate::page::svg_mm(ctx) {
290	        Some(k) => (format!("{}mm", f4(vw / k)), format!("{}mm", f4(vh / k))),
291	        None => (f4(vw), f4(vh)),
292	    };
293	    let mut s = String::new();
294	    s.push_str(&format!(
295	        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"{} {} {} {}\" width=\"{}\" height=\"{}\" class=\"lini {}\">\n",
296	        f4(vx),
297	        f4(vy),
298	        f4(vw),
299	        f4(vh),
300	        sw,
301	        sh,
302	        scope
303	    ));
304	    s.push_str("  <style>\n");
305	    s.push_str(&css_scoped);
306	    s.push_str("  </style>\n");
307	    if out.defs.is_empty() {
308	        s.push_str("  <defs/>\n");
309	    } else {
310	        s.push_str("  <defs>\n");
311	        for d in &out.defs {
312	            s.push_str(&format!("    {}\n", d));
313	        }
314	        s.push_str("  </defs>\n");
315	    }
316	    if canvas_fill.is_some() {
317	        s.push_str(&format!(
318	            "  <rect class=\"lini-canvas\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"/>\n",
319	            f4(vx),
320	            f4(vy),
321	            f4(vw),
322	            f4(vh)
323	        ));
324	    }
325	    s.push_str("  <g class=\"lini-scene\">\n");
326	    s.push_str(&scene);
327	    s.push_str("  </g>\n");
328	    s.push_str(&links_layer);
329	    s.push_str("</svg>\n");
330	    Ok(s)
331	}
