499	pub fn node_classes(ctx: &Ctx, i: usize, out: &mut Out) -> String {
500	    let n = &ctx.nodes[i];
501	    let mut cls = vec!["lini-node".to_string()];
502	    for t in &n.chain {
503	        cls.push(format!("lini-{}", t));
504	        if !out.used_types.contains(t) {
505	            out.used_types.push(t.clone());
506	        }
507	    }
508	    for c in &n.classes {
509	        cls.push(format!("lini-style-{}", c));
510	        if !out.used_classes.contains(c) {
511	            out.used_classes.push(c.clone());
512	        }
513	    }
514	    cls.join(" ")
515	}
