691	pub fn shape_lines(ctx: &Ctx, i: usize) -> Vec<String> {
692	    let n = &ctx.nodes[i];
693	    let c = &ctx.comp[i];
694	    let (w, h) = (n.w, n.h);
695	    if let Some(v) = crate::drawing::shape_override(ctx, i) {
696	        return v;
697	    }
698	    let mut v = Vec::new();
699	    match n.prim {
700	        Prim::Block if w == 0.0 || h == 0.0 => {}
701	        Prim::Block => {
702	            v.push(format!(
703	                "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" ry=\"{}\"/>",
704	                f4(-w / 2.0),
705	                f4(-h / 2.0),
706	                f4(w),
707	                f4(h),
708	                f4(c.radius),
709	                f4(c.radius)
710	            ));
711	        }
712	        Prim::Oval => {
713	            v.push(format!("<ellipse cx=\"0\" cy=\"0\" rx=\"{}\" ry=\"{}\"/>", f4(w / 2.0), f4(h / 2.0)));
714	        }
715	        Prim::Hex => {
716	            v.push(format!(
717	                "<polygon points=\"{},0 {},{} {},{} {},0 {},{} {},{}\"/>",
718	                f4(-w / 2.0),
719	                f4(-w / 4.0),
720	                f4(-h / 2.0),
721	                f4(w / 4.0),
722	                f4(-h / 2.0),
723	                f4(w / 2.0),
724	                f4(w / 4.0),
725	                f4(h / 2.0),
726	                f4(-w / 4.0),
727	                f4(h / 2.0)
728	            ));
729	        }
730	        Prim::Diamond => {
731	            v.push(format!(
732	                "<polygon points=\"0,{} {},0 0,{} {},0\"/>",
733	                f4(-h / 2.0),
734	                f4(w / 2.0),
735	                f4(h / 2.0),
736	                f4(-w / 2.0)
737	            ));
738	        }
739	        Prim::Slant => {
740	            let skew = prop_nums(ctx, i, "skew").first().copied().unwrap_or(15.0);
741	            let off = (skew.to_radians()).tan() * h / 2.0;
742	            v.push(format!(
743	                "<polygon points=\"{},{} {},{} {},{} {},{}\"/>",
744	                f4(-w / 2.0 + off),
745	                f4(-h / 2.0),
746	                f4(w / 2.0 + off),
747	                f4(-h / 2.0),
748	                f4(w / 2.0 - off),
749	                f4(h / 2.0),
750	                f4(-w / 2.0 - off),
751	                f4(h / 2.0)
752	            ));
753	        }
754	        Prim::Cyl => {
755	            let ry = h * 0.1;
756	            let rx = w / 2.0;
757	            let t = h / 2.0 - ry;
758	            v.push(format!(
759	                "<path d=\"M {} {} L {} {} A {} {} 0 0 0 {} {} L {} {} A {} {} 0 0 0 {} {} Z\"/>",
760	                f4(-rx),
761	                f4(-t),
762	                f4(-rx),
763	                f4(t),
764	                f4(rx),
765	                f4(ry),
766	                f4(rx),
767	                f4(t),
768	                f4(rx),
769	                f4(-t),
770	                f4(rx),
771	                f4(ry),
772	                f4(-rx),
773	                f4(-t)
774	            ));
775	            v.push(format!("<ellipse cx=\"0\" cy=\"{}\" rx=\"{}\" ry=\"{}\"/>", f4(-t), f4(rx), f4(ry)));
776	        }
777	        Prim::Line | Prim::Poly | Prim::Path => {
778	            let sw = c.stroke_width;
779	            match &n.geo {
780	                Some(crate::scene::Geo::Path(d)) => v.push(format!("<path d=\"{}\"/>", xml_escape(d))),
781	                Some(crate::scene::Geo::Points(pts)) => {
782	                    let mut pts = pts.clone();
783	                    let ms = prop_str(ctx, i, "marker-start").or_else(|| prop_str(ctx, i, "marker"));
784	                    let me = prop_str(ctx, i, "marker-end").or_else(|| prop_str(ctx, i, "marker"));
785	                    let mut marks = Vec::new();
786	                    if n.prim == Prim::Line && pts.len() >= 2 {
787	                        let k = pts.len();
788	                        if let Some(m) = ms.as_deref() {
789	                            if m != "none" {
790	                                let (p, q) = (pts[0], pts[1]);
791	                                let (lines, pull) = crate::markers::marker(m, p, (p.0 - q.0, p.1 - q.1), sw);
792	                                marks.extend(lines);
793	                                let d = crate::markers::unit((q.0 - p.0, q.1 - p.1));
794	                                pts[0] = (p.0 + d.0 * pull, p.1 + d.1 * pull);
795	                            }
796	                        }
797	                        if let Some(m) = me.as_deref() {
798	                            if m != "none" {
799	                                let (p, q) = (pts[k - 1], pts[k - 2]);
800	                                let (lines, pull) = crate::markers::marker(m, p, (p.0 - q.0, p.1 - q.1), sw);
801	                                marks.extend(lines);
802	                                let d = crate::markers::unit((q.0 - p.0, q.1 - p.1));
803	                                pts[k - 1] = (p.0 + d.0 * pull, p.1 + d.1 * pull);
804	                            }
805	                        }
806	                    }
807	                    let ps: Vec<String> = pts.iter().map(|(x, y)| format!("{},{}", f4(*x), f4(*y))).collect();
808	                    if n.prim == Prim::Poly {
809	                        v.push(format!("<polygon points=\"{}\"/>", ps.join(" ")));
810	                    } else if pts.len() == 2 {
811	                        v.push(format!(
812	                            "<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\"/>",
813	                            f4(pts[0].0),
814	                            f4(pts[0].1),
815	                            f4(pts[1].0),
816	                            f4(pts[1].1)
817	                        ));
818	                    } else {
819	                        v.push(format!("<polyline points=\"{}\"/>", ps.join(" ")));
820	                    }
821	                    let stroke_style = ctx.nodes[i].inline.iter().rev().find(|d| d.name == "stroke").map(|d| d.value.clone());
822	                    for m in marks {
823	                        let mut m = m;
824	                        if let Some(sv) = &stroke_style {
825	                            if let Some(t) = single_term(sv) {
826	                                let mut tmp = Vec::new();
827	                                if let Ok(col) = color_css(t, &mut tmp, sv.span) {
828	                                    if m.contains("lini-marker-open") {
829	                                        // open glyphs inherit the line's stroke
830	                                    } else {
831	                                        m = m.replacen("/>", &format!(" style=\"fill: {}\"/>", col), 1);
832	                                    }
833	                                }
834	                            }
835	                        }
836	                        v.push(m);
837	                    }
838	                }
839	                None => {}
840	            }
841	        }
842	        Prim::Icon => v.extend(crate::icon::shape_lines(ctx, i)),
843	        Prim::Image => v.extend(crate::image::shape_lines(ctx, i)),
844	        _ => {}
845	    }
846	    v
847	}
