    &ctx.sheet.env
}

// The cascade for one node: type chain (base first, defaults then user
// rules), classes, id rules, inline. Returns (rule-level props, all props).
pub fn cascade(sheet: &SheetModel, n: &Node) -> (Vec<(String, Value)>, Vec<(String, Value)>) {
    let mut props: Vec<(String, Value)> = Vec::new();
    fn set(props: &mut Vec<(String, Value)>, k: &str, v: &Value) {
        if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
            e.1 = v.clone();
        } else {
            props.push((k.to_string(), v.clone()));
        }
    }
    // table column classes (.lini-align-*, .lini-justify-*) sit below every rule
    for t in n.chain.iter() {
        if let Some((k, v)) = crate::table::pseudo_class(t) {
            set(&mut props, k, &crate::table::pseudo_value(v));
        }
    }
    for t in n.chain.iter().rev() {
        for d in type_defaults(t) {
            set(&mut props, &d.name, &d.value);
        }
        if let Some(df) = sheet.define(t) {
            for d in &df.decls {
                set(&mut props, &d.name, &d.value);
            }
        }
        for d in sheet.type_rule(t) {
            set(&mut props, &d.name, &d.value);
        }
    }
    for c in &n.classes {
        if let Some(cr) = sheet.class(c) {
            for d in &cr.decls {
                set(&mut props, &d.name, &d.value);
            }
        }
    }
    let rule_level = props.clone();
    if let Some(id) = &n.id {
        for (rid, ds) in &sheet.id_rules {
            if rid == id {
                for d in ds {
                    set(&mut props, &d.name, &d.value);
                }
            }
        }
    }
    for d in &n.inline {
        set(&mut props, &d.name, &d.value);
    }
    (rule_level, props)
}

pub fn get<'a>(props: &'a [(String, Value)], k: &str) -> Option<&'a Value> {
    props.iter().find(|e| e.0 == k).map(|e| &e.1)
}

fn parse_align(s: &str) -> Option<Align> {
    match s {
        "start" | "top" | "left" => Some(Align::Start),
        "center" | "middle" => Some(Align::Center),
        "end" | "bottom" | "right" => Some(Align::End),
        "stretch" => Some(Align::Stretch),
        _ => None,
    }
}

pub fn compute(ctx: &mut Ctx) {
    let n = ctx.nodes.len();
    ctx.comp = vec![Computed::default(); n];
    // nodes are created parent-before-child, so a forward pass sees parents first
    for i in 0..n {
        let parent = ctx.nodes[i].parent;
        let pc = parent.map(|p| ctx.comp[p].clone());
        let (_, props) = if i == 0 { (vec![], ctx.nodes[0].inline.iter().map(|d| (d.name.clone(), d.value.clone())).collect()) } else { cascade(&ctx.sheet, &ctx.nodes[i]) };
        let env = &ctx.sheet.env;
        let mut c = Computed::default();
        if let Some(p) = &pc {
            c.font_size = p.font_size;
            c.font_weight = p.font_weight;
            c.family = p.family;
            c.letter_spacing = p.letter_spacing;
            c.line_spacing = p.line_spacing;
            c.text_transform = p.text_transform.clone();
            c.family_css = p.family_css.clone();
        }
        let num = |k: &str| get(&props, k).and_then(|v| value_num(env, v));
        if let Some(v) = num("font-size") {
            c.font_size = v;
        } else if let Some(v) = get(&props, "font-scale") {
            let xs = value_nums(env, v);
            if xs.len() == 2 {
                let base = pc.as_ref().map(|p| p.font_size).unwrap_or(15.0);
                c.font_size = xs[0] * base / xs[1];
            }
        }
        if let Some(v) = get(&props, "font-weight") {
            c.font_weight = weight_num(v);
        }
        if let Some(v) = get(&props, "font-family") {
            c.family = family_of(v);
            c.family_css = Some(font_family_css(v));
        }
        if let Some(v) = num("letter-spacing") {
            c.letter_spacing = v;
        }
        if let Some(v) = num("line-spacing") {
            c.line_spacing = v;
        }
        if let Some(v) = get(&props, "text-transform") {
            c.text_transform = ident_of(v).map(|s| s.to_string());
        }
        if let Some(v) = get(&props, "padding") {
            let xs = value_nums(env, v);
            c.padding = match xs.len() {
                1 => [xs[0]; 4],
                2 => [xs[0], xs[1], xs[0], xs[1]],
                4 => [xs[0], xs[1], xs[2], xs[3]],
                _ => [0.0; 4],
            };
        }
        if let Some(v) = get(&props, "gap") {
            let xs = value_nums(env, v);
            c.gap = match xs.len() {
                1 => (xs[0], xs[0]),
                2 => (xs[0], xs[1]),
                _ => c.gap,
            };
        }
        if let Some(v) = get(&props, "direction") {
            if ident_of(v) == Some("column") {
                c.direction = Dir::Column;
            }
        }
        if let Some(v) = get(&props, "align") {
            if let Some(a) = ident_of(v).and_then(parse_align) {
                c.align = a;
            }
        }
        if let Some(v) = get(&props, "justify") {
            if let Some(a) = ident_of(v).and_then(parse_align) {
                c.justify = a;
            }
        }
        c.width = num("width");
        c.height = num("height");
        c.max_width = num("max-width");
        if let Some(v) = num("stroke-width") {
            c.stroke_width = v;
        }
        if let Some(v) = get(&props, "stroke") {
            c.has_stroke = ident_of(v) != Some("none");
        }
        if let Some(v) = num("radius") {
            c.radius = v;
        }
        if let Some(v) = get(&props, "pin") {
            let mut parts = Vec::new();
            for g in &v.groups {
                for t in g {
                    if let Term::Ident(s, _) = t {
                        parts.push(s.clone());
                    }
                }
            }
            c.pin = Some(parts.join(" "));
        }
        if let Some(v) = get(&props, "translate") {
            let xs = value_nums(env, v);
            if xs.len() == 2 {
                c.translate = (xs[0], xs[1]);
            }
        }
        if let Some(v) = num("rotate") {
            c.rotate = v;
        }
        if let Some(v) = get(&props, "layout") {
            if let Some(s) = ident_of(v) {
                c.layout = s.to_string();
            }
        }
        if let Some(v) = get(&props, "text-wrap") {
            c.nowrap = ident_of(v) == Some("nowrap");
        }
        ctx.nodes[i].props = props.into_iter().collect();
        ctx.comp[i] = c;
    }
}

pub fn root_decls_node(sheet: &SheetModel) -> Node {
    let mut n = Node::new(Prim::Block, vec![], Span::default());
    let defaults = parse_decls("layout: flow; padding: 20; gap: 36; font-size: 15;");
    let mut inline = defaults;
    for d in &sheet.root {
        if let Some(e) = inline.iter_mut().find(|e| e.name == d.name) {
            *e = d.clone();
        } else {
            inline.push(d.clone());
        }
    }
    n.inline = inline;
    n
}
// Compile-time expression evaluation: bindings, functions, math.

use crate::ast::{Expr, Term};
use crate::diag::{Diag, Span};
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum EV {
    Num(f64),
    Tuple(Vec<EV>),
    Str(String),
}

impl EV {
    pub fn num(&self) -> Option<f64> {
        match self {
            EV::Num(v) => Some(*v),
            _ => None,
        }
    }
}

#[derive(Clone, Debug)]
pub struct Func {
    pub params: Vec<String>,
    pub body: Term,
}

#[derive(Default, Clone, Debug)]
pub struct Env {
    pub vars: HashMap<String, EV>,
    pub funcs: HashMap<String, Func>,
}

pub fn err(msg: &str, span: Span) -> Diag {
    Diag::error("resolve", msg, span)
}

impl Env {
    pub fn eval_term(&self, t: &Term, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
        match t {
            Term::Num(v, _, _) => Ok(EV::Num(*v)),
            Term::Group(e, _) => self.eval(e, locals),
            Term::Call(name, args, sp) => self.call(name, args, locals, *sp),
            Term::Ident(n, sp) => self.lookup(n, locals, *sp),
            Term::Str(s, _) => Ok(EV::Str(s.clone())),
            _ => Err(err("expected a number", t.span())),
        }
    }

    fn lookup(&self, n: &str, locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
        if let Some(v) = locals.get(n) {
            return Ok(v.clone());
        }
        if let Some(v) = self.vars.get(n) {
            return Ok(v.clone());
        }
        match n {
            "pi" => Ok(EV::Num(std::f64::consts::PI)),
            "e" => Ok(EV::Num(std::f64::consts::E)),
            _ => Err(err(&format!("unknown name '{}' in an expression", n), sp)),
        }
    }

    pub fn eval(&self, e: &Expr, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
        match e {
            Expr::Num(v, _) => Ok(EV::Num(*v)),
            Expr::Percent(v, _) => Ok(EV::Num(*v / 100.0)),
            Expr::Str(s, _) => Ok(EV::Str(s.clone())),
            Expr::Ident(n, sp) => self.lookup(n, locals, *sp),
            Expr::Var(_, sp) | Expr::Hash(_, sp) => Err(err("expected a number", *sp)),
            Expr::Call(name, args, sp) => self.call(name, args, locals, *sp),
            Expr::Unary(op, a, sp) => {
                let v = self.eval(a, locals)?;
                let x = v.num().ok_or_else(|| err("expected a number", *sp))?;
                Ok(EV::Num(match op.as_str() {
                    "-" => -x,
                    "!" => {
                        if x == 0.0 {
                            1.0
                        } else {
                            0.0
                        }
                    }
                    _ => x,
                }))
            }
            Expr::Bin(op, a, b, sp) => {
                let x = self.eval(a, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                if op == "&&" {
                    if x == 0.0 {
                        return Ok(EV::Num(0.0));
                    }
                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
                }
                if op == "||" {
                    if x != 0.0 {
                        return Ok(EV::Num(1.0));
                    }
                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
                }
                let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                let b2 = |c: bool| if c { 1.0 } else { 0.0 };
                Ok(EV::Num(match op.as_str() {
                    "+" => x + y,
                    "-" => x - y,
                    "*" => x * y,
                    "/" => x / y,
                    "^" => x.powf(y),
                    "<" => b2(x < y),
                    ">" => b2(x > y),
                    "<=" => b2(x <= y),
                    ">=" => b2(x >= y),
                    "==" => b2(x == y),
                    "!=" => b2(x != y),
                    _ => return Err(err("unknown operator", *sp)),
                }))
            }
            Expr::Ternary(c, a, b, sp) => {
                let cv = self.eval(c, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                if cv != 0.0 {
                    self.eval(a, locals)
                } else {
                    self.eval(b, locals)
                }
            }
            Expr::Tuple(items, _) => {
                let mut out = Vec::new();
                for it in items {
                    out.push(self.eval(it, locals)?);
                }
                Ok(EV::Tuple(out))
            }
            Expr::Block(binds, body, _) => {
                let mut l2 = locals.clone();
                for (n, ex) in binds {
                    let v = self.eval(ex, &l2)?;
                    l2.insert(n.clone(), v);
                }
                self.eval(body, &l2)
            }
        }
    }

    fn call(&self, name: &str, args: &[Expr], locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
        if let Some(f) = self.funcs.get(name) {
            let mut l2 = locals.clone();
            for (i, p) in f.params.iter().enumerate() {
                let v = match args.get(i) {
                    Some(a) => self.eval(a, locals)?,
                    None => EV::Num(0.0),
                };
                l2.insert(p.clone(), v);
            }
            return self.eval_term(&f.body, &l2);
        }
        let mut xs = Vec::new();
        for a in args {
            match self.eval(a, locals)? {
                EV::Num(v) => xs.push(v),
                _ => return Err(err("expected a number", a.span())),
            }
        }
        let a = |i: usize| xs.get(i).copied().unwrap_or(0.0);
        let v = match name {
            "sin" => a(0).sin(),
            "cos" => a(0).cos(),
            "tan" => a(0).tan(),
            "sqrt" => a(0).sqrt(),
            "abs" => a(0).abs(),
            "exp" => a(0).exp(),
            "ln" => a(0).ln(),
            "log" => a(0).log10(),
            "floor" => a(0).floor(),
            "round" => a(0).round(),
            "pow" => a(0).powf(a(1)),
            "min" => xs.iter().cloned().fold(f64::INFINITY, f64::min),
            "max" => xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
            "clamp" => a(0).max(a(1)).min(a(2)),
            _ => return Err(err(&format!("unknown function '{}'", name), sp)),
        };
        Ok(EV::Num(v))
    }
}

let (mut rule_props, all) = crate::compile::cascade(&ctx.sheet, n);
    let mut own: Vec<(String, Value)> = Vec::new();
    // no `.lini-image` rule is emitted: the image type's own rules ride inline
    let sw_default = if n.prim == Prim::Image { crate::image::inline_type_rules(ctx, n, &mut own, &mut rule_props) } else { 2.0 };
    if let Some(id) = &n.id {
        for (rid, ds) in &ctx.sheet.id_rules {
            if rid == id {
                for d in ds {
                    own.retain(|e| e.0 != d.name);
                    own.push((d.name.clone(), d.value.clone()));
                }
            }
        }
    }
    for d in &n.inline {
        own.retain(|e| e.0 != d.name);
        own.push((d.name.clone(), d.value.clone()));
    }
    let sw_all = get(&all, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(sw_default);
    let mut tmp = Vec::new();
    let own_d = css_decls(ctx, &own, &mut tmp, sw_all, text)?;
    let mut tmp2 = Vec::new();
    let sw_rule = get(&rule_props, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(sw_default);
    let rule_d = css_decls(ctx, &rule_props, &mut tmp2, sw_rule, text)?;
    let mut keep = Vec::new();
    let mut own_d = own_d;
    if text {
        if let Some(fam) = &ctx.comp[i].family_css {
            if !own_d.iter().any(|(k, _)| k == "font-family") {
                own_d.push(("font-family".into(), fam.clone()));
                let pos = |k: &str| CSS_ORDER.iter().position(|x| *x == k || (*x == "stroke-style" && k == "stroke-dasharray") || (*x == "color" && k == "fill" && false)).unwrap_or(99);
                own_d.sort_by_key(|(k, _)| if k == "fill" { 0 } else { pos(k) });
            }
        }
    }
    for (k, v) in own_d {
        if rule_d.iter().any(|(rk, rv)| rk == &k && rv == &v) {
            continue;
        }
        keep.push((k, v));
    }
    // stroke-style depends on the effective stroke width
    if get(&own, "stroke-style").is_none() && get(&own, "stroke-width").is_some() {
        if let Some(st) = get(&all, "stroke-style").and_then(ident_of) {
            if st != "solid" {
                if let Some(d) = dasharray(st, sw_all) {
                    if !rule_d.iter().any(|(rk, rv)| rk == "stroke-dasharray" && rv == &d) {
                        keep.push(("stroke-dasharray".into(), d));
                    }
                }
            }
        }
    }
    // a font-scale resolves against the parent's size, the rule against the root's
    if !text && get(&own, "font-size").is_none() && get(&all, "font-size").is_none() {
        if let Some(rule_sz) = font_scale_size(ctx, &all) {
            let sz = ctx.comp[i].font_size;
            if (sz - rule_sz).abs() > 1e-9 {
                let pos = |k: &str| CSS_ORDER.iter().position(|x| *x == k || (*x == "stroke-style" && k == "stroke-dasharray")).unwrap_or(99);
                let at = keep.iter().position(|(k, _)| pos(k) > pos("font-size")).unwrap_or(keep.len());
                keep.insert(at, ("font-size".to_string(), format!("{}px", f4(sz))));
            }
        }
    }
    let mut vars = Vec::new();
    let _ = css_decls(ctx, &own, &mut vars, sw_all, text)?;
    for (k, _) in &keep {
        let _ = k;
    }
    for v in vars {
        // only vars that survive into the emitted style count
        if keep.iter().any(|(_, val)| val.contains(&format!("var(--lini-{})", v))) {
            use_var(&mut out.vars, &v);
        }
    }
    Ok(join_decls(&keep))
}

fn render_text(ctx: &Ctx, i: usize, ind_n: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
    out.any_text = true;
    let n = &ctx.nodes[i];
    let c = &ctx.comp[i];
    let style = inline_style(ctx, i, out, true)?;
    let mut extra = String::new();
    let x = n.x + c.translate.0;
    let y = n.y + c.translate.1;
    let fam_attr = if let Some(v) = n.inline.iter().find(|d| d.name == "font-family") {
        Some(font_family_css(&v.value))
    } else {
        None
    };
    let _ = fam_attr;
    if !style.is_empty() {
        extra = format!(" style=\"{}\"", xml_escape(&style));
    }
    // worn classes ride the text element
    let mut tcls = String::from("lini-text");
    for k in &n.classes {
        tcls.push_str(&format!(" lini-style-{}", k));
        if !out.used_classes.contains(k) {
            out.used_classes.push(k.clone());
        }
    }
    let lines = &n.lines;
    let ls = c.letter_spacing;
    let dx_for = |l: &str| -> String {
        let cnt = l.chars().count();
        if ls != 0.0 && cnt > 1 {
            let mut v = vec!["0".to_string()];
            for _ in 1..cnt {
                v.push(f4(ls));
            }
            format!(" dx=\"{}\"", v.join(" "))
        } else {
            String::new()
        }
    };
    if lines.len() <= 1 {
        let l = lines.first().cloned().unwrap_or_default();
        s.push_str(&format!(
            "{}<text class=\"{}\" x=\"{}\" y=\"{}\" dy=\"0.358em\"{}{}>{}</text>\n",
            ind(ind_n),
            tcls,
            f4(x),
            f4(y),
            dx_for(&l),
            extra,
            xml_escape(&l)
        ));
    } else {
        let pitch = 1.2 * c.font_size + c.line_spacing;
        let total = (lines.len() as f64 - 1.0) * pitch;
        let first = y - total / 2.0 + 0.358 * c.font_size;
        let mut t = String::new();
        // lines flush by the holding box's horizontal knob
        let knob = crate::table::text_flush(ctx, i);
        for (k, l) in lines.iter().enumerate() {
            let slack = n.w - crate::layout::line_width(ctx, i, l);
            let lx = match knob {
                crate::compile::Align::Start => x - slack / 2.0,
                crate::compile::Align::End => x + slack / 2.0,
                _ => x,
            };
            if k == 0 {
                t.push_str(&format!("<tspan x=\"{}\" y=\"{}\"{}>{}</tspan>", f4(lx), f4(first), dx_for(l), xml_escape(l)));
            } else {
                t.push_str(&format!("<tspan x=\"{}\" dy=\"{}\"{}>{}</tspan>", f4(lx), f4(pitch), dx_for(l), xml_escape(l)));
            }
        }
        s.push_str(&format!("{}<text class=\"{}\" x=\"{}\" y=\"{}\"{}>{}</text>\n", ind(ind_n), tcls, f4(x), f4(y), extra, t));
    }
    Ok(())
}

pub fn prop_str(ctx: &Ctx, i: usize, k: &str) -> Option<String> {
    let v = ctx.nodes[i].props.get(k)?;
    match single_term(v)? {
        Term::Str(x, _) => Some(x.clone()),
        Term::Ident(x, _) => Some(x.clone()),
        _ => None,
    }
}

pub fn prop_nums(ctx: &Ctx, i: usize, k: &str) -> Vec<f64> {
    match ctx.nodes[i].props.get(k) {
        Some(v) => value_nums(&ctx.sheet.env, v),
        None => vec![],
    }
}

// The node's outline elements (unindented), centred on its origin.
pub fn shape_lines(ctx: &Ctx, i: usize) -> Vec<String> {
    let n = &ctx.nodes[i];
    let c = &ctx.comp[i];
    let (w, h) = (n.w, n.h);
    if let Some(v) = crate::drawing::shape_override(ctx, i) {
        return v;
    }
    let mut v = Vec::new();
    match n.prim {
        Prim::Block if w == 0.0 || h == 0.0 => {}
        Prim::Block => {
            v.push(format!(
                "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" ry=\"{}\"/>",
                f4(-w / 2.0),
                f4(-h / 2.0),
                f4(w),
                f4(h),
                f4(c.radius),
                f4(c.radius)
            ));
        }
        Prim::Oval => {
            v.push(format!("<ellipse cx=\"0\" cy=\"0\" rx=\"{}\" ry=\"{}\"/>", f4(w / 2.0), f4(h / 2.0)));
        }
        Prim::Hex => {
            v.push(format!(
                "<polygon points=\"{},0 {},{} {},{} {},0 {},{} {},{}\"/>",
                f4(-w / 2.0),
                f4(-w / 4.0),
                f4(-h / 2.0),
                f4(w / 4.0),
                f4(-h / 2.0),
                f4(w / 2.0),
                f4(w / 4.0),
                f4(h / 2.0),
                f4(-w / 4.0),
                f4(h / 2.0)
            ));
        }
        Prim::Diamond => {
            v.push(format!(
                "<polygon points=\"0,{} {},0 0,{} {},0\"/>",
                f4(-h / 2.0),
                f4(w / 2.0),
                f4(h / 2.0),
                f4(-w / 2.0)
            ));
        }
        Prim::Slant => {
            let skew = prop_nums(ctx, i, "skew").first().copied().unwrap_or(15.0);
            let off = (skew.to_radians()).tan() * h / 2.0;
            v.push(format!(
                "<polygon points=\"{},{} {},{} {},{} {},{}\"/>",
                f4(-w / 2.0 + off),
                f4(-h / 2.0),
                f4(w / 2.0 + off),
                f4(-h / 2.0),
                f4(w / 2.0 - off),
                f4(h / 2.0),
                f4(-w / 2.0 - off),
                f4(h / 2.0)
            ));
        }
        Prim::Cyl => {
            let ry = h * 0.1;
            let rx = w / 2.0;
            let t = h / 2.0 - ry;
            v.push(format!(
                "<path d=\"M {} {} L {} {} A {} {} 0 0 0 {} {} L {} {} A {} {} 0 0 0 {} {} Z\"/>",
                f4(-rx),
                f4(-t),
                f4(-rx),
                f4(t),
                f4(rx),
                f4(ry),
                f4(rx),
                f4(t),
                f4(rx),
                f4(-t),
                f4(rx),
                f4(ry),
                f4(-rx),
                f4(-t)
            ));
            v.push(format!("<ellipse cx=\"0\" cy=\"{}\" rx=\"{}\" ry=\"{}\"/>", f4(-t), f4(rx), f4(ry)));
        }
        Prim::Line | Prim::Poly | Prim::Path => {
            let sw = c.stroke_width;
            match &n.geo {
                Some(crate::scene::Geo::Path(d)) => v.push(format!("<path d=\"{}\"/>", xml_escape(d))),
                Some(crate::scene::Geo::Points(pts)) => {
                    let mut pts = pts.clone();
                    let ms = prop_str(ctx, i, "marker-start").or_else(|| prop_str(ctx, i, "marker"));
                    let me = prop_str(ctx, i, "marker-end").or_else(|| prop_str(ctx, i, "marker"));
                    let mut marks = Vec::new();
                    if n.prim == Prim::Line && pts.len() >= 2 {
                        let k = pts.len();
                        if let Some(m) = ms.as_deref() {
                            if m != "none" {
                                let (p, q) = (pts[0], pts[1]);
                                let (lines, pull) = crate::markers::marker(m, p, (p.0 - q.0, p.1 - q.1), sw);
                                marks.extend(lines);
                                let d = crate::markers::unit((q.0 - p.0, q.1 - p.1));
                                pts[0] = (p.0 + d.0 * pull, p.1 + d.1 * pull);
                            }
                        }
                        if let Some(m) = me.as_deref() {
                            if m != "none" {
                                let (p, q) = (pts[k - 1], pts[k - 2]);
                                let (lines, pull) = crate::markers::marker(m, p, (p.0 - q.0, p.1 - q.1), sw);
                                marks.extend(lines);
                                let d = crate::markers::unit((q.0 - p.0, q.1 - p.1));
                                pts[k - 1] = (p.0 + d.0 * pull, p.1 + d.1 * pull);
                            }
                        }
                    }
                    let ps: Vec<String> = pts.iter().map(|(x, y)| format!("{},{}", f4(*x), f4(*y))).collect();
                    if n.prim == Prim::Poly {
                        v.push(format!("<polygon points=\"{}\"/>", ps.join(" ")));
                    } else if pts.len() == 2 {
                        v.push(format!(
                            "<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\"/>",
                            f4(pts[0].0),
                            f4(pts[0].1),
                            f4(pts[1].0),
                            f4(pts[1].1)
                        ));
                    } else {
                        v.push(format!("<polyline points=\"{}\"/>", ps.join(" ")));
                    }
                    let stroke_style = ctx.nodes[i].inline.iter().rev().find(|d| d.name == "stroke").map(|d| d.value.clone());
                    for m in marks {
                        let mut m = m;
                        if let Some(sv) = &stroke_style {
                            if let Some(t) = single_term(sv) {
                                let mut tmp = Vec::new();
                                if let Ok(col) = color_css(t, &mut tmp, sv.span) {
                                    if m.contains("lini-marker-open") {
                                        // open glyphs inherit the line's stroke
                                    } else {
                                        m = m.replacen("/>", &format!(" style=\"fill: {}\"/>", col), 1);
                                    }
                                }
                            }
                        }
                        v.push(m);
                    }
                }
                None => {}
            }
        }
        Prim::Icon => v.extend(crate::icon::shape_lines(ctx, i)),
        Prim::Image => v.extend(crate::image::shape_lines(ctx, i)),
        _ => {}
    }
    v
}

fn shadow_filter(ctx: &Ctx, i: usize, out: &mut Out) -> Option<String> {
    let xs = prop_nums(ctx, i, "shadow");
    if xs.len() < 3 {
        return None;
    }
    let theme = crate::theme::resolve("default").unwrap();
    let col = theme.light_value("shadow-color").unwrap_or_default();
    let key = format!("{},{},{},{}", f4(xs[0]), f4(xs[1]), f4(xs[2]), col);
    let id = format!("lini-shadow-{}", hash8(&key));
    let def = format!(
        "<filter id=\"{}\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feDropShadow dx=\"{}\" dy=\"{}\" stdDeviation=\"{}\" flood-color=\"{}\"/></filter>",
        id,
        f4(xs[0]),
        f4(xs[1]),
        f4(xs[2]),
        col
    );
    if !out.defs.contains(&def) {
        out.defs.push(def);
    }
    Some(id)
}

pub fn render_node(ctx: &Ctx, i: usize, ind_n: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
    let n = &ctx.nodes[i];
    let c = &ctx.comp[i];
    if n.prim == Prim::Text {
        return render_text(ctx, i, ind_n, s, out);
    }
    if crate::drawing::is_chrome(ctx, i) {
        return crate::drawing::render_chrome(ctx, i, ind_n, s, out);
    }
    let href = prop_str(ctx, i, "href");
    let mut ind_n = ind_n;
    if let Some(h) = &href {
        s.push_str(&format!("{}<a href=\"{}\">\n", ind(ind_n), xml_escape(h)));
        ind_n += 2;
    }
    let cls = node_classes(ctx, i, out);
    if n.is("table") {
        // a table resolves its header band's look whether or not a band is drawn
        let hp = type_rule_props(ctx, "header");
        let _ = css_decls(ctx, &hp, &mut out.vars, 2.0, false)?;
    }
    let style = inline_style(ctx, i, out, false)?;
    let mut head = format!("{}<g class=\"{}\"", ind(ind_n), cls);
    if let Some(id) = &n.id {
        head.push_str(&format!(" data-id=\"{}\"", xml_escape(id)));
    }
    if !style.is_empty() {
        head.push_str(&format!(" style=\"{}\"", xml_escape(&style)));
    }
    let tx = n.x + c.translate.0 + n.geo_off.0;
    let ty = n.y + c.translate.1 + n.geo_off.1;
    head.push_str(&format!(" transform=\"translate({},{})", f4(tx), f4(ty)));
    if c.rotate != 0.0 {
        head.push_str(&format!(" rotate({})", f4(c.rotate)));
    }
    head.push_str("\">\n");
    s.push_str(&head);
    let ci = ind_n + 2;
    if let Some(hint) = prop_str(ctx, i, "hint") {
        s.push_str(&format!("{}<title>{}</title>\n", ind(ci), xml_escape(&hint)));
    }
    if crate::chart::is_chart(ctx, i) {
        crate::chart::render(ctx, i, ci, s, out)?;
        s.push_str(&format!("{}</g>\n", ind(ind_n)));
        if href.is_some() {
            s.push_str(&format!("{}</a>\n", ind(ind_n - 2)));
        }
        return Ok(());
    }
    // a closed outline with no area is not drawn
    let empty = matches!(n.prim, Prim::Block | Prim::Oval | Prim::Hex | Prim::Slant | Prim::Cyl | Prim::Diamond) && (n.w <= 0.0 || n.h <= 0.0);
    let shape = if empty { vec![] } else { shape_lines(ctx, i) };
    if shape.iter().any(|l| l.contains("lini-marker")) {
        out.markers = true;
    }
    let multiple = prop_nums(ctx, i, "multiple").first().copied();
    let shadow = shadow_filter(ctx, i, out);
    let mut si = ci;
    if let Some(id) = &shadow {
        s.push_str(&format!("{}<g filter=\"url(#{})\">\n", ind(si), id));
        si += 2;
    }
    if let Some(m) = multiple {
        s.push_str(&format!("{}<g transform=\"translate({},{})\">\n", ind(si), f4(m), f4(-m)));
        for l in &shape {
            s.push_str(&format!("{}{}\n", ind(si + 2), l));
        }
        s.push_str(&format!("{}</g>\n", ind(si)));
    }
    for l in &shape {
        s.push_str(&format!("{}{}\n", ind(si), l));
    }
    if shadow.is_some() {
        s.push_str(&format!("{}</g>\n", ind(ci)));
    }
    if !n.gutters.is_empty() {
        let fill = match ctx.nodes[i].props.get("gap-fill").and_then(single_term) {
            Some(t) => color_css(t, &mut out.vars, t.span())?,
            None => String::new(),
        };
        out.gutters = true;
        for &(x, y, w, h) in &n.gutters {
            s.push_str(&format!(
                "{}<rect class=\"lini-gutter\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" fill=\"{}\"/>\n",
                ind(ci),
                f4(x),
                f4(y),
                f4(w),
                f4(h),
                xml_escape(&fill)
            ));
        }
    }
    let ordered = paint_order(ctx, &n.children);
    for ch in ordered {
        render_node(ctx, ch, ci, s, out)?;
    }
    s.push_str(&format!("{}</g>\n", ind(ind_n)));
    if href.is_some() {
        s.push_str(&format!("{}</a>\n", ind(ind_n - 2)));
    }
    Ok(())
}

// Stylesheet rule order. Type rules use their type name as the slot; user
// defines and classes use "@define:NNNN" / "@class:NNNN".
pub static SLOT_ORDER: &[&str] = &[
    "canvas",
    "block", "oval", "hex", "slant", "cyl", "diamond", "poly", "path", "sketch", "line", "dim-text", "text", "icon", "image",
    "chart-title", "chart-text", "chart-label", "chart-legend", "gutter",
    "box", "rect", "group", "row", "column", "grid", "caption", "footnote", "badge", "table", "cell", "header", "entity",
    "sign", "note", "topic", "mindmap", "chart", "bars", "area", "dots", "bubble", "band", "mark", "axis", "pie", "slice",
    "sequence", "loop", "alt", "opt", "else", "stack", "drawing", "floorplan", "hole", "centerline",
    "pitch-circle", "breakline", "hidden", "shoulder", "threadline", "plane", "magnifier", "feature-control", "datum",
    "surface-finish", "balloon", "page", "title-block",
    "field", "frame", "zone", "tick", "wall", "partition", "door", "window", "stairs", "bed", "sofa", "dining",
    "appliance", "bath", "schematic", "sch-line", "ref", "component", "pin", "space", "label",
    "@define",
    "link", "link-dashed", "link-dotted", "link-label", "cut-bg", "cut", "marker", "marker-dim", "plane-end",
    "plane-shaft", "plane-arrow", "link-marker", "chart-label-pe",
    "@class",
    "marker-open",
    "chart-tip", "chart-hit",
];

pub fn slot_rank(slot: &str) -> (usize, String) {
    if let Some(rest) = slot.strip_prefix("@define:") {
        let p = SLOT_ORDER.iter().position(|s| *s == "@define").unwrap();
        return (p, rest.to_string());
    }
    if let Some(rest) = slot.strip_prefix("@class:") {
        let p = SLOT_ORDER.iter().position(|s| *s == "@class").unwrap();
        return (p, rest.to_string());
    }
    match SLOT_ORDER.iter().position(|s| *s == slot) {
        Some(p) => (p, String::new()),
        None => (SLOT_ORDER.len(), slot.to_string()),
    }
}

