pub struct Out {
    pub body: String,
    pub vars: Vec<String>,
    pub used_types: Vec<String>,
    pub used_classes: Vec<String>,
    pub any_text: bool,
    pub defs: Vec<String>,
    pub markers: bool,
    pub gutters: bool,
