// Engineering drawings: the chrome a part grows inside a drawing — the
// centerlines of mirrored and turned outlines, shoulder edges, thread and
// break lines, a hole's cross of centerlines, a cutting plane's mark — and
// the caption a view carries under it.

use super::lower::Cx;
use super::out::{Item, ONode};
use super::syntax::Decl;

fn chrome(cx: &mut Cx, ty: &str, what: &str) -> Item {
    let mut l = cx.typed(ty);
    l.decls = vec![Decl::val("chrome", what)];
    Item::Node(l)
}

// the first declaration of a property speaks for the drawing pass
fn first_term(o: &ONode, name: &str) -> Option<String> {
    o.decls.iter().find(|d| d.name == name).and_then(|d| d.first().map(|s| s.to_string()))
}

// a datum plane in a drawing draws as chrome (written with its own decls)
pub fn plane_chrome(o: &mut ONode, chain: &[String]) {
    if chain.iter().any(|c| c == "plane") {
        o.decls.push(Decl::val("chrome", "plane"));
    }
}

// the plan's measures (wall thickness, the size unit): under a drawing or a
// stack, whichever unit context is nearest
pub fn plan_decls(cx: &mut Cx, o: &mut ONode, chain: &[String]) {
    floorplan(cx, o, chain, true, false);
}

// a drawing's chrome: centre lines, thread and break lines, plane chrome,
// floor-plan linework
pub fn chrome_after(cx: &mut Cx, o: &mut ONode, chain: &[String]) {
    let is = |t: &str| chain.iter().any(|c| c == t);
    if o.prim == "sketch" {
        let mut extra = Vec::new();
        if let Some(m) = first_term(o, "mirror") {
            // an open outline fuses across its axis and draws it
            if m != "none" && any_open(o) {
                extra.push(chrome(cx, "centerline", &m));
            }
        }
        if let Some(r) = first_term(o, "revolve") {
            extra.push(chrome(cx, "centerline", &r));
            extra.push(chrome(cx, "shoulder", "edges"));
            if o.decls.iter().any(|d| d.name == "thread") {
                extra.push(chrome(cx, "threadline", "thread"));
            }
        }
        if o.decls.iter().any(|d| d.name == "break") {
            extra.push(chrome(cx, "breakline", "break 0"));
            extra.push(chrome(cx, "breakline", "break 1"));
        }
        o.children.extend(extra);
    } else if is("hole") {
        let mut extra = vec![chrome(cx, "centerline", "x-axis"), chrome(cx, "centerline", "y-axis")];
        // a thread is one positive number
        let thread = o.decls.iter().find(|d| d.name == "thread").and_then(|d| match d.groups.as_slice() {
            [g] if g.len() == 1 && g[0].parse::<f64>().map_or(false, |v| v > 0.0) => Some(g[0].clone()),
            _ => None,
        });
        if let Some(t) = thread {
            extra.push(chrome(cx, "threadline", &format!("thread-arc internal {}", t)));
        }
        if first_term(o, "pattern").map_or(false, |p| p.starts_with("radial(")) {
            extra.push(chrome(cx, "pitch-circle", "ring"));
        }
        o.children.extend(extra);
    }
    floorplan(cx, o, chain, false, true);
}

fn unit_mm(cx: &Cx) -> f64 {
    let unit = cx.stack.last().and_then(|f| f.unit.clone());
    match unit.as_deref().and_then(super::sheet::unit_mm) {
        Some(Some(m)) => m,
        _ => 1.0,
    }
}

fn num(v: f64) -> String {
    crate::format::parse::render_number(v)
}

// floor plans: wall thickness and the size unit, door/window/stair linework
fn floorplan(cx: &mut Cx, o: &mut ONode, chain: &[String], decls: bool, linework: bool) {
    let is = |t: &str| chain.iter().any(|c| c == t);
    if is("wall") {
        if decls && !o.decls.iter().any(|d| d.name == "thickness") {
            let t = if is("partition") {
                num(100.0 / unit_mm(cx))
            } else {
                match cx.stack.last().and_then(|f| f.thickness.clone()) {
                    Some(t) => t,
                    None => num(200.0 / unit_mm(cx)),
                }
            };
            o.decls.push(Decl::val("wall-thickness", &t));
        }
        return;
    }
    let fixture = ["door", "window", "stairs", "bed", "sofa", "dining", "bath", "appliance"];
    if !fixture.iter().any(|f| is(f)) {
        return;
    }
    if decls {
        o.decls.push(Decl::val("unit-mm", &num(unit_mm(cx))));
    }
    if !linework {
        return;
    }
    let mut extra = Vec::new();
    if is("door") {
        match first_term(o, "symbol").as_deref() {
            Some("double") => {
                extra.push(chrome(cx, "door-leaf", "leaf 0"));
                extra.push(chrome(cx, "door-swing", "swing 0"));
                extra.push(chrome(cx, "door-leaf", "leaf 1"));
                extra.push(chrome(cx, "door-swing", "swing 1"));
            }
            Some("sliding") => {
                extra.push(chrome(cx, "door-leaf", "panel 0"));
                extra.push(chrome(cx, "door-leaf", "panel 1"));
            }
            _ => {
                extra.push(chrome(cx, "door-leaf", "leaf 0"));
                extra.push(chrome(cx, "door-swing", "swing 0"));
            }
        }
    } else if is("window") {
        extra.push(chrome(cx, "window-sill", "sill 0"));
        extra.push(chrome(cx, "window-sill", "sill 1"));
    } else if is("stairs") {
        if let Some(n) = first_term(o, "steps").and_then(|s| s.parse::<f64>().ok()) {
            let n = n.trunc();
            if n >= 2.0 {
                for k in 0..(n as i64 - 1) {
                    extra.push(chrome(cx, "stair-tread", &format!("tread {}", k)));
                }
                extra.push(chrome(cx, "stair-arrow", "arrow 0"));
            }
        }
    }
    o.children.extend(extra);
}

// does any subpath of the outline stay open (not ended by close() or a circle)?
fn any_open(o: &ONode) -> bool {
    let d = match o.decls.iter().rev().find(|d| d.name == "draw") {
        Some(d) => d,
        None => return false,
    };
    let terms: Vec<&String> = d.groups.iter().flatten().collect();
    let mut subpaths: Vec<Vec<&String>> = vec![Vec::new()];
    for t in terms {
        if t.starts_with("move(") {
            if !subpaths.last().unwrap().is_empty() {
                subpaths.push(Vec::new());
            }
            continue;
        }
        subpaths.last_mut().unwrap().push(t);
    }
    // circles stand apart and corner modifiers draw nothing: a subpath is
    // open unless its strokes end in close()
    subpaths.iter().any(|s| {
        let strokes: Vec<&str> = s
            .iter()
            .map(|t| t.split(':').next().unwrap_or(""))
            .filter(|h| {
                !(h.starts_with("circle(") || h.starts_with("fillet(") || h.starts_with("chamfer(") || h.starts_with("point("))
            })
            .collect();
        match strokes.last() {
            None => false,
            Some(h) => *h != "close()",
        }
    })
}

// The compile pipeline: scene → styles → layout → routes → SVG.

use crate::ast::*;
use crate::diag::{Diag, Span};
use crate::eval::Env;
use crate::font::Family;
use crate::scene::*;
use crate::style::*;
use crate::types::Prim;
use std::collections::HashMap;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Dir {
    Row,
    Column,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Align {
    Start,
    Center,
    End,
    Stretch,
}

#[derive(Clone, Debug)]
pub struct Computed {
    pub font_size: f64,
    pub font_weight: u32,
    pub family: Family,
    pub letter_spacing: f64,
    pub line_spacing: f64,
    pub text_transform: Option<String>,
    pub padding: [f64; 4], // top right bottom left
    pub gap: (f64, f64),   // (row gap, column gap)
    pub direction: Dir,
    pub align: Align,
    pub justify: Align,
    pub width: Option<f64>,
    pub height: Option<f64>,
    pub max_width: Option<f64>,
    pub stroke_width: f64,
    pub has_stroke: bool,
    pub radius: f64,
    pub pin: Option<String>,
    pub translate: (f64, f64),
    pub rotate: f64,
    pub layout: String,
    pub nowrap: bool,
    pub family_css: Option<String>,
}

impl Default for Computed {
    fn default() -> Self {
        Computed {
            font_size: 15.0,
            font_weight: 500,
            family: Family::Sans,
            letter_spacing: 0.0,
            line_spacing: 0.0,
            text_transform: None,
            padding: [0.0; 4],
            gap: (36.0, 36.0),
            direction: Dir::Row,
            align: Align::Center,
            justify: Align::Center,
            width: None,
            height: None,
            max_width: None,
            stroke_width: 2.0,
            has_stroke: false,
            radius: 0.0,
            pin: None,
            translate: (0.0, 0.0),
            rotate: 0.0,
            layout: "flow".into(),
            nowrap: false,
            family_css: None,
        }
    }
}

pub struct Ctx {
    pub src: String,
    pub file: String,
    pub sheet: SheetModel,
    pub nodes: Vec<Node>,
    pub comp: Vec<Computed>,
    pub links: Vec<Link>,
    pub warnings: Vec<Diag>,
    pub root_font_size: f64,
    // sketch / drawing layout state (src/drawing.rs)
    pub sk: crate::drawing::State,
    // routed links (filled by links::compute after layout)
    pub link_geo: Vec<crate::links::LinkGeo>,
}

pub fn env(ctx: &Ctx) -> &Env {
    &ctx.sheet.env
}

// The cascade for one node: type chain (base first, defaults then user
// rules), classes, id rules, inline. Returns (rule-level props, all props).
pub fn cascade(sheet: &SheetModel, n: &Node) -> (Vec<(String, Value)>, Vec<(String, Value)>) {
    let mut props: Vec<(String, Value)> = Vec::new();
    fn set(props: &mut Vec<(String, Value)>, k: &str, v: &Value) {
        if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
            e.1 = v.clone();
        } else {
            props.push((k.to_string(), v.clone()));
        }
    }
    // table column classes (.lini-align-*, .lini-justify-*) sit below every rule
    for t in n.chain.iter() {
        if let Some((k, v)) = crate::table::pseudo_class(t) {
            set(&mut props, k, &crate::table::pseudo_value(v));
        }
    }
    for t in n.chain.iter().rev() {
        for d in type_defaults(t) {
            set(&mut props, &d.name, &d.value);
        }
        if let Some(df) = sheet.define(t) {
            for d in &df.decls {
                set(&mut props, &d.name, &d.value);
            }
        }
        for d in sheet.type_rule(t) {
            set(&mut props, &d.name, &d.value);
        }
    }
    for c in &n.classes {
        if let Some(cr) = sheet.class(c) {
            for d in &cr.decls {
                set(&mut props, &d.name, &d.value);
            }
        }
    }
    let rule_level = props.clone();
    if let Some(id) = &n.id {
        for (rid, ds) in &sheet.id_rules {
            if rid == id {
                for d in ds {
                    set(&mut props, &d.name, &d.value);
                }
            }
        }
    }
    for d in &n.inline {
        set(&mut props, &d.name, &d.value);
    }
    (rule_level, props)
}

pub fn get<'a>(props: &'a [(String, Value)], k: &str) -> Option<&'a Value> {
    props.iter().find(|e| e.0 == k).map(|e| &e.1)
}

fn parse_align(s: &str) -> Option<Align> {
    match s {
        "start" | "top" | "left" => Some(Align::Start),
        "center" | "middle" => Some(Align::Center),
        "end" | "bottom" | "right" => Some(Align::End),
        "stretch" => Some(Align::Stretch),
        _ => None,
    }
}

pub fn compute(ctx: &mut Ctx) {
    let n = ctx.nodes.len();
    ctx.comp = vec![Computed::default(); n];
    // nodes are created parent-before-child, so a forward pass sees parents first
    for i in 0..n {
        let parent = ctx.nodes[i].parent;
        let pc = parent.map(|p| ctx.comp[p].clone());
        let (_, props) = if i == 0 { (vec![], ctx.nodes[0].inline.iter().map(|d| (d.name.clone(), d.value.clone())).collect()) } else { cascade(&ctx.sheet, &ctx.nodes[i]) };
        let env = &ctx.sheet.env;
        let mut c = Computed::default();
        if let Some(p) = &pc {
            c.font_size = p.font_size;
            c.font_weight = p.font_weight;
            c.family = p.family;
            c.letter_spacing = p.letter_spacing;
            c.line_spacing = p.line_spacing;
            c.text_transform = p.text_transform.clone();
            c.family_css = p.family_css.clone();
        }
        let num = |k: &str| get(&props, k).and_then(|v| value_num(env, v));
        if let Some(v) = num("font-size") {
            c.font_size = v;
        } else if let Some(v) = get(&props, "font-scale") {
            let xs = value_nums(env, v);
            if xs.len() == 2 {
                let base = pc.as_ref().map(|p| p.font_size).unwrap_or(15.0);
                c.font_size = xs[0] * base / xs[1];
            }
        }
        if let Some(v) = get(&props, "font-weight") {
            c.font_weight = weight_num(v);
        }
        if let Some(v) = get(&props, "font-family") {
            c.family = family_of(v);
            c.family_css = Some(font_family_css(v));
        }
        if let Some(v) = num("letter-spacing") {
            c.letter_spacing = v;
        }
        if let Some(v) = num("line-spacing") {
            c.line_spacing = v;
        }
        if let Some(v) = get(&props, "text-transform") {
            c.text_transform = ident_of(v).map(|s| s.to_string());
        }
        if let Some(v) = get(&props, "padding") {
            let xs = value_nums(env, v);
            c.padding = match xs.len() {
                1 => [xs[0]; 4],
                2 => [xs[0], xs[1], xs[0], xs[1]],
                4 => [xs[0], xs[1], xs[2], xs[3]],
                _ => [0.0; 4],
            };
        }
        if let Some(v) = get(&props, "gap") {
            let xs = value_nums(env, v);
            c.gap = match xs.len() {
                1 => (xs[0], xs[0]),
                2 => (xs[0], xs[1]),
                _ => c.gap,
            };
        }
        if let Some(v) = get(&props, "direction") {
            if ident_of(v) == Some("column") {
                c.direction = Dir::Column;
            }
        }
        if let Some(v) = get(&props, "align") {
            if let Some(a) = ident_of(v).and_then(parse_align) {
                c.align = a;
            }
        }
        if let Some(v) = get(&props, "justify") {
            if let Some(a) = ident_of(v).and_then(parse_align) {
                c.justify = a;
            }
        }
        c.width = num("width");
        c.height = num("height");
        c.max_width = num("max-width");
        if let Some(v) = num("stroke-width") {
            c.stroke_width = v;
        }
        if let Some(v) = get(&props, "stroke") {
            c.has_stroke = ident_of(v) != Some("none");
        }
        if let Some(v) = num("radius") {
            c.radius = v;
        }
        if let Some(v) = get(&props, "pin") {
            let mut parts = Vec::new();
            for g in &v.groups {
                for t in g {
                    if let Term::Ident(s, _) = t {
                        parts.push(s.clone());
                    }
                }
            }
            c.pin = Some(parts.join(" "));
        }
        if let Some(v) = get(&props, "translate") {
            let xs = value_nums(env, v);
            if xs.len() == 2 {
                c.translate = (xs[0], xs[1]);
            }
        }
        if let Some(v) = num("rotate") {
            c.rotate = v;
        }
        if let Some(v) = get(&props, "layout") {
            if let Some(s) = ident_of(v) {
                c.layout = s.to_string();
            }
        }
        if let Some(v) = get(&props, "text-wrap") {
            c.nowrap = ident_of(v) == Some("nowrap");
        }
        ctx.nodes[i].props = props.into_iter().collect();
        ctx.comp[i] = c;
    }
}

pub fn root_decls_node(sheet: &SheetModel) -> Node {
    let mut n = Node::new(Prim::Block, vec![], Span::default());
    let defaults = parse_decls("layout: flow; padding: 20; gap: 36; font-size: 15;");
    let mut inline = defaults;
    for d in &sheet.root {
        if let Some(e) = inline.iter_mut().find(|e| e.name == d.name) {
            *e = d.clone();
        } else {
            inline.push(d.clone());
        }
    }
    n.inline = inline;
    n
}

