#!/usr/bin/env python3
# Mask-id hash helpers: hash8 of `x y w h [(cx, cy, cw, ch), ...]` with Rust {:?} floats.
import math


def rdbg(x):
    if x == 0:
        return '-0.0' if math.copysign(1, x) < 0 else '0.0'
    if x == int(x) and abs(x) < 1e16:
        return '%d.0' % int(x)
    r = repr(x)
    if 'e' in r:
        m, e = r.split('e')
        e = int(e)
        return '%se%d' % (m, e)
    return r


def fnv(s):
    h = 0xcbf29ce484222325
    for b in s.encode():
        h ^= b
        h = (h * 0x100000001b3) & 0xFFFFFFFFFFFFFFFF
    return '%08x' % (((h >> 32) ^ h) & 0xFFFFFFFF)


def key(x0, y0, w, h, cuts):
    cs = ', '.join('(%s, %s, %s, %s)' % tuple(rdbg(v) for v in c) for c in cuts)
    return '%s %s %s %s [%s]' % (rdbg(x0), rdbg(y0), rdbg(w), rdbg(h), cs)


def mask_id(x0, y0, w, h, cuts):
    return fnv(key(x0, y0, w, h, cuts))


def cut_exact(x, y, units, upem, fs):
    tw = 0.0
    for u in units:
        tw += u / upem * fs
    w = tw + 2.0 * (0.3 * fs)
    hh = fs + 2.0 * (0.15 * fs)
    return (x - w / 2.0, y - hh / 2.0, w, hh)

