import sys, struct, itertools
sys.path.insert(0, '/tmp/link2')
from mh import *
def ulp(x, n):
    b = struct.unpack('<q', struct.pack('<d', x))[0]
    b = b - n if x < 0 else b + n
    return struct.unpack('<d', struct.pack('<q', b))[0]
target = sys.argv[1] if len(sys.argv) > 1 else 'a4492179'
X0, X1, Y = -41.95500000000001, 43.57499999999999, -63.0
t = 0.35
found = 0
for dx0 in range(-6, 7):
    for dx1 in range(-6, 7):
        x0p = ulp(X0, dx0); x1p = ulp(X1, dx1)
        for mform in range(2):
            m = 2.0
            mbx0 = x0p - m
            if mform == 0:
                mbw = (x1p + m) - (x0p - m)
            else:
                mbw = (x1p - x0p) + 2 * m
            L = x1p - x0p
            xs = set([x0p + (x1p - x0p) * t, x0p + t * L, x0p * (1 - t) + x1p * t, x1p - (1 - t) * L, (x0p + x1p) / 2 + (t - 0.5) * L])
            for dl in range(-3, 4):
                for xv in list(xs):
                    xv2 = ulp(xv, dl)
                    for cform in range(2):
                        if cform == 0:
                            c = cut_exact(xv2, Y, [619.0], 1000.0, 11.0)
                        else:
                            tw = 619.0 / 1000.0 * 11.0
                            w = tw + 0.6 * 11.0
                            c = (xv2 - w / 2, Y - 1.3 * 11 / 2, w, 1.3 * 11)
                        h = mask_id(mbx0, Y - m, mbw, 4.0, [c])
                        if h == target:
                            print('FOUND', dx0, dx1, mform, dl, cform, repr(xv2), repr(x0p), repr(x1p))
                            found += 1
print('done', found)

