arguments.content:
#!/usr/bin/env python3
# usage: rx.py [-b BIN] [-g REGEX] [-m "args1" -m "args2" ...] 'source'   (source '-' = stdin)
# runs the original (or BIN) on the snippet with each arg set; prints output (optionally grep)
import subprocess, sys, os, re, tempfile
bin_='/workspace/executable'; modes=[]; pat=None; src=None
a=sys.argv[1:]; i=0
while i<len(a):
    if a[i]=='-b': bin_=a[i+1]; i+=2; continue
    if a[i]=='-g': pat=a[i+1]; i+=2; continue
    if a[i]=='-m': modes.append(a[i+1]); i+=2; continue
    src=a[i]; i+=1
if src=='-': src=sys.stdin.read()
if not modes: modes=['']
d=tempfile.mkdtemp(prefix='rx',dir='/tmp/core')
open(os.path.join(d,'r_in.lini'),'w').write(src)
for m in modes:
    r=subprocess.run([bin_]+m.split()+['r_in.lini'],capture_output=True,cwd=d)
    out=r.stdout.decode('utf8','replace'); err=r.stderr.decode('utf8','replace')
    if len(modes)>1: print('== [%s]'%m)
    if pat:
        for l in (err+out).split('\n'):
            for mm in re.findall(pat,l): print(mm)
    else:
        sys.stdout.write(err); sys.stdout.write(out); print('[exit %d]'%r.returncode)
import shutil; shutil.rmtree(d)

