import sys, struct
sys.path.insert(0, '/tmp/link2')
from mh import *
def ulp(x, n):
    if x == 0:
        return x
    b = struct.unpack('<q', struct.pack('<d', x))[0]
    b = b - n if x < 0 else b + n
    return struct.unpack('<d', struct.pack('<q', b))[0]
target = sys.argv[1]
Y0 = float(sys.argv[2])
LY0 = -63.0
X0, X1 = -41.95500000000001, 43.57499999999999
R = int(sys.argv[3]) if len(sys.argv) > 3 else 6
for dy in range(-R, R + 1):
    y = ulp(Y0, dy)
    for dly in range(-R, R + 1):
        ly = ulp(LY0, dly)
        for dx0 in range(-3, 4):
            for dx1 in range(-3, 4):
                x0 = ulp(X0, dx0); x1 = ulp(X1, dx1)
                lx = x0 + (x1 - x0) * 0.35
                for mbform in range(2):
                    if mbform == 0:
                        mx0, my0, mw, mh_ = x0 - 2, y - 2, (x1 + 2) - (x0 - 2), (y + 2) - (y - 2)
                    else:
                        mx0, my0, mw, mh_ = x0 - 2, y - 2, (x1 - x0) + 4, 4.0
                    h = mask_id(mx0, my0, mw, mh_, [cut_exact(lx, ly, [619.0], 1000.0, 11.0)])
                    if h == target:
                        print('FOUND', dy, dly, dx0, dx1, mbform, repr(y), repr(ly), repr(x0), repr(x1))
print('done')

