    .S .lini-centerline { fill: none; stroke: var(--lini-stroke-light); stroke-width: 1; stroke-dasharray: 10,3,1,3; }
    .S .lini-surface-finish { fill: none; stroke: var(--lini-stroke-dark); stroke-width: 1; font-size: 12px; }
    .S .lini-feature-control { fill: var(--lini-bg); stroke: var(--lini-stroke-dark); stroke-width: 1; font-size: 12px; }
    .S .lini-datum { fill: var(--lini-bg); stroke: var(--lini-stroke-dark); stroke-width: 1; font-size: 12px; }
    .S .lini-marker { fill: var(--lini-stroke); stroke: none; }
    .S .lini-dim-line .lini-marker { fill: var(--lini-stroke-dark); }
    .S .lini-marker-dim { fill: var(--lini-stroke-dark); }
    .S .lini-marker-datum { fill: var(--lini-stroke-dark); }

