#!/usr/bin/env python3
# measure x/y spacing between two cells for various value texts
import sys, re
sys.path.insert(0, '/tmp/sch/scripts')
from summ import run

def pos(svg, id_):
    m = re.search(r'data-id="%s" transform="translate\(([-\d.]+),([-\d.]+)\)' % id_, svg)
    return float(m.group(1)), float(m.group(2))

def width_of(svg, id_):
    # rect line following the node
    m = re.search(r'data-id="%s" transform="[^"]+">\n\s*<rect x="([-\d.]+)" y="([-\d.]+)" width="([-\d.]+)" height="([-\d.]+)"' % id_, svg)
    return tuple(float(x) for x in m.groups())

texts = sys.argv[1:] or ['10k', '10kkkkkkkk', 'WWWWWWWWWWWWWW', 'WWWWWWWWWWWWWWWWWWWWWWWW']
for t in texts:
    src = '''{ layout: schematic; padding: 0; gap: 0 }
|R#r1| "%s" { cell: 1 1; }
|R#r2| "%s" { cell: 2 1; }
|R#r3| "%s" { cell: 1 2; }''' % (t, t, t)
    o, e, c = run(src)
    p1 = pos(o, 'r1'); p2 = pos(o, 'r2'); p3 = pos(o, 'r3')
    vb = re.search(r'viewBox="([^"]+)"', o).group(1)
    # value label width
    m = re.search(r'lini-part-value lini-block" transform="[^"]+">\n\s*<rect x="([-\d.]+)" y="[-\d.]+" width="([-\d.]+)"', o)
    print('%-28s dx=%g dy=%g p1=%s valw=%s vb=%s' % (t, p2[0]-p1[0], p3[1]-p1[1], p1, m.group(2), vb))

