#!/usr/bin/env python3
# x spacing between two cells with different value texts (gap given)
import sys, re
sys.path.insert(0, '/tmp/sch/scripts')
from summ import run

def pos(svg, id_):
    m = re.search(r'data-id="%s" transform="translate\(([-\d.]+),([-\d.]+)\)' % id_, svg)
    return float(m.group(1)), float(m.group(2))

gap = sys.argv[1]
pairs = sys.argv[2:]
for pr in pairs:
    a, b = pr.split(',')
    src = '''{ layout: schematic; padding: 0; gap: %s }
|R#r1| "%s" { cell: 1 1; }
|R#r2| "%s" { cell: 2 1; }''' % (gap, a, b)
    o, e, c = run(src)
    p1 = pos(o, 'r1'); p2 = pos(o, 'r2')
    vals = re.findall(r'lini-part-value lini-block" transform="[^"]+">\n\s*<rect x="([-\d.]+)" y="[-\d.]+" width="([-\d.]+)"', o)
    vb = re.search(r'viewBox="([^"]+)"', o).group(1)
    print('%-30s dx=%g p1=%g p2=%g w=%s vb=%s' % (pr, p2[0]-p1[0], p1[0], p2[0], [v[1] for v in vals], vb))

