// brute force gradient key search
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

static uint32_t h8(const char *s, size_t n) {
    uint64_t h = 0xcbf29ce484222325ULL;
    for (size_t i = 0; i < n; i++) { h ^= (unsigned char)s[i]; h *= 0x100000001b3ULL; }
    return (uint32_t)(h >> 32) ^ (uint32_t)h;
}

typedef struct { const char *name; uint32_t target; int radial; const char *c[4]; int n; int rot; int css; } Target;

static Target T[] = {
    {"lin135", 0xa94e6447, 0, {"red", "blue"}, 2, 45, 135},
    {"lin45", 0xc71195c2, 0, {"red", "blue"}, 2, -45, 45},
    {"rad", 0x140eca72, 1, {"red", "blue"}, 2, 0, 0},
};

static const char *KL[] = {"", "linear", "Linear", "linear-gradient", "linearGradient", "l", "L", "lin", "lg", "gradient", "g", "LINEAR", "0", "1", "false", "true", "Lin", "line", "Linear(", "linear(", "linear-gradient(", "gradient(", "<linearGradient", "linear_gradient", "LinearGradient", "Gradient::Linear", "Paint::Linear", "Linear{", "Linear {", NULL};
static const char *KR[] = {"", "radial", "Radial", "radial-gradient", "radialGradient", "r", "R", "rad", "rg", "gradient", "g", "RADIAL", "0", "1", "false", "true", "Rad", "Radial(", "radial(", "radial-gradient(", "gradient(", "<radialGradient", "radial_gradient", "RadialGradient", "Gradient::Radial", "Paint::Radial", "Radial{", "Radial {", NULL};
static const char *SEP[] = {"", ",", ", ", " ", "|", ";", ":", "/", "\n", "-", "_", "+", "#", "@", "\t", "; ", ": ", "=", "(", ")", "\x1f", "\x00", " | ", " ", ",", NULL};
static const char *WR[][2] = {{"", ""}, {"(", ")"}, {"[", "]"}, {"{", "}"}, {"", ")"}, {"", ";"}, {"", ","}, {"", "|"}, {"", "\n"}, {"", " }"}, {"", "]"}, {"", "])"}, {"", "] }"}, {NULL, NULL}};

int main() {
    char buf[1024];
    char angles[40][64];
    long long cnt = 0;
    for (int ti = 0; ti < 3; ti++) {
        Target *t = &T[ti];
        int na = 0;
        if (t->radial) {
            const char *ra[] = {"", "None", "0", "0.0", "-90", "90", "-90.0", "90.0", "135", "45", "135.0", "45.0", "null", "radial", "circle", "nan", "NaN", "None,", NULL};
            for (int i = 0; ra[i]; i++) strcpy(angles[na++], ra[i]);
        } else {
            int r = t->rot, c = t->css;
            sprintf(angles[na++], "%d", c);
            sprintf(angles[na++], "%d", r);
            sprintf(angles[na++], "%d.0", c);
            sprintf(angles[na++], "%d.0", r);
            sprintf(angles[na++], "%ddeg", c);
            sprintf(angles[na++], "%ddeg", r);
            sprintf(angles[na++], "rotate(%d 0.5 0.5)", r);
            sprintf(angles[na++], "rotate(%d)", r);
            sprintf(angles[na++], " gradientTransform=\"rotate(%d 0.5 0.5)\"", r);
            sprintf(angles[na++], "gradientTransform=\"rotate(%d 0.5 0.5)\"", r);
            sprintf(angles[na++], "Some(%d.0)", c);
            sprintf(angles[na++], "Some(%d.0)", r);
            sprintf(angles[na++], "Some(%d)", c);
            sprintf(angles[na++], "%.17g", c * 3.14159265358979323846 / 180);
            sprintf(angles[na++], "%.16g", c * 3.14159265358979323846 / 180);
            sprintf(angles[na++], "%.17g", r * 3.14159265358979323846 / 180);
            sprintf(angles[na++], "%.16g", r * 3.14159265358979323846 / 180);
            sprintf(angles[na++], "%s", "");
            sprintf(angles[na++], "angle: %d.0", c);
            sprintf(angles[na++], "angle: %d.0", r);
            sprintf(angles[na++], "angle:%d", c);
            sprintf(angles[na++], "%d°", c);
            sprintf(angles[na++], "Linear(%d.0)", c);
            sprintf(angles[na++], "Linear(%d.0)", r);
        }
        const char **K = t->radial ? KR : KL;
        // stop formats: build stop strings per format
        // offsets variants
        const char *offs[6][4] = {{"", "", "", ""}, {"0%", "100%"}, {"0", "100"}, {"0", "1"}, {"0.0", "1.0"}, {"0.0", "100.0"}};
        const char *sfmt[] = {"%c", "\"%c\"", "%o %c", "%c %o", "%o:%c", "%c:%o", "%o,%c", "%c,%o", "%o=%c", "%c@%o", "(%o, \"%c\")", "(\"%c\", %o)", "(%o,%c)", "%o|%c", "%c|%o",
            "<stop offset=\"%o\" style=\"stop-color: %c\"/>", "<stop offset=\"%o\" stop-color=\"%c\"/>", "%c %o%", "%o% %c", "Stop { offset: %o, color: \"%c\" }", "Stop { color: \"%c\", offset: %o }", "stop-color: %c", "'%c'", NULL};
        for (int ki = 0; K[ki]; ki++)
        for (int ai = 0; ai < na; ai++)
        for (int s1 = 0; SEP[s1]; s1++)
        for (int s2 = 0; SEP[s2]; s2++)
        for (int fi = 0; sfmt[fi]; fi++)
        for (int oi = 0; oi < 6; oi++) {
            int hasO = strstr(sfmt[fi], "%o") != NULL;
            if (hasO && oi == 0) continue;
            if (!hasO && oi > 0) continue;
            char stops[4][128];
            for (int k = 0; k < t->n; k++) {
                char *d = stops[k]; const char *f = sfmt[fi];
                while (*f) {
                    if (f[0] == '%' && f[1] == 'c') { strcpy(d, t->c[k]); d += strlen(t->c[k]); f += 2; }
                    else if (f[0] == '%' && f[1] == 'o') { strcpy(d, offs[oi][k]); d += strlen(offs[oi][k]); f += 2; }
                    else *d++ = *f++;
                }
                *d = 0;
            }
            for (int s3 = 0; SEP[s3]; s3++)
            for (int w = 0; WR[w][0]; w++)
            for (int ord = 0; ord < 4; ord++) {
                // build
                char *p = buf;
                #define PUT(s) do { size_t L = strlen(s); memcpy(p, s, L); p += L; } while (0)
                const char *k = K[ki]; const char *a = angles[ai];
                char st[512]; char *q = st;
                for (int j = 0; j < t->n; j++) { if (j) { size_t L = strlen(SEP[s3]); memcpy(q, SEP[s3], L); q += L; } size_t L = strlen(stops[j]); memcpy(q, stops[j], L); q += L; }
                *q = 0;
                PUT(WR[w][0]);
                if (ord == 0) { PUT(k); if (*k) PUT(SEP[s1]); PUT(a); if (*a) PUT(SEP[s2]); PUT(st); }
                else if (ord == 1) { PUT(k); if (*k) PUT(SEP[s1]); PUT(st); if (*a) { PUT(SEP[s2]); PUT(a); } }
                else if (ord == 2) { PUT(a); if (*a) PUT(SEP[s1]); PUT(st); if (*k) { PUT(SEP[s2]); PUT(k); } }
                else { PUT(st); if (*k) { PUT(SEP[s1]); PUT(k); } if (*a) { PUT(SEP[s2]); PUT(a); } }
                PUT(WR[w][1]);
                size_t n = p - buf;
                cnt++;
                if (h8(buf, n) == t->target) { fwrite("FOUND ", 1, 6, stdout); fwrite(buf, 1, n, stdout); printf(" [%s]\n", t->name); fflush(stdout); }
                buf[n] = '\n';
                if (h8(buf, n + 1) == t->target) { fwrite("FOUNDNL ", 1, 8, stdout); fwrite(buf, 1, n, stdout); printf(" [%s]\n", t->name); fflush(stdout); }
            }
        }
    }
    printf("tried %lld\n", cnt);
}

