// -------------------------------------------------------------- components
struct Slot {
    pin: Option<Node>, // None: a space
    space: Option<Node>,
    side: Option<String>, // explicit and valid
    generated: bool,
}


// the pose is spent on classes
fn drop_pose(o: &mut ONode) {
    o.decls.retain(|d| d.name != "rotate" && d.name != "mirror");
}

// the slots a `|space|` takes: a whole number of one or more (one otherwise)
fn space_span(cx: &Cx, sp: &Node) -> f64 {
    let ch = chain_of(cx, sp);
    let d = match prop_decl(cx, &sp.style, &ch, "span") {
        Some(d) => d,
        None => return 1.0,
    };
    match d.groups.as_slice() {
        [g] if g.len() == 1 => match g[0].parse::<f64>() {
            Ok(v) if v.trunc() >= 1.0 => v.trunc(),
            _ => 1.0,
        },
        _ => 1.0,
    }
}

pub fn component(cx: &mut Cx, n: &Node, mut o: ONode, chain: &[String]) -> R<ONode> {
    if let Some(f) = cx.stack.last_mut() {
        f.plan_breaks = true;
    }
    let mut pose = written_pose(cx, n, chain)?;
    if prop(cx, &n.style, chain, "rotate").is_none() {
        if let Some(id) = &n.id {
            if let Some(p) = cx.sch_pose(id) {
                pose.rot = p.rot;
            }
        }
    }
    drop_pose(&mut o);
    cancel_define_pose(cx, &mut o, chain);
    o.classes.extend(pose.classes());
    let r = ref_text(cx, n, chain);
    for d in Decl::list("direction: column; gap: 0;") {
        if !o.decls.iter().any(|x| x.name == d.name) {
            o.decls.push(d);
        }
    }
    // the pins: generated (a connector's `pins: N`) then the children
    let mut slots: Vec<Slot> = Vec::new();
    if chain.iter().any(|c| c == "J") {
        if let Some(k) = prop(cx, &n.style, chain, "pins").and_then(|s| s.parse::<f64>().ok()) {
            for i in 1..=(k.max(0.0) as usize) {
                let pn = Node {
                    ty: Some("pin".into()),
                    id: Some(format!("p{}", i)),
                    label: None,
                    classes: vec![],
                    style: vec![Decl::val("number", &i.to_string()), Decl::val("side", "left")],
                    children: None,
                    span: n.span,
                    head_span: n.span,
                    ty_span: n.span,
                };
                slots.push(Slot { pin: Some(pn), space: None, side: Some("left".into()), generated: true });
            }
        }
    }
    let mut extra: Vec<&Stmt> = Vec::new();
    for s in n.children.as_deref().unwrap_or(&[]) {
        if let Some(c) = node_is(cx, s, "pin") {
            let side = prop(cx, &c.style, &chain_of(cx, c), "side").filter(|s| Dir::of_side(s).is_some());
            slots.push(Slot { pin: Some(c.clone()), space: None, side, generated: false });
        } else if let Some(c) = node_is(cx, s, "space") {
            slots.push(Slot { pin: None, space: Some(c.clone()), side: None, generated: false });
        } else {
            extra.push(s);
        }
    }
    // auto pins split left / right, spaces ride with their pin
    let autos: Vec<usize> = (0..slots.len()).filter(|&i| slots[i].pin.is_some() && slots[i].side.is_none()).collect();
    let half = (autos.len() + 1) / 2;
    let mut sides: Vec<String> = vec![String::new(); slots.len()];
    for (k, &i) in autos.iter().enumerate() {
        sides[i] = if k < half { "left".into() } else { "right".into() };
    }
    for i in 0..slots.len() {
        if let Some(s) = &slots[i].side {
            sides[i] = s.clone();
        }
    }
    for i in 0..slots.len() {
        if slots[i].pin.is_none() {
            let prev = (0..i).rev().find(|&j| slots[j].pin.is_some()).map(|j| sides[j].clone());
            let next = (i + 1..slots.len()).find(|&j| slots[j].pin.is_some()).map(|j| sides[j].clone());
            // a space without a pin to ride with is dropped
            sides[i] = prev.or(next).unwrap_or_default();
        }
    }
    // group by side (left/right top→bottom, top/bottom left→right), then pose
    let mut by: HashMap<&str, Vec<usize>> = HashMap::new();
    for (i, s) in sides.iter().enumerate() {
        if s.is_empty() {
            continue;
        }
        by.entry(match s.as_str() {
            "right" => "right",
            "top" => "top",
            "bottom" => "bottom",
            _ => "left",
        })
        .or_default()
        .push(i);
    }
    let get = |by: &HashMap<&str, Vec<usize>>, k: &str| by.get(k).cloned().unwrap_or_default();
    let (mut left, mut right, mut top, mut bottom) = (get(&by, "left"), get(&by, "right"), get(&by, "top"), get(&by, "bottom"));
    let rev = |v: &Vec<usize>| v.iter().rev().cloned().collect::<Vec<usize>>();
    match pose.mirror {
        Some('x') => {
            let (t, b) = (top.clone(), bottom.clone());
            top = b;
            bottom = t;
            left = rev(&left);
            right = rev(&right);
        }
        Some('y') => {
            let (l, r) = (left.clone(), right.clone());
            left = r;
            right = l;
            top = rev(&top);
            bottom = rev(&bottom);
        }
        _ => {}
    }
    for _ in 0..(pose.rot / 90) {
        let (l, r, t, b) = (left.clone(), right.clone(), top.clone(), bottom.clone());
        top = rev(&l);
        right = t;
        bottom = rev(&r);
        left = b;
    }
    let mut children: Vec<Item> = Vec::new();
    let connector = chain.iter().any(|c| c == "J");
    let lower_pins = |cx: &mut Cx, idx: &[usize], side: &str| -> R<Vec<Item>> {
        let mut v = Vec::new();
        for &i in idx {
            let s = &slots[i];
            if let Some(sp) = &s.space {
                let mut b = typed_as(cx, sp, "space");
                b.id = sp.id.clone();
                b.classes.extend(sp.classes.iter().cloned());
                b.decls = sp.style.clone();
                let k = space_span(cx, sp);
                if k != 1.0 {
                    let along = if side == "left" || side == "right" { "height" } else { "width" };
                    b.decls.push(Decl::val(along, &num(20.0 * k)));
                }
                v.push(Item::Node(b));
                continue;
            }
            let pn = s.pin.as_ref().unwrap();
            // a connector's pins go unnamed
            v.push(pin_node(cx, pn, side, s.side.is_some() || s.generated, s.generated || connector)?);
        }
        Ok(v)
    };
    let spans: Vec<f64> = slots.iter().map(|s| s.space.as_ref().map_or(1.0, |sp| space_span(cx, sp))).collect();
    let slots_of = |idx: &[usize]| -> f64 { idx.iter().map(|&i| spans[i]).sum() };
    let middle = !left.is_empty() || !right.is_empty();
    if !top.is_empty() {
        let even = slots_of(&top) % 2.0 == 0.0;
        let mut row = cx.typed("row");
        row.decls = Decl::list(&format!(
            "gap: 0; align: start;{} height: 20;",
            if even { " padding: 0 20 0 0;" } else { "" }
        ));
        row.children = lower_pins(cx, &top, "top")?;
        children.push(Item::Node(row));
    } else if middle && !bottom.is_empty() {
        let mut row = cx.typed("row");
        row.decls = Decl::list("height: 20;");
        children.push(Item::Node(row));
    }
    if middle {
        let mut cols = Vec::new();
        for (idx, side, align) in [(&left, "left", "start"), (&right, "right", "end")] {
            if idx.is_empty() {
                continue;
            }
            let even = slots_of(idx) % 2.0 == 0.0;
            let mut col = cx.typed("column");
            col.decls = Decl::list(&format!(
                "gap: 0; align: {};{}",
                align,
                if even { " padding: 0 0 20 0;" } else { "" }
            ));
            col.children = lower_pins(cx, idx, side)?;
            cols.push(Item::Node(col));
        }
        if cols.len() == 2 {
            let mut row = cx.typed("row");
            row.decls = Decl::list("gap: 24; align: center;");
            row.children = cols;
            children.push(Item::Node(row));
        } else {
            children.extend(cols);
        }
    }
    if !bottom.is_empty() {
        let even = slots_of(&bottom) % 2.0 == 0.0;
        let mut row = cx.typed("row");
        row.decls = Decl::list(&format!(
            "gap: 0; align: end;{} height: 20;",
            if even { " padding: 0 20 0 0;" } else { "" }
        ));
        row.children = lower_pins(cx, &bottom, "bottom")?;
        children.push(Item::Node(row));
    } else if middle && !top.is_empty() {
        let mut row = cx.typed("row");
        row.decls = Decl::list("height: 20;");
        children.push(Item::Node(row));
    }
    let lift = if top.is_empty() { 0.0 } else { 20.0 };
    if let Some(l) = n.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty()) {
        children.push(block_with(cx, "part-value", &format!("pin: top; translate: 0 {};", num(-20.0 - lift)), Some(&l)));
    }
    if cx.in_labels == 0 {
        children.push(block_with(cx, "ref", &format!("pin: top; translate: 0 {};", num(-36.0 - lift)), Some(&r)));
    }
    let bodies = cx.bodies(chain)?;
    children.extend(bodies);
    for s in extra {
        cx.stmts(std::slice::from_ref(s), &mut children)?;
    }
    o.children = children;
    Ok(o)
}

fn pin_node(cx: &mut Cx, pn: &Node, side: &str, rewrite: bool, generated: bool) -> R<Item> {
    let mut p = typed_as(cx, pn, "pin");
    p.id = pn.id.clone();
    p.classes.extend(pn.classes.iter().cloned());
    p.decls = pn.style.clone();
    if rewrite {
        let old = own(&p.decls, "side");
        if old.as_deref() != Some(side) && old.is_some() {
            p.decls.retain(|d| d.name != "side");
            p.decls.push(Decl::val("side", side));
        }
    }
    let vertical = side == "top" || side == "bottom";
    if vertical {
        p.decls.push(Decl::val("width", "20"));
        p.decls.push(Decl::val("height", "auto"));
    }
    let label = pn.label.as_ref().map(|l| l.trim().to_string()).filter(|l| !l.is_empty());
    if label.is_none() && !generated {
        if let Some(id) = &pn.id {
            p.children.push(Cx::text_item(id));
        }
    }
    let (stub, numpos) = match side {
        "right" => ("points: 0 0, 20 0; pin: right; translate: 28 0;", "pin: right; translate: 28 -9; width: 20;"),
        "top" => ("points: 0 0, 0 20; pin: top; translate: 0 -28;", "pin: top; translate: 9 -28; height: 20;"),
        "bottom" => ("points: 0 0, 0 20; pin: bottom; translate: 0 28;", "pin: bottom; translate: 9 28; height: 20;"),
        _ => ("points: 0 0, 20 0; pin: left; translate: -28 0;", "pin: left; translate: -28 -9; width: 20;"),
    };
    let mut st = cx.typed("pin-stub");
    st.decls = Decl::list(stub);
    p.children.push(Item::Node(st));
    // a pin number is a number (its first term), written on the pin
    let number = own(&pn.style, "number").filter(|t| t.parse::<f64>().is_ok());
    if let Some(t) = number {
        p.children.push(block_with(cx, "pin-number", numpos, Some(&t)));
    }
    if let Some(l) = label {
        p.children.push(Cx::text_item(&l));
    }
    // a pin's own children follow
    if let Some(ch) = &pn.children {
        let mut v = Vec::new();
        cx.stmts(ch, &mut v)?;
        p.children.extend(v);
    }
    Ok(Item::Node(p))
}

// a wire is plain (-, --, ~); a text end's marker shapes its tag:
// (the plain operators, the tag's shape)
pub fn wire_ops(l: &Link) -> R<(Vec<String>, Option<&'static str>)> {
    let one_ended = l.groups.len() == 1;
    let plain = |o: &str| matches!(o, "-" | "--" | "~");
    let mut ops: Vec<String> = Vec::new();
    let mut text_shape: Option<&'static str> = None;
    for op in &l.ops {
        if plain(op) {
            ops.push(op.clone());
            continue;
        }

let mut out = Vec::new();
    for c in 1..n - 1 {
        let r = want[c - 1];
        let before = if c == 1 { seg(0) - pull_s } else { share(seg(c - 1), r, want[c - 2]) };
        let after = if c == n - 2 { seg(c) - pull_e } else { share(seg(c), r, want[c]) };
        out.push(r.min(before).min(after).max(0.0));
    }
    out
}

fn stray() -> Routed {
    Routed { stray: true, pts: vec![], radii: vec![], curve: None, sa: None, sb: None }
}

// One wire being planned.
#[derive(Clone, Debug)]
struct W {
    req: usize,
    bundle: usize,
    slot: usize,
    // polyline from the (promoted) start node to the end node
    pts: Vec<(f64, f64)>,
    sa: Side,
    sb: Side,
    from: usize,
    to: usize,
    k: f64,
    // logical offsets per segment (ports and tracks), for nested radii
    offs: Vec<f64>,
    straight: bool,
    // fan groups sharing a trunk port at the start / end node
    fan_s: Option<usize>,
    fan_e: Option<usize>,
    // a container-to-inner link takes its line from the inner node's side
    inner_end: Option<usize>,
    // a straight wire's preferred line: halfway between the two centres,
    // kept inside the range both sides can take
    ideal: Option<f64>,
}

pub fn route_links(ctx: &Ctx, world: &World, reqs: &[LinkReq]) -> Vec<Routed> {
    let mut out: Vec<Option<Routed>> = (0..reqs.len()).map(|_| None).collect();
    // natural and straight routing need no planning
    for (i, req) in reqs.iter().enumerate() {
        let a = world.rects[req.from];
        let b = world.rects[req.to];
        if req.routing == "straight" {
            let (p, q) = crate::links::stray_line(&a, &b);
            out[i] = Some(Routed { stray: false, pts: vec![p, q], radii: vec![], curve: None, sa: None, sb: None });
        } else if req.routing == "natural" {
            let (pts, curve, sa, sb) = natural(&a, &b, req);
            out[i] = Some(Routed { stray: false, pts, radii: vec![], curve: Some(curve), sa: Some(sa), sb: Some(sb) });
        } else if req.from == req.to {
            let k = req.k;
            let pts = vec![(a.x1, a.cy()), (a.x1 + k, a.cy()), (a.x1 + k, a.y0 - k), (a.cx(), a.y0 - k), (a.cx(), a.y0)];
            let want = vec![req.radius; 3];
            let radii = cap_radii(&pts, &want, req.pull_s, req.pull_e);
            out[i] = Some(Routed { stray: false, pts, radii, curve: None, sa: Some(Side::Right), sb: Some(Side::Top) });
        }
    }
    let (bundles, of) = bundles_of(reqs);
    // fans: links of one statement sharing a start (or an end) node
    let mut fan_groups: Vec<(usize, Vec<usize>)> = Vec::new(); // (shared node, reqs)
    let mut fan_of_start: Vec<Option<usize>> = vec![None; reqs.len()];
    let mut fan_of_end: Vec<Option<usize>> = vec![None; reqs.len()];
    {
        let mut outs: std::collections::BTreeMap<(usize, usize), Vec<usize>> = std::collections::BTreeMap::new();
        let mut ins: std::collections::BTreeMap<(usize, usize), Vec<usize>> = std::collections::BTreeMap::new();
        for (i, r) in reqs.iter().enumerate() {
            if of[i] == usize::MAX {
                continue;
            }
            outs.entry((r.stmt, r.from)).or_default().push(i);
            ins.entry((r.stmt, r.to)).or_default().push(i);
        }
        let mut groups: Vec<(usize, usize, Vec<usize>, bool)> = Vec::new();
        for ((_, node), v) in outs {
            if v.len() >= 2 {
                groups.push((v[0], node, v, true));
            }
        }
        for ((_, node), v) in ins {
            if v.len() >= 2 {
                groups.push((v[0], node, v, false));
            }
        }
        groups.sort_by_key(|g| g.0);
        for (_, node, v, is_out) in groups {
            let gi = fan_groups.len();
            for &ri in &v {
                if is_out {
                    if fan_of_start[ri].is_none() {
                        fan_of_start[ri] = Some(gi);
                    }
                } else if fan_of_end[ri].is_none() {
                    fan_of_end[ri] = Some(gi);
                }
            }
            fan_groups.push((node, v));
        }
    }
    let mut occ = Occupancy { sides: std::collections::HashMap::new(), chans: Vec::new() };
    // each bundle's port slot keys at its two nodes
    let slot_key = |ri: usize, node: usize| -> i64 {
        let g = if reqs[ri].from == node { fan_of_start[ri] } else { fan_of_end[ri] };
        match g {
            Some(gi) if fan_groups[gi].0 == node => gi as i64,
            _ => -(ri as i64) - 1,
        }
    };
    let keys: Vec<(Vec<i64>, Vec<i64>)> = bundles.iter().map(|b| (b.reqs.iter().map(|&ri| slot_key(ri, b.p)).collect(), b.reqs.iter().map(|&ri| slot_key(ri, b.q)).collect())).collect();
    let mut wires: Vec<W> = Vec::new();
    let envs: Vec<Env> = bundles.iter().map(|b| env_for(ctx, world, b.p, b.q, reqs[b.reqs[0]].k)).collect();
    let mut done = vec![false; bundles.len()];
    for bi in 0..bundles.len() {
        if done[bi] {
            continue;
        }
        // a fresh fan routes jointly: every member leaves the shared node
        // through the same side, the cheapest such side overall
        let first = bundles[bi].reqs[0];
        // the first fan (out, then in) whose member bundles are all fresh
        let fresh = |gi: usize, done: &Vec<bool>| -> bool {
            let (_, members) = &fan_groups[gi];
            let mut mbs: Vec<usize> = Vec::new();
            for &ri in members {
                if !mbs.contains(&of[ri]) {
                    mbs.push(of[ri]);
                }
            }
            mbs.len() >= 2 && mbs.iter().all(|&mb| !done[mb])
        };
        let fan = [fan_of_start[first], fan_of_end[first]].into_iter().flatten().find(|&gi| fresh(gi, &done));
        let mut joint: Option<Vec<(usize, Path)>> = None;
        if let Some(gi) = fan {
            let (node, members) = &fan_groups[gi];
            let mut mbs: Vec<usize> = Vec::new();
            for &ri in members {
                if !mbs.contains(&of[ri]) {
                    mbs.push(of[ri]);
                }
            }
            {
                let mut best: Option<(f64, Vec<(usize, Path)>)> = None;
                for &sd in ORDER.iter() {
                    let mut total = 0.0;
                    let mut got: Vec<(usize, Path)> = Vec::new();
                    let mut ok = true;
                    for &mb in &mbs {
                        match route_bundle(&envs[mb], bundles[mb].reqs.len(), &bundles[mb], &keys[mb], &occ, Some((*node, sd))) {
                            Some((c, p)) => {
                                total += c;
                                got.push((mb, p));
                            }
                            None => {
                                ok = false;
                                break;
                            }
                        }
                    }
                    if ok && best.as_ref().map_or(true, |(bc, _)| total < *bc - 1e-9) {
                        best = Some((total, got));
                    }
                }
                joint = best.map(|b| b.1);
            }
        }
        let plan: Vec<(usize, Option<Path>)> = match joint {
            Some(v) => v.into_iter().map(|(mb, p)| (mb, Some(p))).collect(),
            None => {
                let b = &bundles[bi];
                let nested = crate::links::is_ancestor(ctx, b.p, b.q) || crate::links::is_ancestor(ctx, b.q, b.p);
                if nested {
                    vec![(bi, Some(parent_child(world, b.p, b.q, crate::links::is_ancestor(ctx, b.p, b.q))))]
                } else {
                    vec![(bi, route_bundle(&envs[bi], bundles[bi].reqs.len(), &bundles[bi], &keys[bi], &occ, None).map(|x| x.1))]
                }
            }
        };
        for (mb, path) in plan {
            done[mb] = true;
            let b = &bundles[mb];
            let env = &envs[mb];
            let k = env.k;
            let n = b.reqs.len();
            let Some(path) = path else {
                for &ri in &b.reqs {
                    out[ri] = Some(stray());
                }
                continue;
            };
            for (node, side, ks) in [(b.p, path.sa, &keys[mb].0), (b.q, path.sb, &keys[mb].1)] {
                let v = occ.sides.entry((node, side.idx())).or_default();
                for k in ks.iter() {
                    if !v.contains(k) {
                        v.push(*k);
                    }
                }
            }
            for (j, u) in u_segments(&path.pts) {
                let (horiz, pos, lo, hi) = seg_span(path.pts[j], path.pts[j + 1]);
                let depth = channel_depth(env, path.pts[j], path.pts[j + 1], u);
                occ.chans.push(ChanUse { horiz, pos, u, lo, hi, depth, count: n });
            }
            let facing = facing_overlap(&env.a, path.sa, &env.b, path.sb, k);
            let z_straight = path.pts.len() <= 4 && facing.map_or(false, |(lo, hi)| n <= 1 || hi - lo >= (n as f64 - 1.0) * k / 2.0 - 1e-9);
            let straight = (path.pts.len() == 2 && path.sa == path.sb) || z_straight;
            let ideal = if z_straight && !(path.pts.len() == 2 && path.sa == path.sb) {
                let (lo, hi) = facing.unwrap();
                let mid = if path.sa.horizontal() { (env.a.cx() + env.b.cx()) / 2.0 } else { (env.a.cy() + env.b.cy()) / 2.0 };
                Some(mid.max(lo).min(hi))
            } else {
                None
            };
            // bundle order: forward links in order, then backward ones reversed
            let mut order: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from == b.p).collect();
            let mut back: Vec<usize> = b.reqs.iter().cloned().filter(|&ri| reqs[ri].from != b.p).collect();
            back.reverse();
            order.extend(back);
            for (slot, &ri) in order.iter().enumerate() {
                let pts = path.pts.clone();
                let m = pts.len();
                // fan groups seen from the bundle's orientation
                let (fs, fe) = if reqs[ri].from == b.p { (fan_of_start[ri], fan_of_end[ri]) } else { (fan_of_end[ri], fan_of_start[ri]) };
                let inner_end = if crate::links::is_ancestor(ctx, b.p, b.q) {
                    Some(1)
                } else if crate::links::is_ancestor(ctx, b.q, b.p) {
                    Some(0)
                } else {
                    None
                };
                wires.push(W { req: ri, bundle: mb, slot, pts, sa: path.sa, sb: path.sb, from: b.p, to: b.q, k, offs: vec![0.0; m - 1], straight, fan_s: fs, fan_e: fe, inner_end, ideal });
            }
        }
    }
    plan_ports(ctx, world, &bundles, &mut wires);
    plan_tracks(&envs, &mut wires);
    // nested corners: a corner wrapped round a parallel inner corner takes
    // the inner radius plus half the offsets between them
    let nests = nest_corners(&wires);
    let cross_caps = crossing_caps(&wires);
    // a nested corner grows from what the corner just inside it wants,
    // once that is held to its end legs and to crossing wires (sharing an
    // inner leg with a neighbour corner does not carry over)
    let mut eff: Vec<Vec<f64>> = wires.iter().map(|wr| vec![reqs[wr.req].radius; wr.pts.len().saturating_sub(2)]).collect();
    let wants_of = |w: usize, eff: &Vec<Vec<f64>>| -> Vec<f64> {
        let req = &reqs[wires[w].req];
        nests[w]
            .iter()
            .map(|&(extra, inner)| match inner {
                Some((xw, xc)) => eff[xw][xc] + extra,
                None => req.radius,
            })
            .collect()
    };
    for _ in 0..8 {
        let mut changed = false;
        for w in 0..wires.len() {
            let pts = &wires[w].pts;
            let m = pts.len();
            if m < 3 {
                continue;
            }
            let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
            let want = wants_of(w, &eff);
            for c in 0..m - 2 {
                let mut v = want[c].min(cross_caps[w][c]);
                if c == 0 {
                    v = v.min(seg(0));
                }
                if c == m - 3 {
                    v = v.min(seg(m - 2));
                }
                if (v - eff[w][c]).abs() > 1e-12 {
                    eff[w][c] = v;
                    changed = true;
                }
            }
        }
        if !changed {
            break;
        }
    }
    let radii_of = |w: usize| -> Vec<f64> {
        let wr = &wires[w];
        let req = &reqs[wr.req];
        let pts = &wr.pts;
        let want = wants_of(w, &eff);
        // pull-backs in this wire's own orientation
        let (ps, pe) = if req.from == wr.from { (req.pull_s, req.pull_e) } else { (req.pull_e, req.pull_s) };
        let m = pts.len();
        let seg = |i: usize| ((pts[i + 1].0 - pts[i].0).abs() + (pts[i + 1].1 - pts[i].1).abs());
        let pull_e = if m >= 2 && pe > seg(m - 2) + 1e-9 { 0.0 } else { pe };
        let pull_s = if m >= 2 && ps > seg(0) + 1e-9 { 0.0 } else { ps };
        let mut radii = cap_radii(pts, &want, pull_s, pull_e);
        // an arc never sweeps over a crossing wire
        for (r, c) in radii.iter_mut().zip(cross_caps[w].iter()) {
            if *r > *c {
                *r = *c;
            }
        }
        radii
    };
    for (w, wr) in wires.iter().enumerate() {
        let req = &reqs[wr.req];
        let mut pts = wr.pts.clone();
        let mut radii = if wr.straight { vec![] } else { radii_of(w) };
        let (mut sa, mut sb) = (wr.sa, wr.sb);
        if req.from != wr.from {
            pts.reverse();
            radii.reverse();
            std::mem::swap(&mut sa, &mut sb);
        }
        out[wr.req] = Some(Routed { stray: false, pts, radii, curve: None, sa: Some(sa), sb: Some(sb) });
    }
    out.into_iter().map(|o| o.unwrap_or_else(stray)).collect()
}

