        '<stop offset="0%" stop-color="red"/><stop offset="100%" stop-color="blue"/>']
cnt=0
for t,(k,css,rot) in T.items():
    pre=set()
    kinds=[k,k.capitalize(),k+'-gradient',k+'Gradient','<'+k+'Gradient','<'+k+'Gradient>',k[0],k[0].upper(),'']
    if css is None: angs=['','0','None','90','-90','0.0']
    else: angs=[str(css),str(rot),'%d.0'%css,'%d.0'%rot,'rotate(%d 0.5 0.5)'%rot,' gradientTransform="rotate(%d 0.5 0.5)"'%rot,'gradientTransform="rotate(%d 0.5 0.5)"'%rot,' gradientTransform="rotate(%d 0.5 0.5)">'%rot,'']
    seps=['',',',', ',' ','|',';',':','/','\n','-','_','>','\t']
    for kk in kinds:
        for a in angs:
            for s1 in seps:
                for s2 in seps:
                    p=kk+(s1 if kk else '')+a+(s2 if a else '')
                    pre.add(p)
                    p=a+(s1 if a else '')+kk+(s2 if kk else '')
                    pre.add(p)
    for p in pre:
        for sx in stopsx:
            for suf in ['','</'+k+'Gradient>','>','\n']:
                for c in [p+sx+suf, sx+suf+p]:
                    cnt+=1
                    if h8(c)==t: print('FOUND',t,repr(c))
print('tried',cnt)

