import sys
sys.path.insert(0, '/tmp/tree')
from lt import *

def info(w, kids, gap='64 48', extra=''):
    src = '|column| { layout: tree; gap: %s; } [ |topic| "R" { width: %s; } [ %s ] ]' % (gap, w, ' ; '.join('|topic| "%s"%s' % (k, extra) for k in kids))
    o, e, c = run(src)
    ps = paths(o)
    ns = absnodes(o)
    return ps, ns, e

def thresh(kids, which, gap='64 48', lo=20.0, hi=300.0):
    def ok(w):
        ps, ns, e = info(w, kids, gap)
        return 'A' not in ps[which]
    if not ok(hi):
        return None
    if ok(lo):
        return lo
    for _ in range(16):
        mid = (lo + hi) / 2
        if ok(mid):
            hi = mid
        else:
            lo = mid
    return round(hi, 3)

for gap in ['64 48', '64 60', '64 80', '64 100']:
    for kids in [['A', 'BBBBBBBBBBBBBBB'], ['AAAA', 'BBBBBBBBBBBBBBB']]:
        t = thresh(kids, 1, gap)
        ps, ns, e = info(t or 100, kids, gap)
        xs = [x[3] for x in ns if x[0] == 2]
        ws = [round(x[5] + 2, 4) for x in ns if x[0] == 2]
        print(gap, kids, 'thr rect', t, 'outer half', t and (t + 2) / 2, 'xs', xs, 'ws', ws)

