// brute force gradient key search v2: fields K, A, S joined by s1/s2 in any order, wrapped
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

static inline uint32_t h8(const char *s, size_t n) {
    uint64_t h = 0xcbf29ce484222325ULL;
    for (size_t i = 0; i < n; i++) { h ^= (unsigned char)s[i]; h *= 0x100000001b3ULL; }
    return (uint32_t)(h >> 32) ^ (uint32_t)h;
}

typedef struct { const char *name; uint32_t target; int radial; const char *c[4]; int n; int rot; int css; } Target;

static Target T[] = {
    {"lin135", 0xa94e6447, 0, {"red", "blue"}, 2, 45, 135},
    {"rad", 0x140eca72, 1, {"red", "blue"}, 2, 0, 0},
    {"lin135num", 0x779dc0e8, 0, {"1", "2"}, 2, 45, 135},
};

static const char *KL[] = {"", "linear", "Linear", "linear-gradient", "linearGradient", "l", "L", "lin", "lg", "gradient", "LINEAR", "0", "1", "false", "true", "LinearGradient", "linear_gradient", NULL};
static const char *KR[] = {"", "radial", "Radial", "radial-gradient", "radialGradient", "r", "R", "rad", "rg", "gradient", "RADIAL", "0", "1", "false", "true", "RadialGradient", "radial_gradient", NULL};
static const char *SEP[] = {"", ",", ", ", " ", "|", ";", ":", "/", "\n", "-", "_", "#", "\t", "; ", ": ", "=", "\x1f", "~", "&", NULL};
static const char *WR[][2] = {{"", ""}, {"(", ")"}, {"[", "]"}, {"{", "}"}, {"", ";"}, {"", ","}, {"", "|"}, {"", "\n"}, {"", ":"}, {"", " "}, {NULL, NULL}};

int main(int argc, char **argv) {
    int only = argc > 1 ? atoi(argv[1]) : -1;
    char buf[2048];
    char angles[40][96];
    long long cnt = 0;
    for (int ti = 0; ti < 3; ti++) {
        if (only >= 0 && ti != only) continue;
        Target *t = &T[ti];
        int na = 0;
        if (t->radial) {
            const char *ra[] = {"", "None", "0", "0.0", "-90", "90", "135", "45", "null", "nan", "NaN", NULL};
            for (int i = 0; ra[i]; i++) strcpy(angles[na++], ra[i]);
        } else {
            int r = t->rot, c = t->css;
            sprintf(angles[na++], "%d", c);
            sprintf(angles[na++], "%d", r);
            sprintf(angles[na++], "%d.0", c);
            sprintf(angles[na++], "%d.0", r);
            sprintf(angles[na++], "%ddeg", c);
            sprintf(angles[na++], "%ddeg", r);
            sprintf(angles[na++], "rotate(%d 0.5 0.5)", r);
            sprintf(angles[na++], "rotate(%d)", r);
            sprintf(angles[na++], "Some(%d.0)", c);
            sprintf(angles[na++], "Some(%d.0)", r);
            sprintf(angles[na++], "%.17g", c * 3.14159265358979323846 / 180);
            sprintf(angles[na++], "%.17g", r * 3.14159265358979323846 / 180);
            sprintf(angles[na++], "%s", "");
        }
        const char **K = t->radial ? KR : KL;
        const char *offs[6][4] = {{"", "", "", ""}, {"0%", "100%"}, {"0", "100"}, {"0", "1"}, {"0.0", "1.0"}, {"0.0", "100.0"}};
        const char *sfmt[] = {"%c", "\"%c\"", "var(--lini-%c)", "--%c", "%o %c", "%c %o", "%o:%c", "%c:%o", "%o,%c", "%c,%o", "%o=%c", "(%o, \"%c\")", "(\"%c\", %o)", "%o|%c", "%c|%o", "%c %o%", "%o% %c", "stop-color: %c", "'%c'", NULL};
        for (int fi = 0; sfmt[fi]; fi++)
        for (int oi = 0; oi < 6; oi++) {
            int hasO = strstr(sfmt[fi], "%o") != NULL;
            if (hasO && oi == 0) continue;
            if (!hasO && oi > 0) continue;
            char stops[4][128];
            for (int k = 0; k < t->n; k++) {
                char *d = stops[k]; const char *f = sfmt[fi];
                while (*f) {
                    if (f[0] == '%' && f[1] == 'c') { strcpy(d, t->c[k]); d += strlen(t->c[k]); f += 2; }
                    else if (f[0] == '%' && f[1] == 'o') { strcpy(d, offs[oi][k]); d += strlen(offs[oi][k]); f += 2; }
                    else *d++ = *f++;
                }
                *d = 0;
            }
            for (int s3 = 0; SEP[s3]; s3++)
            for (int sw = 0; WR[sw][0]; sw++) {
                char st[512]; char *q = st;
                size_t L;
                L = strlen(WR[sw][0]); memcpy(q, WR[sw][0], L); q += L;
                for (int j = 0; j < t->n; j++) { if (j) { L = strlen(SEP[s3]); memcpy(q, SEP[s3], L); q += L; } L = strlen(stops[j]); memcpy(q, stops[j], L); q += L; }
                L = strlen(WR[sw][1]); memcpy(q, WR[sw][1], L); q += L;
                *q = 0;
                for (int ki = 0; K[ki]; ki++)
                for (int ai = 0; ai < na; ai++)
                for (int s1 = 0; SEP[s1]; s1++)
                for (int s2 = 0; SEP[s2]; s2++)
                for (int w = 0; WR[w][0]; w++)
                for (int ord = 0; ord < 6; ord++) {
                    const char *f3[3]; const char *k = K[ki]; const char *a = angles[ai];
                    switch (ord) {
                        case 0: f3[0]=k; f3[1]=a; f3[2]=st; break;
                        case 1: f3[0]=k; f3[1]=st; f3[2]=a; break;
                        case 2: f3[0]=a; f3[1]=k; f3[2]=st; break;
                        case 3: f3[0]=a; f3[1]=st; f3[2]=k; break;
                        case 4: f3[0]=st; f3[1]=k; f3[2]=a; break;
                        default: f3[0]=st; f3[1]=a; f3[2]=k; break;
                    }
                    if ((!*k || !*a) && s2) continue; // only need one separator when a field is empty
                    char *p = buf;
                    #define PUT(s) do { size_t LL = strlen(s); memcpy(p, s, LL); p += LL; } while (0)
                    PUT(WR[w][0]);
                    int first = 1; int si = 0;
                    for (int z = 0; z < 3; z++) {
                        if (!*f3[z]) continue;
                        if (!first) { PUT(si == 0 ? SEP[s1] : SEP[s2]); si++; }
                        PUT(f3[z]); first = 0;
                    }
                    PUT(WR[w][1]);
                    size_t n = p - buf;
                    cnt++;
                    if (h8(buf, n) == t->target) { fwrite("FOUND ", 1, 6, stdout); fwrite(buf, 1, n, stdout); printf(" [%s]\n", t->name); fflush(stdout); }
                }
            }
        }
    }
    fprintf(stderr, "tried %lld\n", cnt);
}

