// The lowered document for the compile path: the stylesheet lines, the
// items (each node carrying the span of the source node it lowers), and the
// types and classes the lowering wore.
pub struct Lowered {
    pub sheet: Vec<out::SheetLine>,
    pub items: Vec<out::Item>,
    pub used: std::collections::HashSet<String>,
}

pub fn lower(src: &str) -> Result<Lowered, Diag> {
    let (sheet, items, used) = lower_all(src)?;
    Ok(Lowered { sheet, items, used })
}

pub use out::{Item, OLink, ONode, OText, SheetLine};
pub use syntax::Decl as LDecl;

// the children of a lowered node in the order they print (the label text
// first when every child is bare text, else after the define bodies)
pub fn print_children(n: &ONode) -> Vec<Item> {
    match &n.text_label {
        Some((l, at)) => {
            let mut first = vec![Item::text(l)];
            first.extend(n.children.iter().cloned());
            let plain = first.iter().all(|e| matches!(e, Item::Text(t) if t.classes.is_empty() && t.decls.is_empty()));
            if plain {
                first
            } else {
                let mut v = n.children.clone();
                let k = (*at).min(v.len());
                v.insert(k, Item::text(l));
                v
            }
        }
        None => n.children.clone(),
    }
}

