#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rect {
    pub x0: f64,
    pub y0: f64,
    pub x1: f64,
    pub y1: f64,
    pub ccx: f64,
    pub ccy: f64,
    pub cw: f64,
    pub ch: f64,
}

impl Rect {
    pub fn new(x0: f64, y0: f64, x1: f64, y1: f64) -> Rect {
        Rect { x0, y0, x1, y1, ccx: (x0 + x1) / 2.0, ccy: (y0 + y1) / 2.0, cw: x1 - x0, ch: y1 - y0 }
    }
    pub fn centered(cx: f64, cy: f64, w: f64, h: f64) -> Rect {
        Rect { x0: cx - w / 2.0, y0: cy - h / 2.0, x1: cx + w / 2.0, y1: cy + h / 2.0, ccx: cx, ccy: cy, cw: w, ch: h }
    }
    pub fn grow(&self, k: f64) -> Rect {
        Rect {
            x0: self.x0 - k,
            y0: self.y0 - k,
            x1: self.x1 + k,
            y1: self.y1 + k,
            ccx: self.ccx,
            ccy: self.ccy,
            cw: self.cw + 2.0 * k,
            ch: self.ch + 2.0 * k,
        }
    }
    pub fn cx(&self) -> f64 {
        self.ccx
    }
    pub fn cy(&self) -> f64 {
        self.ccy
    }
    pub fn w(&self) -> f64 {
        self.cw
    }
    pub fn h(&self) -> f64 {
        self.ch
    }
    pub fn overlaps(&self, o: &Rect) -> bool {
        self.x0 < o.x1 && o.x0 < self.x1 && self.y0 < o.y1 && o.y0 < self.y1
    }
    pub fn contains_open(&self, x: f64, y: f64) -> bool {
        x > self.x0 + EPS && x < self.x1 - EPS && y > self.y0 + EPS && y < self.y1 - EPS
