pub fn shape_override(ctx: &Ctx, i: usize) -> Option<Vec<String>> {
    let n = &ctx.nodes[i];
    if n.prim != crate::types::Prim::Block || n.geo_off == (0.0, 0.0) || !place::is_component(ctx, i) {
        return None;
    }
