#!/usr/bin/env python3
# run a schematic snippet with a standard 3-pin anchor header; print summary
import sys
sys.path.insert(0, '/tmp/sch/scripts')
from summ import run, summarize

HEAD = '''{ layout: schematic; %s |vcc::label| { symbol: power } [ "5V" ] }
|component#u1| "U" [ |pin#a| {side: left}; |pin#b| {side: left}; |pin#c| {side: right} ]
'''
args = sys.argv[1:]
extra = ''
mine = False
while args and args[0].startswith('-'):
    a = args.pop(0)
    if a == '-g':
        extra = 'gap: %s;' % args.pop(0)
    if a == '-m':
        mine = True
for body in args:
    src = HEAD % extra + body.replace('\\n', '\n')
    o, e, c = run(src, exe='/tmp/bin-sch/executable' if mine else '/workspace/executable')
    print('###', body)
    if e: print(e.rstrip())
    print(summarize(o, 1, True))

