import itertools
g=32.0
def check(xs):
    a=repr(xs[1]-23.5); b=repr((xs[2]-xs[1]+24)/2); c='%.4f'%((xs[0]+xs[1])/2)
    return a=='-13.29249999999999' and b=='79.60749999999999' and c=='-62.5037'
def fams(ws):
    n=len(ws)
    out={}
    # distance variants
    dvars={
     'h+g+h': [ws[k]/2+g+ws[k+1]/2 for k in range(n-1)],
     '(w+w)/2+g': [(ws[k]+ws[k+1])/2+g for k in range(n-1)],
     'h+(g+h)': [ws[k]/2+(g+ws[k+1]/2) for k in range(n-1)],
     '(h+h)+g': [(ws[k]/2+ws[k+1]/2)+g for k in range(n-1)],
     'g+h+h': [g+ws[k]/2+ws[k+1]/2 for k in range(n-1)],
    }
    for dn,d in dvars.items():
        xs=[0.0]
        for k in range(n-1): xs.append(xs[-1]+d[k])
        lo=xs[0]-ws[0]/2; hi=xs[-1]+ws[-1]/2
        out[dn+' mid']=[x-(lo+hi)/2 for x in xs]
        out[dn+' lo+half']=[x-lo-(hi-lo)/2 for x in xs]
        out[dn+' half']=[x+(-(hi-lo)/2-lo) for x in xs]
        out[dn+' hi-half']=[x-(hi-(hi-lo)/2) for x in xs]
        tot=hi-lo
        out[dn+' start']=None
        x0=-tot/2+ws[0]/2
        ys=[x0]
        for k in range(n-1): ys.append(ys[-1]+d[k])
        out[dn+' start']=ys
        # start at w0/2
        ys=[ws[0]/2]
        for k in range(n-1): ys.append(ys[-1]+d[k])
        t=ys[-1]+ws[-1]/2
        out[dn+' w0/2 -t/2']=[y-t/2 for y in ys]
    # cursor families
    for tn in ['sum','acc']:
        if tn=='sum': tot=sum(ws)+g*(n-1)
        else:
            tot=0.0
            for k,w in enumerate(ws):
                tot+=w
                if k<n-1: tot+=g
        c=-tot/2; xs=[]
        for w in ws:
            xs.append(c+w/2); c+=w+g
        out['cur '+tn]=xs
        c=-tot/2; xs=[]
        for w in ws:
            xs.append(c+w/2); c=c+w; c=c+g
        out['cur2 '+tn]=xs
        c=0.0; xs=[]
        for w in ws:
            xs.append(c+w/2); c+=w+g
        out['curz '+tn]=[x-tot/2 for x in xs]
    return out
for ws in ([111.81,115.035,91.39500000000001],[111.81,115.035,91.395]):
    print('ws',ws)
    for k,xs in fams(ws).items():
        if xs and check(xs): print('  OK',k,[repr(x) for x in xs])
