        return x
    if var == 'a*s/u':
        x = 0.0
        for a in advs: x += a * size / 1000
        return x
    if var == 'sum*s/u':
        return sum(advs) * size / 1000
    if var == 'sum/u*s':
        return sum(advs) / 1000 * size

def outer(spec, var, wvar):
    if spec[0] == 'fixed':
        return spec[1]
    _, text, extra = spec
    tw = tw_var(text, 15, 500, var)
    if extra is not None:
        tw = max(tw, extra)
    if wvar == 0:
        return ((tw + 20) + 20) + 2
    if wvar == 1:
        return (tw + 40) + 2
    if wvar == 2:
        return tw + 42

g = 32.0

def positions(ws, f):
    n = len(ws)
    if f == 'cum_h_g_h_mid':
        xs = [0.0]
        for i in range(1, n): xs.append(xs[-1] + ws[i-1]/2 + g + ws[i]/2)
        off = (xs[0] - ws[0]/2 + xs[-1] + ws[-1]/2) / 2
        return [x - off for x in xs]
    if f.startswith('d:'):
        _, dn, sh = f.split(':')
        if dn == 'h+g+h': d = [ws[k]/2 + g + ws[k+1]/2 for k in range(n-1)]
        if dn == '(w+w)/2+g': d = [(ws[k]+ws[k+1])/2 + g for k in range(n-1)]
        if dn == 'h+(g+h)': d = [ws[k]/2 + (g + ws[k+1]/2) for k in range(n-1)]
        if dn == '(h+h)+g': d = [(ws[k]/2 + ws[k+1]/2) + g for k in range(n-1)]
        xs = [0.0]
        for k in range(n-1): xs.append(xs[-1] + d[k])
        lo = xs[0] - ws[0]/2; hi = xs[-1] + ws[-1]/2
        if sh == 'mid': return [x - (lo+hi)/2 for x in xs]
        if sh == 'lohalf': return [x - lo - (hi-lo)/2 for x in xs]
        if sh == 'half': return [x + (-(hi-lo)/2 - lo) for x in xs]
        if sh == 'start':
            tot = hi - lo
            ys = [-tot/2 + ws[0]/2]
            for k in range(n-1): ys.append(ys[-1] + d[k])
            return ys
        if sh == 'w0':
            ys = [ws[0]/2]
            for k in range(n-1): ys.append(ys[-1] + d[k])
