                if k < n-1: tot += g
        c = -tot/2; xs = []
        for w in ws:
            xs.append(c + w/2); c += w + g
        return xs
    if f.startswith('curz:'):
        tn = f.split(':')[1]
        c = 0.0; xs = []
        for w in ws:
            xs.append(c + w/2); c += w + g
        tot = c - g
        return [x - tot/2 for x in xs]

