// "; did you mean 'a', 'b'?" → "; did you mean ':a', ':b'?"
fn fix_suggest(s: &str) -> String {
    if s.is_empty() {
        return String::new();
    }
    let mut out = String::new();
    let mut open = false;
    for ch in s.chars() {
        out.push(ch);
        if ch == '\'' {
            if !open {
                out.push(':');
            }
            open = !open;
        }
    }
    out.replace("'::", "':")
}

