from tw import fonts
g = 32.0

def tw(s, size, w):
    t = fonts[w]
    x = 0.0
    for c in s:
        x += t.adv[t.cmap[ord(c)]] / 1000 * size
    return x

def boxw(l):
    return ((tw(l, 15, 500) + 20) + 20) + 2

# messages: (i, j, label)
def algo(ws, msgs, variant):
    n = len(ws)
    c = 0.0
    xs = []
    for k, w in enumerate(ws):
        c += w / 2
        xs.append(c)
        c += w / 2 + g
    tot = c - g
    for (a, b, lab) in msgs:
        i, j = min(a, b), max(a, b)
        need = tw(lab, 13, 400) + 16
        cur = xs[j] - xs[i]
        if cur < need:
            if variant == 'shift_each':
                add = (need - cur) / (j - i)
                for k in range(i + 1, n):
                    xs[k] += add * min(k - i, j - i)
                tot += need - cur
            elif variant == 'shift_loop':
                add = (need - cur) / (j - i)
                for k in range(i + 1, n):
                    m = min(k - i, j - i)
                    xs[k] += add * m
                tot += add * (j - i)
            elif variant == 'gaps':
                add = (need - cur) / (j - i)
                # accumulate per gap
                for step in range(i + 1, j + 1):
                    for k in range(step, n):
                        xs[k] += add
                tot += (need - cur)
            elif variant == 'gaps2':
                add = (need - cur) / (j - i)
                for step in range(i + 1, j + 1):
                    for k in range(step, n):
