cases = eval(open('/tmp/seq/try6.py').read().split('cases = ')[1].split('\nfor variant')[0])

def natural(ws):
    c = 0.0
    xs = []
    for k, w in enumerate(ws):
        c += w / 2
        xs.append(c)
        c += w / 2 + g
    return xs, c - g

def algo(ws, msgs, shift, totv, fin):
    n = len(ws)
    xs, tot = natural(ws)
    for (a, b, lab) in msgs:
        i, j = min(a, b), max(a, b)
        need = tw(lab, 13, 400) + 16
        cur = xs[j] - xs[i]
        if cur < need:
            deficit = need - cur
            add = deficit / (j - i)
            if shift == 'A':
                for k in range(i + 1, n):
                    xs[k] += add * min(k - i, j - i)
            elif shift == 'B':
                for step in range(i + 1, j + 1):
                    for k in range(step, n):
                        xs[k] += add
            elif shift == 'C':
                for k in range(i + 1, n):
                    if k <= j:
                        xs[k] += add * (k - i)
                    else:
                        xs[k] += deficit
            elif shift == 'D':
                for k in range(i + 1, n):
                    xs[k] += add * (min(k, j) - i)
            elif shift == 'E':
                # cumulative: shift accumulates as we go
                acc = 0.0
                for k in range(i + 1, n):
                    if k <= j:
                        acc += add
                    xs[k] += acc
            if totv == 'a':
                tot += deficit
            elif totv == 'b':
                tot += add * (j - i)
            elif totv == 'e':
                acc = 0.0
                for k in range(i + 1, j + 1):
                    acc += add
                tot += acc
    if totv == 'c':
        tot = xs[-1] + ws[-1] / 2
    if fin == 0:
        return [x - tot / 2 for x in xs]
    if fin == 1:
        lo = xs[0] - ws[0] / 2
        hi = xs[-1] + ws[-1] / 2
        return [x - (lo + hi) / 2 for x in xs]

for shift in 'ABCDE':
    for totv in 'abce':
        for fin in [0, 1]:
            res = []
            for labels, msgs, exp in cases:
                ws = [boxw(l) for l in labels]
                xs = algo(ws, msgs, shift, totv, fin)
                got = [repr(x - 23.5) for x in xs]
                res.append(got == exp)
            print(shift, totv, fin, res, sum(res))

