import sys, itertools
exec(open('/tmp/seq/try6.py').read().split('def algo')[0])
cases = eval(open('/tmp/seq/try6.py').read().split('cases = ')[1].split('\nfor variant')[0])

def layout(ws, extra, lv):
    c = 0.0
    xs = []
    n = len(ws)
    for k, w in enumerate(ws):
        e = extra[k] if k < n - 1 else 0.0
        if lv == 0:
            c += w / 2; xs.append(c); c += w / 2 + g + e
        elif lv == 1:
            c += w / 2; xs.append(c); c += w / 2 + (g + e)
        elif lv == 2:
            c += w / 2; xs.append(c); c += w / 2; c += g; c += e
        elif lv == 3:
            c += w / 2; xs.append(c); c += w / 2 + g; c += e
        elif lv == 4:
            c += e if k > 0 else 0.0
            c += w / 2; xs.append(c); c += w / 2 + g
        elif lv == 5:
            # extra added before the next participant (extra of previous gap)
            if k > 0:
                c += extra[k - 1]
            c += w / 2; xs.append(c); c += w / 2 + g
    return xs, c - g

def algo2(ws, msgs, lv, cv):
    n = len(ws)
    extra = [0.0] * (n - 1)
    for (a, b, lab) in msgs:
        i, j = min(a, b), max(a, b)
        need = tw(lab, 13, 400) + 16
        xs, tot = layout(ws, extra, lv)
        cur = xs[j] - xs[i]
        if cur < need:
            add = (need - cur) / (j - i)
            for k in range(i, j):
                extra[k] += add
    xs, tot = layout(ws, extra, lv)
    if cv == 0:
        return [x - tot / 2 for x in xs]
    return [x - (xs[-1] + ws[-1] / 2) / 2 for x in xs]

for lv in range(6):
    for cv in range(2):
        res = []
        for labels, msgs, exp in cases:
            ws = [boxw(l) for l in labels]
            xs = algo2(ws, msgs, lv, cv)
            got = [repr(x - 23.5) for x in xs]
            res.append(got == exp)
        print(lv, cv, res, sum(res))

