#!/usr/bin/env python3
# usage: cmpset.py 'ENV=val' 'ENV=val2' corpora... : list snippets whose pass status differs between two env settings
import subprocess, sys, os, re, tempfile, hashlib, pickle
from concurrent.futures import ThreadPoolExecutor
sys.path.insert(0, '/tmp/link2')
MINE = '/tmp/bin-link2/executable'
CACHE = '/tmp/link2/cache'
e1 = dict(x.split('=') for x in sys.argv[1].split(',') if x)
e2 = dict(x.split('=') for x in sys.argv[2].split(',') if x)
files = sys.argv[3:]


def run(b, src, env=None):
    d = tempfile.mkdtemp(prefix='/tmp/link2/rr.')
    p = d + '/r_in.lini'
    open(p, 'w').write(src)
    en = dict(os.environ)
    if env:
        en.update(env)
    r = subprocess.run([b, 'r_in.lini'], capture_output=True, cwd=d, env=en)
    os.remove(p); os.rmdir(d)
    return (r.stdout, r.stderr, r.returncode)


def orig(src):
    h = hashlib.sha1(src.encode()).hexdigest()
    cp = CACHE + '/' + h
    if os.path.exists(cp):
        return pickle.load(open(cp, 'rb'))
    r = run('/workspace/executable', src)
    pickle.dump(r, open(cp, 'wb'))
    return r


def one(s):
    o = orig(s)
    return (run(MINE, s, e1) == o, run(MINE, s, e2) == o)


with ThreadPoolExecutor(max_workers=16) as ex:
    for f in files:
        snips = [s for s in open(f).read().split('\n----\n') if s.strip()]
        res = list(ex.map(one, snips))
        for i, (a, b) in enumerate(res):
            if a != b:
                print('%s #%d  %s -> %s' % (os.path.basename(f), i, 'ok' if a else 'FAIL', 'ok' if b else 'FAIL'))

