import sys, json
sys.path.insert(0, '/tmp/scripts')
from tw import fonts
g = 32.0

def tw_sum(s, size, w):
    t = fonts[w]
    return sum(t.adv[t.cmap[ord(c)]] for c in s) * size / 1000

def tw_glyph(s, size, w):
    t = fonts[w]
    x = 0.0
    for c in s:
        x += t.adv[t.cmap[ord(c)]] / 1000 * size
    return x

def boxw(l):
    return ((tw_glyph(l, 15, 500) + 20) + 20) + 2

def layout(ws, extra, lv):
    c = 0.0
    xs = []
    n = len(ws)
    for k, w in enumerate(ws):
        e = extra[k] if k < n - 1 else 0.0
        if lv == 0:
            c += w / 2; xs.append(c); c += w / 2 + g + e
        elif lv == 1:
            c += w / 2; xs.append(c); c += w / 2 + (g + e)
        elif lv == 2:
            c += w / 2; xs.append(c); c += w / 2; c += g; c += e
        elif lv == 3:
            c += w / 2; xs.append(c); c += w / 2 + g; c += e
        elif lv == 5:
            if k > 0:
                c += extra[k - 1]
            c += w / 2; xs.append(c); c += w / 2 + g
        elif lv == 6:
            c += w / 2; xs.append(c); c += e + w / 2 + g
        elif lv == 7:
            c += w / 2; xs.append(c); c += (w / 2 + g) + e
    return xs, c - g

def run(ws, msgs, lv, twf, cv):
    n = len(ws)
    extra = [0.0] * (n - 1)
    for (a, b, lab) in msgs:
        i, j = min(a, b), max(a, b)
        need = twf(lab, 13, 400) + 16
        xs, tot = layout(ws, extra, lv)
        cur = xs[j] - xs[i]
        if cur < need:
            add = (need - cur) / (j - i)
            for k in range(i, j):
                extra[k] += add
    xs, tot = layout(ws, extra, lv)
    if cv == 0:
        return [x - tot / 2 for x in xs]
    h = (xs[-1] + ws[-1] / 2) / 2
    return [x - h for x in xs]

