                let (s0, n0) = blocks[blocks.len() - 2];
                if s0 / n0 as f64 > s1 / n1 as f64 + 1e-12 {
                    blocks.pop();
                    blocks.pop();
                    blocks.push((s0 + s1, n0 + n1));
                } else {
                    break;
                }
            }
