import sys, json, itertools
sys.path.insert(0, '/tmp/scripts')
from tw import fonts
g = 32.0

def tw_sum(s, size, w):
    t = fonts[w]
    return sum(t.adv[t.cmap[ord(c)]] for c in s) * size / 1000

def tw_glyph(s, size, w):
    t = fonts[w]
    x = 0.0
    for c in s:
        x += t.adv[t.cmap[ord(c)]] / 1000 * size
    return x

def tw_glyph2(s, size, w):
    t = fonts[w]
    x = 0.0
    for c in s:
        x += t.adv[t.cmap[ord(c)]] * size / 1000
    return x

def boxw(l):
    return ((tw_glyph(l, 15, 500) + 20) + 20) + 2

data = json.load(open('/tmp/seq/collected.json'))
old = eval(open('/tmp/seq/try6.py').read().split('cases = ')[1].split('\nfor variant')[0])
data = [(a, b, c) for a, b, c in old] + data

def natural(ws):
    c = 0.0
    xs = []
    for w in ws:
        c += w / 2
        xs.append(c)
        c += w / 2 + g
    return xs, c - g

def algo(ws, msgs, twf, shift, totv, fin):
    n = len(ws)
    xs, tot = natural(ws)
    for (a, b, lab) in msgs:
        i, j = min(a, b), max(a, b)
        need = twf(lab, 13, 400) + 16
        cur = xs[j] - xs[i]
        if cur < need:
            deficit = need - cur
            add = deficit / (j - i)
            if shift == 'A':
                for k in range(i + 1, n):
                    xs[k] += add * min(k - i, j - i)
            elif shift == 'B':
                for step in range(i + 1, j + 1):
                    for k in range(step, n):
                        xs[k] += add
            elif shift == 'C':
                for k in range(i + 1, n):
                    if k <= j:
                        xs[k] += add * (k - i)
                    else:
                        xs[k] += deficit
            elif shift == 'E':
                acc = 0.0
                for k in range(i + 1, n):
                    if k <= j:
                        acc += add
                    xs[k] += acc
            elif shift == 'F':
                # positions after j keep their distance to j
                for k in range(i + 1, j + 1):
                    xs[k] += add * (k - i)
                for k in range(j + 1, n):
                    xs[k] += add * (j - i)
            elif shift == 'G':
                old_j = xs[j]
                for k in range(i + 1, j + 1):
                    xs[k] = xs[i] + (xs[k] - xs[i]) + add * (k - i)
                for k in range(j + 1, n):
                    xs[k] += xs[j] - old_j
            if totv == 'a':
                tot += deficit
            elif totv == 'b':
                tot += add * (j - i)
    if totv == 'c':
        tot = xs[-1] + ws[-1] / 2
    if fin == 0:
        return [x - tot / 2 for x in xs]
    h = tot / 2
    return [x - h for x in xs]

best = []
for twname, twf in [('sum', tw_sum), ('glyph', tw_glyph), ('glyph2', tw_glyph2)]:
    for shift in 'ABCEFG':
        for totv in 'abc':
            res = []
            for labels, msgs, exp in data:
                ws = [boxw(l) for l in labels]
                xs = algo(ws, msgs, twf, shift, totv, 0)
                got = [repr(x - 23.5) for x in xs]
                res.append(got == exp)
            best.append((sum(res), twname, shift, totv, ''.join('1' if r else '0' for r in res)))
best.sort()
for b in best[-10:]:
    print(b)

