def fnv64(data: bytes) -> int:
    h = 0xcbf29ce484222325
    for b in data:
        h ^= b
        h = (h * 0x100000001b3) & 0xffffffffffffffff
    return h

def hash8(s) -> str:
    if isinstance(s, str):
        s = s.encode()
    h = fnv64(s)
    return '%08x' % (((h >> 32) ^ h) & 0xffffffff)

def f4(v: float) -> str:
    s = '%.4f' % v
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    if s == '-0':
        s = '0'
    return s

def rdisplay(v: float) -> str:
    # Rust Display for f64 (shortest round-trip, no exponent)
    if v != v: return 'NaN'
    if v == float('inf'): return 'inf'
    if v == float('-inf'): return '-inf'
    r = repr(v)
    if 'e' in r or 'E' in r:
        from decimal import Decimal
        d = Decimal(r)
        s = format(d, 'f')
    else:
        s = r
    if s.endswith('.0'):
        s = s[:-2]
    return s

def rdebug(v: float) -> str:
    # Rust Debug for f64: like Display but keeps .0, uses exponent for very large/small
    if v != v: return 'NaN'
    if v == float('inf'): return 'inf'
    if v == float('-inf'): return '-inf'
    a = abs(v)
    if a != 0 and (a < 1e-4 or a >= 1e16):
        r = repr(v)
        # python repr like '1e-05' -> rust '1e-5'
        m, e = r.split('e')
        e = int(e)
        if '.' in m and m.endswith('.0'): m = m[:-2]
        return '%se%d' % (m, e)
    s = rdisplay(v)
    if '.' not in s:
        s += '.0'
    return s

if __name__ == '__main__':
    assert hash8('2,3,3,rgba(0, 0, 0, 0.2)') == '803f42a2', hash8('2,3,3,rgba(0, 0, 0, 0.2)')
    print('ok', rdebug(135.0), rdisplay(135.0), rdebug(-0.0), rdisplay(-0.0), rdebug(1e-7), rdisplay(1e-7), f4(-0.00001))

