import sys, json, itertools
exec(open('/tmp/seq/p5.py').read().split('def algo')[0])

def lay(ws, gaps, startv, totv):
    n = len(ws)
    if totv == 0:
        tot = 0.0
        for k in range(n):
            tot += ws[k]
            if k < n - 1:
                tot += gaps[k]
    elif totv == 1:
        tot = sum(ws) + sum(gaps)
    elif totv == 2:
        c = 0.0
        for k in range(n):
            c += ws[k] / 2
            c += ws[k] / 2
            if k < n - 1:
                c += gaps[k]
        tot = c
    elif totv == 3:
        c = 0.0
        for k in range(n):
            c += ws[k] / 2
            c += ws[k] / 2 + (gaps[k] if k < n - 1 else g)
        tot = c - g
    if startv == 0:
        c = -tot / 2
