from fnv import hash8

# data: (angle, spacing, color_text_variants) -> id
data = [
    (45.0, 10.0, 'red', '1a5710ad'),
    (45.0, 10.0, 'RED', 'a2be7462'),
    (45.0, 10.0, '"red"', 'dc175a5c'),
]

def angle_variants(a):
    return {
        'disp': '45', 'dbg': '45.0', 'deg': '45deg', 'rot': 'rotate(45)', 'some': 'Some(45.0)', 'f4_4': '45.0000',
    }

def spacing_variants(s):
    return {'disp': '10', 'dbg': '10.0', 'f4_4': '10.0000', 'w': 'width="10"', 'some': 'Some(10.0)'}

def color_variants(c):
    import json
    return {'raw': c, 'q': json.dumps(c), 'some': 'Some(%s)' % json.dumps(c), 'stroke': 'stroke: %s' % c, 'somer': 'Some(%s)' % c}

seps = [',', ', ', ' ', '|', ';', ':', '/', '\n', '-', '_', '', '\t', '; ', ' | ', '#', '@', '.', '+', '&', '=', '~', '*', '\x00', '\x1f']
prefixes = ['', 'hatch', 'hatch:', 'hatch(', 'lini-hatch', 'Hatch', 'pattern', 'hatch ', 'hatch|', 'hatch,', 'hatch-', 'h', 'Hatch ', 'Hatch(']
suffixes = ['', ')', '\n', ' }', '}']
extras = [None, '0.75', '0.75.0'[:4], '6', '1']

def gen(a, s, c):
    av = angle_variants(a); sv = spacing_variants(s); cv = color_variants(c)
    for ak, at in av.items():
        for sk, st in sv.items():
            for ck, ct in cv.items():
                for ex in extras:
                    comps = [('A', at), ('S', st), ('C', ct)]
                    if ex is not None:
                        comps.append(('E', ex))
                    for perm in itertools.permutations(comps):
                        for sep in seps:
                            body = sep.join(p[1] for p in perm)
                            for pre in prefixes:
                                for suf in suffixes:
                                    yield (ak, sk, ck, ex, ''.join(p[0] for p in perm), sep, pre, suf), pre + body + suf

a, s, c, target = data[0]
n = 0
cands = []
for key, txt in gen(a, s, c):
    n += 1
    if hash8(txt) == target:
        print('MATCH', key, repr(txt))
        cands.append(key)
print('tested', n)

