import sys, json, itertools
exec(open('/tmp/seq/p5.py').read().split('def algo')[0])

def lay2(ws, extra, iv):
    n = len(ws)
    c = 0.0
    xs = []
    for k in range(n):
        e = extra[k] if k < n - 1 else 0.0
        w = ws[k]
        c += w / 2
        xs.append(c)
        if iv == 'a':
            c += w / 2 + (g + e)
        elif iv == 'b':
            c += w / 2
            c += g + e
        elif iv == 'c':
            c += (g + e) + w / 2
        elif iv == 'd':
            c += w / 2 + g
            c += e
        elif iv == 'e':
            c += (w / 2 + g) + e
        elif iv == 'f':
            c += w / 2
            c += g
            c += e
        elif iv == 'g':
            c += e
            c += w / 2 + g
        elif iv == 'h':
            c += w / 2 + e + g
    # tot: last cursor minus the trailing gap
    tot = c - g
    return [x - tot / 2 for x in xs], xs, tot

def curf(ws, extra, i, j, cv, iv):
    if cv == 0:
        cur = ws[i] / 2 + ws[j] / 2
        for k in range(i, j):
            cur += g + extra[k]
            if k > i:
                cur += ws[k]
        return cur
    if cv == 1:
        _, xs, _ = lay2(ws, extra, iv)
        return xs[j] - xs[i]

def famM(ws, msgs, twf, iv, cv, addv):
    n = len(ws)
    extra = [0.0] * (n - 1)
    for (a, b, lab) in msgs:
        i, j = min(a, b), max(a, b)
        need = twf(lab, 13, 400) + 16
        cur = curf(ws, extra, i, j, cv, iv)
        if cur < need:
            add = (need - cur) / (j - i)
            for k in range(i, j):
                extra[k] += add
    fin, _, _ = lay2(ws, extra, iv)
    return fin

best = []
for twname, twf in [('sum', tw_sum), ('glyph', tw_glyph), ('glyph2', tw_glyph2)]:
    for iv in 'abcdefgh':
        for cv in range(2):
            res = []
            for labels, msgs, exp in data:
                ws = [boxw(l) for l in labels]
                xs = famM(ws, msgs, twf, iv, cv, 0)
                got = [repr(x - 23.5) for x in xs]
                res.append(got == exp)
            best.append((sum(res), twname, iv, cv, ''.join('1' if r else '0' for r in res)))
best.sort()
for b in best[-8:]:
