def pos(ws, g):
    c = 0.0; xs = []
    for k, w in enumerate(ws):
        c += w / 2; xs.append(c); c += w / 2; c += g
    tot = c - g
    return [x - tot / 2 for x in xs]
for g, exp in [(20.0, '-0.2588'), (32.0, '-0.2587'), (10.0, '-0.2588')]:
