// Generic slot-template FNV-1a64-folded brute forcer.
// Spec file format (all strings hex-encoded, "-" for empty):
//   P <npoints> <nvars>
//   <target_hex32> <var0hex> <var1hex> ...       (npoints lines)
//   S <nslots>
//   then per slot one of:
//     V <count> \n <hex>\n ... (count lines)
//     D <varidx>
//     R <slotidx>        (reuse choice of earlier V slot)
//     W <slotidx> <count> \n <hex>... : a vocab slot whose choice index is tied to slot slotidx (parallel list)
// Usage: bf spec.txt nproc [hashmode]
//   hashmode 0: fold32 of fnv1a64 (default); 1: fnv1a32; 2: low32 of fnv1a64; 3: high32
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/wait.h>

typedef struct { int len; unsigned char *s; } Str;
typedef struct { char type; int count; Str *v; int ref; int var; } Slot;

static int npoints, nvars, nslots;
static uint32_t *targets;
static Str **vars; // [point][var]
static Slot *slots;
static int hashmode = 0;
static int choice[64];
static int myid, nproc;
static long long found = 0;

static int hexval(char c){ if(c>='0'&&c<='9')return c-'0'; if(c>='a'&&c<='f')return c-'a'+10; if(c>='A'&&c<='F')return c-'A'+10; return -1; }
static Str parsehex(const char *t){
    Str r; size_t n = strlen(t);
    while (n && (t[n-1]=='\n'||t[n-1]=='\r'||t[n-1]==' ')) n--;
    if (n==1 && t[0]=='-') { r.len=0; r.s=(unsigned char*)""; return r; }
    r.len = n/2; r.s = malloc(r.len+1);
    for (int i=0;i<r.len;i++) r.s[i] = hexval(t[2*i])*16+hexval(t[2*i+1]);
    r.s[r.len]=0; return r;
}

#define FNV_OFF 0xcbf29ce484222325ULL
#define FNV_PRIME 0x100000001b3ULL
#define FNV32_OFF 0x811c9dc5U
#define FNV32_PRIME 0x01000193U

static inline uint64_t upd(uint64_t h, const unsigned char *s, int n){
    if (hashmode==1){ uint32_t g=(uint32_t)h; for(int i=0;i<n;i++){ g^=s[i]; g*=FNV32_PRIME;} return g; }
    for (int i=0;i<n;i++){ h ^= s[i]; h *= FNV_PRIME; }
    return h;
}
static inline uint32_t fin(uint64_t h){
    switch(hashmode){
        case 1: return (uint32_t)h;
        case 2: return (uint32_t)h;
        case 3: return (uint32_t)(h>>32);
        default: return (uint32_t)((h>>32) ^ (h & 0xffffffffULL));
    }
}

static uint64_t hash_point(int p){
    uint64_t h = hashmode==1 ? FNV32_OFF : FNV_OFF;
    for (int i=0;i<nslots;i++){
        Slot *sl=&slots[i]; Str *s;
        if (sl->type=='V') s=&sl->v[choice[i]];
        else if (sl->type=='D') s=&vars[p][sl->var];
        else if (sl->type=='R') s=&slots[sl->ref].v[choice[sl->ref]];
        else /* W */ s=&sl->v[choice[sl->ref]];
        h = upd(h, s->s, s->len);
    }
    return h;
}

static void report(void){
    int ok=1;
    for (int p=1;p<npoints;p++) if (fin(hash_point(p))!=targets[p]) { ok=0; break; }
    int nmatch=1;
    if (!ok){ nmatch=1; for(int p=1;p<npoints;p++) if (fin(hash_point(p))==targets[p]) nmatch++; }
    if (ok || nmatch>=2){
        printf("%s matches=%d/%d key0=\"", ok?"FULLMATCH":"PARTIAL", nmatch, npoints);
        for (int i=0;i<nslots;i++){
            Slot *sl=&slots[i]; Str *s;
            if (sl->type=='V') s=&sl->v[choice[i]];
            else if (sl->type=='D') s=&vars[0][sl->var];
            else if (sl->type=='R') s=&slots[sl->ref].v[choice[sl->ref]];
            else s=&sl->v[choice[sl->ref]];
            for (int k=0;k<s->len;k++){ unsigned char c=s->s[k]; if(c=='\n') printf("\\n"); else if(c=='\t') printf("\\t"); else if(c<32||c>126) printf("\\x%02x",c); else if(c=='"'||c=='\\') printf("\\%c",c); else putchar(c);}
        }
        printf("\" choices=");
        for (int i=0;i<nslots;i++) if (slots[i].type=='V') printf("%d,", choice[i]);
        printf("\n"); fflush(stdout);
    }
    found++;
}

static int firstV = -1;
static void dfs(int i, uint64_t h){
    if (i==nslots){
        if (fin(h)==targets[0]) report();
        return;
    }
    Slot *sl=&slots[i];
    if (sl->type=='V'){
        for (int c=0;c<sl->count;c++){
            if (i==firstV && (c % nproc) != myid) continue;
            choice[i]=c;
            dfs(i+1, upd(h, sl->v[c].s, sl->v[c].len));
        }
    } else {
        Str *s;
        if (sl->type=='D') s=&vars[0][sl->var];
        else if (sl->type=='R') s=&slots[sl->ref].v[choice[sl->ref]];
        else s=&sl->v[choice[sl->ref]];
        dfs(i+1, upd(h, s->s, s->len));
    }
}

int main(int argc, char **argv){
    if (argc<3){ fprintf(stderr,"usage\n"); return 1; }
    FILE *f=fopen(argv[1],"r"); if(!f){perror("open");return 1;}
    nproc=atoi(argv[2]); if (argc>3) hashmode=atoi(argv[3]);
    static char line[1<<20];
    char tag[8];
    if (fscanf(f,"%7s %d %d\n",tag,&npoints,&nvars)!=3) return 2;
    targets=malloc(sizeof(uint32_t)*npoints); vars=malloc(sizeof(Str*)*npoints);
    for (int p=0;p<npoints;p++){
        if(!fgets(line,sizeof line,f)) return 3;
        char *tok=strtok(line," \n"); targets[p]=(uint32_t)strtoul(tok,0,16);
        vars[p]=malloc(sizeof(Str)*(nvars>0?nvars:1));
