#[derive(Clone, Debug)]
enum Outline {
    // a drawn run of segments (closed loops wrap around), stroke width
    Path(Vec<Seg>, bool, f64),
    Ellipse(M, f64, f64, f64),
}

fn outlines(ctx: &Ctx, f: usize) -> Vec<Outline> {
    let mut out = Vec::new();
    let mut stack: Vec<usize> = ctx.nodes[f].children.iter().rev().copied().collect();
    while let Some(i) = stack.pop() {
        let n = &ctx.nodes[i];
        if n.prim == Prim::Text || crate::drawing::is_chrome(ctx, i) || ctx.sk.chrome.contains_key(&i) || is_annotation_node(ctx, i) {
            continue;
        }
        let m = to_frame(ctx, i, f);
        let sw = if ctx.sk.copies.contains(&i) { 0.0 } else { stroke_w(ctx, i) };
        if !is_wrapper(ctx, i) && ctx.comp[i].has_stroke && !crate::drawing::is_frame(ctx, i) {
            let c = pt(-n.geo_off.0, -n.geo_off.1);
            let (hw, hh) = (n.w / 2.0, n.h / 2.0);
            let poly = |ps: &[P]| -> Outline {
                let segs = (0..ps.len()).map(|k| Seg::Line { a: apply(&m, ps[k]), b: apply(&m, ps[(k + 1) % ps.len()]) }).collect();
                Outline::Path(segs, true, sw)
            };
            match n.prim {
                Prim::Oval => {
                    let mm = mul(&m, &[1.0, 0.0, 0.0, 1.0, c.x, c.y]);
                    out.push(Outline::Ellipse(mm, hw, hh, sw));
                }
                Prim::Sketch => {
                    if let Some(l) = ctx.sk.laid.get(&i) {
                        for s in &l.shape.subs {
                            let mut segs: Vec<Seg> = s.segs.iter().map(|g| map_seg(&m, g)).collect();
                            if s.closed && !s.end().near(s.start) {
                                segs.push(map_seg(&m, &Seg::Line { a: s.end(), b: s.start }));
                            }
                            out.push(Outline::Path(segs, s.closed, sw));
                        }
                    }
                }
                Prim::Block if n.w > 0.0 && n.h > 0.0 => {
                    out.push(poly(&[pt(c.x - hw, c.y - hh), pt(c.x + hw, c.y - hh), pt(c.x + hw, c.y + hh), pt(c.x - hw, c.y + hh)]));
                }
                Prim::Hex if n.w > 0.0 && n.h > 0.0 => {
                    let ps: Vec<P> = [pt(-hw, 0.0), pt(-hw / 2.0, -hh), pt(hw / 2.0, -hh), pt(hw, 0.0), pt(hw / 2.0, hh), pt(-hw / 2.0, hh)].iter().map(|p| p.add(c)).collect();
                    out.push(poly(&ps));
                }
                Prim::Diamond if n.w > 0.0 && n.h > 0.0 => {
                    let ps: Vec<P> = [pt(0.0, -hh), pt(hw, 0.0), pt(0.0, hh), pt(-hw, 0.0)].iter().map(|p| p.add(c)).collect();
                    out.push(poly(&ps));
                }
                _ => {}
            }
        }
        for &ch in n.children.iter().rev() {
            stack.push(ch);
        }
    }
    out
}

fn side_of(p: P, d: P, x: P) -> f64 {
    d.cross(x.sub(p))
}

// Crossings of segment p→q with one outline segment: (t along p→q, s along
// the outline segment, sin of the crossing angle).
fn seg_hits(p: P, q: P, g: &Seg) -> Vec<(f64, f64, f64)> {
    let d = q.sub(p);
    let len = d.len();
    if len < 1e-12 {
        return vec![];
    }
    let u = d.mul(1.0 / len);
    let mut out = Vec::new();
    match g {
        Seg::Line { a, b } => {
            let e = b.sub(*a);
            let den = d.cross(e);
            if den.abs() < 1e-12 {
                return out;
            }
            let w = a.sub(p);
            let t = w.cross(e) / den;
            let s = w.cross(d) / den;
            if t > 1e-9 && t < 1.0 - 1e-9 && s > -1e-9 && s < 1.0 + 1e-9 {
                out.push((t, s.clamp(0.0, 1.0), u.cross(e.unit()).abs()));
            }
        }
        Seg::Arc { c, r, sweep, .. } => {
            let f0 = p.sub(*c);
            let a2 = d.dot(d);
            let b2 = 2.0 * f0.dot(d);
            let c2 = f0.dot(f0) - r * r;
            let disc = b2 * b2 - 4.0 * a2 * c2;
            if disc < 0.0 {
                return out;
            }
            let sq = disc.sqrt();
            for t in [(-b2 - sq) / (2.0 * a2), (-b2 + sq) / (2.0 * a2)] {
                if t > 1e-9 && t < 1.0 - 1e-9 {
                    let x = p.add(d.mul(t));
                    if let Some(s) = arc_param(g, x) {
                        let nrm = x.sub(*c).unit();
                        let _ = sweep;
                        out.push((t, s, u.dot(nrm).abs()));
                    }
                }
            }
        }
        Seg::Cubic { .. } => {
            let n = 64;
            let mut prev = seg_point(g, 0.0);
            for k in 1..=n {
                let cur = seg_point(g, k as f64 / n as f64);
                let e = cur.sub(prev);
                let den = d.cross(e);
                if den.abs() > 1e-12 {
                    let w = prev.sub(p);
                    let t = w.cross(e) / den;
                    let s = w.cross(d) / den;
                    if t > 1e-9 && t < 1.0 - 1e-9 && s >= 0.0 && s < 1.0 {
                        out.push((t, ((k - 1) as f64 + s) / n as f64, u.cross(e.unit()).abs()));
                    }
                }
                prev = cur;
            }
        }
    }
    out
}

// The parameter (0..1) of a point on an arc, if it lies on it.
fn arc_param(g: &Seg, x: P) -> Option<f64> {
    if let Seg::Arc { a, c, sweep, .. } = g {
        let v0 = a.sub(*c);
        let v1 = x.sub(*c);
        let mut ang = v0.cross(v1).atan2(v0.dot(v1));
        if *sweep >= 0.0 {
            if ang < -1e-9 {
                ang += 2.0 * std::f64::consts::PI;
            }
            if ang <= sweep + 1e-9 {
                return Some((ang / sweep).clamp(0.0, 1.0));
            }
        } else {
            if ang > 1e-9 {
                ang -= 2.0 * std::f64::consts::PI;
            }
            if ang >= sweep - 1e-9 {
                return Some((ang / sweep).clamp(0.0, 1.0));
            }
        }
    }
    None
}

// A point just inside a segment from one end (for side tests at vertices).
fn near_end(g: &Seg, at_start: bool) -> P {
    let t = if at_start { 1e-3 } else { 1.0 - 1e-3 };
    seg_point(g, t)
}

// Crossings of segment p→q with an outline: (t along p→q, sin of the angle).
// A crossing at a vertex counts once, and only where the outline passes
// from one side of the line to the other.
fn crossings(p: P, q: P, o: &Outline) -> Vec<(f64, f64)> {
    let d = q.sub(p);
    if d.len() < 1e-12 {
        return vec![];
    }
    let mut out = Vec::new();
    match o {
        Outline::Path(segs, closed, _) => {
            let n = segs.len();
            for k in 0..n {
                for (t, s, sin) in seg_hits(p, q, &segs[k]) {
                    if s > 1e-9 && s < 1.0 - 1e-9 {
                        out.push((t, sin));
                        continue;
                    }
                    if s >= 1.0 - 1e-9 {
                        // the next segment's start owns this vertex
                        if k + 1 < n || *closed {
                            continue;
                        }
                        continue;
                    }
                    // at this segment's start vertex
                    let prev = if k > 0 {
                        Some(&segs[k - 1])
                    } else if *closed {
                        Some(&segs[n - 1])
                    } else {
                        None
                    };
                    if let Some(pg) = prev {
                        let before = near_end(pg, false);
                        let after = near_end(&segs[k], true);
                        let (sb, sa) = (side_of(p, d, before), side_of(p, d, after));
                        if sb * sa < 0.0 {
                            out.push((t, sin));
                        }
                    }
                }
            }
        }
        Outline::Ellipse(m, rx, ry, _) => {
            let u = d.unit();
            let inv = match invert(m) {
                Some(v) => v,
                None => return out,
            };
            let lp = apply(&inv, p);
            let ld = apply_v(&inv, d);
            if *rx <= 0.0 || *ry <= 0.0 {
                return out;
            }
            let a2 = (ld.x / rx).powi(2) + (ld.y / ry).powi(2);
            let b2 = 2.0 * (lp.x * ld.x / (rx * rx) + lp.y * ld.y / (ry * ry));
            let c2 = (lp.x / rx).powi(2) + (lp.y / ry).powi(2) - 1.0;
            let disc = b2 * b2 - 4.0 * a2 * c2;
            if disc <= 0.0 {
                return out;
            }
            let sq = disc.sqrt();
            for t in [(-b2 - sq) / (2.0 * a2), (-b2 + sq) / (2.0 * a2)] {
                if t > 1e-9 && t < 1.0 - 1e-9 {
                    let lx = lp.add(ld.mul(t));
                    let ln = pt(lx.x / (rx * rx), lx.y / (ry * ry));
                    let nrm = apply_v(&[inv[0], inv[2], inv[1], inv[3], 0.0, 0.0], ln).unit();
                    out.push((t, u.dot(nrm).abs()));
                }
            }
        }
    }
    out
}

