#!/usr/bin/env python3
# count differing output lines (orig vs mine) over random cases
import sys, random, difflib, os
sys.path.insert(0, '/tmp/tree')
from lt import run, ORIG, MINE
from gen import case, topic

def lines_diff(a, b):
    sa = a.split('\n'); sb = b.split('\n')
    if len(sa) != len(sb):
        return 1000
    return sum(1 for x, y in zip(sa, sb) if x != y)

if __name__ == '__main__':
    seed = int(sys.argv[1]); n = int(sys.argv[2])
    kind = sys.argv[3] if len(sys.argv) > 3 else 'all'
    rng = random.Random(seed)
    tot = 0; bad = 0
    cache = {}
    for i in range(n):
        if kind == 'mm':
            src = topic(rng, 0, rng.choice([2, 3, 4]), True, 'mindmap')
        else:
            src = case(rng)
        a = run(src)
        b = run(src, (), MINE)
        d = lines_diff(a[0], b[0])
        tot += d
        if d:
            bad += 1
    print('cases bad %d / %d, lines %d' % (bad, n, tot))

