            let h = l / 2.0;
            let s = format!(
                "<polygon class=\"lini-marker lini-marker-arrow\" points=\"{} {} {}\"/>",
                pt(p.0, p.1),
                pt(bx + perp.0 * h, by + perp.1 * h),
                pt(bx - perp.0 * h, by - perp.1 * h)
            );
