            let s = format!(
                "<circle class=\"lini-marker lini-marker-dot\" cx=\"{}\" cy=\"{}\" r=\"{}\"/>",
                f4(p.0 - d.0 * r),
                f4(p.1 - d.1 * r),
                f4(r)
            );
            Marker { elems: vec![s], pull: 2.0 * sw, open: false, filled: true }
        }
        "diamond" => {
            let h = l / 2.0;
            let m = (p.0 - d.0 * h, p.1 - d.1 * h);
