            let s = format!(
                "<polygon class=\"lini-marker lini-marker-diamond\" points=\"{} {} {} {}\"/>",
                pt(p.0, p.1),
                pt(m.0 + perp.0 * h, m.1 + perp.1 * h),
                pt(b.0, b.1),
                pt(m.0 - perp.0 * h, m.1 - perp.1 * h)
            );
