fn lay_linear_pref(ctx: &Ctx, f: usize, st: &St, lins: &[Lin], lay: &mut Layout, out: &mut Vec<Item>, prefix: &str) -> Result<(), Diag> {
    if lins.is_empty() {
        return Ok(());
    }
