    // zero-length runs carry no direction
    let mut segs: Vec<((f64, f64), (f64, f64), f64)> = Vec::new();
    for w in fl.windows(2) {
        let l = ((w[1].0 - w[0].0).powi(2) + (w[1].1 - w[0].1).powi(2)).sqrt();
