                let u = ((b.0 - a.0) / l, (b.1 - a.1) / l);
                return ((a.0 + (b.0 - a.0) * t, a.1 + (b.1 - a.1) * t), u);
            }
            acc += l;
        }
        (pts[0], (1.0, 0.0))
    };
    let amp = 1.4;
    let lam = 12.0;
    let ramp = 6.0;
    let cnt = ((total / 3.0).round() as usize).max(1);
    let h = total / cnt as f64;
    let ss = |t: f64| {
        let t = t.clamp(0.0, 1.0);
        3.0 * t * t - 2.0 * t * t * t
    };
    let dss = |t: f64| if t <= 0.0 || t >= 1.0 { 0.0 } else { 6.0 * t - 6.0 * t * t };
