        let y = amp * e * (w * x).sin();
        let dy = amp * (de * (w * x).sin() + e * w * (w * x).cos());
        let (p, u) = at(x);
        let nr = (-u.1, u.0);
        let q = (p.0 + nr.0 * y, p.1 + nr.1 * y);
