fn label_of(l: &Link) -> Option<String> {
    if let Some(t) = &l.label {
        return Some(t.clone());
    }
    for st in &l.labels {
        if let Stmt::Text(t) = st {
            return Some(t.text.clone());
        }
    }
    None
}

