    let ahead = |p: (f64, f64), d: Dir, q: (f64, f64)| -> bool {
        match d {
            Dir::R => q.0 > p.0 - 1e-9,
            Dir::L => q.0 < p.0 + 1e-9,
            Dir::D => q.1 > p.1 - 1e-9,
            Dir::U => q.1 < p.1 + 1e-9,
        }
    };
