        let Stmt::Node(ns) = st else { continue };
        let tname = ns.type_name.clone().unwrap_or_else(|| "box".to_string());
        let chain = crate::scene::type_chain(sheet, &tname).map(|(_, c)| c).unwrap_or_default();
