        let decls: &[Decl] = ns.style.as_deref().unwrap_or(&[]);
        let own_layout = decls.iter().rev().find(|d| d.name == "layout").and_then(|d| ident_of(&d.value).map(|s| s.to_string()));
        let is_sequence = match own_layout.as_deref() {
