sys.path.insert(0, '/tmp/annot')
from h8 import h8
targets = {'c92119d9': (45, 5), '0d0a0343': (-45, 4)}
def cands(a, p):
    nums_a = [str(a), '%s.0' % a, '%d' % a]
    nums_p = [str(p), '%s.0' % p]
    cols = ['', 'var(--lini-stroke)', '--stroke', 'stroke', 'var(--lini-stroke-dark)', '--lini-stroke', 'currentColor', 'none']
    lws = ['', '0.75', '.75']
    seps = [',', ', ', ' ', ':', '|', ';', '/', '_', '-', 'x']
    pres = ['', 'hatch', 'hatch:', 'hatch-', 'hatch(', 'lini-hatch-', 'pattern', 'h']
    out = set()
    for na, np_, c, lw, sep, pre in itertools.product(nums_a, nums_p, cols, lws, seps, pres):
        parts = [na, np_]
        if c: parts.append(c)
        if lw: parts.append(lw)
        s = sep.join(parts)
        for v in [pre + s, pre + s + ')', pre + sep + s]:
            out.add(v)
        parts2 = [np_, na] + parts[2:]
        out.add(pre + sep.join(parts2))
    return out
for t, (a, p) in targets.items():
    for c in cands(a, p):
        if h8(c) == t:
            print('MATCH', t, repr(c))
# also the full element strings
el = '<pattern id="lini-hatch-%s" patternUnits="userSpaceOnUse" width="5" height="5" patternTransform="rotate(45)"><g style="stroke: var(--lini-stroke)" stroke-width="0.75"><line x1="2.5" y1="0" x2="2.5" y2="5"/></g></pattern>'
