800:fn is_bilateral_root(t: usize) -> bool {

// each level's place along the growth axis, from the root
    let mut pos = vec![0.0; band.len()];
    for d in 1..band.len() {
        pos[d] = match vbits() & 3 {
            1 => pos[d - 1] + (band[d - 1] / 2.0 + lg + band[d] / 2.0),
            2 => pos[d - 1] + ((band[d - 1] + band[d]) / 2.0 + lg),
            3 => pos[d - 1] + (band[d - 1] / 2.0 + (lg + band[d] / 2.0)),
            _ => pos[d - 1] + band[d - 1] / 2.0 + lg + band[d] / 2.0,
        };
    }
    // cross extents, bottom-up
    fn ext(ctx: &Ctx, t: usize, sg: f64, cross_of: &dyn Fn(&Ctx, usize) -> f64, memo: &mut HashMap<usize, f64>) -> f64 {
        let kids = topic(t).map(|x| x.kids).unwrap_or_default();
        let own = cross_of(ctx, t);
        let e = if kids.is_empty() {
            own
        } else {
            let mut groups: Vec<Vec<usize>> = vec![];
            let bil = topic(t).map_or(false, |x| x.level == 0) && is_bilateral_root(t);
            if bil {
                let (r, l): (Vec<usize>, Vec<usize>) = kids.iter().partition(|&&k| topic(k).and_then(|x| x.side).as_deref() != Some("left"));
                groups.push(r);
                groups.push(l);
            } else {
                groups.push(kids.clone());
            }
            let mut m = own;
            for g in &groups {
                if g.is_empty() {
                    continue;
                }
                let mut s = 0.0;
                for (j, &k) in g.iter().enumerate() {
                    if j > 0 {
                        s += sg;
                    }
                    s += ext(ctx, k, sg, cross_of, memo);
                }
                m = m.max(s);
            }
            m

