530	    // a sequence root's gap defaults to the sequence type's
531	    let (gap_row, gap_col) = if s == 0 && !ctx.sheet.root.iter().any(|d| d.name == "gap") { (32.0, 32.0) } else { ctx.comp[s].gap };
532	    let activation = ctx.nodes[s].props.get("activation").and_then(|v| ident_of(v).map(|x| x.to_string())).as_deref() != Some("none");
533	    let sizes: Vec<(f64, f64)> = parts.iter().map(|&p| crate::layout::outer(ctx, p)).collect();
534	    let index: HashMap<usize, usize> = parts.iter().enumerate().map(|(k, &p)| (p, k)).collect();
535	    let evs = events(ctx, s);
536	    // ---- horizontal: a labelled message spreads the gaps it spans until
537	    // its label (plus 8 a side) fits between the two lifelines
538	    let ws: Vec<f64> = sizes.iter().map(|s| s.0).collect();
539	    let mut extra: Vec<f64> = vec![0.0; n.saturating_sub(1)];
540	    for ev in &evs {
541	        if let Ev::Msg(li) = ev {
542	            let l = &ctx.links[*li];
543	            let (Some(&a), Some(&b)) = (index.get(&l.from), index.get(&l.to)) else { continue };
544	            if a == b {
545	                continue;
546	            }
547	            let Some(text) = label_of(l) else { continue };
548	            let need = label_width(ctx, s, &text) + 16.0;
549	            let (i, j) = if a < b { (a, b) } else { (b, a) };
550	            let mut cur = ws[i] / 2.0 + ws[j] / 2.0;
551	            for k in i..j {
552	                cur += gap_col + extra[k];
553	                if k > i {
554	                    cur += ws[k];
555	                }
556	            }
557	            if cur < need {
558	                let add = (need - cur) / (j - i) as f64;
559	                for k in i..j {
560	                    extra[k] += add;
561	                }
562	            }
563	        }
564	    }
565	    let mut px = vec![0.0; n];
566	    let mut cur = 0.0;
567	    for k in 0..n {
568	        cur += ws[k] / 2.0;
569	        px[k] = cur;
570	        cur += ws[k] / 2.0;
571	        if k + 1 < n {
572	            cur += gap_col + extra[k];
573	        }
574	    }
575	    let row = cur;
576	    for x in px.iter_mut() {
577	        *x -= row / 2.0;
578	    }
579	    // ---- notes measure with the contextual rule
580	    let note_nodes: Vec<usize> = evs.iter().filter_map(|e| if let Ev::Note(i) = e { Some(*i) } else { None }).collect();
581	    for &nn in &note_nodes {
582	        note_context(ctx, nn);
583	        crate::layout::measure(ctx, nn, None);
584	    }
585	    // ---- vertical
586	    let header: f64 = sizes.iter().map(|s| s.1).fold(0.0, f64::max);
587	    let mut y = header;
588	    let mut fresh = false;
589	    let mut bars: Vec<Bar> = Vec::new();
590	    let mut stacks: Vec<Vec<usize>> = vec![vec![]; n];
591	    let mut msgs: Vec<Msg> = Vec::new();
592	    let mut frames: Vec<Frame> = Vec::new();
593	    let mut open: Vec<usize> = Vec::new(); // indices into frames
594	    let mut notes: Vec<NoteGeo> = Vec::new();
