600	            Ev::Msg(li) => {
601	                let l = ctx.links[*li].clone();
602	                // only a participant's own lifeline carries a message
603	                let pa = index.get(&l.from).copied();
604	                let pb = index.get(&l.to).copied();
605	                let kind = kind_of(&l.op);
606	                let label = label_of(&l);
607	                let pad_top = open.last().map(|&f| frame_pads(ctx, frames[f].node).0);
