from h8 import h8
t = 'a59b54b5'
base = ['45', '5', 'red']
optional = ['hatch', '0.75', 'lini-hatch', 'pattern', 'fill', '2.5', 'stroke', 'url']
seps = [',', ', ', ' ', ':', '|', ';', '/', '_', '-', '', '\n', '\t', '.', '#', '=', '&', '+', '~']
found = False
for k in range(0, 3):
    for opt in itertools.combinations(optional, k):
        toks = base + list(opt)
        for order in itertools.permutations(toks):
            for sep in seps:
                s = sep.join(order)
                for wrap in ['%s', '(%s)', '[%s]', '{%s}', 'hatch(%s)']:
                    v = wrap % s
                    if h8(v) == t:
                        print('MATCH', repr(v)); found = True
print('found' if found else 'none')

