def stackmodel(nloops, nl, variant):
    h = {2: 45.2, 3: ((3 * 1.2 * 13) + 6 + 6) + 2}[nl]
    # items: (gap_before, height, kind)
    items = [(0.0, 42.0, 'hdr'), (16.0, h, 'note')] + [(32.0, 64.0, 'loop')] * nloops
    tail = 32.0
    main = 0.0
    for g, hh, _ in items:
        main += g
        main += hh
    main += tail
    out = []
    if variant == 0:
        cur = -main / 2
        for g, hh, k in items:
            cur += g
            c = cur + hh / 2
            cur += hh
            if k == 'loop':
                out.append(repr(c - hh / 2 + 0.5))
    elif variant == 1:
        cur = -main / 2
        for g, hh, k in items:
            cur += g
            c = cur + hh / 2
            cur += hh
            if k == 'loop':
                out.append(repr((c - hh / 2) + 0.5))
    elif variant == 2:
        # cursor in local coords from 0, then centres shifted by main/2
        cur = 0.0
        for g, hh, k in items:
            cur += g
            c = cur + hh / 2 - main / 2
            cur += hh
            if k == 'loop':
                out.append(repr(c - hh / 2 + 0.5))
    elif variant == 3:
        cur = 0.0
        for g, hh, k in items:
            cur += g
            c = (cur + hh / 2) - main / 2
            cur += hh
            if k == 'loop':
                out.append(repr(c + (0.5 - hh / 2)))
    return out

