import sys, re, random, math
sys.path.insert(0, '/tmp/tree')
from lt import run, absnodes
from gen import topic

def bez(P, t):
    mt = 1 - t
    return (mt**3*P[0][0] + 3*mt*mt*t*P[1][0] + 3*mt*t*t*P[2][0] + t**3*P[3][0],
            mt**3*P[0][1] + 3*mt*mt*t*P[1][1] + 3*mt*t*t*P[2][1] + t**3*P[3][1])

def rect_dist(p, r):
    x0, y0, x1, y1 = r
    dx = max(x0 - p[0], 0, p[0] - x1)
    dy = max(y0 - p[1], 0, p[1] - y1)
    return math.hypot(dx, dy)

def links(o):
    # (from, to, d)
    return re.findall(r'<g class="lini-link[^"]*" data-from="([^"]*)" data-to="([^"]*)">\s*<path d="([^"]*)"', o)

def analyze(src, verbose=False):
    o, e, c = run(src)
    warns = re.findall(r'clearance \(([^ ]*) -> ([^)]*)\): natural wire passes ([0-9.]+) px from the body at \(([^,]*), ([^)]*)\)–\(([^,]*), ([^)]*)\)', e)
    ns = absnodes(o)
    bodies = []
    for n in ns:
        if 'topic' in n[1] and n[5] is not None:
            w, h = n[5] + 2, n[6] + 2
            bodies.append((n[2], (n[3] - w / 2, n[4] - h / 2, n[3] + w / 2, n[4] + h / 2)))
    res = []
    for f, t, d in links(o):
        v = [float(x) for x in re.findall(r'-?[0-9.]+', d)]
        if len(v) != 12:
            continue
        P = [(v[2], v[3]), (v[4], v[5]), (v[6], v[7]), (v[8], v[9])]
        s = (v[0], v[1]); e_ = (v[10], v[11])
        pts = [bez(P, i / 400) for i in range(401)]
        dists = []
        for name, r in bodies:
            dmin = min(rect_dist(p, r) for p in pts)
            dists.append((round(dmin, 2), r))
        w = [x for x in warns if x[0] == f and x[1] == t]
        res.append((f, t, sorted(dists)[:3], w))
    return res, warns

if __name__ == '__main__':
    rng = random.Random(int(sys.argv[1]))
    for i in range(int(sys.argv[2])):
        src = topic(rng, 0, rng.choice([2, 3]), True, 'mindmap', ' { direction: column; }')
        res, warns = analyze(src)
        if not warns:
            continue
        print('=' * 50)
        print(src[:200])
        for w in warns:
            print('  WARN', w)
        for f, t, ds, w in res:
            close = [d for d in ds if d[0] < 10]
            if close or w:
                print('   wire', f, '->', t, 'closest', ds[:3], 'warned' if w else '')

