obs = {}
for nl in [2, 3]:
    for nloops in range(1, 7):
        src = '{ layout: sequence }\n|box#a|\n|note| "%s" { place: over a }\n' % ('\\n'.join(['x'] * nl)) + '|loop| [ a -> a ]\n' * nloops
        obs[(nl, nloops)] = raw_tabs(src)

def rows_model(nl, n, cv, tv, mv):
    h = {2: 45.2, 3: ((3 * 1.2 * 13) + 6 + 6) + 2}[nl]
    rows = [(42.0, 16.0, 'p'), (h, 32.0, 'n')] + [(64.0, 32.0, 'f')] * n
    # main: heights + gaps between + tail
    if mv == 0:
        main = 0.0
        for hh, g, _ in rows:
            main += hh
            main += g
    elif mv == 1:
        main = 0.0
        for hh, g, _ in rows:
            main += hh + g
    elif mv == 2:
        main = sum(hh for hh, _, _ in rows) + sum(g for _, g, _ in rows)
    cur = -main / 2
    out = []
    for hh, g, k in rows:
        c = cur + hh / 2
        if k == 'f':
            if tv == 0:
                out.append(repr(c - hh / 2 + 0.5))
            elif tv == 1:
                out.append(repr(cur + 0.5))
        if cv == 0:
            cur += hh + g
        else:
            cur += hh
            cur += g
    return out

for cv in range(2):
    for tv in range(2):
        for mv in range(3):
            sc = sum(rows_model(nl, n, cv, tv, mv) == obs[(nl, n)] for nl in [2, 3] for n in range(1, 7))
            print(cv, tv, mv, sc)

