import sys, re, random, math
sys.path.insert(0, '/tmp/tree')
from lt import run, absnodes
from e19 import links

WORDS = ['A', 'Bb', 'Ccc', 'Dddd', 'Eeeee', 'Ffffff', 'Ggggggg', 'Hhhhhhhh', 'Iiiiiiiii', 'Jjjjjjjjjj', 'Kkkkkkkkkkkkkk']
rng = random.Random(int(sys.argv[1]))
found = 0
for i in range(int(sys.argv[2])):
    k = rng.choice([2, 3, 4])
    kids = []
    for _ in range(k):
        g = rng.choice([0, 0, 1, 2, 3, 4])
        if g:
            kids.append('|topic| "%s" [ %s ]' % (rng.choice(WORDS), ' ; '.join('|topic| "%s"' % rng.choice(WORDS) for _ in range(g))))
        else:
            kids.append('|topic| "%s"' % rng.choice(WORDS))
    src = '|mindmap| "%s" { direction: column; } [ %s ]' % (rng.choice(WORDS), ' ; '.join(kids))
    o, e, c = run(src)
    if 'clearance' in e:
        found += 1
        print('=' * 50)
        print(src)
        print(e)
        for n in absnodes(o):
            if n[0] <= 1:
                print('  ' * n[0], n[2], n[3], n[4], n[5], n[6])
        for f, t, d in links(o):
            if f == 'lini-topic-1':
                print('   ', f, t, d)
        if found > 3:
            break
print('found', found)

