// For each candidate B1 (hex per line), check Finv(w1, name1+B1) == Finv(w2, name2+B1) [and optional 3rd/4th pair]
// usage: b1check file name1 w1 name2 w2 [name3 w3 name4 w4]
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#define P 0x100000001b3ULL
static uint64_t Pinv;
static int hexval(char c){ if(c>='0'&&c<='9')return c-'0'; if(c>='a'&&c<='f')return c-'a'+10; if(c>='A'&&c<='F')return c-'A'+10; return -1; }
static uint64_t finv(uint64_t h, const unsigned char *d, int n){ for (int i=n-1;i>=0;i--){ h *= Pinv; h ^= d[i]; } return h; }
int main(int argc, char **argv){
    Pinv = 1; for (int i=0;i<7;i++) Pinv *= 2 - P*Pinv;
    FILE *f = fopen(argv[1], "r");
    int np = (argc-2)/2;
    const char *names[4]; uint64_t ws[4];
    for (int i=0;i<np;i++){ names[i]=argv[2+2*i]; ws[i]=strtoull(argv[3+2*i],0,16); }
    static char line[1<<16]; unsigned char buf[1<<15];
    long cnt=0;
    while (fgets(line, sizeof line, f)){
        int n=0; while (line[n] && line[n]!='\n') n++;
        int bl = 0;
        if (!(n==1 && line[0]=='-')) { bl = n/2; for (int i=0;i<bl;i++) buf[i]=hexval(line[2*i])*16+hexval(line[2*i+1]); }
        cnt++;
        uint64_t u0 = 0; int ok = 1;
        for (int p=0;p<np;p++){
            uint64_t h = finv(ws[p], buf, bl);
            h = finv(h, (const unsigned char*)names[p], strlen(names[p]));
            if (p==0) u0 = h; else if (h != u0) { ok = 0; break; }
        }
        if (ok){ printf("MATCH B1=\""); for (int i=0;i<bl;i++) putchar(buf[i]); printf("\" u=%016llx\n", (unsigned long long)u0); fflush(stdout); }
    }
    fprintf(stderr, "checked %ld\n", cnt);
    return 0;
}

