new='''// out of a port along its facing, past every own obstacle it is in
pub fn landing(obs: &[Rect], owner: &[usize], port: &Port) -> (f64, f64) {
    let mut p = port.p;
    let me = match port.own {
        Some(k) => owner[k],
        None => return p,
    };
    // walk out until no own obstacle holds the point (open) or lies ahead on the line
    loop {
        let mut moved = false;
        for (k, r) in obs.iter().enumerate() {
            if owner[k] != me {
                continue;
            }
            let inside = match port.d {
                Dir::R | Dir::L => p.1 > r.y0 + EPS && p.1 < r.y1 - EPS && p.0 > r.x0 - EPS && p.0 < r.x1 - EPS,
                Dir::U | Dir::D => p.0 > r.x0 + EPS && p.0 < r.x1 - EPS && p.1 > r.y0 - EPS && p.1 < r.y1 - EPS,
            };
            if !inside {
                continue;
            }
            let q = match port.d {
                Dir::R => (r.x1, p.1),
                Dir::L => (r.x0, p.1),
                Dir::D => (p.0, r.y1),
                Dir::U => (p.0, r.y0),
            };
            if (q.0 - p.0).abs() > EPS || (q.1 - p.1).abs() > EPS {
                p = q;
                moved = true;
            }
        }
        if !moved {
            break;
        }
    }
    p
}'''
