root='/workspace/.claude/worktrees/agent-a3eceff6d2e2640b7/src/schematic/'
p=root+'router.rs'
s=open(p).read()
start=s.index('pub fn centre(obs: &[Rect], pts: &mut Vec<(f64, f64)>, la: (f64, f64), lb: (f64, f64)) {')
new='''pub fn centre(obs: &[Rect], pts: &mut Vec<(f64, f64)>, la: (f64, f64), lb: (f64, f64), lattice: (f64, f64)) {
    let n = pts.len();
    if n < 4 {
        return;
    }
    // the middle snaps to a lattice line, halves toward the lower one
    let snap = |m: f64, o: f64| -> f64 { (((m - o) / 20.0) - 0.5 + 1e-9).ceil() * 20.0 + o };
    for k in 1..n - 2 {
        // segment k..k+1 between segments k-1..k and k+1..k+2
        let (a, b, c, d) = (pts[k - 1], pts[k], pts[k + 1], pts[k + 2]);
        let vert = (b.0 - c.0).abs() < EPS;
        let (before, after) = if vert { (b.0 - a.0, d.0 - c.0) } else { (b.1 - a.1, d.1 - c.1) };
        let step = before * after > 0.0;
        let (s0, s1) = if vert { (b.1.min(c.1), b.1.max(c.1)) } else { (b.0.min(c.0), b.0.max(c.0)) };
        let pos = if vert { b.0 } else { b.1 };
        // the free channel across the segment
        let mut clo = f64::NEG_INFINITY;
        let mut chi = f64::INFINITY;
        for r in obs {
            let (a0, a1, b0, b1) = if vert { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
            if a0 < s1 - EPS && a1 > s0 + EPS {
                if b1 <= pos + EPS && b1 > clo {
                    clo = b1;
                }
                if b0 >= pos - EPS && b0 < chi {
                    chi = b0;
                }
            }
        }
        if step {
            // the slide range: within both neighbours' spans
            let (mut lo, mut hi) = if vert { (a.0.min(d.0), a.0.max(d.0)) } else { (a.1.min(d.1), a.1.max(d.1)) };
            // the port runs keep their landings
            if k == 1 {
                let l = if vert { la.0 } else { la.1 };
                if before > 0.0 {
                    lo = lo.max(l);
                } else {
                    hi = hi.min(l);
                }
            }
            if k + 2 == n - 1 {
                let l = if vert { lb.0 } else { lb.1 };
                if after > 0.0 {
                    hi = hi.min(l);
                } else {
                    lo = lo.max(l);
                }
            }
            clo = clo.max(lo);
            chi = chi.min(hi);
        } else {
            // a detour: centred between what it goes around and what lies
            // beyond, when something does
            if !clo.is_finite() || !chi.is_finite() {
                continue;
            }
            // the neighbours run away from the side the U opens to
            let open_low = before < 0.0;
