import math, itertools
def fnv(s):
    h = 0xcbf29ce484222325
    for b in s.encode():
        h ^= b
        h = (h * 0x100000001b3) & 0xFFFFFFFFFFFFFFFF
    return '%08x' % (((h >> 32) ^ h) & 0xFFFFFFFF)
def rs(x):
    # Rust {:?} for f64
    r = repr(x)
    if r.endswith('.0') or 'e' in r or 'inf' in r or 'nan' in r:
        return r
    if '.' not in r:
        return r + '.0'
    return r
def key(x0, y0, w, h, cuts):
    cs = ', '.join('(%s, %s, %s, %s)' % tuple(rs(v) for v in c) for c in cuts)
    return '%s %s %s %s [%s]' % (rs(x0), rs(y0), rs(w), rs(h), cs)
def nx(x, k):
    for _ in range(abs(k)):
        x = math.nextafter(x, math.inf if k > 0 else -math.inf)
