import itertools


def mains(ws, g):
    n = len(ws)
    out = {}
    m = 0.0
    for w in ws:
        m += w
    out['M1'] = m + g * (n - 1) if n > 1 else m
    m = 0.0
    for w in ws:
        m += w + g
    out['M2'] = m - g
    m = 0.0
    for i, w in enumerate(ws):
        m += w
        if i + 1 < n:
            m += g
    out['M3'] = m
    m = 0.0
    for i, w in enumerate(ws):
        if i > 0:
            m += g
        m += w
    out['M4'] = m
    m = 0.0
    for i, w in enumerate(ws):
        m = m + (w if i == 0 else g + w)
    out['M5'] = m
    return out


def starts(main):
    return {'S1': -main / 2, 'S2': main * -0.5, 'S3': -(main / 2)}


def centres(ws, g, s):
    n = len(ws)
    out = {}
    cur = s; r = []
    for w in ws:
        r.append(cur + w / 2); cur += w + g
    out['C1'] = r
    cur = s; r = []
    for w in ws:
        r.append(cur + w / 2); cur = cur + w + g
    out['C2'] = r
    c = s + ws[0] / 2; r = [c]
    for i in range(1, n):
        c = c + ((ws[i - 1] + ws[i]) / 2 + g); r.append(c)
    out['C3'] = r
    c = s + ws[0] / 2; r = [c]
    for i in range(1, n):
        c = c + ws[i - 1] / 2 + g + ws[i] / 2; r.append(c)
    out['C4'] = r
    c = s + ws[0] / 2; r = [c]
    for i in range(1, n):
        c = c + (ws[i - 1] / 2 + g + ws[i] / 2); r.append(c)
    out['C5'] = r
    cur = s; r = []
    for w in ws:
        r.append(cur + w / 2); cur = cur + (w + g)
    out['C6'] = r
    acc = 0.0; r = []
    for w in ws:
        r.append(s + (acc + w / 2)); acc += w + g
    out['C7'] = r
    acc = 0.0; r = []
    for w in ws:
        r.append((s + acc) + w / 2); acc += w + g
    out['C8'] = r
    acc = 0.0; r = []
    for w in ws:
        r.append(s + (acc + w / 2)); acc = acc + w + g
    out['C9'] = r
    acc = 0.0; r = []
    for w in ws:
        r.append((s + acc) + w / 2); acc = acc + w + g
    out['C10'] = r
    # left edges
    cur = s; r = []
    for w in ws:
        x0 = cur; x1 = x0 + w; r.append((x0 + x1) / 2); cur = x1 + g
    out['C11'] = r
    cur = s; r = []
    for w in ws:
        r.append(cur + w * 0.5); cur += w + g
    out['C12'] = r
    return out


def all_candidates(ws, g):
    res = {}
    for mn, m in mains(ws, g).items():
        for sn, s in starts(m).items():
            for cn, cs in centres(ws, g, s).items():
                res['%s/%s/%s' % (mn, sn, cn)] = cs
    return res

