"""Focused search: Debug-formatted angle lists, f4 pitch, colour strings."""
import itertools
import sys
sys.path.insert(0, "/tmp/hatch_search")
from h import hash8

TARGET = "c92119d9"  # (45, 5, default)
TARGET_RED = "a59b54b5"  # (45, 5, red)

