                            for pre in PREFIXES:
                                for suf in SUFFIXES:
                                    n += 1
                                    if hash8(pre + body + suf) == TARGET:
                                        print("MATCH", repr(pre + body + suf), flush=True)
    print("tested", n)


if __name__ == "__main__":
    main()

