"""Unwind hypotheses: pitch last or angles last, with various tails."""
import struct
import sys
sys.path.insert(0, "/tmp/hatch_search")
from drive import line_for, run

PITCH = {"f4": [("5", "c92119d9"), ("6", "fecd99e1"), ("5.5", "66e90a76")],
         "dbg": [("5.0", "c92119d9"), ("6.0", "fecd99e1"), ("5.5", "66e90a76")]}
ANG = {"disp": [("45", "c92119d9"), ("30", "0e62e4e4"), ("0", "6e072d51")],
       "dbg": [("45.0", "c92119d9"), ("30.0", "0e62e4e4"), ("0.0", "6e072d51")]}
ANGB = {
    "bitsLE": [(struct.pack("<d", 45.0), "c92119d9"), (struct.pack("<d", 30.0), "0e62e4e4"), (struct.pack("<d", 0.0), "6e072d51")],
    "bitsBE": [(struct.pack(">d", 45.0), "c92119d9"), (struct.pack(">d", 30.0), "0e62e4e4"), (struct.pack(">d", 0.0), "6e072d51")],
}

YS = ["", ")", "\"", "]", "\xff", ";", "\n", "|", ",", " ", "}", " }", "px", "deg", "deg)", ")\"", "\x00", "°"]

if __name__ == "__main__":
    mode = sys.argv[1]
    lines = []
    if mode == "pitch":
        for rn, data in PITCH.items():
            for y in YS:
                yb = y.encode("utf-8") if y != "\xff" else b"\xff"
                lines.append(line_for("pitch:%s Y=%r" % (rn, y), [(v.encode() + yb, t) for v, t in data]))
    elif mode == "angle":
        for rn, data in ANG.items():
            for y in YS:
                yb = y.encode("utf-8") if y != "\xff" else b"\xff"
                lines.append(line_for("angle:%s Y=%r" % (rn, y), [(v.encode() + yb, t) for v, t in data]))
        for rn, data in ANGB.items():
            for y in ["", "\xff"]:
                yb = y.encode("utf-8") if y != "\xff" else b"\xff"
                lines.append(line_for("angle:%s Y=%r" % (rn, y), [(v + yb, t) for v, t in data]))
    out, err = run(lines)
    print(out)
    print(err)

