if pos.is_none() {
    let gap = outward * (DIM_GAP + if between { DIM_TEXT } else { 0.0 });
    let overlaps = |core: &BBox| {
        let (plo, phi) = if vertical { (core.y0, core.y1) } else { (core.x0, core.x1) };
        phi > olo + 1e-9 && plo < ohi - 1e-9
    };
