// the line: a chain's links share their first link's line. Any
// other dimension takes the first row of its side it fits in (no
// overlap with that row's runs) — a new row clears the plan and the
// rows it would cross — then steps past any other side's dimension
// whose line, arrows or text stand across its run.
let stmt = l.stmt_index;
let mut pos: Option<f64> = None;
if let Some((s0, sd, p0)) = last_stmt {
    if s0 == stmt && sd == side {
        pos = Some(p0);
    }
}
let mut row_of = None;
if pos.is_none() {
    let gap = outward * (DIM_GAP + if between { DIM_TEXT } else { 0.0 });
    let further = |a: f64, b: f64| if outward > 0.0 { a.max(b) } else { a.min(b) };
    let rows = tiers.entry(side).or_default();
    let mut base = None;
    for (k, (b, runs)) in rows.iter().enumerate() {
        if runs.iter().all(|(a, z, _)| ohi <= *a + 1e-9 || olo >= *z - 1e-9) {
            base = Some(*b);
            row_of = Some(k);
            break;
        }
    }
    let base = match base {
        Some(b) => b,
        None => {
            let mut e = edge(&bb);
            for (_, runs) in rows.iter() {
                for (a, z, whole) in runs {
                    if ohi > *a + 1e-9 && olo < *z - 1e-9 {
                        e = further(e, edge(whole));
                    }
                }
            }
            rows.push((e + gap, vec![]));
            row_of = Some(rows.len() - 1);
            e + gap
        }
    };
    let mut e = base - gap;
    for (pside, core, whole) in &placed {
        if *pside == side {
            continue;
        }
        let (plo, phi) = if vertical { (core.y0, core.y1) } else { (core.x0, core.x1) };
        if phi > olo + 1e-9 && plo < ohi - 1e-9 {
            e = further(e, edge(whole));
        }
    }
    pos = Some(e + gap);
}
let p = pos.unwrap();
last_stmt = Some((stmt, side, p));

