#!/usr/bin/env python3
# Normalized diff (scope hash removed; root var list split) of original vs ours.
import subprocess, sys, os, re, difflib
mine = '/tmp/bin-seq/executable'
for f in sys.argv[1:]:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    outs = []
    for binp in ['/workspace/executable', mine]:
        r = subprocess.run([binp, b], capture_output=True, cwd=d, text=True)
        s = re.sub(r'lini-scope-[0-9a-f]+', 'SCOPE', r.stdout)
        lines = []
        for l in s.split('\n'):
            if ':root, .SCOPE' in l:
                lines.extend(['  VAR ' + v.strip() for v in l.split(';')])
            else:
                lines.append(l)
        outs.append(lines)
    print('=====', f)
    for l in list(difflib.unified_diff(outs[0], outs[1], 'orig', 'mine', n=0, lineterm=''))[:30]:
        print(l[:250])

