import sys, re, os
sys.path.insert(0, '/tmp/sch/scripts')
from summ import run

HEAD = '''{ layout: schematic; |vsys::label| { symbol: power; } [ "VSYS" ]  |vm::label| { symbol: power; } [ "VM" ] }
|component#U6| "TPS61023DRLR" [
  |pin#VIN| { side: left; number: 3; }
  |space|
  |pin#SW| { side: left; number: 5; }
  |space| { span: 2; }
  |pin#EN| { side: left; number: 4; }
  |pin#GND| { side: bottom; number: 1; }
  |pin#VOUT| { side: right; number: 6; }
  |space| { span: 5; }
  |pin#FB| { side: right; number: 2; }
]
|C#C11| "10u"
|L#L2| "1uH"
|R#R15| "240k"
|R#R16| "30k"
|C#C12| "10u"
|C#C13| "10u"
|C#C14| "10u"
'''
STEPS = [
    'U6.VIN - |vsys|',
    'U6.VIN - C11 - |gnd|',
    'U6.SW - L2 - U6.VIN',
    'U6.EN - "EN_BSTD"',
    'U6.GND - |gnd|',
    'U6.VOUT - |vm|',
    'U6.VOUT - C12 - |gnd|',
    'U6.VOUT - C13 - |gnd|',
    'U6.VOUT - C14 - |gnd|',
    'U6.VOUT - R15 - R16.p1 - |gnd|',
    'U6.FB - R16.p1',
]
which = [int(x) for x in sys.argv[1].split(',')]
src = HEAD + '\n'.join(STEPS[k] for k in which) + '\n'
for exe in ['/workspace/executable', '/tmp/bin-sch/executable'] if os.environ.get('BOTH') else ['/workspace/executable']:
    o, e, c = run(src, exe=exe)
    pos = {}
    for i, x, y in re.findall(r'\n    <g class="lini-node [^"]*" data-id="([^"]+)" transform="translate\(([-\d.]+),([-\d.]+)\)', o):
