#!/usr/bin/env python3
import subprocess, sys, os, re, difflib
mine = '/tmp/bin-seq/executable'
for f in sys.argv[1:]:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    outs = []
    for binp in ['/workspace/executable', mine]:
        r = subprocess.run([binp, b], capture_output=True, cwd=d, text=True)
        s = re.sub(r'lini-scope-[0-9a-f]+', 'SCOPE', r.stdout + '\n#ERR ' + r.stderr)
        lines = []
        for l in s.split('\n'):
            if ':root, .SCOPE' in l:
                lines.extend(['  VAR ' + v.strip() for v in l.split(';')])
            else:
                lines.append(l)
        outs.append(lines)
    diff = [l for l in difflib.unified_diff(outs[0], outs[1], 'o', 'm', n=0, lineterm='') if l[:1] in '+-' and not l.startswith(('+++', '---'))]
    if diff:
        print(os.path.basename(f), '|', diff[0][:160])

