// Rotate a point by `deg` degrees (screen, clockwise positive).
fn rot(p: P, deg: f64) -> P {
    let (s, c) = deg.to_radians().sin_cos();
    pt(p.x * c - p.y * s, p.x * s + p.y * c)
}

