root='/workspace/.claude/worktrees/agent-a3eceff6d2e2640b7/src/schematic/'
p=root+'wire.rs'
s=open(p).read()
old_start=s.index('''fn place_label(pts: &[(f64, f64)], along: f64, text: String) -> (String, f64, f64, f64) {''')
old_end=s.index('''// points where three ways of one net meet''')
new='''fn place_label(ctx: &Ctx, pts: &[(f64, f64)], along: f64, text: String) -> (String, f64, f64, f64) {
    let mut total = 0.0;
    for k in 1..pts.len() {
        total += (pts[k].0 - pts[k - 1].0).abs() + (pts[k].1 - pts[k - 1].1).abs();
    }
    let tw = {
        let w = if ctx.comp[0].layout == "schematic" { ctx.comp[0].font_weight } else { 400 };
        crate::font::text_width(crate::font::Family::Sans, w, 11.0, &text)
    };
    let mut s = total * along;
    for k in 1..pts.len() {
        let (p, q) = (pts[k - 1], pts[k]);
        let len = (q.0 - p.0).abs() + (q.1 - p.1).abs();
        if s <= len + 1e-9 || k == pts.len() - 1 {
            let f = if len > 0.0 { s / len } else { 0.0 };
            let x = p.0 + (q.0 - p.0) * f;
            let y = p.1 + (q.1 - p.1) * f;
            if same(p.1, q.1) {
                return (text, x, y - 9.5, 0.0);
            }
            // upright: to the right of the trace, unless that crowds the
            // wire's own other runs
            let crowded = |lx: f64| -> bool {
                let b = [lx - 5.5 - CLEAR, y - tw / 2.0 - CLEAR, lx + 5.5 + CLEAR, y + tw / 2.0 + CLEAR];
                (1..pts.len()).any(|j| {
                    if j == k {
                        return false;
                    }
                    let (a, c) = (pts[j - 1], pts[j]);
                    let (x0, x1) = (a.0.min(c.0), a.0.max(c.0));
                    let (y0, y1) = (a.1.min(c.1), a.1.max(c.1));
                    x0 < b[2] && x1 > b[0] && y0 < b[3] && y1 > b[1]
                })
            };
            if !crowded(x + 9.5) {
                return (text, x + 9.5, y, 270.0);
            }
            return (text, x - 9.5, y, 270.0);
        }
        s -= len;
    }
    (text, pts[0].0, pts[0].1 - 9.5, 0.0)
}

