#!/usr/bin/env python3
"""Compile each fill value in its own document (avoids in-document dedup) and print the def."""
import re
import subprocess
import sys

EXE = "/workspace/executable"


def one(fill, layout_drawing=False):
    src = ("{ layout: drawing; }\n" if layout_drawing else "") + "|box#b0| { fill: %s; }\n" % fill
    path = "/tmp/hatch_search/gsep.lini"
    open(path, "w").write(src)
    p = subprocess.run([EXE, path], capture_output=True, text=True)
    defs = re.findall(r'(<(linearGradient|radialGradient|pattern) id="([^"]+)".*?</\2>)', p.stdout)
    m = re.search(r'data-id="b0" style="fill: url\(#([^)]+)\)', p.stdout)
    bydef = {d[2]: d[0] for d in defs}
    if m:
        return m.group(1), bydef.get(m.group(1), ""), p.stderr.strip()
    return None, "", p.stderr.strip()


if __name__ == "__main__":
    for f in sys.argv[1:]:
        i, d, e = one(f)
        print("%-50s %s   %s %s" % (f, i, d[:260], ("STDERR: " + e[:200]) if e else ""))

