479	fn emit_branches(b: &mut Builder, i: usize) {
480	    let Some(t) = topic(i) else { return };
481	    if t.kids.is_empty() {
482	        return;
483	    }
484	    let dir = ST.with(|s| s.borrow().boxes[t.tree].dir.clone());
485	    let kid_info: Vec<(usize, Option<String>, Option<String>)> = t
486	        .kids
487	        .iter()
488	        .map(|&k| {
489	            let kt = topic(k).unwrap();
490	            (k, kt.side, kt.hue)
491	        })
492	        .collect();
493	    // statements: (from side, to side, members, hue class)
494	    let mut stmts: Vec<(&str, &str, Vec<usize>, Option<String>)> = Vec::new();
495	    let all: Vec<usize> = t.kids.clone();
496	    if t.mindmap && dir != "bilateral" {
497	        let (f, to) = if dir == "row" { ("right", "left") } else { ("bottom", "top") };
498	        if t.level == 0 {
499	            for (k, _, h) in &kid_info {
500	                stmts.push((f, to, vec![*k], h.clone()));
501	            }
502	        } else {
503	            stmts.push((f, to, all, t.hue.clone()));
504	        }
505	    } else {
506	        match dir.as_str() {
507	            "column" => stmts.push(("bottom", "top", all, None)),
508	            "row" => stmts.push(("right", "left", all, None)),
509	            _ => {
510	                if t.level == 0 {
511	                    if t.mindmap {
512	                        for (k, sd, h) in &kid_info {
513	                            if sd.as_deref() == Some("left") {
514	                                stmts.push(("left", "right", vec![*k], h.clone()));
515	                            } else {
516	                                stmts.push(("right", "left", vec![*k], h.clone()));
517	                            }
518	                        }
519	                    } else {
520	                        let right: Vec<usize> = kid_info.iter().filter(|x| x.1.as_deref() != Some("left")).map(|x| x.0).collect();
521	                        let left: Vec<usize> = kid_info.iter().filter(|x| x.1.as_deref() == Some("left")).map(|x| x.0).collect();
522	                        if !right.is_empty() {
523	                            stmts.push(("right", "left", right, None));
524	                        }
525	                        if !left.is_empty() {
526	                            stmts.push(("left", "right", left, None));
527	                        }
528	                    }
529	                } else if t.side.as_deref() == Some("left") {
530	                    stmts.push(("left", "right", all, if t.mindmap { t.hue.clone() } else { None }));
531	                } else {
532	                    stmts.push(("right", "left", all, if t.mindmap { t.hue.clone() } else { None }));
533	                }
534	            }
535	        }
536	    }
537	    let container = b.nodes[i].parent.unwrap_or(0);
538	    // the scene's own wires close the document; the rest follow their topic
539	    let span = if container == 0 { crate::diag::Span::new(b.src.len(), b.src.len()) } else { b.nodes[i].span };
540	    for (f, to, members, hue) in stmts {
541	        let idx = b.stmt_counter;
542	        b.stmt_counter += 1;
543	        for m in members {
544	            let li = b.links.len();
545	            b.links.push(Link {
546	                from: i,
547	                to: m,
548	                op: "-".to_string(),
549	                label: None,
550	                labels: vec![],
551	                classes: vec![],
552	                style: vec![],
553	                from_anchor: Some(f.to_string()),
554	                to_anchor: Some(to.to_string()),
555	                from_index: None,
556	                to_index: None,
557	                span,
558	                stmt_index: idx,
559	                container,
