// Serialise an expression argument of a colour function.
fn expr_text(e: &Expr) -> String {
    match e {
        Expr::Num(v, _) => f4(*v),
        Expr::Percent(v, _) => format!("{}%", f4(*v)),
        Expr::Ident(n, _) => n.clone(),
        Expr::Unary(op, a, _) => format!("{}{}", op, expr_text(a)),
        Expr::Var(v, _) => format!("var(--lini-{})", v),
        Expr::Hash(h, _) => format!("#{}", h),
        Expr::Tuple(items, _) => items.iter().map(expr_text).collect::<Vec<_>>().join(" "),
        _ => String::new(),
    }
}

// `oklch(L, C, H[, A])` → #rrggbb[aa].
pub fn oklch_call_hex(args: &[Expr], span: Span) -> Result<String, Diag> {
    let nums: Vec<f64> = args
        .iter()
        .map(|a| match a {
            Expr::Num(v, _) => *v,
            Expr::Unary(o, b, _) if o == "-" => match &**b {
                Expr::Num(v, _) => -*v,
                _ => f64::NAN,
            },
            _ => f64::NAN,
        })
        .collect();
    let bad = (nums.len() != 3 && nums.len() != 4)
        || nums.iter().any(|x| x.is_nan())
        || !(0.0..=1.0).contains(&nums[0])
        || nums[1] < 0.0
        || nums.get(3).map(|a| !(0.0..=1.0).contains(a)).unwrap_or(false);
    if bad {
        return Err(Diag::error(
            "resolve",
            "oklch expects (L, C, H) or (L, C, H, A) — L and A in 0..1, C ≥ 0, H in degrees",
            span,
        ));
    }
    Ok(crate::color::oklch_hex(nums[0], nums[1], nums[2], nums.get(3).copied()))
}

