#!/usr/bin/env python3
"""Meet-in-the-middle: find X with fnv1a64(X) == STATE_X, where key = X + 'red")'."""
import itertools
import sys
sys.path.insert(0, "/tmp/hatch_search")
from h import fnv1a64

M = 0xFFFFFFFFFFFFFFFF
P = 0x100000001b3
PINV = pow(P, -1, 1 << 64)
STATE_X = 0x78fc044694b29259  # state after X for hatch(45, 5, red)


def unwind(h, s: bytes):
    for b in reversed(s):
        h = ((h * PINV) & M) ^ b
    return h


def fwd(h, s: bytes):
    for b in s:
        h = ((h ^ b) * P) & M
    return h


# backward tails: X ends with these
VARIANTS = ["Ident", "Name", "Named", "Keyword", "Kw", "Word", "Color", "Colour", "Raw", "Css", "Lit", "Literal", "Str",
            "String", "Id", "Identifier", "Plain", "Bare", "Text", "Symbol", "Sym", "Atom", "Token", "Value", "Val", "Enum",
            "Key", "Unquoted", "BareWord", "Bareword", "Term", "Some", "Ok", "CssColor", "NamedColor", "Named Color", "Paint",
            "Fill", "Stroke", "Solid", "Literal", "Keyword", "Builtin", "Other", "Custom", "Unknown", "Word", "Atom", "Css",
            "CssValue", "Var", "Hash", "Hex", "Call", "Func", "Function", "Number", "Num", "List", "Ref", "Name"]
tails = set()
for v in VARIANTS:
    tails.add(v + '("')
    for w in ["Color::", "Colour::", "Term::", "Value::", "Expr::", "Paint::", "Css::", "Token::", "Tok::", "Val::"]:
        tails.add(w + v + '("')
for sep in [", ", ",", "|", " ", ";", "; ", ":", ": ", "/", "_", "-", "\n", "\t", "\x00", ""]:
    tails.add(sep + '"')
    for v in VARIANTS:
        tails.add(sep + v + '("')
tails = sorted(tails)
print("tails", len(tails))
B = {}
for t in tails:
    B.setdefault(unwind(STATE_X, t.encode()), []).append(t)


def disp(x):
    if x == int(x) and abs(x) < 1e16:
        return "%d" % int(x)
    return repr(x)


def dbg(x):
    if x == int(x) and abs(x) < 1e16:
        return "%d.0" % int(x)
    return repr(x)


A = ["[45.0]", "45.0", "45", "[45]", "[45.0deg]", "45deg", "(45.0,)", "[Num(45.0)]", "[45.0, ]", "Some([45.0])", "[0.7853981633974483]", "0.7853981633974483", "angles: [45.0]", "angle: 45.0", "angles=[45.0]", "angle=45"]
PITCH = ["5", "5.0", "5px", "Some(5.0)", "\"5\"", "5.0000", "pitch: 5.0", "pitch: \"5\"", "pitch=5", "5 5", "5,5", "5x5", "5.0 5.0", "[5.0]"]
SEP = [", ", ",", "|", " ", ";", "; ", ":", ": ", "/", "_", "-", "\n", "\t", "\x00", "", " | ", " / ", "#", "@", "&", "~", "+", ".", "*", "x", " ; "]
PRE = ["", "hatch", "hatch:", "hatch(", "hatch-", "hatch|", "hatch,", "hatch ", "lini-hatch-", "hatch/", "hatch_", "pattern", "pattern:", "hatch;", "hatch@", "hatch#", "hatch\n", "Hatch", "Hatch ", "Hatch(", "HATCH", "h", "h:", "hatch=", "(", "[", "{", "Hatch { ", "hatch{", "hatch[", "hatch((", "(("]

found = 0
n = 0
for pre in PRE:
    h0 = fwd(0xcbf29ce484222325, pre.encode())
    for order in ["AP", "PA"]:
        first, second = (A, PITCH) if order == "AP" else (PITCH, A)
        for x1 in first:
            h1 = fwd(h0, x1.encode())
            for s1 in SEP:
                h2 = fwd(h1, s1.encode())
                for x2 in second:
                    h3 = fwd(h2, x2.encode())
                    n += 1
                    if h3 in B:
                        print("MATCH", repr(pre + x1 + s1 + x2), B[h3], flush=True)
                        found += 1
                    # allow an extra separator before the tail
                    for s2 in SEP:
                        h4 = fwd(h3, s2.encode())
                        n += 1
                        if h4 in B:
                            print("MATCH", repr(pre + x1 + s1 + x2 + s2), B[h4], flush=True)
                            found += 1
print("tested", n, "found", found)

