pub fn family_of(v: &Value) -> crate::font::Family {
    // only a single name classifies; a run of words reads as the default face
    match single_term(v) {
        Some(Term::Str(x, _)) | Some(Term::Ident(x, _)) => family_of_name(x),
        _ => crate::font::Family::Sans,
    }
}

