import re, os, subprocess, glob, collections, sys
res = collections.defaultdict(list)
files = sys.argv[1:]
for f in files:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    o = subprocess.run(['/workspace/executable', b], capture_output=True, cwd=d, text=True).stdout
    vmap = {i: (float(x), float(y)) for i, x, y in re.findall(r'class="lini-node lini-vcc[^"]*" data-id="([^"]+)" transform="translate\(([-\d.]+),([-\d.]+)\)', o)}
    # scope origin of nested schematic
    for m in re.finditer(r'data-from="([^"]+)" data-to="([^"]+)">\n\s*<path d="([^"]+)"', o):
        fr, to, dd = m.groups()
        if to not in vmap: continue
        nums = [float(v) for v in re.findall(r'-?[\d.]+', dd)]
        pts = list(zip(nums[0::2], nums[1::2]))
