            res['Z'].append((pts[0][0], vmap[to][0], b))
        else:
            res['other-%d' % len(pts)].append((pts[-1][0], vmap[to][0], b))
for k in sorted(res):
    print(k, sorted(set((x, cx) for x, cx, b in res[k])))

