1534	// A face of a wall run in the frame's datum: (a, b) of the offset line.
1535	fn face_of(ctx: &Ctx, wall: usize, anchor: &str) -> Result<Option<(P, P)>, String> {
1536	    let base = match ctx.sk.base.get(&wall) {
1537	        Some(b) => b,
1538	        None => return Ok(None),
1539	    };
1540	    let (name, face) = if let Some(n) = anchor.strip_suffix("-in") {
1541	        (n, 1)
1542	    } else if let Some(n) = anchor.strip_suffix("-out") {
1543	        (n, -1)
1544	    } else {
1545	        (anchor, 0)
1546	    };
1547	    let mut hit: Option<(usize, usize)> = None;
1548	    for (si, s) in base.subs.iter().enumerate() {
1549	        for (gi, t) in s.tags.iter().enumerate() {
1550	            if t.as_deref() == Some(name) {
1551	                hit = Some((si, gi));
1552	            }
1553	        }
1554	    }
1555	    let (si, gi) = match hit {
1556	        Some(x) => x,
1557	        None => return Err(name.to_string()),
1558	    };
1559	    let k = crate::drawing::ps(ctx, wall);
1560	    let s = &base.subs[si];
1561	    let g = &s.segs[gi];
1562	    let (a, b) = (g.start().mul(k), g.end().mul(k));
1563	    let tr = ctx.comp[wall].translate;
1564	    let off = pt(tr.0, tr.1);
1565	    if face == 0 {
1566	        return Ok(Some((a.add(off), b.add(off))));
1567	    }
1568	    let h = wall_thickness(ctx, wall) * k / 2.0;
1569	    // `-in`: the loop's interior for a closed run, else the pen's left
1570	    let mut in_left = true;
1571	    if s.closed {
1572	        let mut area = 0.0;
1573	        let mut q = s.start;
1574	        for g in &s.segs {
1575	            let e = g.end();
1576	            area += q.x * e.y - e.x * q.y;
1577	            q = e;
1578	        }
1579	        area += q.x * s.start.y - s.start.x * q.y;
1580	        in_left = area < 0.0;
1581	    }
1582	    let left = if face > 0 { in_left } else { !in_left };
1583	    let n = b.sub(a).unit().left().mul(if left { h } else { -h });
1584	    Ok(Some((a.add(n).add(off), b.add(n).add(off))))
1585	}
