1798	        // the plan's own loose text (room names) never pushes a dimension out
1799	        if ctx.comp[ch].pin.is_some() || ctx.sk.fp.parts.contains_key(&ch) || ctx.nodes[ch].prim == Prim::Text {
1800	            continue;
1801	        }
1802	        crate::drawing::deep_bbox(ctx, ch, &ident, &mut bb);
1803	    }
1804	    if bb.is_empty() {
1805	        bb.add(0.0, 0.0);
