1808	    // the boxes of the dimensions placed so far
1809	    // per placed dimension: its core (line, arrows, text) and whole box
1810	    let mut placed: Vec<(&'static str, BBox, BBox)> = Vec::new();
1811	    let mut tiers: HashMap<&'static str, Vec<(f64, Vec<(f64, f64, BBox)>)>> = HashMap::new();
1812	    let mut last_stmt: Option<(usize, &'static str, f64)> = None;
1813	    let mut last_row: Option<usize> = None;
1814	    let ppu = crate::drawing::ps(ctx, frame);
1815	    let obstacles = collect_obstacles(ctx, frame);
1816	    let mut next_mask = 0usize;
1817	    for d in mine {
1818	        let li = ctx.sk.fp.dims[d].link;
1819	        let l = &ctx.links[li];
1820	        let anch = |n: usize, a: Option<&str>| -> Option<Anch> {
1821	            if ctx.nodes[n].is("wall") {
