1824	                node_anchor(ctx, frame, n, a)
1825	            }
1826	        };
1827	        let fa = anch(l.from, l.from_anchor.as_deref());
1828	        let fb = anch(l.to, l.to_anchor.as_deref());
1829	        let (fa, fb) = match (fa, fb) {
1830	            (Some(a), Some(b)) => (a, b),
1831	            _ => continue,
1832	        };
1833	        let da = match (fa.dir(), fb.dir()) {
1834	            (Some(x), _) => x,
1835	            (None, Some(y)) => y,
1836	            (None, None) => continue,
1837	        };
1838	        let vertical = da.x.abs() > da.y.abs();
1839	        let side_s = l.style.iter().rev().find(|d| d.name == "side").and_then(|d| ident_of(&d.value)).map(|s| s.to_string());
1840	        let side: &'static str = match (vertical, side_s.as_deref()) {
1841	            (true, Some("left")) => "left",
1842	            (true, _) => "right",
1843	            (false, Some("top")) => "top",
1844	            (false, _) => "bottom",
1845	        };
1846	        // the measured coordinates, and where each witness line springs: a
1847	        // face's end nearest the side, a side's midpoint, a point
1848	        let coord = |f: Anch| match f {
1849	            Anch::Face(a, b) | Anch::Edge(a, b) => {
1850	                let m = pt((a.x + b.x) / 2.0, (a.y + b.y) / 2.0);
