import sys, re
sys.path.insert(0, '/tmp/fp')
from probe import run, scene

# dim line from tip (60.8,105.6) along (0.8,0.6), 200 long
def mk(x):
    return '''{ layout: floorplan; unit: m; scale: 0.02 }
|wall#o| { draw: move(0, 0) right(5):n down(4):e left(5):s close():w; }
|sofa#p| { symbol: stool; translate: 1 1 }
|sofa#q| { symbol: stool; translate: 3 2.5 }
|rect| { width: 0.01; height: 0.6; translate: %s %s; fill: none; stroke: --stroke-dark; stroke-width: 1 }
p (-) q
''' % (x[0], x[1])

for s0 in [float(a) for a in sys.argv[1:]]:
    px = 60.8 + 0.8 * s0
    py = 105.6 + 0.6 * s0
    o, e, c = run(mk(('%.4f' % (px / 80), '%.4f' % (py / 80))))
    s = scene(o)
    m = re.search(r'lini-dim-line lini-line" transform="[^"]*">\n(\s*<mask.*)', s)
    halos = re.findall(r'points="([^"]*)"', m.group(1)) if m else []
    print(s0, halos)

