703	// Walk the timeline in offsets below the participant row: message, note and
704	// fragment positions, activation bars, frame spans. Returns the timeline's
705	// length (last event plus a row gap) as the last value.
706	fn timeline(ctx: &Ctx, tl: &Tl) -> TimelineOut {
707	    let s = tl.s;
708	    let parts = tl.parts;
709	    let index = tl.index;
710	    let px = tl.px;
711	    let gap_row = tl.gap_row;
712	    let activation = tl.activation;
713	    let n = parts.len();
714	    let mut y = 0.0;
715	    let mut fresh = false;
716	    let mut bars: Vec<Bar> = Vec::new();
717	    let mut stacks: Vec<Vec<usize>> = vec![vec![]; n];
718	    let mut msgs: Vec<Msg> = Vec::new();
719	    let mut frames: Vec<Frame> = Vec::new();
720	    let mut open: Vec<usize> = Vec::new(); // indices into frames
721	    let mut notes: Vec<NoteGeo> = Vec::new();
722	    // frame extents: lifeline x range of the messages inside
723	    let mut ext: Vec<Option<(f64, f64)>> = Vec::new();
724	    let bar_x = |px: &[f64], b: &Bar| px[b.part] + 4.0 * b.depth as f64;
725	    for ev in tl.evs {
726	        match ev {
727	            Ev::Msg(li) => {
728	                let l = ctx.links[*li].clone();
729	                // only a participant's own lifeline carries a message
730	                let pa = index.get(&l.from).copied();
731	                let pb = index.get(&l.to).copied();
732	                let kind = kind_of(&l.op);
733	                let label = label_of(&l);
734	                let pad_top = open.last().map(|&f| frame_pads(ctx, frames[f].node).0);
735	                if pa.is_some() && pa == pb {
736	                    // a self-message: internal work, activation unchanged
737	                    let a = pa.unwrap();
738	                    y += if fresh { pad_top.unwrap_or(0.0) } else { gap_row };
739	                    fresh = false;
740	                    let lx = px[a];
741	                    let sx = match stacks[a].last() {
742	                        Some(&bi) => {
743	                            let bx = bar_x(&px, &bars[bi]);
744	                            if lx >= bx {
745	                                bx + 6.0
746	                            } else {
747	                                bx - 6.0
748	                            }
749	                        }
750	                        None => lx,
751	                    };
752	                    let pts = vec![(sx, y), (sx + 16.0, y), (sx + 16.0, y + 16.0), (sx, y + 16.0)];
753	                    let lab = label.map(|t| {
754	                        let tw = label_width(ctx, s, &t);
755	                        (t, sx + 8.0 + tw / 2.0, y - 11.5)
756	                    });
757	                    msgs.push(Msg { li: *li, pts, radii: vec![8.0, 8.0], label: lab });
758	                    for &f in &open {
759	                        let e = ext[f].get_or_insert((lx, lx + 21.0));
760	                        e.0 = e.0.min(lx);
761	                        e.1 = e.1.max(lx + 21.0);
762	                    }
763	                    y += 16.0;
764	                    continue;
765	                }
766	                y += if fresh { pad_top.unwrap_or(0.0).max(32.0) } else { gap_row };
767	                fresh = false;
768	                if kind == Kind::Call && activation {
769	                    if let Some(b) = pb {
770	                        let depth = stacks[b].len();
771	                        bars.push(Bar { part: b, depth, y0: y, y1: f64::NAN });
772	                        stacks[b].push(bars.len() - 1);
773	                    }
774	                }
775	                let (Some(a), Some(b)) = (pa, pb) else {
776	                    // drawn nowhere, but its lifeline end still spans the frames
777	                    for k in [pa, pb].into_iter().flatten() {
778	                        let x = px[k];
779	                        for &f in &open {
780	                            let e = ext[f].get_or_insert((x, x));
781	                            e.0 = e.0.min(x);
782	                            e.1 = e.1.max(x);
783	                        }
784	                    }
785	                    if kind == Kind::Return && activation {
786	                        if let Some(a) = pa {
787	                            if let Some(bi) = stacks[a].pop() {
788	                                bars[bi].y1 = y;
789	                            }
790	                        }
791	                    }
792	                    continue;
793	                };
794	                let (xa, xb) = (px[a], px[b]);
795	                let sx = match stacks[a].last() {
796	                    Some(&bi) => {
797	                        let bx = bar_x(&px, &bars[bi]);
798	                        if xb >= bx {
799	                            bx + 6.0
800	                        } else {
801	                            bx - 6.0
802	                        }
803	                    }
804	                    None => xa,
805	                };
806	                let ex = match stacks[b].last() {
807	                    Some(&bi) => {
808	                        let bx = bar_x(&px, &bars[bi]);
809	                        if xa >= bx {
810	                            bx + 6.0
811	                        } else {
812	                            bx - 6.0
813	                        }
814	                    }
815	                    None => xb,
816	                };
817	                if kind == Kind::Return && activation {
818	                    if let Some(bi) = stacks[a].pop() {
819	                        bars[bi].y1 = y;
820	                    }
821	                }
822	                let lab = label.map(|t| (t, (xa + xb) / 2.0, y - 11.5));
823	                msgs.push(Msg { li: *li, pts: vec![(sx, y), (ex, y)], radii: vec![], label: lab });
824	                let (lo, hi) = if xa < xb { (xa, xb) } else { (xb, xa) };
825	                for &f in &open {
826	                    let e = ext[f].get_or_insert((lo, hi));
827	                    e.0 = e.0.min(lo);
828	                    e.1 = e.1.max(hi);
829	                }
830	            }
831	            Ev::Note(i) => {
832	                let pad_top = open.last().map(|&f| frame_pads(ctx, frames[f].node).0);
833	                y += if fresh { pad_top.unwrap_or(0.0) } else { gap_row / 2.0 };
834	                fresh = false;
835	                let (nw, nh) = crate::layout::outer(ctx, *i);
836	                let place = place_decl(ctx, *i).and_then(|d| parse_place(&d.value));
837	                let mut g = NoteGeo { node: *i, cx: 0.0, cy: y + nh / 2.0, w: nw, h: nh, drawn: false };
838	                if let Some((mode, names)) = place {
839	                    let ks: Vec<Option<usize>> = names.iter().map(|nm| parts.iter().position(|&p| ctx.nodes[p].id.as_deref() == Some(nm.as_str()))).collect();
840	                    if ks.iter().all(|k| k.is_some()) && !ks.is_empty() {
841	                        let xs: Vec<f64> = ks.iter().map(|k| px[k.unwrap()]).collect();
842	                        let lo = xs.iter().cloned().fold(f64::INFINITY, f64::min);
843	                        let hi = xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
844	                        g.drawn = true;
845	                        match mode.as_str() {
846	                            "left" => g.cx = lo - nw / 2.0 - 12.0,
847	                            "right" => g.cx = hi + nw / 2.0 + 12.0,
848	                            _ => {
849	                                g.w = nw.max(hi - lo + 24.0);
850	                                g.cx = (lo + hi) / 2.0;
851	                            }
852	                        }
853	                    }
854	                }
855	                notes.push(g);
856	                y += nh;
857	            }
858	            Ev::Open(f) => {
859	                if !fresh {
860	                    y += gap_row;
861	                }
862	                fresh = true;
863	                frames.push(Frame { node: *f, depth: open.len(), top: y, ..Default::default() });
864	                ext.push(None);
865	                open.push(frames.len() - 1);
866	            }
867	            Ev::Else(e, f) => {
868	                let k = frames.iter().rposition(|fr| fr.node == *f).unwrap_or(0);
869	                y += frame_pads(ctx, *f).1;
870	                fresh = true;
871	                frames[k].elses.push((*e, y));
872	            }
873	            Ev::Close(f) => {
874	                let k = open.pop().unwrap_or(0);
875	                let (pt, pb) = frame_pads(ctx, *f);
876	                if fresh {
877	                    y += pt;
878	                }
879	                y += pb;
880	                fresh = false;
881	                frames[k].bottom = y;
882	            }
883	        }
884	    }
885	    let end = y + gap_row;
886	    (bars, msgs, frames, notes, ext, end)
887	}
