37	pub fn has(ctx: &Ctx, i: usize, t: &str) -> bool {
38	    ctx.nodes[i].chain.iter().any(|c| c == t)
39	}
40	
41	pub fn is_part(ctx: &Ctx, i: usize) -> bool {
42	    ctx.nodes[i].chain.iter().any(|c| super::PART_TYPES.contains(&c.as_str()))
43	}
44	
45	pub fn is_component(ctx: &Ctx, i: usize) -> bool {
46	    has(ctx, i, "component") && !is_part(ctx, i)
47	}
48	
49	pub fn is_label(ctx: &Ctx, i: usize) -> bool {
50	    has(ctx, i, "label")
51	}
52	
53	// the pins of a component (its `|pin|` descendants) or a part (its symbol's)
54	pub fn pins_of(ctx: &Ctx, i: usize) -> Vec<usize> {
55	    let mut out = Vec::new();
56	    let mut stack: Vec<usize> = ctx.nodes[i].children.iter().rev().cloned().collect();
57	    while let Some(k) = stack.pop() {
58	        if has(ctx, k, "pin") {
59	            out.push(k);
60	            continue;
61	        }
62	        if has(ctx, k, "row") || has(ctx, k, "column") {
63	            for &c in ctx.nodes[k].children.iter().rev() {
64	                stack.push(c);
65	            }
66	        }
67	    }
68	    out
69	}
70	
71	pub fn pin_count(ctx: &Ctx, i: usize) -> usize {
72	    if is_component(ctx, i) {
73	        return pins_of(ctx, i).len();
74	    }
75	    if is_part(ctx, i) {
76	        let ty = ctx.nodes[i].chain.iter().find(|c| super::PART_TYPES.contains(&c.as_str())).cloned().unwrap_or_default();
77	        let sym = crate::render::prop_str(ctx, i, "symbol");
78	        return crate::desugar::part_pins(&ty, sym.as_deref()).len();
79	    }
80	    0
81	}
82	
83	pub fn has_cell(ctx: &Ctx, i: usize) -> bool {
84	    ctx.nodes[i].props.contains_key("cell")
85	}
86	
87	pub fn role(ctx: &Ctx, i: usize) -> Role {
88	    if has_cell(ctx, i) {
89	        return Role::Anchor;
90	    }
91	    if is_label(ctx, i) {
92	        return Role::Satellite;
93	    }
94	    if is_part(ctx, i) || is_component(ctx, i) {
95	        let k = pin_count(ctx, i);
96	        if (1..=2).contains(&k) {
97	            return Role::Satellite;
98	        }
99	    }
100	    Role::Anchor
101	}
102	
103	// the name a diagnostic gives a node: its id, its reference, or its type
104	pub fn display_name(ctx: &Ctx, i: usize) -> String {
105	    if let Some(id) = &ctx.nodes[i].id {
106	        return id.clone();
107	    }
108	    for &c in &ctx.nodes[i].children {
109	        if has(ctx, c, "ref") {
110	            if let Some(&t) = ctx.nodes[c].children.first() {
111	                if let Some(s) = &ctx.nodes[t].text {
112	                    return s.clone();
113	                }
114	            }
115	        }
116	    }
117	    format!("|{}|", ctx.nodes[i].chain.first().cloned().unwrap_or_default())
118	}
