207	// a node's drawn extent around its own origin (its group's frame)
208	pub fn extent(ctx: &Ctx, i: usize) -> [f64; 4] {
209	    let mut b = [f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY];
210	    let n = &ctx.nodes[i];
211	    walk(ctx, i, &[1.0, 0.0, 0.0, 1.0, -n.x - n.geo_off.0, -n.y - n.geo_off.1], &mut b);
212	    b
213	}
214	
215	// ------------------------------------------------------- component bodies
216	
217	// A component's body centres on its pins: a column of an even count is
218	// padded by a slot to keep its middle on a pin, and the drawn body (with the
219	// labels pinned to it) shifts back by half a slot.
220	pub fn seat_component(ctx: &mut Ctx, i: usize) {
221	    let kids = ctx.nodes[i].children.clone();
222	    let mut sides = false;
223	    let mut ends = false;
224	    // (rows: real x extents), (columns: real y extents), relative to the node
225	    let mut xs: Vec<(f64, f64)> = Vec::new();
226	    let mut ys: Vec<(f64, f64)> = Vec::new();
227	    for &k in &kids {
228	        if ctx.comp[k].pin.is_some() {
229	            continue;
230	        }
231	        let (kx, ky) = (ctx.nodes[k].x, ctx.nodes[k].y);
232	        let cols: Vec<(usize, f64, f64)> = if has(ctx, k, "column") {
233	            vec![(k, 0.0, 0.0)]
234	        } else if has(ctx, k, "row") {
235	            let sub = ctx.nodes[k].children.clone();
236	            if sub.iter().any(|&s| has(ctx, s, "column")) {
237	                sub.iter().filter(|&&s| has(ctx, s, "column")).map(|&s| (s, kx, ky)).collect()
238	            } else {
239	                // a pin row (top / bottom) or a filler
240	                let pad = ctx.comp[k].padding;
241	                let w = ctx.nodes[k].w;
242	                if sub.iter().any(|&s| has(ctx, s, "pin") || has(ctx, s, "space")) {
243	                    ends = true;
244	                    xs.push((kx - w / 2.0 + pad[3], kx + w / 2.0 - pad[1]));
245	                } else {
246	                    ends = true;
247	                }
248	                continue;
249	            }
250	        } else {
251	            continue;
252	        };
253	        for (col, ox, oy) in cols {
254	            if !ctx.nodes[col].children.iter().any(|&s| has(ctx, s, "pin")) {
255	                continue;
256	            }
257	            sides = true;
258	            let (cx, cy) = (ox + ctx.nodes[col].x, oy + ctx.nodes[col].y);
259	            let _ = cx;
260	            let h = ctx.nodes[col].h;
261	            let pad = ctx.comp[col].padding;
262	            ys.push((cy - h / 2.0 + pad[0], cy + h / 2.0 - pad[2]));
263	        }
264	    }
265	    let mut dx = 0.0;
266	    let mut dy = 0.0;
267	    if !ends && !ys.is_empty() {
268	        let lo = ys.iter().map(|v| v.0).fold(f64::INFINITY, f64::min);
269	        let hi = ys.iter().map(|v| v.1).fold(f64::NEG_INFINITY, f64::max);
270	        dy = (lo + hi) / 2.0;
271	    }
272	    if !sides && !xs.is_empty() {
273	        let lo = xs.iter().map(|v| v.0).fold(f64::INFINITY, f64::min);
274	        let hi = xs.iter().map(|v| v.1).fold(f64::NEG_INFINITY, f64::max);
275	        dx = (lo + hi) / 2.0;
276	    }
277	    if dx == 0.0 && dy == 0.0 {
278	        return;
279	    }
280	    // the box centre moves to (dx, dy) from the origin
281	    ctx.nodes[i].geo_off = (-dx, -dy);
282	    for &k in &kids {
283	        if ctx.comp[k].pin.is_some() {
284	            ctx.nodes[k].x += dx;
285	            ctx.nodes[k].y += dy;
286	        }
287	    }
288	}
