335	// a part stood on end reads its value and reference beside it, flush left
336	fn side_labels(ctx: &mut Ctx, i: usize) {
337	    let (rot, _) = super::net::pose_of(ctx, i);
338	    if rot != 90 && rot != 270 {
339	        return;
340	    }
341	    for k in ctx.nodes[i].children.clone() {
342	        if (has(ctx, k, "part-value") || has(ctx, k, "ref")) && ctx.comp[k].pin.as_deref() == Some("center") {
