#!/usr/bin/env python3
# usage: suite.py [-v] [-b BIN] [-l] files... : run each snippet file (snippets separated by \n----\n),
# compare original vs ours, print per-file summary. Original outputs are cached by content hash.
#   -v : print failing snippet indices with categories
#   -l : list failing snippet sources
import subprocess, sys, os, re, tempfile, hashlib, pickle, difflib
from concurrent.futures import ThreadPoolExecutor
MINE = '/tmp/bin-link2/executable'
ORIG = '/workspace/executable'
CACHE = '/tmp/link2/cache'
os.makedirs(CACHE, exist_ok=True)
args = sys.argv[1:]
verbose = False
listing = False
files = []
i = 0
while i < len(args):
    a = args[i]
    if a == '-v':
        verbose = True
    elif a == '-l':
        listing = True
    elif a == '-b':
        MINE = args[i + 1]; i += 1
    else:
        files.append(a)
    i += 1


def run(b, src):
    d = tempfile.mkdtemp(prefix='/tmp/link2/rr.')
    p = d + '/r_in.lini'
    open(p, 'w').write(src)
    try:
        r = subprocess.run([b, 'r_in.lini'], capture_output=True, cwd=d, timeout=60)
        res = (r.stdout, r.stderr, r.returncode)
    except subprocess.TimeoutExpired:
        res = (b'TIMEOUT', b'', -1)
    os.remove(p)
    os.rmdir(d)
    return res


def orig(src):
    h = hashlib.sha1(src.encode()).hexdigest()
    cp = CACHE + '/' + h
    if os.path.exists(cp):
        try:
            return pickle.load(open(cp, 'rb'))
        except Exception:
            pass
    r = run(ORIG, src)
    pickle.dump(r, open(cp, 'wb'))
    return r


