#!/usr/bin/env python3
"""Find VAR(name) Debug text given full 64-bit states on both sides.

start = fnv('[45.0] 5 Tuple([')
end   = unwind(STATE, ', Ident("')   where STATE is the recovered state after '...VAR(name), Ident("'
"""
import itertools
import string
import sys
sys.path.insert(0, "/tmp/hatch_search")
from h import fnv1a64

M = 0xFFFFFFFFFFFFFFFF
P = 0x100000001b3
PINV = pow(P, -1, 1 << 64)


def unwind(h, s: bytes):
    for b in reversed(s):
        h = ((h * PINV) & M) ^ b
    return h


def fwd(h, s: bytes):
    for b in s:
        h = ((h ^ b) * P) & M
    return h


START = fnv1a64(b"[45.0] 5 Tuple([")
CASES = {"foo": 0x56aca24ede525c1d, "stroke": 0x2ee141b89c4c9a6b}

if __name__ == "__main__":
    for name, st in CASES.items():
        end = unwind(st, b', Ident("')
        # 1) brute force the whole VAR text up to length 3 is pointless; try: VAR = H + name + T
        # backward set over tails T (all strings up to length 3 over printable ASCII), keyed by state before name
        chars = [bytes([c]) for c in range(32, 127)]
        back = {}
        tails = [b""]
        for L in range(1, 4):
            for tup in itertools.product(chars, repeat=L):
                tails.append(b"".join(tup))
        print(name, "tails", len(tails), flush=True)
        for t in tails:
            s = unwind(end, name.encode() + t)
            back.setdefault(s, []).append(t)
        # forward over heads H: dictionary of variant-ish openings
        words = set()
        for line in open("/tmp/hatch_search/words.txt"):
            w = line.strip()
            if w:
                words.add(w)
        heads = set()
        for w in words:
            for op in ['("', '(', ' { name: "', '{ name: "', ' { "', '("--', '("--lini-', '(Ident("', '(String("', '("var(--lini-', '(["', ' "', '"']:
                heads.add(w + op)
        for op in ['"', '("', '--', '"--', 'var(--lini-', '"var(--lini-', "'", "Var"]:
            heads.add(op)
        print(name, "heads", len(heads), flush=True)
        n = 0
        for hd in heads:
            s = fwd(START, hd.encode())
            if s in back:
                print("MATCH", name, repr(hd), [repr(t) for t in back[s]], flush=True)
                n += 1
        print(name, "done", n, flush=True)

