    paths = []
    if os.path.isfile(root):
        paths = [root]
    else:
        for dp, dn, fn in os.walk(root):
            for f in fn:
                paths.append(os.path.join(dp, f))
    for p in paths:
        try:
            txt = open(p, encoding="utf-8", errors="ignore").read()
        except Exception:
            continue
