// Brute-force a common tail T (built right-to-left) such that
//   unwind(E1, N1 + T) == unwind(E2, N2 + T)
// where E1/E2 are known 64-bit end states and N1/N2 known (different) name strings.
// usage: tailbf E1hex N1 E2hex N2 maxlen charset
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define P 0x100000001b3ULL
static uint64_t PINV;

static uint64_t inv64(uint64_t a) {
    uint64_t x = a;
    for (int i = 0; i < 6; i++) x *= 2 - a * x;
    return x;
}

static const char *N1, *N2;
static int n1, n2;
static const char *CS;
static int ncs;
static int maxlen;

static uint64_t unwind_str(uint64_t h, const char *s, int n) {
    for (int i = n - 1; i >= 0; i--) h = (h * PINV) ^ (unsigned char)s[i];
    return h;
}

static void report(const unsigned char *t, int len, uint64_t a) {
#pragma omp critical
    {
        printf("FOUND len=%d T='", len);
        for (int i = 0; i < len; i++) putchar(t[i]);
        printf("' state_before_name1=%016llx\n", (unsigned long long)a);
        fflush(stdout);
    }
}

// t[pos..maxlen-1] filled from the right; h1/h2 = states before t[pos..]
static void dfs(unsigned char *t, int pos, uint64_t h1, uint64_t h2) {
    // check with current tail t[pos..maxlen)
    uint64_t a = unwind_str(h1, N1, n1);
    uint64_t b = unwind_str(h2, N2, n2);
    if (a == b) report(t + pos, maxlen - pos, a);
    if (pos == 0) return;
    for (int i = 0; i < ncs; i++) {
        unsigned char c = CS[i];
        t[pos - 1] = c;
        dfs(t, pos - 1, (h1 * PINV) ^ c, (h2 * PINV) ^ c);
    }
}

int main(int argc, char **argv) {
    if (argc < 7) {
        fprintf(stderr, "usage\n");
        return 1;
    }
    PINV = inv64(P);
    uint64_t E1 = strtoull(argv[1], NULL, 16);
    N1 = argv[2];
    n1 = strlen(N1);
    uint64_t E2 = strtoull(argv[3], NULL, 16);
    N2 = argv[4];
    n2 = strlen(N2);
    maxlen = atoi(argv[5]);
    CS = argv[6];
    ncs = strlen(CS);
    // empty tail
    {
        uint64_t a = unwind_str(E1, N1, n1), b = unwind_str(E2, N2, n2);
        if (a == b) printf("FOUND empty tail state=%016llx\n", (unsigned long long)a);
    }
    // parallelise over the last two characters
#pragma omp parallel for schedule(dynamic) collapse(2)
    for (int i = 0; i < ncs; i++) {
        for (int j = 0; j < ncs; j++) {
            unsigned char t[64];
            unsigned char c1 = CS[i], c2 = CS[j];
            t[maxlen - 1] = c1;
            uint64_t h1 = (E1 * PINV) ^ c1, h2 = (E2 * PINV) ^ c1;
            if (j == 0) {
                uint64_t a = unwind_str(h1, N1, n1), b = unwind_str(h2, N2, n2);
                if (a == b) report(t + maxlen - 1, 1, a);
            }
            if (maxlen < 2) continue;
            t[maxlen - 2] = c2;
            dfs(t, maxlen - 2, (h1 * PINV) ^ c2, (h2 * PINV) ^ c2);
        }
    }
    fprintf(stderr, "done\n");
    return 0;
}

