// A wire run already laid along a channel: it takes one of the slots a
// bounded channel offers (half a clearance apart).
#[derive(Clone, Debug)]
pub struct Taken {
    pub horiz: bool,
    // position across the run, and its span along it
    pub pos: f64,
    pub lo: f64,
    pub hi: f64,
    pub count: usize,
    // a run touching a port (first or last of its wire)
    pub term: bool,
    // laid by a fellow fan member: it fills channels but is crossed freely
    pub sibling: bool,
}

// Port offsets per side of the two endpoints (default: side centre).
pub struct PortReq<'a> {
    pub sides_a: &'a [Side],
    pub sides_b: &'a [Side],
    // free width a channel must offer across every segment (bundles)
    pub need: f64,
    // runs other wires already hold
    pub taken: &'a [Taken],
}

// The free band across an axis-aligned segment: between the inflated
// obstacles on either side over the segment's span (infinite when open).
pub fn free_band(solids: &[Rect], p: (f64, f64), q: (f64, f64)) -> (f64, f64) {
    let horiz = (p.1 - q.1).abs() < 1e-9;
    let (lo_s, hi_s) = if horiz { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
    let pos = if horiz { p.1 } else { p.0 };
    let mut lo = f64::NEG_INFINITY;
    let mut hi = f64::INFINITY;
    for r in solids {
        let (a0, a1, b0, b1) = if horiz { (r.x0, r.x1, r.y0, r.y1) } else { (r.y0, r.y1, r.x0, r.x1) };
        if a0 < hi_s - EPS && a1 > lo_s + EPS {
            if b1 <= pos + EPS && b1 > lo {
                lo = b1;
            }
            if b0 >= pos - EPS && b0 < hi {
                hi = b0;
            }
        }
    }
    (lo, hi)
}

// Wires already running along the band [lo, hi] over the span of p-q.
pub fn taken_in(taken: &[Taken], p: (f64, f64), q: (f64, f64), lo: f64, hi: f64, k: f64) -> usize {
    let horiz = (p.1 - q.1).abs() < 1e-9;
    let (s0, s1) = if horiz { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
    taken
        .iter()
        .filter(|t| t.horiz == horiz && t.lo < s1 + margin() * k - EPS && t.hi > s0 - margin() * k + EPS && t.pos > lo - EPS && t.pos < hi + EPS)
        .map(|t| t.count)
        .sum()
}

// Wires already laid that the axis-aligned edge p-q crosses (each crossing
// counted once along a path: the crossing point is taken half-open on the
// edge, strictly inside the laid run).
pub fn crossings(taken: &[Taken], p: (f64, f64), q: (f64, f64), zones: &[Rect]) -> usize {
    let horiz = (p.1 - q.1).abs() < 1e-9;
    let (s0, s1) = if horiz { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
    let at = if horiz { p.1 } else { p.0 };
    taken
        .iter()
        .filter(|t| t.horiz != horiz && t.pos >= s0 - 1e-9 && t.pos < s1 - 1e-9 && at > t.lo + 1e-9 && at < t.hi - 1e-9)
        .filter(|t| !t.sibling && (t.term || xmode() == 0))
        .filter(|t| {
            // wires sharing an end's side get spread apart there: no crossing
            let (x, y) = if horiz { (t.pos, at) } else { (at, t.pos) };
            !zones.iter().any(|z| x > z.x0 - 1e-9 && x < z.x1 + 1e-9 && y > z.y0 - 1e-9 && y < z.y1 + 1e-9)
        })
        .map(|t| t.count)
        .sum()
}

fn xmode() -> u32 {
    static M: std::sync::OnceLock<u32> = std::sync::OnceLock::new();
    *M.get_or_init(|| std::env::var("LINI_XMODE").ok().and_then(|s| s.parse().ok()).unwrap_or(0))
}

fn cross_pen() -> f64 {
    static M: std::sync::OnceLock<f64> = std::sync::OnceLock::new();
    *M.get_or_init(|| std::env::var("LINI_XPEN").ok().and_then(|s| s.parse().ok()).unwrap_or(4.0))
}

// Free width across an axis-aligned segment: the gap between the inflated
// obstacles on either side over the segment's span.
pub fn free_width(solids: &[Rect], p: (f64, f64), q: (f64, f64)) -> f64 {
    let horiz = (p.1 - q.1).abs() < 1e-9;
    let (lo_s, hi_s) = if horiz { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
    let pos = if horiz { p.1 } else { p.0 };
    let mut lo = f64::NEG_INFINITY;
    let mut hi = f64::INFINITY;
    for r in solids {
        let (a0, a1, b0, b1) = if horiz { (r.x0, r.x1, r.y0, r.y1) } else { (r.y0, r.y1, r.x0, r.x1) };
        if a0 < hi_s - EPS && a1 > lo_s + EPS {
            if b1 <= pos + EPS && b1 > lo {
                lo = b1;
            }
            if b0 >= pos - EPS && b0 < hi {
                hi = b0;
            }
        }
    }
    hi - lo
}

// The straight stub leaving an endpoint side: out of the endpoint's own
// clearance and through every container that holds only this end, ending
// the clearance beyond the outermost border. None when blocked.
pub fn stub(env: &Env, solids: &[Rect], bands: &[Band], first: bool, sd: Side) -> Option<((f64, f64), (f64, f64))> {
    let k = env.k;
    let node = if first { env.a } else { env.b };
    let other = if first { env.b } else { env.a };
    let wall_kind = if first { ObKind::WallA } else { ObKind::WallB };
    let p = side_point(&node, sd, 0.0);
    let d = sd.dir();
    let mut ext: f64 = 0.0;
    let mut walls: Vec<Rect> = Vec::new();
    for o in &env.obs {
        if o.kind != wall_kind {
            continue;
        }
        let w = o.r;
        let dist = match sd {
            Side::Right => w.x1 - p.0,
            Side::Left => p.0 - w.x0,
            Side::Bottom => w.y1 - p.1,
            Side::Top => p.1 - w.y0,
        };
        // the crossing keeps the clearance from the border's ends
        let (lo, hi, at) = if sd.horizontal() { (w.x0 + k, w.x1 - k, p.0) } else { (w.y0 + k, w.y1 - k, p.1) };
        if at < lo - EPS || at > hi + EPS {
            return None;
        }
        ext = ext.max(dist);
        walls.push(w.grow(k));
    }
    let len = ext + k;
    let e = (p.0 + d.0 * len, p.1 + d.1 * len);
    // clear of everything but the walls it crosses and its own node
    let own = node.grow(k);
    let others: Vec<Rect> = solids.iter().filter(|r| **r != own && !walls.contains(r)).cloned().collect();
    let _ = other;
    if !seg_clear(&others, p, e) || others.iter().any(|r| r.contains_open(e.0, e.1)) {
        return None;
    }
    if !seg_band_ok(bands, p, e) {
        return None;
    }
    Some((p, e))
}

