#[derive(Clone, Copy, Debug)]
pub struct BBox {
    pub x0: f64,
    pub y0: f64,
    pub x1: f64,
    pub y1: f64,
}

impl BBox {
    pub fn empty() -> BBox {
        BBox { x0: f64::INFINITY, y0: f64::INFINITY, x1: f64::NEG_INFINITY, y1: f64::NEG_INFINITY }
    }
    pub fn add(&mut self, x: f64, y: f64) {
        self.x0 = self.x0.min(x);
        self.y0 = self.y0.min(y);
        self.x1 = self.x1.max(x);
        self.y1 = self.y1.max(y);
    }
    pub fn is_empty(&self) -> bool {
        self.x0 > self.x1
    }
    pub fn w(&self) -> f64 {
        if self.is_empty() {
            0.0
        } else {
            self.x1 - self.x0
        }
    }
    pub fn h(&self) -> f64 {
        if self.is_empty() {
            0.0
        } else {
            self.y1 - self.y0
        }
    }
    pub fn cx(&self) -> f64 {
        if self.is_empty() {
            0.0
        } else {
            (self.x0 + self.x1) / 2.0
        }
    }
    pub fn cy(&self) -> f64 {
        if self.is_empty() {
            0.0
        } else {
            (self.y0 + self.y1) / 2.0
