                r = r.mul(-1.0);
            }
            let up = r.left();
            // the side: left / right of the reading first → second, else
            // away from the plan's centre
            let o = match side_s.as_deref() {
                Some("left") => n_ab.left(),
                Some("right") => n_ab.right(),
