            // the witness lines)
            let mut core = BBox::empty();
            core.add(l0.x, l0.y);
            core.add(l1.x, l1.y);
            for m in [&m0, &m1] {
                for q in m.iter() {
                    core.add(q.x, q.y);
                }
            }
            let (hwt, hht) = if vertical { (DIM_TEXT / 2.0, tw / 2.0) } else { (tw / 2.0, DIM_TEXT / 2.0) };
            core.add(text_at.x - hwt, text_at.y - hht);
            core.add(text_at.x + hwt, text_at.y + hht);
            let mut db = core;
            for (a, b) in &exts {
                db.add(a.x, a.y);
                db.add(b.x, b.y);
            }
            let mut band = core;
            for (_, b) in &exts {
                band.add(b.x, b.y);
            }
            placed.push(Placed { side, core, whole: db, shape: corners(&band) });
            let row = row_of.or(chain_row);
            if let Some(k) = row {
                if let Some(rows) = tiers.get_mut(side) {
                    if let Some(r) = rows.get_mut(k) {
                        r.1.push((olo, ohi, db));
                    }
                }
            }
            last_row = row;
            (exts, (l0, l1), vec![m0, m1], text, text_at, rotd, db, false)
        };
        let (exts, line, marks, text, text_at, rotd, db, aligned) = laid;
        // halos where a witness line (or an aligned dimension's own line)
        // crosses another outline — never under the dimension's arrows
        let mut halos = Vec::new();
        let mut mask_ids = Vec::new();
        for (a, b) in &exts {
            let hs = clear_marks(halo_gaps(&obstacles, *a, *b, true), *a, *b, &marks);
            if hs.is_empty() {
                mask_ids.push(None);
            } else {
                mask_ids.push(Some(next_mask));
                next_mask += 1;
            }
            halos.push(hs);
        }
        let mut line_halos = Vec::new();
        let mut line_mask = None;
        if aligned {
            line_halos = clear_marks(halo_gaps(&obstacles, line.0, line.1, false), line.0, line.1, &marks);
            if !line_halos.is_empty() {
                line_mask = Some(next_mask);
                next_mask += 1;
            }
        }
        let dm = &mut ctx.sk.fp.dims[d];
        dm.halos = halos;
        dm.mask_ids = mask_ids;
        dm.line_halos = line_halos;
        dm.line_mask = line_mask;
        dm.ext = exts;
        dm.line = line;
        dm.marks = marks;
        dm.text = text;
        dm.text_at = text_at;
        dm.text_rot = rotd;
        dm.laid = true;
        let ni = dm.node;
        let n = &mut ctx.nodes[ni];
        n.w = db.w();
        n.h = db.h();
        n.geo_off = (-db.cx(), -db.cy());
        n.x = db.cx();
        n.y = db.cy();
    }
}

// Halo gaps along a → b that reach under one of the dimension's own
// arrowheads (their box, half a pixel out) never open.
fn clear_marks(gaps: Vec<(f64, f64)>, a: P, b: P, marks: &[[P; 3]]) -> Vec<(f64, f64)> {
    if gaps.is_empty() {
        return gaps;
    }
    let u = b.sub(a).unit();
    let mut spans: Vec<(f64, f64)> = Vec::new();
    for m in marks {
        let mut bx = BBox::empty();
        for q in m.iter() {
            bx.add(q.x, q.y);
        }
        let (x0, x1, y0, y1) = (bx.x0 - 0.5, bx.x1 + 0.5, bx.y0 - 0.5, bx.y1 + 0.5);
        // the line's run inside the box
        let mut t0 = f64::NEG_INFINITY;
        let mut t1 = f64::INFINITY;
        for (p, v, lo, hi) in [(a.x, u.x, x0, x1), (a.y, u.y, y0, y1)] {
            if v.abs() < 1e-12 {
                if p <= lo || p >= hi {
                    t0 = f64::INFINITY;
                }
                continue;
            }
            let (s0, s1) = ((lo - p) / v, (hi - p) / v);
            t0 = t0.max(s0.min(s1));
            t1 = t1.min(s0.max(s1));
        }
        if t0 < t1 {
            spans.push((t0, t1));
        }
    }
    gaps.into_iter().filter(|(g0, g1)| !spans.iter().any(|(s0, s1)| g0 < s1 && g1 > s0)).collect()
}

