                        if u0.y.abs() >= 1e-12 {
                            add(t, rot_vec(pt(0.0, 1.0), *rot), *sw);
                        } else {
                            touch(t, rot_vec(pt(0.0, 1.0), *rot), *sw);
                        }
                    }
                }
                for y in [-*hh, *hh] {
                    if u0.y.abs() < 1e-12 {
                        continue;
                    }
                    let t = (y - a0.y) / u0.y;
                    let x = a0.x + u0.x * t;
                    if x > -*hw + 1e-9 && x < *hw - 1e-9 {
                        add(t, rot_vec(pt(1.0, 0.0), *rot), *sw);
                    } else if (x.abs() - *hw).abs() <= 1e-9 && u0.x.abs() < 1e-12 {
                        touch(t, rot_vec(pt(1.0, 0.0), *rot), *sw);
                    }
                }"""
