                let lv = q.sub(*p).len();
                if lv == 0.0 {
                    continue;
                }
                let v = q.sub(*p).unit();
                let den = u.cross(v);
                if den.abs() < 1e-12 {
                    continue;
                }
                let w = p.sub(a);
                let t = w.cross(v) / den;
                let s = w.cross(u) / den;
                // a line touching a corner never crosses it
                if s <= 1e-9 || s >= lv - 1e-9 {
                    if s >= -1e-9 && s <= lv + 1e-9 {
                        touch(t, v, *sw);
                    }
                    continue;
                }
                add(t, v, *sw);
            }"""
new2 = """            Ob::Seg(p, q, sw) => {
