                if den.abs() < 1e-12 {
                    continue;
                }
                let w = p.sub(a);
                let t = w.cross(v) / den;
                let s = w.cross(u) / den;
                // a vertex met across counts once (from the run it starts);
                // one where the line runs along the outline only touches
                if s <= 1e-9 || s >= lv - 1e-9 {
                    if s >= -1e-9 && s <= lv + 1e-9 {
                        let x = a.add(u.mul(t));
                        let along = obs.iter().any(|(o2, w2)| {
                            *w2 == owner
                                && match o2 {
                                    Ob::Seg(p2, q2, _) => {
                                        let v2 = q2.sub(*p2);
                                        v2.len() > 0.0
                                            && u.cross(v2.unit()).abs() < 1e-12
                                            && u.cross(p2.sub(a)).abs() < 1e-7
