LAB = sys.argv[5] if len(sys.argv) > 5 else ''
FIRST = sys.argv[6] if len(sys.argv) > 6 else 'o:w-in (-) o:e-in { side: top }'


def mk(dy):
    return '''{ layout: floorplan; unit: m; scale: 0.02 }
|wall#o| { draw: move(0, 0) right(5):n down(4):e left(5):s close():w; }
|sofa#p| { symbol: stool; translate: %.8f %.8f }
|sofa#q| { symbol: stool; translate: %.8f %.8f }
%s
p (-) q%s
''' % (PX, PY + dy, QX, QY + dy, FIRST, LAB)


def lines(src):
    o = run(src)[0]
    return re.findall(r'lini-dim-line lini-line" [^>]*>\n(?:\s*<mask[^\n]*\n)?\s*<line x1="([^"]*)" y1="([^"]*)" x2="([^"]*)" y2="([^"]*)"', o)


def alone(dy):
    o = run(mk(dy).replace(FIRST, ''))[0]
    return re.findall(r'lini-dim-line lini-line" [^>]*>\n(?:\s*<mask[^\n]*\n)?\s*<line x1="([^"]*)" y1="([^"]*)" x2="([^"]*)" y2="([^"]*)"', o)


def pushed(dy):
    a = alone(dy)[0]
    b = lines(mk(dy))[-1]
    return a != b


lo, hi = -1.0, 1.5
