#!/usr/bin/env python3
# value-shape probe: for each property in a valid context, try several values; print first diagnostics
import subprocess, sys, tempfile, json, os, pickle
from concurrent.futures import ThreadPoolExecutor
sys.path.insert(0,'/tmp/core/scripts')
from propprobe_list import PROPS
m=pickle.load(open('/tmp/core/matrix_1.pkl','rb'))
types=sorted(set(t for t,p in m))
pref=['box','line','chart','axis','title-block','sketch','icon','image','label','pin','R','J','component','plane','door','pie','slice','bubble','mark','band','area','bars','slant','path','page','note','feature-control','drawing','floorplan','wall','hole','poly']
VALUES=sys.argv[1:] or ['red','1','0','-1','1 2','1 2 3','1, 2','"s"','5%','--x','foo','(1+2)','none','auto','2.5']
def ctx(p):
    for t in pref:
        r=m.get((t,p))
        if r and not (r[0]=='V002'):
            return '|%s|'%t
    return 'link'
base=tempfile.mkdtemp(dir='/tmp/core')
jobs=[]
for p in PROPS:
    c=ctx(p)
    for v in VALUES:
        jobs.append((p,c,v))
def run(job):
    p,c,v=job
    d=os.path.join(base,'%d'%abs(hash(job))); os.makedirs(d,exist_ok=True)
    if c=='link': src='a -> b { %s: %s }\n'%(p,v)
    else: src='%s { %s: %s }\n'%(c,p,v)
    open(d+'/r.lini','w').write(src)
    r=subprocess.run(['/workspace/executable','--json','r.lini'],capture_output=True,cwd=d)
    try: j=json.loads(r.stdout)
    except: return job,'BAD'
    ds=j['diagnostics']
    errs=[x for x in ds if x['severity']=='error']
    x=errs[0] if errs else (ds[0] if ds else None)
    if not x: return job,'OK'
    return job,'%s%s [%d..%d] %s'%('' if errs else 'W:',x['code'],x['span']['start'],x['span']['end'],x['message'])
with ThreadPoolExecutor(12) as ex:
    res=list(ex.map(run,jobs))
cur=None
for (p,c,v),r in res:
    if p!=cur:
        print('=== %s on %s'%(p,c)); cur=p
    print('   %-8s %s'%(v,r[:200]))

