#!/usr/bin/env python3
# usage: classify.py [-v] corpus.txt... : classify failing snippets by the first kind of link difference
#   route: some link takes a different topology (direction sequence)
#   geom : same topologies, different coordinates (ports, tracks, radii)
#   other: links identical, something else differs (labels, masks, viewBox, stderr)
import sys, subprocess, re, os, tempfile, hashlib, pickle
from concurrent.futures import ThreadPoolExecutor
MINE = '/tmp/bin-link2/executable'
CACHE = '/tmp/link2/cache'
args = sys.argv[1:]
verbose = False
if args and args[0] == '-v':
    verbose = True
    args = args[1:]


def run(b, src):
    d = tempfile.mkdtemp(prefix='/tmp/link2/rr.')
    p = d + '/r_in.lini'
    open(p, 'w').write(src)
    r = subprocess.run([b, 'r_in.lini'], capture_output=True, cwd=d, timeout=60)
    os.remove(p)
    os.rmdir(d)
    return (r.stdout, r.stderr, r.returncode)


def orig(src):
    h = hashlib.sha1(src.encode()).hexdigest()
    cp = CACHE + '/' + h
    if os.path.exists(cp):
        try:
            return pickle.load(open(cp, 'rb'))
        except Exception:
            pass
    r = run('/workspace/executable', src)
    pickle.dump(r, open(cp, 'wb'))
    return r


def links(out):
    res = []
    cur = None
    for l in out.splitlines():
