from probe import run
# p,q placed after FIRST; bisect the shift (along SHIFT direction, m) at
# which p-q stops being pushed. args: px qx py qy sx sy [FIRST] [LAB]
PX, QX, PY, QY, SX, SY = [float(v) for v in sys.argv[1:7]]
FIRST = sys.argv[7] if len(sys.argv) > 7 else 'o:w-in (-) o:e-in { side: bottom }'
LAB = sys.argv[8] if len(sys.argv) > 8 else ''


def mk(t, first=True):
    return '''{ layout: floorplan; unit: m; scale: 0.02 }
|wall#o| { draw: move(0, 0) right(5):n down(4):e left(5):s close():w; }
|sofa#p| { symbol: stool; translate: %.8f %.8f }
|sofa#q| { symbol: stool; translate: %.8f %.8f }
%s
p (-) q%s
''' % (PX + SX * t, PY + SY * t, QX + SX * t, QY + SY * t, FIRST if first else '', LAB)


def last_line(src):
    o = run(src)[0]
    return re.findall(r'lini-dim-line lini-line" [^>]*>\n(?:\s*<mask[^\n]*\n)?\s*<line x1="([^"]*)" y1="([^"]*)" x2="([^"]*)" y2="([^"]*)"', o)[-1]


def pushed(t):
    return last_line(mk(t)) != last_line(mk(t, False))


lo, hi = 0.0, 1.5
print('pushed lo', pushed(lo), 'hi', pushed(hi))
if not pushed(lo) or pushed(hi):
    sys.exit()
