arguments.content:
import sys, re, math
sys.path.insert(0, '/tmp/fp')
from probe import run
# P = p2-q2 (p-q shifted by k px along -up(p->q) = the "above" normal and by
# m px along d); placed first. D = p-q after. Bisect k where D stops being
# pushed.  args: px py qx qy m [Pside] [Dside]
PX, PY, QX, QY, M = [float(v) for v in sys.argv[1:6]]
PS = sys.argv[6] if len(sys.argv) > 6 else ''
DS = sys.argv[7] if len(sys.argv) > 7 else ''
p = (PX * 80, PY * 80)
q = (QX * 80, QY * 80)
L = math.hypot(q[0] - p[0], q[1] - p[1])
d = ((q[0] - p[0]) / L, (q[1] - p[1]) / L)
up = (d[1], -d[0])
SIGN = float(sys.argv[8]) if len(sys.argv) > 8 else 1.0


def mk(k, first=True):
    p2 = (p[0] + up[0] * k * SIGN + d[0] * M, p[1] + up[1] * k * SIGN + d[1] * M)
    q2 = (q[0] + up[0] * k * SIGN + d[0] * M, q[1] + up[1] * k * SIGN + d[1] * M)
    return '''{ layout: floorplan; unit: m; scale: 0.02 }
|wall#o| { draw: move(-3, -3) right(11):n down(10):e left(11):s close():w; }
|sofa#p| { symbol: stool; translate: %.8f %.8f }
|sofa#q| { symbol: stool; translate: %.8f %.8f }
|sofa#p2| { symbol: stool; translate: %.8f %.8f }
|sofa#q2| { symbol: stool; translate: %.8f %.8f }
%s
p (-) q%s
''' % (p[0] / 80, p[1] / 80, q[0] / 80, q[1] / 80, p2[0] / 80, p2[1] / 80, q2[0] / 80, q2[1] / 80, ('p2 (-) q2' + PS) if first else '', DS)


def lines(src):
    o = run(src)[0]
    return re.findall(r'lini-dim-line lini-line" [^>]*>\n(?:\s*<mask[^\n]*\n)?\s*<line x1="([^"]*)" y1="([^"]*)" x2="([^"]*)" y2="([^"]*)"', o)


def pushed(k):
    return lines(mk(k))[-1] != lines(mk(k, False))[-1]


lo, hi = float(sys.argv[9]) if len(sys.argv) > 9 else 0.0, float(sys.argv[10]) if len(sys.argv) > 10 else 120.0
print('pushed lo', pushed(lo), 'hi', pushed(hi))
if pushed(lo) == pushed(hi):
    sys.exit()
want = pushed(lo)
for _ in range(30):
    mid = (lo + hi) / 2
    if pushed(mid) == want:
        lo = mid
    else:
        hi = mid
print('threshold k %.5f' % lo)
ls = lines(mk(lo))
print('P line', ls[0], 'D alone', lines(mk(lo, False))[-1])

