"""Find the head H of the var term: fwd(START, H) == G, VAR(x) = H + x + '", raw: false }'."""
import sys
sys.path.insert(0, "/tmp/hatch_search")
from var_mitm import fwd, START

G = 0x9e340655baa5578d
words = [w.strip() for w in open("/tmp/hatch_search/words.txt") if w.strip()]
FIELDS = ["name", "var", "id", "key", "ident", "value", "text", "css", "token", "label", "path", "prop", "property", "name_", "n", "s"]
found = 0
for v in words:
    for f in FIELDS:
        for h in ['%s { %s: "' % (v, f), '%s { %s: "--' % (v, f), '%s{ %s: "' % (v, f), '%s { %s: "lini-' % (v, f), '%s { %s: "--lini-' % (v, f)]:
            if fwd(START, h.encode()) == G:
                print("MATCH", repr(h))
                found += 1
print("done", found)

