#!/usr/bin/env python3
# For column a, b, c with `a -> c`: for each c label, scan b labels (sorted by width) and report the
# original's start side, to find the b width threshold where the choice flips.
import subprocess, re, os, tempfile, sys
from concurrent.futures import ThreadPoolExecutor
a = sys.argv[1]
cs = sys.argv[2].split(',')
bs = ['f', 'x', 'db', 'iii', 'mm', 'api', 'ap', 'apl', 'apr', 'apt', 'svc', 'log', 'web', 'auth', 'apim', 'user', 'store', 'cache', 'queue', 'Work', 'Worker', 'Gateway', 'Worker pool']


def run(src):
    d = tempfile.mkdtemp(prefix='/tmp/link2/th.')
    open(d + '/r_in.lini', 'w').write(src)
    r = subprocess.run(['/workspace/executable', 'r_in.lini'], capture_output=True, cwd=d)
    os.remove(d + '/r_in.lini')
    os.rmdir(d)
    return r.stdout.decode()


jobs = []
for c in cs:
    for b in bs:
        jobs.append((c, b, '{ direction: column }\n|box#a| "%s"\n|box#b| "%s"\n|box#c| "%s"\na -> c\n' % (a, b, c)))
with ThreadPoolExecutor(max_workers=16) as ex:
    outs = list(ex.map(lambda j: run(j[2]), jobs))
rows = {}
for (c, b, _), o in zip(jobs, outs):
    ws = [float(w) for w in re.findall(r'<rect x="[^"]*" y="[^"]*" width="([^"]*)"', o)]
    d = re.search(r'<path d="(M[^"]*)"', o).group(1)
    nums = [float(v) for v in re.findall(r'-?[0-9.]+', d)]
    x0, y0 = nums[0], nums[1]
    ha, hb, hc = ws[0] / 2 + 1, ws[1] / 2 + 1, ws[2] / 2 + 1
    if abs(y0 - (-93)) < 0.01:
        s = 'L' if x0 < 0 else 'R'
    elif y0 > -93:
        s = 'B'
    else:
        s = 'T'
    # end side
    xe, ye = nums[-2], nums[-1]
    if abs(ye - 93) < 0.01:
        e = 'L' if xe < 0 else 'R'
    elif ye < 93:
        e = 'T'
    else:
        e = 'B'
    rows.setdefault(c, []).append((hb, b, s + e, ha, hc))
for c in cs:
    r = sorted(rows[c])
    print('c=%s (hc %.2f) a hx %.2f: ' % (c, r[0][4], r[0][3]) + ' '.join('%s:%.2f:%s' % (b, hb, s) for hb, b, s, _, _ in r))

