}

impl Placed {
    fn shape(&self) -> Vec<P> {
        let mut v = self.band.clone();
        v.extend(self.tbox.iter().copied());
        v
    }
}"""
new = """    band: Vec<P>,
    tbox: Vec<P>,
    // the axis it reads along
    dir: P,
}

impl Placed {
    // what a dimension along `r` stands clear of: a parallel one's band and
    // text box, any other's band
    fn shape(&self, r: P) -> Vec<P> {
        let mut v = self.band.clone();
        if self.dir.cross(r).abs() < 1e-9 {
            v.extend(self.tbox.iter().copied());
        }
        v
    }
}"""
assert s.count(old) == 1
s = s.replace(old, new)
old2 = """                        for q in &placed {
                            if overlap(&me, &q.band) || overlap(&me, &q.tbox) {
                                let to = extent(&q.shape(), o).1 + gap;"""
new2 = """                        for q in &placed {
                            let par = q.dir.cross(r).abs() < 1e-9;
                            if overlap(&me, &q.band) || (par && overlap(&me, &q.tbox)) {
                                let to = extent(&q.shape(r), o).1 + gap;"""
assert s.count(old2) == 1
s = s.replace(old2, new2)
old3 = """            let mut shape = band.clone();
            shape.extend(tbox.iter().copied());
            let sb = bbox_of(&shape);"""
new3 = """            let sb = bbox_of(&band);"""
assert s.count(old3) == 1
s = s.replace(old3, new3)
old4 = """            placed.push(Placed { side: "", core: sb, whole: sb, band, tbox });"""
new4 = """            placed.push(Placed { side: "", core: sb, whole: sb, band, tbox, dir: r });"""
assert s.count(old4) == 1
s = s.replace(old4, new4)
old5 = """            placed.push(Placed { side, core, whole: db, band: corners(&band), tbox: tb });"""
new5 = """            let dir = if vertical { pt(0.0, -1.0) } else { pt(1.0, 0.0) };
            placed.push(Placed { side, core, whole: db, band: corners(&band), tbox: tb, dir });"""
assert s.count(old5) == 1
s = s.replace(old5, new5)
open(p, 'w').write(s)
print('ok')
EOF

