// A marker property's value must name a known marker.
pub fn marker_error(props: &[(String, Value)]) -> Option<String> {
    for k in ["marker", "marker-end", "marker-start"] {
        if let Some((_, v)) = props.iter().find(|(n, _)| n == k) {
