#!/usr/bin/env python3
# multi-error and mixed-context snippets
import sys, random
sys.path.insert(0,'/tmp/core/scripts')
from propprobe_list import PROPS
from types_list import TYPES
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 2)
VALUES=['red','1','0','-1','1 2','1 2 3','1, 2','"s"','5%','--x','foo','(1+2)','none','auto','2.5','(nope)','wave(1)','#abc','gradient(red, blue)','rgb(300,1,2)','top left','start','bold','400','dashed','a b c','(1 2)','max(1 2)','sin(1, 2)','oklch(2, 1, 1)','gradient(red)','linear-gradient(red, blue)']
NAMES=PROPS+['colr','widht','heigth','fil','strok','paddin','gapp','labl','x','zz','font','border','margin','background','text-align','fill-opacity']
def decl():
    return '%s: %s'%(random.choice(NAMES), random.choice(VALUES))
def decls(n):
    return '; '.join(decl() for _ in range(n))
out=[]
for k in range(1500):
    shape=random.randrange(8)
    if shape==0:
        out.append('|%s| "a" { %s }'%(random.choice(TYPES), decls(random.randint(1,3))))
    elif shape==1:
        out.append('{ %s }\n|box| "a" { %s }'%(decls(2), decls(2)))
    elif shape==2:
        out.append('{ |%s| { %s }\n  .c { %s } }\n|%s| "x" .c\n|box| "y" { %s }'%(random.choice(TYPES), decls(2), decls(2), random.choice(TYPES), decls(1)))
    elif shape==3:
        out.append('a -> b "l" { %s }\nc -> d [ "t" { %s } ]'%(decls(2), decls(1)))
    elif shape==4:
        out.append('|group| "g" { %s } [\n  |box| "a" { %s }\n  "t" { %s }\n]'%(decls(1), decls(2), decls(1)))
    elif shape==5:
        out.append('{ |svc::%s| { %s } }\n|svc| "a" { %s }'%(random.choice(['box','oval','line','icon','group']), decls(2), decls(1)))
    elif shape==6:
        out.append('{ #k { %s }\n  |-| { %s } }\n|box#k| "x"\nk -> m'%(decls(2), decls(2)))
    else:
        out.append('|grid| { columns: 2 } [\n  |box| "a" { %s }\n  |box| "b" { %s }\n]'%(decls(2), decls(2)))
print('\n----\n'.join(out))

