+    let zone_of = |x: f64, y: f64, z: &Rect| -> &'static str {
+        let ix = x > z.x0 + 1e-9 && x < z.x1 - 1e-9;
+        let iy = y > z.y0 + 1e-9 && y < z.y1 - 1e-9;
+        let bx = (x - z.x0).abs() < 1e-9 || (x - z.x1).abs() < 1e-9;
+        let by = (y - z.y0).abs() < 1e-9 || (y - z.y1).abs() < 1e-9;
+        if ix && iy {
+            "in"
+        } else if (ix && by) || (iy && bx) {
+            "edge"
+        } else if bx && by {
