+        } else {
+            "out"
+        }
+    };
+    for i in 0..pts.len().saturating_sub(1) {
+        let (p, q) = (pts[i], pts[i + 1]);
+        let horiz = (p.1 - q.1).abs() < 1e-9;
+        let (s0, s1) = if horiz { (p.0.min(q.0), p.0.max(q.0)) } else { (p.1.min(q.1), p.1.max(q.1)) };
+        let at = if horiz { p.1 } else { p.0 };
+        for t in taken {
+            if t.horiz == horiz {
+                continue;
+            }
+            if t.pos < s0 - 1e-9 || t.pos > s1 + 1e-9 || at < t.lo - 1e-9 || at > t.hi + 1e-9 {
+                continue;
+            }
+            let (x, y) = if horiz { (t.pos, at) } else { (at, t.pos) };
+            let on_seg = if (t.pos - s0).abs() < 1e-9 { "min" } else if (t.pos - s1).abs() < 1e-9 { "max" } else { "mid" };
+            let head = if horiz { (q.0 - t.pos).abs() < 1e-9 } else { (q.1 - t.pos).abs() < 1e-9 };
+            let tail = if horiz { (p.0 - t.pos).abs() < 1e-9 } else { (p.1 - t.pos).abs() < 1e-9 };
+            let on_run = if (at - t.lo).abs() < 1e-9 || (at - t.hi).abs() < 1e-9 { "runend" } else { "runmid" };
