#!/usr/bin/env python3
# broader search: frame offsets F (various), association orders
import re
data = []
for line in open('/tmp/sch/zdata.txt'):
    m = re.match(r"5V (\S+) (True|False) rect \('([^']+)', '([^']+)', '([^']+)', '([^']+)'\)", line)
    L = float(m.group(1)); z = m.group(2) == 'True'
    rx = float(m.group(3)); W = float(m.group(5))
    data.append((L, z, rx, W))

res = []
for lw in (34.986, 34.986000000000004):
    h = lw / 2
    o1s = {'h-8.75': h - 8.75, '(h-0.75)-8': (h - 0.75) - 8, '-((-h+0.75)+8)': -((-h + 0.75) + 8), 'lit8.743': 8.743, 'lit8.742999999999999': 8.742999999999999, 'h-(0.75+8)': h - (0.75 + 8)}
    rels = {
        'c+((-h+.75)+8)': lambda c: c + ((-h + 0.75) + 8),
        '(c+(-h+.75))+8': lambda c: (c + (-h + 0.75)) + 8,
        '((c-h)+.75)+8': lambda c: ((c - h) + 0.75) + 8,
        '(c-h)+8.75': lambda c: (c - h) + 8.75,
        'c-o1': None,
        '(c-lw/2)+8.75': lambda c: (c - lw / 2) + 8.75,
        '(c+(-lw/2+.75))+8': lambda c: (c + (-lw / 2 + 0.75)) + 8,
    }
    for o1n, o1 in o1s.items():
        for reln, rel in rels.items():
            if rel is None:
                rel = (lambda o1: (lambda c: c - o1))(o1)
            for frn in ['none', 'W/2', 'W/2+20', 'W/2-20', '-rx', '-rx+20', '-rx-20', 'W/2+40', '-rx+40']:
                for assoc in ['label_local_first', 'frame_first']:
                    good = 0
                    for (L, z, rx, W) in data:
                        F = {'none': 0.0, 'W/2': W / 2, 'W/2+20': W / 2 + 20, 'W/2-20': W / 2 - 20, '-rx': -rx, '-rx+20': -rx + 20, '-rx-20': -rx - 20, 'W/2+40': W / 2 + 40, '-rx+40': -rx + 40}[frn]
                        s = L + F
                        if assoc == 'label_local_first':
                            c = (L + o1) + F
                        else:
                            c = (L + F) + o1
                        a = rel(c)
                        # compare back in local
                        if ((a - F) != (s - F)) == z:
                            good += 1
                    res.append((good, lw, o1n, reln, frn, assoc))
res.sort(reverse=True)
for r in res[:20]:
    print(r)

