import sys, re, math
sys.path.insert(0, '/tmp/fp')
from probe import run
from decimal import Decimal as Dd, getcontext
getcontext().prec = 40

# fk1: P0 = p0 -> p1 (default side), D = p2 -> p3 { side: right }.
