p0 = (432.0, 16.0); p1 = (240.0, 120.0)
p2 = (376.0, 200.0); p3 = (208.0, 88.0)
v = (p3[0] - p2[0], p3[1] - p2[1]); L = math.hypot(*v); n = (v[0] / L, v[1] / L)
oD = (-n[1], n[0])
SIDE = sys.argv[1] if len(sys.argv) > 1 else ' { side: left }'


def mk(k, first=True):
    a = (p0[0] - oD[0] * k, p0[1] - oD[1] * k)
    b = (p1[0] - oD[0] * k, p1[1] - oD[1] * k)
    return '''{ layout: floorplan; unit: m; scale: 0.02 }
|wall#o| { draw: move(-3, -3) right(12):n down(10):e left(12):s close():w; }
|sofa#p0| { symbol: stool; translate: %.13f %.13f }
|sofa#p1| { symbol: stool; translate: %.13f %.13f }
|sofa#p2| { symbol: stool; translate: 4.7 2.5 }
|sofa#p3| { symbol: stool; translate: 2.6 1.1 }
%s
p2 (-) p3 { side: right }
''' % (a[0] / 80, a[1] / 80, b[0] / 80, b[1] / 80, ('p0 (-) p1' + SIDE) if first else '')


def lines(src):
    o = run(src)[0]
    return re.findall(r'lini-dim-line lini-line" [^>]*>\n(?:\s*<mask[^\n]*\n)?\s*<line x1="([^"]*)" y1="([^"]*)" x2="([^"]*)" y2="([^"]*)"', o)


def pushed(k):
    return lines(mk(k))[-1] != lines(mk(k, False))[-1]


