#!/usr/bin/env python3
# classify failing cases: stderr differs / node placement differs / only wires differ / other
import sys, os, subprocess, re, collections
files = sys.argv[1:]
cats = collections.defaultdict(list)
def nodes(svg):
    return re.findall(r'<g class="lini-node[^"]*"(?: data-id="[^"]*")? transform="[^"]*">', svg)
def wires(svg):
    return re.findall(r'<path d="[^"]*"[^>]*/>', svg.split('<g class="lini-links"')[-1]) if '<g class="lini-links"' in svg else []
for f in files:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    r1 = subprocess.run(['/workspace/executable', b], cwd=d, capture_output=True, text=True)
    r2 = subprocess.run(['/tmp/bin-sch/executable', b], cwd=d, capture_output=True, text=True)
    if r1.stdout == r2.stdout and r1.stderr == r2.stderr:
        continue
    if r1.stderr != r2.stderr:
        cats['stderr'].append(b)
    elif nodes(r1.stdout) != nodes(r2.stdout):
        cats['nodes'].append(b)
    elif wires(r1.stdout) != wires(r2.stdout):
        cats['wires'].append(b)
    else:
        cats['other'].append(b)
for k, v in cats.items():
    print(k, len(v), ' '.join(v[:40]))

