al = rep_in(al, "let inside = span >= tw + 30.0 - 1e-9;", "let inside = span >= tw + 2.0 * alen + 6.0 - 1e-9;")
al = rep_in(al, "if inside { (lo, hi) } else { (lo - 14.0, hi + 14.0) };", "if inside { (lo, hi) } else { (lo - over, hi + over) };")
al = rep_in(al, "ohi = hi + 18.0 + tw;", "ohi = hi + over + 4.0 + tw;")
al = rep_in(al, "olo = lo - 18.0 - tw;", "olo = lo - over - 4.0 - tw;")
al = rep_in(al, "let (k0, k1) = if above { (-ARROW_HALF, DIM_TEXT_OFF + DIM_TEXT / 2.0) } else { (-(DIM_TEXT_OFF + DIM_TEXT / 2.0), EXT_OVER) };",
            "let (k0, k1) = if above { (-ahalf, (toff + fs / 2.0).max(EXT_OVER)) } else { (-(toff + fs / 2.0).max(ahalf), EXT_OVER.max(ahalf)) };")
al = rep_in(al, """                l0 = tlo.add(r.mul(2.0));
                l1 = thi.sub(r.mul(2.0));
                m0 = arrow(tlo, r.mul(-1.0));
                m1 = arrow(thi, r);""", """                l0 = tlo.add(r.mul(inset));
                l1 = thi.sub(r.mul(inset));
                m0 = arrow(tlo, r.mul(-1.0), alen, ahalf);
                m1 = arrow(thi, r, alen, ahalf);""")
