                m0 = arrow(tlo, r, alen, ahalf);
                m1 = arrow(thi, r.mul(-1.0), alen, ahalf);""")
al = rep_in(al, "pt((tlo.x + thi.x) / 2.0, (tlo.y + thi.y) / 2.0).add(up.mul(DIM_TEXT_OFF))", "pt((tlo.x + thi.x) / 2.0, (tlo.y + thi.y) / 2.0).add(up.mul(toff))")
al = rep_in(al, "let past = if shallow { thi.add(r.mul(14.0 + 4.0 + tw / 2.0)) } else { tlo.sub(r.mul(14.0 + 4.0 + tw / 2.0)) };",
            "let past = if shallow { thi.add(r.mul(over + 4.0 + tw / 2.0)) } else { tlo.sub(r.mul(over + 4.0 + tw / 2.0)) };")
al = rep_in(al, "past.add(up.mul(DIM_TEXT_OFF))", "past.add(up.mul(toff))")
al = rep_in(al, "let (hwt, hht) = (tw / 2.0 * cs + DIM_TEXT / 2.0 * sn, tw / 2.0 * sn + DIM_TEXT / 2.0 * cs);", "let (hwt, hht) = (tw / 2.0 * cs + fs / 2.0 * sn, tw / 2.0 * sn + fs / 2.0 * cs);")
al = rep_in(al, "band_pts.push(text_at.add(r.mul(sa * tw / 2.0)).add(up.mul(sc * DIM_TEXT / 2.0)));", "band_pts.push(text_at.add(r.mul(sa * tw / 2.0)).add(up.mul(sc * fs / 2.0)));")

