ax = rep_in(ax, "let tw = crate::font::text_width(crate::font::Family::Sans, 400, DIM_TEXT, &text);", "let tw = crate::font::text_width(crate::font::Family::Sans, 400, fs, &text);")
ax = rep_in(ax, "let inside = span >= tw + 30.0 - 1e-9;", "let inside = span >= tw + 2.0 * alen + 6.0 - 1e-9;")
ax = rep_in(ax, "let (mut olo, mut ohi) = if inside { (lo, hi) } else { (lo - 14.0, hi + 14.0) };", "let (mut olo, mut ohi) = if inside { (lo, hi) } else { (lo - over, hi + over) };")
ax = rep_in(ax, "olo = lo - 18.0 - tw;", "olo = lo - over - 4.0 - tw;")
ax = rep_in(ax, "ohi = hi + 18.0 + tw;", "ohi = hi + over + 4.0 + tw;")
