                l1 = at(hi - inset);
                let d0 = if vertical { pt(0.0, -1.0) } else { pt(-1.0, 0.0) };
                m0 = arrow(at(lo), d0, alen, ahalf);
                m1 = arrow(at(hi), d0.mul(-1.0), alen, ahalf);""")
ax = rep_in(ax, """                l0 = at(lo - 14.0);
                l1 = at(hi + 14.0);
                let d0 = if vertical { pt(0.0, 1.0) } else { pt(1.0, 0.0) };
                m0 = arrow(at(lo), d0);
                m1 = arrow(at(hi), d0.mul(-1.0));""", """                l0 = at(lo - over);
                l1 = at(hi + over);
                let d0 = if vertical { pt(0.0, 1.0) } else { pt(1.0, 0.0) };
                m0 = arrow(at(lo), d0, alen, ahalf);
                m1 = arrow(at(hi), d0.mul(-1.0), alen, ahalf);""")
ax = rep_in(ax, "let y = if text_in { mid } else { lo - 14.0 - 4.0 - tw / 2.0 };", "let y = if text_in { mid } else { lo - over - 4.0 - tw / 2.0 };")
ax = rep_in(ax, "(pt(p - DIM_TEXT_OFF, y), -90.0)", "(pt(p - toff, y), -90.0)")
ax = rep_in(ax, "let x = if text_in { mid } else { hi + 14.0 + 4.0 + tw / 2.0 };", "let x = if text_in { mid } else { hi + over + 4.0 + tw / 2.0 };")
ax = rep_in(ax, "(pt(x, p - DIM_TEXT_OFF), 0.0)", "(pt(x, p - toff), 0.0)")
ax = rep_in(ax, "let (hwt, hht) = if vertical { (DIM_TEXT / 2.0, tw / 2.0) } else { (tw / 2.0, DIM_TEXT / 2.0) };", "let (hwt, hht) = if vertical { (fs / 2.0, tw / 2.0) } else { (tw / 2.0, fs / 2.0) };")

s = s[:a0] + al + ax + s[ax_end:]

# 4. sized arrowheads
rep("""// An arrowhead with its tip at p, pointing along d.
fn arrow(p: P, d: P) -> [P; 3] {
    let base = p.sub(d.mul(ARROW_LEN));
    let r = d.right().mul(ARROW_HALF);
    [p, base.add(r), base.sub(r)]
}""", """// An arrowhead with its tip at p, pointing along d.
fn arrow(p: P, d: P, len: f64, half: f64) -> [P; 3] {
    let base = p.sub(d.mul(len));
    let r = d.right().mul(half);
    [p, base.add(r), base.sub(r)]
}""")

# 5. the text size / weight ride to render
rep("""        dm.text_rot = rotd;
        dm.laid = true;""", """        dm.text_rot = rotd;
        dm.fs = fs;
        dm.sw = sw;
        dm.laid = true;""")
rep("""    pub err: Option<Diag>,
}""", """    pub err: Option<Diag>,
    // the link's own text size and stroke weight
    pub fs: f64,
    pub sw: f64,
}""")
open(p, 'w').write(s)
print('ok')

