#!/usr/bin/env python3
# run our binary on every snippet in the given files with several modes; report panics/timeouts
import subprocess, sys, tempfile, os
from concurrent.futures import ThreadPoolExecutor
modes=[[],['--static'],['--embed-font'],['--json'],['--static','--theme','dark']]
snips=[]
for f in sys.argv[1:]:
    snips+= [s.strip('\n') for s in open(f).read().split('\n----\n') if s.strip()]
base=tempfile.mkdtemp(dir='/tmp/core')
def run(k):
    s=snips[k]; d=os.path.join(base,str(k)); os.makedirs(d)
    open(d+'/r_in.lini','w').write(s+'\n')
    bad=[]
    for m in modes:
        try:
            r=subprocess.run(['/tmp/bin-core/executable']+m+['r_in.lini'],capture_output=True,cwd=d,timeout=20)
            if r.returncode not in (0,1,2,3) or b'panicked' in r.stderr:
                bad.append((m, r.returncode, r.stderr.decode()[:300]))
        except subprocess.TimeoutExpired:
            bad.append((m,'TIMEOUT',''))
    return (s,bad) if bad else None
with ThreadPoolExecutor(12) as ex:
    res=[r for r in ex.map(run,range(len(snips))) if r]
for s,bad in res[:30]:
    print('### '+s.replace('\n','⏎')[:200])
    for b in bad: print('   ',b)
print('PANICS %d / %d'%(len(res),len(snips)))

