// Two polylines that are reflections of each other across a vertical or a
// horizontal line.
fn is_mirror(p: &[(f64, f64)], q: &[(f64, f64)]) -> bool {
    if p.len() != q.len() || p.len() < 3 {
        return false;
    }
    let mx = p[0].0 + q[0].0;
    let my = p[0].1 + q[0].1;
    let xm = p.iter().zip(q.iter()).all(|(a, b)| (a.1 - b.1).abs() < 1e-6 && (a.0 + b.0 - mx).abs() < 1e-6);
