565	            let base = mine.iter().map(|&k| plans[k].min_lane).fold(if sgn(f) > 0.0 { f64::NEG_INFINITY } else { f64::INFINITY }, |a, b| if sgn(f) > 0.0 { a.max(b) } else { a.min(b) });
