567	            // nearest that end first; then the others, from the far end
568	            let mut pins: Vec<(usize, Dir, f64)> = Vec::new();
569	            for &k in &mine {
570	                let pl = &plans[k];
571	                match pins.iter_mut().find(|p| p.0 == pl.pin) {
572	                    Some(p) => {
573	                        if sgn(pl.d1) > 0.0 {
574	                            p.1 = pl.d1;
575	                        }
576	                    }
577	                    None => pins.push((pl.pin, pl.d1, pl.row)),
578	                }
579	            }
580	            pins.sort_by(|a, b| {
581	                let ka = if sgn(a.1) < 0.0 { (0, a.2) } else { (1, -a.2) };
582	                let kb = if sgn(b.1) < 0.0 { (0, b.2) } else { (1, -b.2) };
583	                ka.partial_cmp(&kb).unwrap_or(std::cmp::Ordering::Equal)
584	            });
