import subprocess, sys, os, difflib, re
from concurrent.futures import ThreadPoolExecutor
files = [l.strip() for l in open(sys.argv[1]) if l.strip().startswith('/')]
MINE = '/tmp/bin-link2/executable'


def run(b, f):
    r = subprocess.run([b, f], capture_output=True, cwd='/tmp/link2')
    return r.stdout.decode(errors='replace'), r.stderr.decode(errors='replace'), r.returncode


def one(f):
    a = run('/workspace/executable', f)
    b = run(MINE, f)
    xa = a[0].split('\n')
    xb = b[0].split('\n')
    link = other = 0
    in_links_a = set()
    # mark lines inside <g class="lini-links"> in either output
    def link_lines(xs):
        s = set()
        inside = False
        for i, l in enumerate(xs):
            if '<g class="lini-links"' in l:
                inside = True
            if inside:
                s.add(l)
            if inside and l.startswith('  </g>'):
                inside = False
        return s
    la, lb = link_lines(xa), link_lines(xb)
    for d in difflib.unified_diff(xa, xb, lineterm='', n=0):
        if d.startswith(('---', '+++', '@@')):
