// A box's max-width wraps text only: a child of any other kind whose
// natural width overflows the room it leaves (padding and stroke-width
// cleared) is an error. Every child's subtree reports first.
fn check_max_width(ctx: &mut Ctx, i: usize) {
    let c = ctx.comp[i].clone();
    let Some(m) = c.max_width else { return };
    if i == 0 || matches!(c.layout.as_str(), "sequence" | "tree" | "drawing" | "floorplan" | "chart" | "pie") {
        return;
    }
    let room = m - c.padding[1] - c.padding[3] - c.stroke_width;
    let kids: Vec<usize> = ctx.nodes[i].children.iter().copied().filter(|&ch| ctx.nodes[ch].prim != Prim::Text && ctx.comp[ch].pin.is_none()).collect();
    for &ch in &kids {
        measure(ctx, ch, None);
    }
    if ERR.with(|e| e.borrow().is_some()) {
        return;
    }
    for &ch in &kids {
        if outer(ctx, ch).0 > room + 1e-9 {
            let msg = format!("a child is wider than 'max-width: {}' — only text wraps", crate::util::f4(m));
            let d = crate::diag::Diag::error("layout", &msg, ctx.nodes[ch].span);
            ERR.with(|e| *e.borrow_mut() = Some(d));
            return;
        }
    }
}

