#!/usr/bin/env python3
# genlay.py N SEED : random nested docs with several (often invalid) layout attributes
import random, sys
n=int(sys.argv[1]); random.seed(int(sys.argv[2]))
vals={
 'padding':['foo','1 2 3','5','4 8','1 2 3 4','(zz)','--x'],
 'gap':['foo','1 2 3','6','4 8','"s"'],
 'layout':['zz','row','column','grid','flow','radial'],
 'direction':['up','row','column','5'],
 'translate':['foo','3 4','1 2 3','"q"'],
 'pin':['foo','top','top left','left left','none','center'],
 'mirror':['foo','x-axis','none','45'],
 'max-width':['50','120','300'],
 'width':['30','60','200'],
}
keys=list(vals)
def attrs():
    k=random.sample(keys, random.randint(0,3))
    return '; '.join('%s: %s'%(a, random.choice(vals[a])) for a in k)
def node(depth):
    t=random.choice(['box','box','oval','group'])
    a=attrs()
    s='|%s|'%t
    if a: s+=' { %s }'%a
    if depth<3 and random.random()<0.6:
        kids=[node(depth+1) for _ in range(random.randint(1,3))]
        if random.random()<0.3: kids.append('"t%d"'%random.randint(0,9))
        s+=' [ '+'; '.join(kids)+' ]'
    elif random.random()<0.5:
        s+=' "x"'
    return s
out=[]
for _ in range(n):
    lines=[]
    if random.random()<0.3:
        lines.append('{ %s }'%(attrs() or 'gap: 4'))
    for _ in range(random.randint(1,3)):
        lines.append(node(0))
    out.append('\n'.join(lines))
print('\n----\n'.join(out))

