#!/usr/bin/env python3
# for failing cases: the first few differing node translates (orig / mine)
import sys, os, subprocess, re
for f in sys.argv[1:]:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    o = subprocess.run(['/workspace/executable', b], cwd=d, capture_output=True, text=True).stdout
    m = subprocess.run(['/tmp/bin-sch/executable', b], cwd=d, capture_output=True, text=True).stdout
    if o == m:
        continue
    no = re.findall(r'<g class="lini-node ([^"]*)" data-id="([^"]*)" transform="translate\(([-\d.]+),([-\d.]+)\)">', o)
    nm = re.findall(r'<g class="lini-node ([^"]*)" data-id="([^"]*)" transform="translate\(([-\d.]+),([-\d.]+)\)">', m)
    mm = {k[1]: (float(k[2]), float(k[3])) for k in nm}
    diffs = []
    for cls, i, x, y in no:
        if i in mm:
            dx, dy = mm[i][0] - float(x), mm[i][1] - float(y)
            if abs(dx) > 1e-6 or abs(dy) > 1e-6:
                diffs.append('%s(%s) d=(%g,%g)' % (i, cls.split()[0].replace('lini-', ''), dx, dy))
    if diffs:
        print(b, ' '.join(diffs[:6]))

