1	// The wires of every schematic scope, routed after layout between fixed
2	// ports: a pin's stub tip (left along the pin's facing), a part's station, a
3	// label's connection point (a run's far end: the wire travels its length).
4	// Routes run on the scope's lattice lines clear of every body's lattice
5	// cells; a wire of a net already drawn joins it where it can, and the points
6	// where three ways of one net meet get a junction dot.
7	
8	use super::net::{origin_in, Dir, Kind, Term};
9	use crate::compile::Ctx;
10	use std::cell::RefCell;
11	
12	#[derive(Clone, Debug)]
13	pub struct Routed {
14	    pub li: usize,
15	    pub pts: Vec<(f64, f64)>,
16	    // the net name along the trace: (text, x, y, rotation)
17	    pub labels: Vec<(String, f64, f64, f64)>,
18	    pub scope: usize,
19	}
20	
21	#[derive(Default)]
22	pub struct Wiring {
23	    pub wires: Vec<Routed>,
24	    pub junctions: Vec<(f64, f64)>,
25	    // a scope a wire is drawn in is not the root: wires wear the class
26	    pub nested: bool,
27	}
28	
29	thread_local! {
30	    pub static WIRING: RefCell<Wiring> = RefCell::new(Wiring::default());
31	}
32	
33	pub fn reset() {
34	    WIRING.with(|w| *w.borrow_mut() = Wiring::default());
35	}
36	
37	pub const CLEAR: f64 = 10.0;
38	// a wire's width
39	pub const WIRE: f64 = 1.5;
40	
41	fn abs_point(ctx: &Ctx, t: &Term) -> (f64, f64) {
42	    let o = origin_in(ctx, t.dev, 0);
43	    (o.0 + t.off.0, o.1 + t.off.1)
44	}
45	
46	fn same(a: f64, b: f64) -> bool {
47	    (a - b).abs() < 1e-9
48	}
49	
50	// a direct route: straight, or one corner
51	fn direct(a: (f64, f64), da: Dir, b: (f64, f64), db: Dir) -> Option<Vec<(f64, f64)>> {
52	    let ahead = |p: (f64, f64), d: Dir, q: (f64, f64)| -> bool {
53	        match d {
54	            Dir::R => q.0 > p.0 - 1e-9,
55	            Dir::L => q.0 < p.0 + 1e-9,
56	            Dir::D => q.1 > p.1 - 1e-9,
57	            Dir::U => q.1 < p.1 + 1e-9,
58	        }
59	    };
60	    if da == db.opposite() {
61	        let aligned = if da.horizontal() { same(a.1, b.1) } else { same(a.0, b.0) };
62	        if aligned && ahead(a, da, b) {
63	            return Some(vec![a, b]);
64	        }
65	        if ahead(a, da, b) {
66	            // a staircase: the jog halfway
67	            if da.horizontal() {
68	                let m = (a.0 + b.0) / 2.0;
69	                return Some(vec![a, (m, a.1), (m, b.1), b]);
70	            } else {
71	                let m = (a.1 + b.1) / 2.0;
72	                return Some(vec![a, (a.0, m), (b.0, m), b]);
73	            }
74	        }
75	        return None;
76	    }
77	    if da.horizontal() != db.horizontal() {
78	        let c = if da.horizontal() { (b.0, a.1) } else { (a.0, b.1) };
79	        if ahead(a, da, c) && ahead(b, db, c) {
80	            return Some(vec![a, c, b]);
81	        }
82	    }
83	    None
84	}
