177	    if pts.len() == 2 && fa.is_none() && fb.is_none() {
178	        let (a, b) = (pts[0], pts[1]);
179	        if a.0 != b.0 && (a.0 - b.0).abs() < 1e-6 && (a.1 - b.1).abs() > 1e-6 {
180	            let m = (la.1 + lb.1) / 2.0;
181	            pts = vec![a, (a.0, m), (b.0, m), b];
182	        } else if a.1 != b.1 && (a.1 - b.1).abs() < 1e-6 && (a.0 - b.0).abs() > 1e-6 {
183	            let m = (la.0 + lb.0) / 2.0;
