244	            for side in 0..2 {
245	                let t = if side == 0 { &w.a } else { &w.b };
246	                if t.kind != Kind::Run {
247	                    continue;
248	                }
249	                if runs_met.contains(&t.dev) {
250	                    if let Some(near) = t.through {
251	                        let mut w2 = w.clone();
252	                        let t2 = if side == 0 { &mut w2.a } else { &mut w2.b };
253	                        t2.dir = Dir::of_vec(t2.off.0 - near.0, t2.off.1 - near.1);
254	                        t2.kind = Kind::Other;
255	                        t2.through = None;
256	                        onward = Some(w2);
257	                    }
258	                } else {
259	                    runs_met.push(t.dev);
260	                }
261	            }
262	            if let Some(w2) = onward {
263	                let pass = net_runs(ctx, &wires, w.li);
264	                let back = route_one(ctx, &obs, &owner, &w, so, &pass);
265	                let on = route_one(ctx, &obs, &owner, &w2, so, &pass);
266	                let pts = if path_cost(&on) < path_cost(&back) - 1e-9 { on } else { back };
267	                all.wires.push(Routed { li: w.li, pts, labels: Vec::new(), scope: s });
268	                continue;
269	            }
270	            // a tag attaches by the end facing the other end of its wire (by
271	            // its edge above or below off an upright pin)
272	            let facing = |tag: &Term, other: &Term| -> Dir {
273	                let o = origin_in(ctx, tag.dev, 0);
274	                let p = abs_point(ctx, other);
275	                if other.kind == Kind::Pin && !other.dir.horizontal() {
276	                    if p.1 > o.1 {
277	                        Dir::D
278	                    } else {
279	                        Dir::U
280	                    }
281	                } else if p.0 > o.0 {
282	                    Dir::R
283	                } else {
284	                    Dir::L
285	                }
286	            };
287	            if w.a.kind == Kind::Flag {
288	                let d = facing(&w.a, &w.b);
289	                w.a = super::net::flag_end(ctx, &w.a, d);
290	            }
291	            if w.b.kind == Kind::Flag {
292	                let d = facing(&w.b, &w.a);
293	                w.b = super::net::flag_end(ctx, &w.b, d);
294	            }
295	            let pass = net_runs(ctx, &wires, w.li);
296	            let pts = route_one(ctx, &obs, &owner, &w, so, &pass);
297	            all.wires.push(Routed { li: w.li, pts, labels: Vec::new(), scope: s });
298	        }
299	    }
300	    // wires of different nets sharing a line spread apart
301	    nudge(ctx, &mut all.wires);
302	    // net names along the trace
303	    let routes: Vec<Vec<(f64, f64)>> = all.wires.iter().map(|r| r.pts.clone()).collect();
304	    let mut placed: Vec<[f64; 4]> = Vec::new();
305	    for (wi, r) in all.wires.iter_mut().enumerate() {
306	        let others: Vec<Vec<(f64, f64)>> = routes.iter().enumerate().filter(|(j, _)| *j != wi).map(|(_, p)| p.clone()).collect();
307	        let mut blocks: Vec<[f64; 4]> = placed.clone();
308	        if let Some(list) = raws.iter().find(|(sc, _)| *sc == r.scope) {
309	            // (the wire's own ends aside)
310	            let l = &ctx.links[r.li];
311	            let ends = [super::net::device_of(ctx, r.scope, l.from), super::net::device_of(ctx, r.scope, l.to)];
312	            blocks.extend(list.1.iter().filter(|(d, _)| !ends.contains(&Some(*d))).map(|(_, b)| *b));
313	        }
314	        // each name at its own `along` (the last one standing for the rest)
315	        let alongs: Vec<f64> = ctx.links[r.li]
316	            .style
317	            .iter()
318	            .rev()
319	            .find(|d| d.name == "along")
320	            .map(|d| crate::style::value_nums(&ctx.sheet.env, &d.value))
321	            .unwrap_or_default();
322	        for (k, t) in link_texts(ctx, r.li).into_iter().enumerate() {
323	            let along = alongs.get(k).or(alongs.last()).cloned().unwrap_or(0.5);
324	            let lb = place_label(ctx, &r.pts, along, t, &others, &blocks);
325	            let tw = {
326	                let w = if ctx.comp[0].layout == "schematic" { ctx.comp[0].font_weight } else { 400 };
327	                crate::font::text_width(crate::font::Family::Sans, w, 11.0, &lb.0)
328	            };
329	            let b = label_box(lb.1, lb.2, lb.3, tw);
330	            placed.push(b);
331	
332	            r.labels.push(lb);
333	        }
334	    }
335	    all.junctions = junctions(ctx, &all.wires);
336	    WIRING.with(|w| *w.borrow_mut() = all);
337	}
