1586	fn lay_leader_stmt(ctx: &Ctx, f: usize, st: &St, lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
1587	    // a fan (`a & b <- "x"`): one note, a ray-cast leg onto each further end
1588	    let ones: Vec<usize> = st.links.iter().copied().filter(|&li| ctx.links[li].one_ended).collect();
1589	    if ones.len() > 1 && st.op != ">-" {
1590	        let r = ref_of(ctx, f, ones[0], false)?;
1591	        let base = if r.run.is_some() { thread_spec(ctx, f, &r) } else { None };
1592	        let weight = if base.is_some() && st.label.is_none() { ctx.comp[f].font_weight } else { 400 };
1593	        let text = label_text(st, base);
1594	        let mut note = Vec::new();
1595	        lay_note(ctx, f, st, &r, &text, weight, lay, &mut note)?;
1596	        let knee = match note.first() {
1597	            Some(it) if it.pts.len() >= 2 => it.pts[1],
1598	            _ => r.p,
1599	        };
1600	        let txt = note.pop();
1601	        out.extend(note);
1602	        for &li in &ones[1..] {
1603	            let r2 = ref_of(ctx, f, li, false)?;
1604	            let center = if r2.feature { origin_in(ctx, f, r2.node) } else { r2.p };
1605	            let d = knee.sub(center).unit();
1606	            let tip = if r2.feature { rim(ctx, f, r2.node, d).unwrap_or(center) } else { r2.p };
1607	            let mut leg = Item::new(Kind::Line, "lini-dim-line", vec![tip.add(d.mul(LINE_INSET)), knee]);
1608	            leg.halo = true;
1609	            leg.own_tips = vec![tip];
1610	            out.push(leg);
1611	            let mut m = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(tip, d));
1612	            m.tip = Some(tip);
1613	            out.push(m);
1614	            lay.tips.push(tip);
1615	        }
1616	        if let Some(t) = txt {
1617	            out.push(t);
1618	        }
1619	        return Ok(());
1620	    }
1621	    for &li in &st.links {
1622	        if !ctx.links[li].one_ended {
1623	            lay_connector(ctx, f, st, li, lay, out)?;
1624	            continue;
1625	        }
1626	        let mut r = ref_of(ctx, f, li, false)?;
1627	        // a pattern's leader lands on the copy furthest toward its side
