1666	fn lay_round_stmt(ctx: &Ctx, f: usize, st: &St, lay: &mut Layout, out: &mut Vec<Item>, rows: bool) -> Result<(), Diag> {
1667	    for &li in &st.links {
1668	        let r = ref_of(ctx, f, li, false)?;
1669	        let station = r.run.is_some() && r.twin.is_some();
1670	        if station != rows {
1671	            continue;
1672	        }
1673	        if !station && !r.feature && r.arc.is_none() && ctx.nodes[r.node].prim == Prim::Oval {
1674	            lay_inside_diameter(ctx, f, st, &r, out)?;
1675	            continue;
1676	        }
1677	        if station {
1678	            // a ⌀ station on a revolved run: the run and its twin, measured across
1679	            let (a0, a1) = r.run.unwrap();
1680	            let (b0, b1) = r.twin.unwrap();
1681	            let pa = a0.add(a1).mul(0.5);
1682	            let pb = b0.add(b1).mul(0.5);
1683	            let ra = Ref { run: None, n: None, twin: None, p: pa, ..r.clone() };
1684	            let rb = Ref { run: None, n: None, twin: None, p: pb, ..r.clone() };
1685	            lay_station(ctx, f, st, ra, rb, li, lay, out)?;
1686	        } else {
1687	            lay_round(ctx, f, st, &r, lay, out)?;
1688	        }
1689	    }
1690	    Ok(())
1691	}
