#!/usr/bin/env python3
# genr.py N SEED : stylesheets with several R-phase errors spread over rule kinds
import random, sys
n=int(sys.argv[1]); random.seed(int(sys.argv[2]))
bad=['oklch(1 2)','rgb(300, 0, 0)','(zz)','(1 / 0)','hsl(400, 10%, 10%)','gradient(red)','linear-gradient(red, blue)','oklch(2, 0, 0)']
good=['red','--sky','#123','(1 + 2)','5']
props_paint=['fill','stroke','color']
props_num=['width','height','padding','gap','font-size','stroke-width','radius','opacity']
def val(p):
    if random.random()<0.35:
        v=random.choice(bad)
    else:
        v=random.choice(good)
    if p in props_num and v in ('red','--sky','#123'): v='5'
    if p in props_paint and v in ('5',): v='red'
    return v
def decls(k):
    ps=random.sample(props_paint+props_num, k)
    return '; '.join('%s: %s'%(p,val(p)) for p in ps)
for _ in range(n):
    items=[]
    for _ in range(random.randint(2,6)):
        kind=random.choice(['type','type','class','link','id','define','root','var','scoped'])
        if kind=='type': items.append('|%s| { %s }'%(random.choice(['box','oval','group','text']), decls(random.randint(1,3))))
        elif kind=='class': items.append('.%s { %s }'%(random.choice(['c','d']), decls(random.randint(1,3))))
        elif kind=='link': items.append('|-| { stroke: %s }'%val('stroke'))
        elif kind=='id': items.append('#a { %s }'%decls(random.randint(1,2)))
        elif kind=='define': items.append('|svc::box| { %s }'%decls(random.randint(1,2)))
        elif kind=='root': items.append('%s: %s;'%(random.choice(['padding','gap','font-size','fill','stroke-width']), val('fill' if random.random()<0.3 else 'padding')))
        elif kind=='var': items.append('--v%d: %s;'%(random.randint(0,3), random.choice(bad+good)))
        elif kind=='scoped': items.append('|box| |oval| { %s }'%decls(1))
    body=[]
    body.append(random.choice(['|box#a| "a" .c','|oval#a| "a"','|svc#a| "a" .d','|box#a| [ |oval| "x" ]']))
    if random.random()<0.6: body.append(random.choice(['|oval#b| "b"','|box#b| "b" .c','|group#b| [ "g" ]']))
    if random.random()<0.5: body.append('a -> %s'%random.choice(['b','zz']))
    if random.random()<0.3: body.append('|box| "q" { %s }'%decls(1))
    print('{\n  '+'\n  '.join(items)+'\n}\n'+'\n'.join(body))
    print('----')

