984	fn lay_aligned(ctx: &Ctx, f: usize, st: &St, lin: &Lin, k: f64, _lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
985	    let (a, b) = (&lin.a, &lin.b);
