#!/usr/bin/env python3
# strays.py files... : the original's stray lines, with the end devices' rects (absolute, top-level only)
import sys, os, subprocess, re
for f in sys.argv[1:]:
    d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
    o = subprocess.run(['/workspace/executable', b], cwd=d, capture_output=True, text=True).stdout
    for m in re.finditer(r'<g class="lini-stray" data-from="([^"]+)" data-to="([^"]+)">\s*<path d="([^"]+)"', o):
        print(b, m.group(1), '->', m.group(2), ':', m.group(3))
        for dev in (m.group(1).split('.')[0], m.group(2).split('.')[0]):
            mm = re.search(r'data-id="%s" transform="translate\(([-\d.]+),([-\d.]+)\)">\s*<rect x="([-\d.]+)" y="([-\d.]+)" width="([-\d.]+)" height="([-\d.]+)"' % re.escape(dev), o)
            if mm:
                tx, ty, x, y, w, h = map(float, mm.groups())
                print('    %s at (%g,%g) rect [%g, %g] x [%g, %g]' % (dev, tx, ty, tx + x, tx + x + w, ty + y, ty + y + h))

