1	// An orthogonal search between two fixed ports. Every drawn box is an
2	// obstacle, grown by the clearance. A wire leaves its port straight along
3	// the port's facing until it is clear of its own body (the landing), then
4	// searches a sparse grid — the scope's lattice lines and the obstacles'
5	// edges — for the cheapest route: length plus two clearances per bend.
6	// Segment placement follows: a staircase step centres in its channel, on
7	// the lattice line nearest the middle when the channel holds one; a detour
8	// keeps to the first lattice line clear of what it goes around, or centres
9	// between that and whatever lies beyond.
10	
11	use super::net::Dir;
12	use std::collections::BinaryHeap;
13	
14	const EPS: f64 = 1e-6;
15	const PITCH: f64 = 20.0;
16	
17	#[derive(Clone, Copy, Debug)]
18	pub struct Rect {
19	    pub x0: f64,
20	    pub y0: f64,
21	    pub x1: f64,
22	    pub y1: f64,
23	}
24	
25	impl Rect {
26	    pub fn new(x0: f64, y0: f64, x1: f64, y1: f64) -> Rect {
27	        Rect { x0, y0, x1, y1 }
28	    }
29	    pub fn grow(&self, k: f64) -> Rect {
30	        Rect::new(self.x0 - k, self.y0 - k, self.x1 + k, self.y1 + k)
31	    }
32	}
33	
34	#[derive(Clone, Copy, Debug)]
35	pub struct Port {
36	    pub p: (f64, f64),
37	    // the way the wire leaves the port
38	    pub d: Dir,
39	    // one of the port's own obstacles (its body: left straight from the port)
40	    pub own: Option<usize>,
41	    // the wire may leave the port any way but back
42	    pub free: bool,
43	    // a part's station: a detour off it keeps to its landing
44	    pub station: bool,
45	}
46	
47	pub struct World {
48	    pub obs: Vec<Rect>,
49	    // what segment placement measures channels against (a part's own
50	    // drawing at its full clearance)
51	    pub place_obs: Vec<Rect>,
52	    pub owner: Vec<usize>,
53	    // the lattice origin (the scope's centre)
54	    pub lattice: (f64, f64),
55	}
56	
57	fn idx(d: Dir) -> usize {
58	    match d {
59	        Dir::R => 0,
60	        Dir::D => 1,
61	        Dir::L => 2,
62	        Dir::U => 3,
63	    }
64	}
65	
66	const DIRS: [Dir; 4] = [Dir::R, Dir::D, Dir::L, Dir::U];
67	
68	// is the segment p-q clear of every obstacle's open interior (but `skip`)?
69	pub fn seg_clear(obs: &[Rect], skip: &[usize], p: (f64, f64), q: (f64, f64)) -> bool {
70	    let (x0, x1) = (p.0.min(q.0), p.0.max(q.0));
71	    let (y0, y1) = (p.1.min(q.1), p.1.max(q.1));
72	    for (k, r) in obs.iter().enumerate() {
73	        if skip.contains(&k) {
74	            continue;
75	        }
76	        if (y1 - y0).abs() < EPS {
77	            if y0 > r.y0 + EPS && y0 < r.y1 - EPS && x0 < r.x1 - EPS && x1 > r.x0 + EPS {
78	                return false;
79	            }
80	        } else if x0 > r.x0 + EPS && x0 < r.x1 - EPS && y0 < r.y1 - EPS && y1 > r.y0 + EPS {
81	            return false;
82	        }
83	    }
84	    true
85	}
86	
