88	    fn own_set(&self, p: &Port) -> Vec<usize> {
89	        match p.own {
90	            Some(k) => (0..self.obs.len()).filter(|&j| self.owner[j] == self.owner[k]).collect(),
91	            None => vec![],
92	        }
93	    }
94	
95	    // out of a port along its facing, past every own obstacle it meets (a
96	    // free port is entered where it lies)
97	    pub fn landing(&self, port: &Port) -> (f64, f64) {
98	        let mut p = port.p;
99	        if port.free {
100	            return p;
101	        }
102	        let own = self.own_set(port);
103	        loop {
104	            let mut moved = false;
105	            for &k in &own {
106	                let r = self.obs[k];
107	                let on = match port.d {
108	                    Dir::R | Dir::L => p.1 > r.y0 + EPS && p.1 < r.y1 - EPS && p.0 > r.x0 - EPS && p.0 < r.x1 - EPS,
109	                    Dir::U | Dir::D => p.0 > r.x0 + EPS && p.0 < r.x1 - EPS && p.1 > r.y0 - EPS && p.1 < r.y1 - EPS,
110	                };
111	                if !on {
112	                    continue;
113	                }
114	                let q = match port.d {
115	                    Dir::R => (r.x1, p.1),
116	                    Dir::L => (r.x0, p.1),
117	                    Dir::D => (p.0, r.y1),
118	                    Dir::U => (p.0, r.y0),
119	                };
120	                if (q.0 - p.0).abs() > EPS || (q.1 - p.1).abs() > EPS {
121	                    p = q;
122	                    moved = true;
123	                }
124	            }
125	            if !moved {
126	                break;
127	            }
128	        }
129	        p
130	    }
131	
132	    fn lattice_lines(&self, lo: f64, hi: f64, o: f64) -> Vec<f64> {
133	        let mut v = Vec::new();
134	        let mut k = ((lo - o) / PITCH).ceil();
135	        while k * PITCH + o <= hi + EPS {
136	            v.push(k * PITCH + o);
137	            k += 1.0;
138	        }
139	        v
140	    }
141	
142	    // the cheapest route between two ports: length plus `bend` per bend
143	    pub fn search(&self, a: &Port, b: &Port, bend: f64) -> Option<Vec<(f64, f64)>> {
144	        let la = self.landing(a);
145	        let lb = self.landing(b);
146	        let skip_a = self.own_set(a);
147	        let skip_b = self.own_set(b);
148	        let mut xs = vec![la.0, lb.0];
149	        let mut ys = vec![la.1, lb.1];
150	        let (mut x0, mut y0, mut x1, mut y1) = (la.0.min(lb.0), la.1.min(lb.1), la.0.max(lb.0), la.1.max(lb.1));
151	        for r in &self.obs {
152	            xs.push(r.x0);
153	            xs.push(r.x1);
154	            ys.push(r.y0);
155	            ys.push(r.y1);
156	            x0 = x0.min(r.x0);
157	            y0 = y0.min(r.y0);
158	            x1 = x1.max(r.x1);
159	            y1 = y1.max(r.y1);
160	        }
161	        xs.extend(self.lattice_lines(x0 - 2.0 * PITCH, x1 + 2.0 * PITCH, self.lattice.0));
162	        ys.extend(self.lattice_lines(y0 - 2.0 * PITCH, y1 + 2.0 * PITCH, self.lattice.1));
163	        let xs = uniq(xs);
164	        let ys = uniq(ys);
165	        let nx = xs.len();
166	        let ny = ys.len();
167	        let find = |v: &[f64], x: f64| v.iter().position(|t| (t - x).abs() < 1e-7);
168	        let (sx, sy) = (find(&xs, la.0)?, find(&ys, la.1)?);
169	        let (gx, gy) = (find(&xs, lb.0)?, find(&ys, lb.1)?);
170	        let state = |ix: usize, iy: usize, d: usize| (iy * nx + ix) * 4 + d;
171	        let n = nx * ny * 4;
172	        let mut dist = vec![f64::INFINITY; n];
173	        let mut prev = vec![usize::MAX; n];
174	        let mut heap = BinaryHeap::new();
175	        let mut seq = 0u64;
176	        let start = state(sx, sy, idx(a.d));
177	        dist[start] = 0.0;
178	        heap.push(Item { cost: 0.0, seq, state: start });
179	        let want = idx(b.d.opposite());
180	        let order: Vec<Dir> = match std::env::var("LINI_SCH_DIRS") {
181	            Ok(v) => v
182	                .chars()
183	                .filter_map(|c| match c {
184	                    'L' => Some(Dir::L),
185	                    'R' => Some(Dir::R),
186	                    'U' => Some(Dir::U),
187	                    'D' => Some(Dir::D),
188	                    _ => None,
189	                })
190	                .collect(),
191	            Err(_) => DIRS.to_vec(),
192	        };
193	        let mut best: Option<(f64, usize)> = None;
194	        while let Some(Item { cost, state: st, .. }) = heap.pop() {
195	            if cost > dist[st] + EPS {
196	                continue;
197	            }
198	            if let Some((bc, _)) = best {
199	                if cost > bc + EPS {
200	                    break;
201	                }
202	            }
203	            let d = st % 4;
204	            let cell = st / 4;
205	            let (ix, iy) = (cell % nx, cell / nx);
206	            if ix == gx && iy == gy {
207	                let extra = if b.free {
208	                    if d == (want + 2) % 4 {
209	                        f64::INFINITY
210	                    } else {
211	                        0.0
212	                    }
213	                } else if d == want {
214	                    0.0
215	                } else if (d + 2) % 4 == want {
216	                    f64::INFINITY
217	                } else {
218	                    bend
219	                };
220	                if extra.is_finite() {
221	                    let c = cost + extra;
222	                    if best.map_or(true, |(bc, _)| c < bc - EPS) {
223	                        best = Some((c, st));
224	                    }
225	                }
226	            }
227	            for nd in order.iter() {
228	                let k = idx(*nd);
229	                if k == (d + 2) % 4 {
230	                    continue;
231	                }
232	                let (jx, jy) = match nd {
233	                    Dir::R if ix + 1 < nx => (ix + 1, iy),
234	                    Dir::L if ix > 0 => (ix - 1, iy),
235	                    Dir::D if iy + 1 < ny => (ix, iy + 1),
236	                    Dir::U if iy > 0 => (ix, iy - 1),
237	                    _ => continue,
238	                };
239	                let p = (xs[ix], ys[iy]);
240	                let q = (xs[jx], ys[jy]);
241	                if !seg_clear(&self.obs, &[], p, q) {
242	                    let mut ok = false;
243	                    if seg_clear(&self.obs, &skip_a, p, q) && on_stub(a, la, p, q) {
244	                        ok = true;
245	                    }
246	                    if seg_clear(&self.obs, &skip_b, p, q) && on_stub(b, lb, p, q) {
247	                        ok = true;
248	                    }
249	                    // a free port is reached along its own lines through
250	                    // what it owns
251	                    for (port, skip) in [(a, &skip_a), (b, &skip_b)] {
252	                        if port.free && seg_clear(&self.obs, skip, p, q) {
253	                            let along = if (p.1 - q.1).abs() < EPS { (p.1 - port.p.1).abs() < EPS } else { (p.0 - port.p.0).abs() < EPS };
254	                            if along {
255	                                ok = true;
256	                            }
257	                        }
258	                    }
259	                    if !ok {
260	                        continue;
261	                    }
262	                }
263	                let len = (q.0 - p.0).abs() + (q.1 - p.1).abs();
264	                let turn = if k == d || (st == start && a.free) { 0.0 } else { bend };
265	                let nc = cost + len + turn;
266	                let ns = state(jx, jy, k);
267	                if nc < dist[ns] - EPS {
268	                    dist[ns] = nc;
269	                    prev[ns] = st;
270	                    seq += 1;
271	                    heap.push(Item { cost: nc, seq, state: ns });
272	                }
273	            }
274	        }
275	        let (_, mut st) = best?;
276	        let mut cells: Vec<(f64, f64)> = Vec::new();
277	        loop {
278	            let cell = st / 4;
279	            cells.push((xs[cell % nx], ys[cell / nx]));
280	            if prev[st] == usize::MAX {
281	                break;
282	            }
283	            st = prev[st];
284	        }
285	        cells.reverse();
286	        let mut pts = vec![a.p];
287	        pts.extend(cells);
288	        pts.push(b.p);
289	        let mut pts = simplify(&pts);
290	        if std::env::var("LINI_SCH_DBG").is_ok() {
291	            eprintln!("  raw path {:?} cost {:?}", pts, best.map(|b| b.0));
292	        }
293	        self.place(&mut pts, la, lb, a.station, b.station);
294	        Some(simplify(&pts))
295	    }
296	
297	    // the lattice line nearest `m` within [lo, hi] (halves toward the lower),
298	    // else `m`
299	    fn snap_within(&self, m: f64, lo: f64, hi: f64, o: f64) -> f64 {
300	        let k = (((m - o) / PITCH) - 0.5 + 1e-9).ceil();
301	        let near = k * PITCH + o;
302	        let mut cands: Vec<f64> = vec![near, near - PITCH, near + PITCH];
303	        cands.retain(|c| *c >= lo - EPS && *c <= hi + EPS);
304	        cands.sort_by(|a, b| {
305	            let da = (a - m).abs();
306	            let db = (b - m).abs();
307	            da.partial_cmp(&db).unwrap().then(a.partial_cmp(b).unwrap())
308	        });
309	        cands.first().cloned().unwrap_or(m)
310	    }
311	
312	    // segment placement: steps centre in their channel; detours hug, or
313	    // centre between what they go around and what lies beyond
314	    fn place(&self, pts: &mut Vec<(f64, f64)>, la: (f64, f64), lb: (f64, f64), sa: bool, sb: bool) {
315	        let n = pts.len();
316	        if n < 4 {
317	            return;
318	        }
319	        for k in 1..n - 2 {
320	            let (a, b, c, d) = (pts[k - 1], pts[k], pts[k + 1], pts[k + 2]);
321	            let vert = (b.0 - c.0).abs() < EPS;
322	            let (before, after) = if vert { (b.0 - a.0, d.0 - c.0) } else { (b.1 - a.1, d.1 - c.1) };
323	            let step = before * after > 0.0;
324	            let (s0, s1) = if vert { (b.1.min(c.1), b.1.max(c.1)) } else { (b.0.min(c.0), b.0.max(c.0)) };
325	            let pos = if vert { b.0 } else { b.1 };
326	            let o = if vert { self.lattice.0 } else { self.lattice.1 };
327	            // the free channel across the segment
328	            let mut clo = f64::NEG_INFINITY;
329	            let mut chi = f64::INFINITY;
330	            for r in &self.place_obs {
331	                let (a0, a1, b0, b1) = if vert { (r.y0, r.y1, r.x0, r.x1) } else { (r.x0, r.x1, r.y0, r.y1) };
332	                if a0 < s1 - EPS && a1 > s0 + EPS {
333	                    if b1 <= pos + EPS && b1 > clo {
334	                        clo = b1;
335	                    }
336	                    if b0 >= pos - EPS && b0 < chi {
337	                        chi = b0;
338	                    }
339	                    // a box the segment already stands in (a part's own
340	                    // drawing at its full clearance) bounds it on its side
341	                    if b0 < pos - EPS && b1 > pos + EPS {
342	                        if (b0 + b1) / 2.0 > pos {
343	                            chi = chi.min(b0);
344	                        } else {
345	                            clo = clo.max(b1);
346	                        }
347	                    }
348	                }
349	            }
350	            // the ports' runs keep their landings
351	            let mut lo = f64::NEG_INFINITY;
352	            let mut hi = f64::INFINITY;
353	            if k == 1 {
354	                let l = if vert { la.0 } else { la.1 };
355	                if before > 0.0 {
356	                    lo = lo.max(l);
357	                } else {
358	                    hi = hi.min(l);
359	                }
360	            }
361	            if k + 2 == n - 1 {
362	                let l = if vert { lb.0 } else { lb.1 };
363	                if after > 0.0 {
364	                    hi = hi.min(l);
365	                } else {
366	                    lo = lo.max(l);
367	                }
368	            }
369	            let m = if step {
370	                // within both neighbours' spans
371	                let (sl, sh) = if vert { (a.0.min(d.0), a.0.max(d.0)) } else { (a.1.min(d.1), a.1.max(d.1)) };
372	                let lo = lo.max(sl).max(clo);
373	                let hi = hi.min(sh).min(chi);
374	                if !lo.is_finite() || !hi.is_finite() || hi < lo - EPS {
375	                    continue;
376	                }
377	                self.snap_within((lo + hi) / 2.0, lo, hi, o)
378	            } else {
379	                // a detour off a part's station keeps to the station's landing
380	                if (k == 1 && sa) || (k + 2 == n - 1 && sb) {
381	                    continue;
382	                }
383	                // a detour: its neighbours come from the side it goes around
384	                let toward_low = before > 0.0;
385	                let (hug, beyond) = if toward_low { (clo, chi) } else { (chi, clo) };
386	                if !hug.is_finite() {
387	                    continue;
388	                }
389	                // the first lattice line clear of what it goes around
390	                let first = if toward_low {
391	                    (((hug - o) / PITCH) - 1e-9).ceil() * PITCH + o
392	                } else {
393	                    (((hug - o) / PITCH) + 1e-9).floor() * PITCH + o
394	                };
395	                if beyond.is_finite() {
396	                    let (l2, h2) = if toward_low { (hug, beyond) } else { (beyond, hug) };
397	                    if h2 < l2 - EPS {
398	                        continue;
399	                    }
400	                    self.snap_within((l2 + h2) / 2.0, l2.max(lo), h2.min(hi), o)
401	                } else {
402	                    if first < lo - EPS || first > hi + EPS {
403	                        continue;
404	                    }
405	                    first
406	                }
407	            };
408	            if vert {
409	                pts[k].0 = m;
410	                pts[k + 1].0 = m;
411	            } else {
412	                pts[k].1 = m;
413	                pts[k + 1].1 = m;
414	            }
415	        }
416	    }
417	}
418	
419	fn uniq(mut v: Vec<f64>) -> Vec<f64> {
420	    v.retain(|x| x.is_finite());
421	    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
422	    let mut o: Vec<f64> = Vec::new();
423	    for x in v {
424	        if o.last().map_or(true, |l: &f64| (x - *l).abs() > 1e-7) {
425	            o.push(x);
426	        }
427	    }
428	    o
429	}
430	
431	#[derive(PartialEq)]
432	struct Item {
433	    cost: f64,
434	    seq: u64,
435	    state: usize,
436	}
437	impl Eq for Item {}
438	impl PartialOrd for Item {
439	    fn partial_cmp(&self, o: &Self) -> Option<std::cmp::Ordering> {
440	        Some(self.cmp(o))
441	    }
442	}
443	impl Ord for Item {
444	    fn cmp(&self, o: &Self) -> std::cmp::Ordering {
445	        // costs equal to a millionth tie, the earlier found first
446	        let q = |c: f64| (c * 1e6).round() as i64;
447	        q(o.cost).cmp(&q(self.cost)).then(o.seq.cmp(&self.seq))
448	    }
449	}
450	
451	pub fn simplify(pts: &[(f64, f64)]) -> Vec<(f64, f64)> {
452	    let mut o: Vec<(f64, f64)> = Vec::new();
453	    for &p in pts {
454	        if let Some(l) = o.last() {
455	            if (l.0 - p.0).abs() < EPS && (l.1 - p.1).abs() < EPS {
456	                continue;
457	            }
458	        }
459	        o.push(p);
460	    }
461	    let mut k = 1;
462	    while k + 1 < o.len() {
463	        let (a, b, c) = (o[k - 1], o[k], o[k + 1]);
464	        let col = ((a.0 - b.0).abs() < EPS && (b.0 - c.0).abs() < EPS) || ((a.1 - b.1).abs() < EPS && (b.1 - c.1).abs() < EPS);
465	        if col {
466	            o.remove(k);
467	        } else {
468	            k += 1;
469	        }
470	    }
471	    o
472	}
473	
474	fn on_stub(port: &Port, land: (f64, f64), p: (f64, f64), q: (f64, f64)) -> bool {
475	    let within = |t: (f64, f64)| {
476	        let (x0, x1) = (port.p.0.min(land.0), port.p.0.max(land.0));
477	        let (y0, y1) = (port.p.1.min(land.1), port.p.1.max(land.1));
478	        t.0 >= x0 - EPS && t.0 <= x1 + EPS && t.1 >= y0 - EPS && t.1 <= y1 + EPS
479	    };
480	    within(p) && within(q)
481	}
