pub fn text_block_height(ctx: &Ctx, i: usize, nlines: usize) -> f64 {
    let c = &ctx.comp[i];
    if nlines <= 1 {
        c.font_size
    } else {
        nlines as f64 * 1.2 * c.font_size + (nlines as f64 - 1.0) * c.line_spacing
    }
}

pub fn measure_text(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
    let raw = ctx.nodes[i].text.clone().unwrap_or_default();
    let tt = ctx.comp[i].text_transform.clone();
    let text = transform_text(raw.trim(), &tt);
    let lines: Vec<String> = match avail {
        Some(m) if !ctx.comp[i].nowrap => wrap(ctx, i, &text, m),
        _ => text.split('\n').map(|s| s.to_string()).collect(),
    };
    let mut w: f64 = 0.0;
    for l in &lines {
        w = w.max(line_width(ctx, i, l));
    }
    let h = text_block_height(ctx, i, lines.len());
    let n = &mut ctx.nodes[i];
    n.lines = lines;
    n.w = w;
    n.h = h;

832:fn grid(
986:pub struct Bridge {
996:pub struct BridgePlan {
1015:fn bridge_spans(ctx: &Ctx, anchors: &[usize], b: &Bridge) -> bool {
1037:pub fn find_bridges(ctx: &Ctx, anchors: &[usize], wires: &[super::net::Wire]) -> Vec<Bridge> {
1097:fn plan_bridge(ctx: &Ctx, b: &Bridge, margin: f64) -> BridgePlan {

832	fn grid(
833	    ctx: &Ctx,
834	    _scope: usize,
835	    anchors: &[usize],
836	    reach: &[[f64; 4]],
837	    row_gap: f64,
838	    col_gap: f64,
839	    pos: &mut Vec<(usize, f64, f64)>,
840	    wires: &[super::net::Wire],
841	    bridges: &mut [BridgePlan],
842	) {
843	    use super::net::{Dir, Kind};
844	    let cells: Vec<(usize, usize, usize)> = anchor_cells(ctx, anchors).into_iter().zip(anchors).map(|((c, r), &k)| (k, c, r)).collect();
845	    // collapse empty tracks
846	    let mut cols: Vec<usize> = cells.iter().map(|c| c.1).collect();
847	    cols.sort();
848	    cols.dedup();
849	    let mut rows: Vec<usize> = cells.iter().map(|c| c.2).collect();
850	    rows.sort();
851	    rows.dedup();
852	    let exts: Vec<[f64; 4]> = reach.to_vec();
853	    let col_of = |c: usize| cols.iter().position(|&x| x == c).unwrap();
854	    let row_of = |r: usize| rows.iter().position(|&x| x == r).unwrap();
855	    // wires straight across a gap: the pitch keeps a pitch per wire, and the
856	    // first wire between two anchors lines their pins up (the anchor whose
857	    // pin sits nearer the low end steps toward the other's)
858	    let mut shift = vec![(0.0f64, 0.0f64); anchors.len()];
859	    let mut col_wires = vec![0usize; cols.len()];
860	    let mut row_wires = vec![0usize; rows.len()];
861	    let mut paired: Vec<(usize, usize)> = Vec::new();
862	    for w in wires {
863	        let at = |dev: usize| anchors.iter().position(|&a| a == dev);
864	        let (ia, ib) = match (at(w.a.dev), at(w.b.dev)) {
865	            (Some(a), Some(b)) if a != b => (a, b),
866	            _ => continue,
867	        };
868	        if !matches!(w.a.kind, Kind::Pin | Kind::Station) || !matches!(w.b.kind, Kind::Pin | Kind::Station) {
869	            continue;
870	        }
871	        let (ca, ra) = (col_of(cells[ia].1), row_of(cells[ia].2));
872	        let (cb, rb) = (col_of(cells[ib].1), row_of(cells[ib].2));
873	        if ra == rb && ca.abs_diff(cb) == 1 {
874	            let (l, r, tl, tr) = if ca < cb { (ia, ib, &w.a, &w.b) } else { (ib, ia, &w.b, &w.a) };
875	            col_wires[ca.max(cb)] += 1;
876	            if tl.dir == Dir::R && tr.dir == Dir::L {
877	                if !paired.contains(&(l, r)) {
878	                    paired.push((l, r));
879	                    let (yl, yr) = (shift[l].1 + tl.off.1, shift[r].1 + tr.off.1);
880	                    if yl < yr {
881	                        shift[l].1 += yr - yl;
882	                    } else {
883	                        shift[r].1 += yl - yr;
884	                    }
885	                }
886	            }
887	        } else if ca == cb && ra.abs_diff(rb) == 1 {
888	            let (u, d, tu, td) = if ra < rb { (ia, ib, &w.a, &w.b) } else { (ib, ia, &w.b, &w.a) };
889	            row_wires[ra.max(rb)] += 1;
890	            if tu.dir == Dir::D && td.dir == Dir::U {
891	                if !paired.contains(&(u, d)) {
892	                    paired.push((u, d));
893	                    let (xu, xd) = (shift[u].0 + tu.off.0, shift[d].0 + td.off.0);
894	                    if xu < xd {
895	                        shift[u].0 += xd - xu;
896	                    } else {
897	                        shift[d].0 += xu - xd;
898	                    }
899	                }
900	            }
901	        }
902	    }
903	    // a bridge across a gap lines its pins up like a wire
904	    for b in bridges.iter_mut() {
905	        let (ca, ra) = (col_of(cells[b.a].1), row_of(cells[b.a].2));
906	        let (cb, rb) = (col_of(cells[b.b].1), row_of(cells[b.b].2));
907	        if ra != rb || ca.abs_diff(cb) != 1 {
908	            continue;
909	        }
910	        let facing = if ca < cb { b.pa.dir == Dir::R && b.pb.dir == Dir::L } else { b.pa.dir == Dir::L && b.pb.dir == Dir::R };
911	        if !facing {
912	            continue;
913	        }
914	        b.used = true;
915	        let (l, r) = if ca < cb { (b.a, b.b) } else { (b.b, b.a) };
916	        if !paired.contains(&(l, r)) {
917	            paired.push((l, r));
918	            let (ya, yb) = (shift[b.a].1 + b.pa.off.1, shift[b.b].1 + b.pb.off.1);
919	            if ya < yb {
920	                shift[b.a].1 += yb - ya;
921	            } else {
922	                shift[b.b].1 += ya - yb;
923	            }
924	        }
925	    }
926	    let mut left = vec![0.0f64; cols.len()];
927	    let mut right = vec![0.0f64; cols.len()];
928	    let mut top = vec![0.0f64; rows.len()];
929	    let mut bottom = vec![0.0f64; rows.len()];
930	    for (k, c) in cells.iter().enumerate() {
931	        let (ci, ri) = (col_of(c.1), row_of(c.2));
932	        let (sx, sy) = shift[k];
933	        left[ci] = left[ci].max(-(exts[k][0] + sx));
934	        right[ci] = right[ci].max(exts[k][2] + sx);
935	        top[ri] = top[ri].max(-(exts[k][1] + sy));
936	        bottom[ri] = bottom[ri].max(exts[k][3] + sy);
937	    }
938	    let mut colx = vec![0.0; cols.len()];
939	    for k in 1..cols.len() {
940	        let need = ceil_lattice(right[k - 1] + left[k] + PITCH * col_wires[k].max(1) as f64);
941	        let mut pitch = need.max(ceil_lattice(col_gap));
942	        // a bridge stands a pitch past its first anchor's reach, the next
943	        // anchor the gap (or its reach) past the bridge's last part
944	        for b in bridges.iter_mut().filter(|b| b.used) {
945	            let (ca, cb) = (col_of(cells[b.a].1), col_of(cells[b.b].1));
946	            if ca.max(cb) != k {
947	                continue;
948	            }
949	            let (ea, eb) = (&reach[b.a], &reach[b.b]);
950	            let (sxa, sxb) = (shift[b.a].0, shift[b.b].0);
951	            let (near_a, near_b) = if ca < cb { (ea[2] + sxa, -(eb[0] + sxb)) } else { (-(ea[0] + sxa), eb[2] + sxb) };
952	            let first = ceil_lattice(near_a + PITCH + b.h_first);
953	            let tail = ceil_lattice((col_gap).max(b.h_last + near_b));
954	            b.first = first;
955	            pitch = pitch.max(first + b.span + tail);
956	        }
957	        colx[k] = colx[k - 1] + pitch;
958	    }
959	    let mut rowy = vec![0.0; rows.len()];
960	    for k in 1..rows.len() {
961	        let need = ceil_lattice(bottom[k - 1] + top[k] + PITCH * row_wires[k].max(1) as f64);
962	        rowy[k] = rowy[k - 1] + need.max(ceil_lattice(row_gap));
963	    }
964	    for (k, c) in cells.iter().enumerate() {
965	        pos.push((c.0, colx[col_of(c.1)] + shift[k].0, rowy[row_of(c.2)] + shift[k].1));
966	    }
967	    // the bridges' parts, from their first anchor
968	    for b in bridges.iter_mut().filter(|b| b.used) {
969	        let dir = if b.pa.dir == Dir::R { 1.0 } else { -1.0 };
970	        let mut seats = Vec::new();
971	        for &(rx, ry, res) in &b.rel {
972	            let x = dir * b.first + rx;
973	            let y = b.pa.off.1 + ry;
974	            let res = if dir > 0.0 {
975	                [res[0] + b.first, res[1] + b.pa.off.1, res[2] + b.first, res[3] + b.pa.off.1]
976	            } else {
977	                [res[0] - b.first, res[1] + b.pa.off.1, res[2] - b.first, res[3] + b.pa.off.1]
978	            };
979	            seats.push((x, y, res));
980	        }
981	        b.seats = seats;
982	    }
983	}
984	
985	// a chain of two-pin parts between pins of two anchors
986	pub struct Bridge {
987	    // anchor indices: the chain's first end, its last
988	    pub a: usize,
989	    pub b: usize,
990	    pub pa: super::net::Term,
991	    pub pb: super::net::Term,
992	    // (part, its entry term)
993	    pub parts: Vec<(usize, super::net::Term)>,
994	}
995	
996	pub struct BridgePlan {
997	    a: usize,
998	    b: usize,
999	    pa: super::net::Term,
1000	    pb: super::net::Term,
1001	    // the parts relative to the first one's place on its anchor's side:
1002	    // (x, y off the pin's row, reserved box)
1003	    rel: Vec<(f64, f64, [f64; 4])>,
1004	    // the first part's reach toward its anchor, the last one's away
1005	    h_first: f64,
1006	    h_last: f64,
1007	    // the last part's centre from the first's
1008	    span: f64,
1009	    // the first part's centre from its anchor (set by the grid)
1010	    first: f64,
1011	    used: bool,
1012	    seats: Vec<(f64, f64, [f64; 4])>,
1013	}
1014	
1015	fn bridge_spans(ctx: &Ctx, anchors: &[usize], b: &Bridge) -> bool {
1016	    let cells = anchor_cells(ctx, anchors);
1017	    let (ca, ra) = cells[b.a];
1018	    let (cb, rb) = cells[b.b];
1019	    let mut cols: Vec<usize> = cells.iter().map(|c| c.0).collect();
1020	    cols.sort();
1021	    cols.dedup();
1022	    let ia = cols.iter().position(|&c| c == ca).unwrap_or(0);
1023	    let ib = cols.iter().position(|&c| c == cb).unwrap_or(0);
1024	    if ra != rb || ia.abs_diff(ib) != 1 {
1025	        return false;
1026	    }
1027	    use super::net::Dir;
1028	    if ia < ib {
1029	        b.pa.dir == Dir::R && b.pb.dir == Dir::L
1030	    } else {
1031	        b.pa.dir == Dir::L && b.pb.dir == Dir::R
1032	    }
1033	}
1034	
1035	// chains of two-pin parts from one anchor's pin to another anchor's, in
1036	// statement order
1037	pub fn find_bridges(ctx: &Ctx, anchors: &[usize], wires: &[super::net::Wire]) -> Vec<Bridge> {
