# gengrid.py N SEED : grid layouts with random tracks, spans, cells and alignment
import random, sys
n=int(sys.argv[1]); random.seed(int(sys.argv[2]))
def tracks():
    k=random.randint(1,4)
    opts=['auto','80','40','120','repeat(2, 60)','repeat(3)','repeat(2, auto)']
    return ', '.join(random.choice(opts) for _ in range(k))
labels=['"a"','"bb"','"a longer label"','"L1\\nL2"']
for _ in range(n):
    st=['layout: grid','columns: %s'%tracks()]
