    if random.random()<0.5: st.append('gap: %s'%random.choice(['0','8','4 12']))
    if random.random()<0.4: st.append('align: %s'%random.choice(['start','end','center','stretch']))
    if random.random()<0.4: st.append('justify: %s'%random.choice(['start','end','center','stretch']))
    if random.random()<0.3: st.append('padding: %s'%random.choice(['0','10']))
    kids=[]
    for _ in range(random.randint(1,7)):
        t=random.choice(['box','oval','box','group'])
        ks=[]
        if random.random()<0.25: ks.append('span: %s'%random.choice(['2','1 2','2 2']))
        if random.random()<0.15: ks.append('cell: %s'%random.choice(['1 1','2 1','1 2','3 2']))
        if random.random()<0.2: ks.append(random.choice(['width: 30','height: 70','align: end']))
        s='|%s| %s'%(t,random.choice(labels))
        if ks: s+=' { %s }'%'; '.join(ks)
        kids.append(s)
    if random.random()<0.3: kids.append(random.choice(labels))
    top='|box| { %s } [ %s ]'%('; '.join(st), '; '.join(kids))
    print(top)
    print('----')

