#!/usr/bin/env python3
# surface finish, balloons, notes, leaders with variety, datums
import random
random.seed(23)
out = []
for t in range(60):
    w = random.choice([40, 60, 80])
    h = random.choice([20, 30, 40])
    src = '{ layout: drawing; }\n|rect#plate| { width: %d; height: %d; } [ |hole#pin| { width: 8; translate: %d %d; } ]\n' % (w, h, random.choice([-10, 0, 10]), random.choice([-5, 0, 5]))
    stmts = []
    for k in range(random.randint(1, 4)):
        kind = random.choice(['sf', 'balloon', 'note', 'leader', 'dot', 'datum', 'sfseat', 'fan'])
        side = random.choice(['top', 'bottom', 'left', 'right', None])
        sd = '' if side is None else ' { side: %s; }' % side
        anchor = random.choice(['plate:top', 'plate:bottom', 'plate:left', 'plate:right', 'plate.pin', 'plate:top-right', 'plate'])
        if kind == 'sf':
            stmts.append('|surface-finish| "%s" { symbol: %s; translate: %d %d; }' % (random.choice(['Ra 1.6', 'Ra 0.8', '']), random.choice(['basic', 'machined', 'prohibited']), random.choice([-20, 0, 20]), random.choice([-30, 30])))
        elif kind == 'sfseat':
            stmts.append('|surface-finish#sf%d| "Ra 3.2" { symbol: machined; }\nsf%d || %s' % (k, k, random.choice(['plate:top', 'plate:bottom', 'plate:left', 'plate:right'])))
        elif kind == 'balloon':
            stmts.append('|balloon#b%d| "%d" { translate: %d %d; }\nb%d -* %s' % (k, k + 1, random.choice([-40, 40]), random.choice([-30, 30]), k, anchor))
        elif kind == 'note':
            stmts.append('|note| "%s" { translate: %d %d; }' % (random.choice(['DEBURR', 'BREAK ALL EDGES', 'NOTE 1']), random.choice([-30, 30]), random.choice([-30, 30])))
        elif kind == 'leader':
            stmts.append('%s <- "%s"%s' % (anchor, random.choice(['THRU', 'R3 TYP', '2× M6']), sd))
        elif kind == 'dot':
