            b[0] = b[0].min(nb[0]);
            b[1] = b[1].min(nb[1]);
            b[2] = b[2].max(nb[2]);
            b[3] = b[3].max(nb[3]);
        }
        if n.prim != Prim::Text {
            for &ch in &n.children {
                go(ctx, ch, &m, b, horiz, lo, hi);
            }
        }
    }
