s=open(p).read()
def rep(old,new,cnt=1):
    global s
    assert s.count(old) >= cnt, old[:70]
    s=s.replace(old,new,cnt)

# 1. thread-local ink + helpers after the constants
rep('''pub const FONT: f64 = 12.0;''','''pub const FONT: f64 = 12.0;

// The statement being laid out: its stroke width (arrowheads and insets
// scale with it) and its text size (the text stands half its size + 2 off
// the line).
thread_local! {
    static INK: std::cell::Cell<(f64, f64)> = std::cell::Cell::new((1.0, FONT));
}
fn set_ink(w: f64, font: f64) {
    INK.with(|c| c.set((w, font)));
}
fn ink_w() -> f64 {
    INK.with(|c| c.get().0)
}
fn font_sz() -> f64 {
    INK.with(|c| c.get().1)
}
fn arrow_l() -> f64 {
    ARROW_L * ink_w()
}
fn arrow_hw() -> f64 {
    ARROW_HW * ink_w()
}
fn line_inset() -> f64 {
    LINE_INSET * ink_w()
}
fn text_off() -> f64 {
    font_sz() / 2.0 + 2.0
}''')

# 2. arrow()
rep('''    let base = tip.add(d.mul(ARROW_L));''','''    let base = tip.add(d.mul(arrow_l()));''')
rep('''    vec![tip, base.add(l.mul(ARROW_HW)), base.sub(l.mul(ARROW_HW))]''','''    vec![tip, base.add(l.mul(arrow_hw())), base.sub(l.mul(arrow_hw()))]''')
# 3. linear items + aligned + leaders + inside diameter: replace constants in code bodies (not comments/consts)
lines = s.split('\n')
out=[]
for ln in lines:
    stripped = ln.strip()
    if stripped.startswith('//') or stripped.startswith('pub const') or 'tp.sub(x).len() <= ARROW_L' in ln:
        out.append(ln); continue
    ln2 = re.sub(r'\bARROW_L\b(?!\s*\*)', 'arrow_l()', ln)
