    ln2 = re.sub(r'\bLINE_INSET\b', 'line_inset()', ln2)
    ln2 = re.sub(r'\bTEXT_OFF\b', 'text_off()', ln2)
    out.append(ln2)
s='\n'.join(out)
# fix the helper definitions that got rewritten
s=s.replace('''fn arrow_l() -> f64 {
    arrow_l() * ink_w()
}''','''fn arrow_l() -> f64 {
    ARROW_L * ink_w()
}''')
s=s.replace('''fn arrow_hw() -> f64 {
    arrow_hw() * ink_w()
}''','''fn arrow_hw() -> f64 {
    ARROW_HW * ink_w()
}''')
s=s.replace('''fn line_inset() -> f64 {
    line_inset() * ink_w()
}''','''fn line_inset() -> f64 {
    LINE_INSET * ink_w()
}''')
# 4. text sizes in dim_text / half_h / text_items
rep('''            Some(_) => (FONT / 2.0).max(1.1 * FONT * TOL_STACK / 2.0 + FONT * TOL_STACK / 2.0),
            None => FONT / 2.0,''','''            Some(_) => (font_sz() / 2.0).max(1.1 * font_sz() * TOL_STACK / 2.0 + font_sz() * TOL_STACK / 2.0),
            None => font_sz() / 2.0,''')
