843	fn dim_axis(a: &Ref, b: &Ref, project: Option<&str>) -> Result<Axis, String> {
844	    match project {
845	        Some("horizontal") => return Ok(Axis::X),
846	        Some("vertical") => return Ok(Axis::Y),
847	        _ => {}
848	    }
849	    let pick = |n: P| if n.x.abs() > n.y.abs() { Axis::X } else { Axis::Y };
850	    match (a.n, b.n) {
851	        (Some(na), Some(nb)) => {
852	            if na.cross(nb).abs() < 1e-6 {
853	                Ok(pick(na))
854	            } else {
855	                Err("perp".into())
856	            }
857	        }
858	        (Some(na), None) => Ok(pick(na)),
859	        (None, Some(nb)) => Ok(pick(nb)),
860	        (None, None) => {
861	            let d = b.p.sub(a.p);
862	            if d.y.abs() < 1e-6 {
863	                Ok(Axis::X)
864	            } else if d.x.abs() < 1e-6 {
865	                Ok(Axis::Y)
866	            } else {
867	                Ok(Axis::A(d.unit()))
868	            }
869	        }
870	    }
871	}
