875	fn break_extra(ctx: &Ctx, f: usize, a: &Ref, b: &Ref, ax: Axis) -> f64 {
876	    let mut owner = None;
877	    for r in [a, b] {
878	        let mut cur = Some(r.node);
879	        let mut found = None;
880	        while let Some(c) = cur {
881	            if c == f {
882	                break;
883	            }
884	            if ctx.sk.laid.get(&c).map(|l| l.brk.is_some()).unwrap_or(false) {
885	                found = Some(c);
886	                break;
887	            }
888	            cur = ctx.nodes[c].parent;
889	        }
890	        match (owner, found) {
891	            (None, Some(s)) => owner = Some(s),
892	            (Some(o), Some(s)) if o == s => {}
893	            _ => return 0.0,
894	        }
895	    }
896	    let s = match owner {
897	        Some(s) => s,
898	        None => return 0.0,
899	    };
900	    let (along_x, ca, _cb, shift) = ctx.sk.laid[&s].brk.unwrap();
901	    if (along_x && ax != Axis::X) || (!along_x && ax != Axis::Y) {
902	        return 0.0;
903	    }
904	    let inv = match invert(&to_frame(ctx, s, f)) {
905	        Some(m) => m,
906	        None => return 0.0,
907	    };
908	    let (pa, pb) = (apply(&inv, a.p), apply(&inv, b.p));
909	    let (va, vb) = if along_x { (pa.x, pb.x) } else { (pa.y, pb.y) };
910	    let (lo, hi) = (va.min(vb), va.max(vb));
911	    if lo <= ca + 1e-9 && hi >= ca + crate::drawing::BREAK_GAP_PX - 1e-9 {
912	        shift
913	    } else {
914	        0.0
915	    }
916	}
